//! Integration tests for the `ostrya` binary.
//!
//! The tests run the built binary as a subprocess over repositories that the
//! `ostrya` library creates. They compare its results with the golden fixture,
//! and with the `ostree` command where that command is installed.
//!
//! The deterministic fixture tree is the tree that `tests/fixtures/generate.sh`
//! commits with `--branch=test/main --subject="fixture commit" owner=0:0
//! --no-xattrs --timestamp=@1700000000`. A commit of this tree through the
//! binary with `--canonical-permissions` (owner 0:0, `perm & 0755`, no xattrs)
//! and `SOURCE_DATE_EPOCH=1700000000` gives the fixture commit id.

use std::io::{BufRead, BufReader, Write};
use std::net::{TcpListener, TcpStream};
use std::os::fd::AsFd;
use std::os::unix::fs::{MetadataExt, PermissionsExt};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::{Arc, Mutex};

use ostrya::{
    Checksum, CommitModifier, CommitModifierFlags, CommitOptions, ComposefsOptions, CreateOptions,
    LockKind, MutableTree, ObjectName, ObjectType, Repo, RepoMode, Type, Value, base64,
};
use ostrya_rt::block_on;

/// The fixture commit id, branch, and timestamp from `generate.sh`/MANIFEST.
const COMMIT: &str = "b3c8e8525e8a5c3409bf6e6db5f5d656da77ae76d08cbc4f8b75b71879757a89";
const BRANCH: &str = "test/main";
const SUBJECT: &str = "fixture commit";
const SOURCE_DATE_EPOCH: &str = "1700000000";

/// The ed25519 sign fixture, shared with the library `sign_ed25519` test: the
/// base64 of the 64-byte secret key and of the matching 32-byte public key.
const ED25519_SECRET_B64: &str =
    "o74ME/dmhvDeYf64dDJQY8kX2piK0M/nyIRWVi30i6DCOzRsHVcvgYToz6zOb5OvK/v8nH6KfLR3dfdsn6ZSyQ==";
const ED25519_PUBLIC_B64: &str = "wjs0bB1XL4GE6M+szm+Tryv7/Jx+iny0d3X3bJ+mUsk=";

/// The instant of the faked clock of a GnuPG home: 2025-01-01T00:00:00Z.
#[cfg(feature = "gpg")]
const FAKED_CLOCK: &str = "20250101T000000!";

/// Returns `true` if the `gpg` binary is available.
#[cfg(feature = "gpg")]
fn gpg_available() -> bool {
    Command::new("gpg")
        .arg("--version")
        .output()
        .is_ok_and(|out| out.status.success())
}

/// A private GnuPG home directory. A home that `create` or `expiring` makes
/// holds one new ed25519 signing key with no passphrase. A drop of the fixture
/// stops the GnuPG daemons of the directory and removes their socket directory.
#[cfg(feature = "gpg")]
struct GpgHome {
    dir: PathBuf,
}

#[cfg(feature = "gpg")]
impl GpgHome {
    /// Generate a signing key for `uid` in a new home directory under `base`.
    fn create(base: &Path, uid: &str) -> GpgHome {
        let dir = base.join("gnupghome");
        std::fs::create_dir(&dir).unwrap();
        std::fs::set_permissions(&dir, std::fs::Permissions::from_mode(0o700)).unwrap();
        let home = GpgHome { dir };
        let status = home
            .gpg()
            .args(["--pinentry-mode", "loopback", "--passphrase", ""])
            .args(["--quick-gen-key", uid, "ed25519", "sign", "never"])
            .status()
            .unwrap();
        assert!(status.success(), "gpg --quick-gen-key failed");
        home
    }

    /// Generate a signing key for `uid` in a new home directory under `base`.
    /// The key has its creation time at the instant of [`FAKED_CLOCK`], and it
    /// expires `expiry` after that instant.
    ///
    /// The instant is in the `gpg.conf` of the home, so every `gpg` run bound
    /// to the home reads that clock. This includes the signing run that gpgme
    /// drives. As a result, this home makes each signature while the key is
    /// live. Verification in ostrya and in the `ostree` command reads the real
    /// clock, and against that clock an expired key is expired.
    fn expiring(base: &Path, uid: &str, expiry: &str) -> GpgHome {
        let dir = base.join("gnupghome");
        std::fs::create_dir(&dir).unwrap();
        std::fs::set_permissions(&dir, std::fs::Permissions::from_mode(0o700)).unwrap();
        std::fs::write(
            dir.join("gpg.conf"),
            format!("faked-system-time {FAKED_CLOCK}\n"),
        )
        .unwrap();
        let home = GpgHome { dir };
        let status = home
            .gpg()
            .args(["--pinentry-mode", "loopback", "--passphrase", ""])
            .args(["--quick-gen-key", uid, "ed25519", "sign", expiry])
            .status()
            .unwrap();
        assert!(status.success(), "gpg --quick-gen-key failed");
        home
    }

    /// Set the expiry of the key, with `gpg` at the instant `when`.
    ///
    /// A new self-signature carries a creation time. `gpg` refuses to write one
    /// at the instant that the replaced self-signature carries. The clock
    /// option stated last takes effect. A run at a later instant then writes
    /// the signature that a run at the instant of the home cannot write.
    fn set_expire_at(&self, when: &str, expiry: &str) {
        let primary = self.fingerprint();
        let status = self
            .gpg()
            .args(["--pinentry-mode", "loopback", "--passphrase", ""])
            .args(["--faked-system-time", when])
            .args(["--quick-set-expire", &primary, expiry])
            .status()
            .unwrap();
        assert!(status.success(), "gpg --quick-set-expire failed");
    }

    /// Add a signing subkey to the key of this home and report its fingerprint.
    /// `gpg` 2.4.9 signs with a signing subkey if the certificate carries one.
    /// As a result, a signature made after this call is a signature of the
    /// subkey. It names two keys: the subkey and the primary key that binds it.
    fn add_signing_subkey(&self) -> String {
        let status = self
            .gpg()
            .args(["--pinentry-mode", "loopback", "--passphrase", ""])
            .args([
                "--quick-add-key",
                &self.fingerprint(),
                "ed25519",
                "sign",
                "never",
            ])
            .status()
            .unwrap();
        assert!(status.success(), "gpg --quick-add-key failed");
        let out = self
            .gpg()
            .args(["--with-colons", "--list-keys"])
            .output()
            .unwrap();
        assert!(out.status.success());
        let text = String::from_utf8(out.stdout).unwrap();
        let fingerprints: Vec<&str> = text
            .lines()
            .filter_map(|line| line.strip_prefix("fpr:"))
            .filter_map(|rest| rest.split(':').nth(8))
            .collect();
        assert_eq!(fingerprints.len(), 2, "the primary key and one subkey");
        fingerprints[1].to_owned()
    }

    /// Generate a second signing key for `uid` in this home directory. A
    /// selector that matches both user ids is then ambiguous.
    fn add_key(&self, uid: &str) {
        let status = self
            .gpg()
            .args(["--pinentry-mode", "loopback", "--passphrase", ""])
            .args(["--quick-gen-key", uid, "ed25519", "sign", "never"])
            .status()
            .unwrap();
        assert!(status.success(), "gpg --quick-gen-key failed");
    }

    /// A `gpg` command in batch mode, bound to this home directory.
    fn gpg(&self) -> Command {
        let mut cmd = Command::new("gpg");
        cmd.arg("--homedir").arg(&self.dir).arg("--batch");
        cmd
    }

    /// The primary-key fingerprint, as uppercase hex.
    fn fingerprint(&self) -> String {
        let out = self
            .gpg()
            .args(["--with-colons", "--list-keys"])
            .output()
            .unwrap();
        assert!(out.status.success());
        let text = String::from_utf8(out.stdout).unwrap();
        text.lines()
            .find_map(|line| {
                let mut fields = line.split(':');
                (fields.next() == Some("fpr")).then(|| fields.nth(8).unwrap().to_owned())
            })
            .expect("a fpr record in the key listing")
    }

    /// The primary-key fingerprint of the one key that `selector` names, as
    /// uppercase hex. The tests read a home with more than one key through this
    /// function, because `gpg` selects the listing order of two keys.
    fn fingerprint_of(&self, selector: &str) -> String {
        let out = self
            .gpg()
            .args(["--with-colons", "--list-keys", "--"])
            .arg(selector)
            .output()
            .unwrap();
        assert!(out.status.success(), "gpg --list-keys failed");
        let text = String::from_utf8(out.stdout).unwrap();
        let fingerprints: Vec<&str> = text
            .lines()
            .filter_map(|line| line.strip_prefix("fpr:"))
            .filter_map(|rest| rest.split(':').nth(8))
            .collect();
        assert!(!fingerprints.is_empty(), "no key matched {selector:?}");
        fingerprints[0].to_owned()
    }

    /// Designate the key that `revoker` names as a revoker of the key that
    /// `key` names. `gpg` writes a new direct-key self-signature that carries
    /// signature subpacket 12, so this home must hold both certificates.
    fn add_revoker(&self, key: &str, revoker: &str) {
        let mut cmd = self.gpg_interactive();
        cmd.arg("--edit-key").arg(key);
        answer(
            cmd,
            format!("addrevoker\n{revoker}\ny\ny\nsave\n").as_bytes(),
            "gpg --edit-key addrevoker",
        );
    }

    /// Write to `path` the key revocation that a designated revoker makes for
    /// the key that `key` names. The output is a transferable public key of
    /// the revoked key with the class 0x20 signature. This home must hold the
    /// secret key of the revoker and a certificate of the revoked key that
    /// designates it.
    fn desig_revoke(&self, key: &str, path: &Path) {
        let mut cmd = self.gpg_interactive();
        cmd.arg("--armor")
            .arg("--output")
            .arg(path)
            .arg("--desig-revoke")
            .arg(key);
        answer(cmd, b"y\n0\n\ny\n", "gpg --desig-revoke");
    }

    /// A `gpg` command bound to this home that reads its answers from standard
    /// input, for the commands that take no batch form.
    fn gpg_interactive(&self) -> Command {
        let mut cmd = Command::new("gpg");
        cmd.arg("--homedir").arg(&self.dir).args([
            "--no-tty",
            "--no-batch",
            "--command-fd",
            "0",
            "--pinentry-mode",
            "loopback",
            "--passphrase",
            "",
        ]);
        cmd
    }

    /// Export the certificate of the one key `selector` names to `path`.
    fn export_one_to(&self, selector: &str, path: &Path) {
        let out = self
            .gpg()
            .arg("--export")
            .arg("--")
            .arg(selector)
            .output()
            .unwrap();
        assert!(out.status.success() && !out.stdout.is_empty());
        std::fs::write(path, out.stdout).unwrap();
    }

    /// Export the public keyring to `path`.
    fn export_to(&self, path: &Path) {
        let out = self.gpg().arg("--export").output().unwrap();
        assert!(out.status.success() && !out.stdout.is_empty());
        std::fs::write(path, out.stdout).unwrap();
    }
}

/// Write to `out` the export of the key that `key` names. The export comes from
/// a new GnuPG home that imports the streams of `streams` in their order.
///
/// The merge runs in a separate home, because `gpg` does not sign with a key
/// that its own keyring reports as revoked. It reports "Unusable secret key".
/// The import of the stream from `gpg --desig-revoke` exits 2. The import
/// merges the class 0x20 signature into the certificate in both cases, so this
/// function does not read the exit status of an import.
#[cfg(feature = "gpg")]
fn merged_export(dir: &Path, key: &str, streams: &[&Path], out: &Path) {
    std::fs::create_dir_all(dir).unwrap();
    std::fs::set_permissions(dir, std::fs::Permissions::from_mode(0o700)).unwrap();
    let gpg = || {
        let mut cmd = Command::new("gpg");
        cmd.arg("--homedir").arg(dir).arg("--batch");
        cmd
    };
    for stream in streams {
        gpg().arg("--import").arg(stream).status().unwrap();
    }
    let export = gpg().arg("--export").arg("--").arg(key).output().unwrap();
    remove_gnupg_sockets(dir);
    assert!(export.status.success() && !export.stdout.is_empty());
    std::fs::write(out, export.stdout).unwrap();
}

/// Stop every GnuPG daemon of the home directory `dir` and remove the socket
/// directory GnuPG made for it under the user runtime directory. GnuPG names
/// that directory from the path string of `dir`, so the call also works after
/// `dir` is removed. Failures are ignored.
#[cfg(feature = "gpg")]
fn remove_gnupg_sockets(dir: &Path) {
    for action in [&["--kill", "all"][..], &["--remove-socketdir"][..]] {
        let _ = Command::new("gpgconf")
            .arg("--homedir")
            .arg(dir)
            .args(action)
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .status();
    }
}

/// Run `cmd` with `answers` on its standard input, and assert that it reported
/// success. `what` names the command in the assertion message.
#[cfg(feature = "gpg")]
fn answer(mut cmd: Command, answers: &[u8], what: &str) {
    use std::io::Write;

    let out = cmd
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::null())
        .spawn()
        .and_then(|mut child| {
            child.stdin.take().unwrap().write_all(answers)?;
            child.wait_with_output()
        })
        .unwrap();
    assert!(out.status.success(), "{what} failed");
}

#[cfg(feature = "gpg")]
impl Drop for GpgHome {
    fn drop(&mut self) {
        remove_gnupg_sockets(&self.dir);
    }
}

// --- temp-dir helper ---------------------------------------------------------

struct TmpDir(PathBuf);

impl TmpDir {
    fn new(tag: &str) -> TmpDir {
        static COUNTER: AtomicU32 = AtomicU32::new(0);
        let n = COUNTER.fetch_add(1, Ordering::Relaxed);
        let dir = std::env::temp_dir().join(format!("ostrya-cli-{tag}-{}-{n}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("create temp dir");
        TmpDir(dir)
    }

    fn path(&self) -> &Path {
        &self.0
    }
}

impl Drop for TmpDir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

// --- fixtures and process driving --------------------------------------------

/// Build the deterministic fixture source tree under `base/src`, the same tree
/// that `generate.sh` builds: a regular file, an empty file, a nested file, and
/// a symlink, with explicit modes.
fn build_fixture_source(base: &Path) {
    let set_mode = |p: &Path, m: u32| {
        std::fs::set_permissions(p, std::fs::Permissions::from_mode(m)).unwrap();
    };
    let src = base.join("src");
    std::fs::create_dir_all(src.join("subdir")).unwrap();
    std::fs::write(src.join("hello.txt"), b"hello ostree\n").unwrap();
    std::fs::write(src.join("empty.txt"), b"").unwrap();
    std::fs::write(src.join("subdir/nested.txt"), b"nested\n").unwrap();
    std::os::unix::fs::symlink("hello.txt", src.join("link")).unwrap();
    set_mode(&src.join("hello.txt"), 0o644);
    set_mode(&src.join("empty.txt"), 0o644);
    set_mode(&src.join("subdir/nested.txt"), 0o644);
    set_mode(&src.join("subdir"), 0o755);
    set_mode(&src, 0o755);
}

/// Create a fresh repository of `mode` at `base/repo` and return its path.
fn create_repo(base: &Path, mode: RepoMode) -> PathBuf {
    let repo = base.join("repo");
    block_on(async {
        Repo::create(&repo, CreateOptions::new(mode)).await.unwrap();
    });
    repo
}

struct Run {
    status: std::process::ExitStatus,
    stdout: Vec<u8>,
    stderr: Vec<u8>,
}

impl Run {
    fn ok(&self) -> &Run {
        assert!(
            self.status.success(),
            "ostrya failed: {}\n{}",
            String::from_utf8_lossy(&self.stdout),
            String::from_utf8_lossy(&self.stderr),
        );
        self
    }

    fn stdout_trimmed(&self) -> String {
        String::from_utf8(self.stdout.clone())
            .unwrap()
            .trim()
            .to_owned()
    }
}

/// Run the `ostrya` binary with `args`, optional `stdin`, and extra env.
fn ostrya(args: &[&str], stdin: Option<&[u8]>, env: &[(&str, &str)]) -> Run {
    ostrya_in(None, args, stdin, env)
}

/// Run the `ostrya` binary from `cwd`. The tests use it where a relative path
/// argument makes the working directory part of the behavior under test.
fn ostrya_in(cwd: Option<&Path>, args: &[&str], stdin: Option<&[u8]>, env: &[(&str, &str)]) -> Run {
    let mut cmd = Command::new(env!("CARGO_BIN_EXE_ostrya"));
    if let Some(dir) = cwd {
        cmd.current_dir(dir);
    }
    cmd.args(args)
        .stdin(if stdin.is_some() {
            Stdio::piped()
        } else {
            Stdio::null()
        })
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    for (k, v) in env {
        cmd.env(k, v);
    }
    let mut child = cmd.spawn().expect("spawn ostrya");
    if let Some(bytes) = stdin {
        child
            .stdin
            .take()
            .unwrap()
            .write_all(bytes)
            .expect("write stdin");
    }
    let out = child.wait_with_output().expect("wait ostrya");
    Run {
        status: out.status,
        stdout: out.stdout,
        stderr: out.stderr,
    }
}

/// The environment variable that changes the skip for an absent `ostree`
/// command into a failure. A harness that sets it declares that `ostree` is
/// installed. If `ostree` is not installed, the harness is broken, and the
/// test fails.
const REQUIRE_OSTREE: &str = "OSTRYA_REQUIRE_OSTREE";

/// Returns `true` if the `ostree` command is available for the cross-check
/// tests. A matrix record cites these tests with `evidence:` as its proof. If
/// the tests skip in a harness with no `ostree`, the harness reports the cited
/// cells as covered, and no assertion runs. If [`REQUIRE_OSTREE`] is set, the
/// absence fails the test. If it is not set, the test skips and says so.
fn ostree_available() -> bool {
    let found = Command::new("ostree")
        .arg("--version")
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false);
    assert!(
        found || std::env::var_os(REQUIRE_OSTREE).is_none(),
        "{REQUIRE_OSTREE} is set and `ostree` is not installed, so the \
         tool-comparison tests cannot run"
    );
    if !found {
        eprintln!("skipped: `ostree` is not installed");
    }
    found
}

/// The environment variable that changes the skip for an `ostree` command with
/// no ed25519 engine into a failure. A harness that sets it declares that the
/// installed `ostree` carries the engine. If `ostree` does not carry it, the
/// harness is broken, and the test fails.
const REQUIRE_OSTREE_ED25519: &str = "OSTRYA_REQUIRE_OSTREE_ED25519";

/// Returns `true` if the `ostree` command carries its ed25519 signing engine.
/// `ostree --version` reports the engine as the `sign-ed25519` feature. The
/// engine is a build option. An `ostree` build without it refuses every
/// ed25519 invocation with `Requested signature type is not implemented`. This
/// refusal is a fact of the `ostree` build and states nothing about ostrya. If
/// [`REQUIRE_OSTREE_ED25519`] is set, the absence fails the test. If it is not
/// set, the test skips and says so.
fn ostree_supports_ed25519() -> bool {
    let supported = ostree_available()
        && Command::new("ostree")
            .arg("--version")
            .output()
            .map(|o| String::from_utf8_lossy(&o.stdout).contains("sign-ed25519"))
            .unwrap_or(false);
    assert!(
        supported || std::env::var_os(REQUIRE_OSTREE_ED25519).is_none(),
        "{REQUIRE_OSTREE_ED25519} is set and the installed `ostree` carries no \
         ed25519 engine, so the ed25519 cross-check tests cannot run"
    );
    if supported {
        return true;
    }
    eprintln!("skipped: `ostree` carries no ed25519 engine");
    false
}

/// The commit a ref resolves to, read through the library.
fn resolve(repo: &Path, refspec: &str) -> Option<String> {
    block_on(async {
        let repo = Repo::open(repo).await.unwrap();
        repo.resolve_rev(refspec, true)
            .await
            .unwrap()
            .map(|c| c.to_hex())
    })
}

/// A sorted description of a checked-out tree: one `(relpath, kind)` line for
/// each entry. `kind` holds the type, the permission bits, and the content or
/// the target.
fn describe_tree(root: &Path) -> Vec<String> {
    fn walk(dir: &Path, prefix: &str, out: &mut Vec<String>) {
        let mut entries: Vec<_> = std::fs::read_dir(dir)
            .unwrap()
            .map(|e| e.unwrap())
            .collect();
        entries.sort_by_key(|e| e.file_name());
        for entry in entries {
            let name = entry.file_name().to_string_lossy().into_owned();
            let rel = format!("{prefix}{name}");
            let meta = entry.path().symlink_metadata().unwrap();
            let ty = meta.file_type();
            let perm = meta.permissions().mode() & 0o7777;
            if ty.is_symlink() {
                let target = std::fs::read_link(entry.path()).unwrap();
                out.push(format!("{rel} symlink -> {}", target.display()));
            } else if ty.is_dir() {
                out.push(format!("{rel} dir {perm:o}"));
                walk(&entry.path(), &format!("{rel}/"), out);
            } else {
                let content = std::fs::read(entry.path()).unwrap();
                out.push(format!("{rel} file {perm:o} {} bytes", content.len()));
            }
        }
    }
    let mut out = Vec::new();
    walk(root, "", &mut out);
    out
}

// --- tests -------------------------------------------------------------------

#[test]
fn commit_from_disk_reproduces_fixture_id_and_ref() {
    let tmp = TmpDir::new("commit");
    let base = tmp.path();
    build_fixture_source(base);
    let repo = create_repo(base, RepoMode::Archive);

    let src = base.join("src");
    let run = ostrya(
        &[
            "commit",
            "--repo",
            repo.to_str().unwrap(),
            "-b",
            BRANCH,
            "-s",
            SUBJECT,
            "--canonical-permissions",
            src.to_str().unwrap(),
        ],
        None,
        &[("SOURCE_DATE_EPOCH", SOURCE_DATE_EPOCH)],
    );
    run.ok();

    assert_eq!(
        run.stdout_trimmed(),
        COMMIT,
        "commit id matches the fixture"
    );
    assert_eq!(
        resolve(&repo, BRANCH).as_deref(),
        Some(COMMIT),
        "--branch points the ref at the new commit",
    );

    // The `ostree` command accepts the repository that ostrya created and
    // filled.
    if ostree_available() {
        let repo_arg = format!("--repo={}", repo.display());
        for sub in [&["fsck"][..], &["show", COMMIT], &["ls", "-R", COMMIT]] {
            let out = Command::new("ostree")
                .arg(&repo_arg)
                .args(sub)
                .output()
                .unwrap();
            assert!(
                out.status.success(),
                "ostree {sub:?} rejected the port's repo:\n{}",
                String::from_utf8_lossy(&out.stderr),
            );
        }
        assert_eq!(
            String::from_utf8_lossy(
                &Command::new("ostree")
                    .arg(&repo_arg)
                    .args(["rev-parse", BRANCH])
                    .output()
                    .unwrap()
                    .stdout
            )
            .trim(),
            COMMIT,
            "the tool resolves the branch to the new commit",
        );
    }
}

/// The command line of the fixture generator, with every option that it uses.
/// Declared ownership, no xattrs, and a fixed timestamp give the golden fixture
/// commit with no `--canonical-permissions`. The test also runs the ISO form of
/// the same instant and the hexadecimal and octal forms of the same ids. It
/// also runs a negative id, which declares nothing, so the tree keeps the
/// ownership of its source.
#[test]
fn commit_flags_reproduce_the_fixture_id() {
    let tmp = TmpDir::new("commit-flags");
    let base = tmp.path();
    build_fixture_source(base);
    let repo = create_repo(base, RepoMode::Archive);
    let src = base.join("src");

    let commit = |timestamp: &str, uid: &str, gid: &str| {
        ostrya(
            &[
                "commit",
                "--repo",
                repo.to_str().unwrap(),
                "-b",
                BRANCH,
                "-s",
                SUBJECT,
                "--parent=none",
                &format!("--owner-uid={uid}"),
                &format!("--owner-gid={gid}"),
                "--no-xattrs",
                &format!("--timestamp={timestamp}"),
                src.to_str().unwrap(),
            ],
            None,
            &[],
        )
    };

    assert_eq!(
        commit("@1700000000", "0", "0").ok().stdout_trimmed(),
        COMMIT,
        "the generator's own flags reproduce the fixture commit id",
    );
    assert_eq!(
        commit("2023-11-14T22:13:20Z", "0", "0")
            .ok()
            .stdout_trimmed(),
        COMMIT,
        "the ISO form of the fixture instant is the same timestamp",
    );
    assert_eq!(
        commit("2023-11-14 23:13:20+01:00", "0x0", "00")
            .ok()
            .stdout_trimmed(),
        COMMIT,
        "an offset-bearing wall clock and hexadecimal and octal ids agree",
    );
    // A negative id declares nothing, so the ownership of the source stays. The
    // test compares with the ids of the source, so the claim holds for any
    // user. A root run has a source tree with the `0:0` of the fixture, so a
    // compare with the fixture cannot tell the two cases apart.
    let source = std::fs::metadata(src.join("hello.txt")).unwrap();
    let (uid, gid) = (source.uid(), source.gid());
    assert_eq!(
        commit("@1700000000", "-1", "-1").ok().stdout_trimmed(),
        commit("@1700000000", &uid.to_string(), &gid.to_string())
            .ok()
            .stdout_trimmed(),
        "a negative id declares nothing, so the source's ownership stands",
    );
    if (uid, gid) != (0, 0) {
        assert_ne!(
            commit("@1700000000", "-1", "-1").ok().stdout_trimmed(),
            COMMIT,
            "the source's ownership differs from the fixture's, so the commit does",
        );
    }

    // `SOURCE_DATE_EPOCH` names the same instant that the fixture uses, and
    // `--timestamp` overrides any value that it holds.
    let over_epoch = ostrya(
        &[
            "commit",
            "--repo",
            repo.to_str().unwrap(),
            "-b",
            BRANCH,
            "-s",
            SUBJECT,
            "--parent=none",
            "--owner-uid=0",
            "--owner-gid=0",
            "--no-xattrs",
            "--timestamp=@1700000000",
            src.to_str().unwrap(),
        ],
        None,
        &[("SOURCE_DATE_EPOCH", "1")],
    );
    assert_eq!(
        over_epoch.ok().stdout_trimmed(),
        COMMIT,
        "--timestamp wins over SOURCE_DATE_EPOCH",
    );
}

/// The four `commit` tree-and-time options against the `ostree` command, over
/// a tree with xattrs, a symlink, and a nested directory. Each command commits
/// the same tree with the same options, and the printed checksums must agree.
/// Equal checksums state that the recorded ownership, mode, xattr set, and
/// timestamp are byte-identical.
#[test]
fn commit_ownership_and_timestamp_flags_match_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("commit-owner");
    let base = tmp.path();
    let tree = base.join("tree");
    ostrya_conformance::corpus::materialize("C0", &tree).unwrap();
    ostrya_conformance::corpus::materialize("C4", &tree.join("attrs")).unwrap();
    // The `ostree` command records no xattr with a value of zero bytes, and
    // ostrya records one. A tree with such an xattr gives two different objects
    // for any options under test. This case belongs to corpus `C4`, and this
    // test leaves it out.
    std::fs::remove_file(tree.join("attrs/empty-value")).unwrap();

    let port_repo = base.join("port");
    let tool_repo = base.join("tool");
    for repo in [&port_repo, &tool_repo] {
        block_on(async {
            Repo::create(repo, CreateOptions::new(RepoMode::Archive))
                .await
                .unwrap();
        });
    }

    // Each case names the branch that its commit binds. Two cases that must
    // give one commit share a branch. `ostree.ref-binding` carries the branch
    // name, so the checksum of a commit states the name too. Every commit is a
    // root commit, for any current tip of the branch.
    let cases: [(&str, &str, Vec<&str>); 7] = [
        ("plain", "plain", vec!["--timestamp=@1234567890"]),
        (
            "owner",
            "owner",
            vec![
                "--timestamp=@1234567890",
                "--owner-uid=42",
                "--owner-gid=43",
            ],
        ),
        (
            "owner-radix",
            "owner",
            vec![
                "--timestamp=@1234567890",
                "--owner-uid=0x2a",
                "--owner-gid=053",
            ],
        ),
        (
            "uid-only",
            "uid-only",
            vec!["--timestamp=@1234567890", "--owner-uid=42"],
        ),
        (
            "no-xattrs",
            "no-xattrs",
            vec!["--timestamp=@1234567890", "--no-xattrs", "--owner-uid=42"],
        ),
        ("iso", "plain", vec!["--timestamp=2009-02-13T23:31:30Z"]),
        ("pre-epoch", "pre-epoch", vec!["--timestamp=@-1"]),
    ];

    let mut checksums = std::collections::BTreeMap::new();
    for (case, branch, options) in &cases {
        let mut args = vec![
            "commit".to_owned(),
            "-b".to_owned(),
            (*branch).to_owned(),
            "-s".to_owned(),
            "x".to_owned(),
            "--parent=none".to_owned(),
        ];
        args.extend(options.iter().map(|option| (*option).to_owned()));
        args.push(tree.to_str().unwrap().to_owned());

        let port = {
            let mut argv = vec!["--repo".to_owned(), port_repo.display().to_string()];
            argv.extend(args.clone());
            let borrowed: Vec<&str> = argv.iter().map(String::as_str).collect();
            ostrya(&borrowed, None, &[]).ok().stdout_trimmed()
        };
        let tool = {
            let out = Command::new("ostree")
                .arg(format!("--repo={}", tool_repo.display()))
                .args(&args)
                .output()
                .unwrap();
            assert!(
                out.status.success(),
                "ostree commit {case} failed:\n{}",
                String::from_utf8_lossy(&out.stderr),
            );
            String::from_utf8(out.stdout).unwrap().trim().to_owned()
        };
        assert_eq!(port, tool, "case `{case}`: the two commits differ");
        checksums.insert(*case, port);
    }

    assert_eq!(
        checksums["owner"], checksums["owner-radix"],
        "`0x2a` and `053` are the ids 42 and 43",
    );
    assert_eq!(
        checksums["plain"], checksums["iso"],
        "`@1234567890` and its ISO form are one instant",
    );
    assert_ne!(
        checksums["plain"], checksums["no-xattrs"],
        "the corpus carries xattrs, so dropping them changes the commit",
    );
}

/// A declared-ownership commit keeps the object identity across the modes that
/// store ownership. It has one checksum in `archive`, in `bare-user`, and in
/// the ostrya extension `bare-user-shared`. The `ostree` command cannot open
/// the third mode, so the `bare-user-shared` cell of corpus `C3` rests on this
/// test. The cells and `commit_ownership_and_timestamp_flags_match_the_tool`
/// compare the other two modes directly with `ostree`.
#[test]
fn declared_ownership_is_one_commit_across_modes() {
    let tmp = TmpDir::new("commit-owner-modes");
    let base = tmp.path();
    build_fixture_source(base);
    let src = base.join("src");

    let mut checksums = Vec::new();
    for (name, mode) in [
        ("archive", RepoMode::Archive),
        ("bare-user", RepoMode::BareUser),
        ("bare-user-shared", RepoMode::BareUserShared),
    ] {
        let repo = base.join(format!("repo-{name}"));
        block_on(async {
            Repo::create(&repo, CreateOptions::new(mode)).await.unwrap();
        });
        let commit = ostrya(
            &[
                "commit",
                "--repo",
                repo.to_str().unwrap(),
                "-b",
                BRANCH,
                "-s",
                SUBJECT,
                "--timestamp=@1700000000",
                "--owner-uid=42",
                "--owner-gid=43",
                src.to_str().unwrap(),
            ],
            None,
            &[],
        );
        checksums.push((name, commit.ok().stdout_trimmed()));
    }

    let (first_name, first) = &checksums[0];
    for (name, checksum) in &checksums[1..] {
        assert_eq!(
            checksum, first,
            "{name} and {first_name} disagree on a declared-ownership commit",
        );
    }
}

/// The values that `commit` refuses, with the words and at the step of the
/// `ostree` command: an id that no C `int` holds, an id with
/// `--canonical-permissions`, and a timestamp that neither reader accepts.
/// Every case leaves the repository empty.
#[test]
fn commit_refuses_the_values_the_tool_refuses() {
    let tmp = TmpDir::new("commit-refuse");
    let base = tmp.path();
    build_fixture_source(base);
    let repo = create_repo(base, RepoMode::Archive);
    let src = base.join("src");
    let tool = ostree_available();

    let cases: [(Vec<&str>, &str); 9] = [
        (
            vec!["--owner-uid=abc"],
            "error: Cannot parse integer value \u{201c}abc\u{201d} for --owner-uid",
        ),
        (
            vec!["--owner-uid="],
            "error: Cannot parse integer value \u{201c}\u{201d} for --owner-uid",
        ),
        (
            vec!["--owner-uid=5x"],
            "error: Cannot parse integer value \u{201c}5x\u{201d} for --owner-uid",
        ),
        (
            vec!["--owner-gid=zz"],
            "error: Cannot parse integer value \u{201c}zz\u{201d} for --owner-gid",
        ),
        (
            vec!["--owner-uid=2147483648"],
            "error: Integer value \u{201c}2147483648\u{201d} for --owner-uid out of range",
        ),
        (
            vec!["--canonical-permissions", "--owner-uid=1"],
            "error: Cannot specify both --canonical-permissions and non-zero --owner-uid",
        ),
        (
            vec!["--canonical-permissions", "--owner-gid=7", "--owner-uid=0"],
            "error: Cannot specify both --canonical-permissions and non-zero --owner-gid",
        ),
        (
            vec!["--timestamp=nonsense"],
            "error: Could not parse 'nonsense'",
        ),
        // The readers of the `ostree` command and of ostrya take no bare epoch
        // count. The `@` form states an epoch count.
        (
            vec!["--timestamp=1234567890"],
            "error: Could not parse '1234567890'",
        ),
    ];

    for (options, message) in &cases {
        // Both commands receive this invocation, apart from `--repo`. ostrya
        // takes `--repo PATH` before the subcommand name. Before the
        // subcommand name, the `ostree` command takes only `--repo=PATH`.
        let mut shared = vec!["commit", "-b", "refused", "-s", "x"];
        shared.extend(options.iter().copied());
        shared.push(src.to_str().unwrap());
        let mut args = vec!["--repo", repo.to_str().unwrap()];
        args.extend(shared.iter().copied());

        let run = ostrya(&args, None, &[]);
        assert_eq!(
            run.status.code(),
            Some(1),
            "`{options:?}` was not refused:\n{}",
            String::from_utf8_lossy(&run.stderr),
        );
        assert!(run.stdout.is_empty(), "`{options:?}` printed a checksum");
        assert_eq!(
            String::from_utf8_lossy(&run.stderr).trim(),
            *message,
            "`{options:?}` was refused in other words",
        );
        assert_eq!(
            resolve(&repo, "refused"),
            None,
            "`{options:?}` left a ref behind",
        );

        if tool {
            let out = Command::new("ostree")
                .arg(format!("--repo={}", repo.display()))
                .args(&shared)
                .output()
                .unwrap();
            assert_eq!(
                out.status.code(),
                Some(1),
                "the tool accepted `{options:?}`",
            );
            assert_eq!(
                String::from_utf8_lossy(&out.stderr).trim(),
                *message,
                "the tool refuses `{options:?}` in other words",
            );
        }
    }
}

/// Every `commit` refusal after the transaction opens removes the staging
/// directory, for each way that the refusal ends the process. The seven cases
/// cover two exit shapes of a refusal:
///
/// - an abort and then a process exit:
///   - a `dir=` source that does not open
///   - a `tar=` source that does not open
///   - a `--consume` removal that fails
///   - a `--tar-pathname-filter` value that the reader refuses
///   - a `--base` revision that does not resolve
/// - a process exit from inside the revision reader: `--tree=ref=` over an
///   unknown ref, and over a revision with no parent
///
/// After each case, `tmp/` holds no `staging-` entry, `objects/` holds the
/// objects that it held before, and no new ref exists.
#[test]
fn commit_source_refusals_leave_no_staging_directory() {
    let tmp = TmpDir::new("commit-staging");
    let base = tmp.path();
    build_fixture_source(base);
    let repo = create_repo(base, RepoMode::Archive);
    let repo_arg = format!("--repo={}", repo.display());
    let src = base.join("src");
    let tar = base.join("src.tar");
    pack_tar(&src, &tar);
    let tar_arg = format!("--tree=tar={}", tar.display());
    // `--consume` removes the source directory after the commit reads its
    // contents. `remove_dir` on the path `./` reports EINVAL, so the refusal
    // occurs for any privileges of the caller. The run empties the directory,
    // so the directory is separate from the fixture source.
    let consumed = base.join("consumed");
    std::fs::create_dir_all(&consumed).unwrap();
    std::fs::write(consumed.join("f.txt"), b"consume me\n").unwrap();
    let objects = |repo: &Path| {
        std::fs::read_dir(repo.join("objects"))
            .unwrap()
            .filter_map(|fanout| std::fs::read_dir(fanout.unwrap().path()).ok())
            .map(|entries| entries.count())
            .sum::<usize>()
    };

    // A root commit on `held` supplies the revision for the two `--tree=ref=`
    // cases. One case names a ref that the repository does not carry. The
    // other asks a root commit for its parent. Every case is measured against
    // the objects of this commit.
    let src_arg = format!("--tree=dir={}", src.display());
    let seed = ostrya(
        &[repo_arg.as_str(), "commit", "-b", "held", &src_arg],
        None,
        &[],
    );
    assert!(seed.status.success(), "seeding the repository failed");
    let held = resolve(&repo, "held").expect("the seed commit moved `held`");
    let baseline = objects(&repo);

    let cases: [(Option<&Path>, Vec<&str>, String); 7] = [
        (
            None,
            vec!["-b", "refused", "/nonexistent-zz"],
            "error: opendir(/nonexistent-zz): No such file or directory".to_owned(),
        ),
        (
            None,
            vec!["-b", "refused", "--tree=tar=/nonexistent.tar"],
            "error: archive_read_open_filename: Failed to open '/nonexistent.tar'".to_owned(),
        ),
        (
            Some(consumed.as_path()),
            vec!["-b", "refused", "--consume", "./"],
            "error: unlinkat(./): Invalid argument".to_owned(),
        ),
        (
            None,
            vec!["-b", "refused", "--tar-pathname-filter=nocomma", &tar_arg],
            "error: Missing ',' in --tar-pathname-filter".to_owned(),
        ),
        (
            None,
            vec!["-b", "refused", "--base=nosuchref", &src_arg],
            "error: Refspec 'nosuchref' not found".to_owned(),
        ),
        (
            None,
            vec!["-b", "refused", "--tree=ref=nosuchref"],
            "error: Refspec 'nosuchref' not found".to_owned(),
        ),
        (
            None,
            vec!["-b", "refused", "--tree=ref=held^"],
            format!("error: Commit {held} has no parent"),
        ),
    ];

    for (cwd, options, message) in &cases {
        let mut args = vec![repo_arg.as_str(), "commit"];
        args.extend(options.iter().copied());
        let run = ostrya_in(*cwd, &args, None, &[]);
        assert_eq!(
            run.status.code(),
            Some(1),
            "`{options:?}` was not refused:\n{}",
            String::from_utf8_lossy(&run.stderr),
        );
        assert_eq!(
            String::from_utf8_lossy(&run.stderr).trim(),
            *message,
            "`{options:?}` was refused in other words",
        );
        assert_eq!(resolve(&repo, "refused"), None, "`{options:?}` wrote a ref");
        let staged: Vec<String> = std::fs::read_dir(repo.join("tmp"))
            .unwrap()
            .map(|entry| entry.unwrap().file_name().to_string_lossy().into_owned())
            .filter(|name| name.starts_with("staging-"))
            .collect();
        assert!(
            staged.is_empty(),
            "`{options:?}` left a staging directory: {staged:?}",
        );
        assert_eq!(
            objects(&repo),
            baseline,
            "`{options:?}` published an object"
        );
    }
}

/// `commit --table-output` prints the seven-line block of the `ostree` command
/// byte for byte. The test runs three repository modes and three commits in
/// each mode. The first commit goes into an empty repository. The second
/// commits a tree with one more file. The third commits the first tree again,
/// and the repository already holds its objects.
///
/// The three commits move every counter, so the comparison states the counts
/// and not only the shape of the block. With a `--tree=ref=` source alone or
/// in the second position, the counters of ostrya and `ostree` differ. This is
/// a recorded divergence. The last part of the test pins each command at the
/// value that it prints.
#[test]
fn commit_table_output_matches_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("commit-table");
    let base = tmp.path();
    let tree = base.join("tree");
    ostrya_conformance::corpus::materialize("C0", &tree).unwrap();
    let grown = base.join("grown");
    ostrya_conformance::corpus::materialize("C0", &grown).unwrap();
    std::fs::write(grown.join("added.txt"), b"one more file\n").unwrap();

    for (name, mode) in [
        ("archive", RepoMode::Archive),
        ("bare", RepoMode::Bare),
        ("bare-user", RepoMode::BareUser),
    ] {
        let port_repo = base.join(format!("port-{name}"));
        let tool_repo = base.join(format!("tool-{name}"));
        for repo in [&port_repo, &tool_repo] {
            block_on(async {
                Repo::create(repo, CreateOptions::new(mode)).await.unwrap();
            });
        }
        let mut blocks = Vec::new();
        for source in [&tree, &grown, &tree] {
            let args = [
                "commit",
                "-b",
                "conformance",
                "-s",
                "x",
                "--timestamp=@1700000000",
                "--table-output",
                source.to_str().unwrap(),
            ];
            let (port, tool) = run_both(&port_repo, &tool_repo, &args);
            assert_runs_agree(&port, &tool, &args.join(" "));
            assert!(
                port.status.success(),
                "the `{name}` step failed:\n{}",
                String::from_utf8_lossy(&port.stderr),
            );
            blocks.push(String::from_utf8_lossy(&port.stdout).into_owned());
        }
        // The three steps give different counters, so the comparison reads the
        // counts and not only the shape of the block. The second step writes
        // one content object more than the first, and the third writes none.
        for (earlier, later) in [(0, 1), (1, 2), (0, 2)] {
            assert_ne!(
                blocks[earlier], blocks[later],
                "steps {earlier} and {later} of the `{name}` sequence printed one block",
            );
        }
    }

    // A `tar=` source of three regular files and a `ref=` source whose tree
    // holds one file, over a pair of `archive` repositories. If a `ref=`
    // source is not the first source, the `ostree` command adds its content
    // objects to `Content Total`. For a `ref=` source alone, the metadata
    // total is one object in `ostree` and two in ostrya. The test asserts each
    // command at the value that it prints, so a change in either command fails
    // the run.
    let (port_repo, tool_repo) = create_repo_pair(base, RepoMode::Archive);
    let three = base.join("three");
    std::fs::create_dir_all(three.join("sub")).unwrap();
    std::fs::write(three.join("a.txt"), b"a\n").unwrap();
    std::fs::write(three.join("sub/b.txt"), b"b\n").unwrap();
    std::fs::write(three.join("sub/c.txt"), b"c\n").unwrap();
    let archive = base.join("a.tar");
    pack_tar(&three, &archive);
    let one = base.join("one");
    std::fs::create_dir_all(&one).unwrap();
    std::fs::write(one.join("o.txt"), b"only\n").unwrap();
    let tar_source = format!("--tree=tar={}", archive.display());
    assert_agrees(
        &port_repo,
        &tool_repo,
        &[
            "commit",
            "-b",
            "only1",
            "-s",
            "x",
            "--timestamp=@1700000000",
            &format!("--tree=dir={}", one.display()),
        ],
    );

    // The six counter lines, which carry no checksum and so compare verbatim.
    let counters = |run: &Run| -> String {
        String::from_utf8_lossy(&run.stdout)
            .lines()
            .filter(|line| !line.starts_with("Commit: "))
            .map(|line| format!("{line}\n"))
            .collect()
    };
    let parts = |branch: &str, extra: &[&str], port_block: &str, tool_block: &str| {
        let mut args = vec![
            "commit",
            "-b",
            branch,
            "-s",
            "x",
            "--timestamp=@1700000000",
            "--table-output",
        ];
        args.extend_from_slice(extra);
        let (port, tool) = run_both(&port_repo, &tool_repo, &args);
        let label = args.join(" ");
        for (who, run) in [("port", &port), ("tool", &tool)] {
            assert_eq!(
                run.status.code(),
                Some(0),
                "the {who} did not commit `{label}`:\n{}",
                String::from_utf8_lossy(&run.stderr)
            );
        }
        let first = |run: &Run| {
            String::from_utf8_lossy(&run.stdout)
                .lines()
                .next()
                .unwrap_or_default()
                .to_owned()
        };
        assert_eq!(
            first(&port),
            first(&tool),
            "`{label}` reached different commits"
        );
        // The counters are the whole difference, so the other stream agrees.
        assert_eq!(
            String::from_utf8_lossy(&port.stderr),
            String::from_utf8_lossy(&tool.stderr),
            "`{label}` wrote different standard error",
        );
        assert_eq!(
            counters(&port),
            port_block,
            "the port's counters for `{label}`"
        );
        assert_eq!(
            counters(&tool),
            tool_block,
            "the tool's counters for `{label}`"
        );
    };

    // A `ref=` source in the second position. `Content Total` counts the one
    // content object of the ref tree in the `ostree` command and not in ostrya.
    parts(
        "c1",
        &[&tar_source, "--tree=ref=only1"],
        "Metadata Total: 5\nMetadata Written: 3\nContent Total: 3\n\
         Content Written: 3\nContent Cache Hits: 0\nContent Bytes Written: 6\n",
        "Metadata Total: 5\nMetadata Written: 3\nContent Total: 4\n\
         Content Written: 3\nContent Cache Hits: 0\nContent Bytes Written: 6\n",
    );
    // The same two sources in the other order, where the whole block agrees.
    assert_agrees(
        &port_repo,
        &tool_repo,
        &[
            "commit",
            "-b",
            "c2",
            "-s",
            "x",
            "--timestamp=@1700000000",
            "--table-output",
            "--tree=ref=only1",
            &tar_source,
        ],
    );
    // A `ref=` source alone. Neither command counts a content object, and
    // `Metadata Total` is one in the `ostree` command and two in ostrya.
    parts(
        "c3",
        &["--tree=ref=only1"],
        "Metadata Total: 2\nMetadata Written: 1\nContent Total: 0\n\
         Content Written: 0\nContent Cache Hits: 0\nContent Bytes Written: 0\n",
        "Metadata Total: 1\nMetadata Written: 1\nContent Total: 0\n\
         Content Written: 0\nContent Cache Hits: 0\nContent Bytes Written: 0\n",
    );
}

/// `commit --fsync=POLICY` takes the boolean words of the `ostree` command. It
/// refuses every other value with the words and at the step of `ostree`. It
/// changes no byte that the repository stores.
#[test]
fn commit_fsync_policy_matches_the_tool() {
    let tmp = TmpDir::new("commit-fsync");
    let base = tmp.path();
    let tree = base.join("tree");
    ostrya_conformance::corpus::materialize("C0", &tree).unwrap();
    let source = tree.to_str().unwrap();
    let tool = ostree_available();

    let port_repo = base.join("port");
    let tool_repo = base.join("tool");
    for repo in [&port_repo, &tool_repo] {
        block_on(async {
            Repo::create(repo, CreateOptions::new(RepoMode::Archive))
                .await
                .unwrap();
        });
    }

    // Every accepted spelling of the true and the false values. Each commit is
    // a root commit on one branch, so the full set must print one checksum.
    // The policy controls durability and changes no recorded byte.
    let accepted = [
        "true", "TRUE", "tRuE", "yes", "yEs", "1", "false", "False", "no", "NO", "0",
    ];
    let mut checksums = Vec::new();
    for value in accepted {
        let args = [
            "commit",
            "-b",
            "fsync",
            "-s",
            "x",
            "--parent=none",
            "--timestamp=@1700000000",
            &format!("--fsync={value}"),
            source,
        ]
        .map(str::to_owned);
        let borrowed: Vec<&str> = args.iter().map(String::as_str).collect();
        if tool {
            assert_agrees(&port_repo, &tool_repo, &borrowed);
        }
        let mut argv = vec!["--repo", port_repo.to_str().unwrap()];
        argv.extend(borrowed.iter().copied());
        checksums.push(ostrya(&argv, None, &[]).ok().stdout_trimmed());
    }
    for (value, checksum) in accepted.iter().zip(&checksums) {
        assert_eq!(
            checksum, &checksums[0],
            "`--fsync={value}` reached another commit",
        );
    }

    // The two policies over two new repositories leave the same object store.
    let mut stores = Vec::new();
    for (name, value) in [("on", "true"), ("off", "false")] {
        let repo = base.join(format!("policy-{name}"));
        block_on(async {
            Repo::create(&repo, CreateOptions::new(RepoMode::Archive))
                .await
                .unwrap();
        });
        ostrya(
            &[
                "commit",
                "--repo",
                repo.to_str().unwrap(),
                "-b",
                "fsync",
                "-s",
                "x",
                "--timestamp=@1700000000",
                &format!("--fsync={value}"),
                source,
            ],
            None,
            &[],
        )
        .ok();
        stores.push(describe_tree(&repo.join("objects")));
    }
    assert_eq!(
        stores[0], stores[1],
        "the fsync policy changed the object store",
    );

    // A value that the reader does not know, and the fault order around it.
    // The refusal comes before the missing branch, before the tree, and before
    // the timestamp. The form with no value takes the next word as its value,
    // and the last case names this form.
    let refusals: [(Vec<&str>, &str); 7] = [
        (
            vec!["-b", "f", "--fsync=on", source],
            "error: Invalid boolean argument 'on'",
        ),
        (
            vec!["-b", "f", "--fsync=garbage", source],
            "error: Invalid boolean argument 'garbage'",
        ),
        (
            vec!["-b", "f", "--fsync=", source],
            "error: Invalid boolean argument ''",
        ),
        (
            vec!["--fsync=on", source],
            "error: Invalid boolean argument 'on'",
        ),
        (
            vec!["-b", "f", "--fsync=on", "no-such-tree"],
            "error: Invalid boolean argument 'on'",
        ),
        (
            vec!["-b", "f", "--fsync=on", "--timestamp=nonsense", source],
            "error: Invalid boolean argument 'on'",
        ),
        (vec!["-b", "f", "--fsync", source], ""),
    ];
    for (options, message) in &refusals {
        let mut args = vec!["commit"];
        args.extend(options.iter().copied());
        let expected = if message.is_empty() {
            format!("error: Invalid boolean argument '{source}'")
        } else {
            (*message).to_owned()
        };
        let mut argv = vec!["--repo", port_repo.to_str().unwrap()];
        argv.extend(args.iter().copied());
        let run = ostrya(&argv, None, &[]);
        assert_eq!(
            run.status.code(),
            Some(1),
            "`{options:?}` was not refused:\n{}",
            String::from_utf8_lossy(&run.stderr),
        );
        assert!(run.stdout.is_empty(), "`{options:?}` printed output");
        assert_eq!(
            String::from_utf8_lossy(&run.stderr).trim(),
            expected,
            "`{options:?}` was refused in other words",
        );
        if tool {
            assert_agrees(&port_repo, &tool_repo, &args);
        }
    }

    // The one fault order that ostrya and the `ostree` command do not share is
    // a recorded divergence. With two refusable values on one command line,
    // `ostree` reports the leftmost value. ostrya reports `--owner-uid` in any
    // position. The test runs both orders, because "in any position" is the
    // claim.
    if tool {
        for order in [
            ["--fsync=on", "--owner-uid=abc"],
            ["--owner-uid=abc", "--fsync=on"],
        ] {
            let (port, tool_run) = run_both(
                &port_repo,
                &tool_repo,
                &["commit", order[0], order[1], "-b", "f", source],
            );
            assert!(
                String::from_utf8_lossy(&port.stderr)
                    .contains("Cannot parse integer value \u{201c}abc\u{201d} for --owner-uid"),
                "the port reported another fault first under {order:?}",
            );
            let leftmost = if order[0] == "--fsync=on" {
                "Invalid boolean argument 'on'"
            } else {
                "Cannot parse integer value"
            };
            assert!(
                String::from_utf8_lossy(&tool_run.stderr).contains(leftmost),
                "the tool reported another fault first under {order:?}",
            );
        }
    }
}

/// `commit` refuses a `[core] fsync` value that the reader does not know, for
/// every state of `--fsync`, the value of the option included. The option
/// narrows the configured policy. As a result, `commit` reads the configured
/// value before the narrowing, and `--fsync=false` hides no fault.
#[test]
fn commit_refuses_a_bad_configured_fsync_under_every_override() {
    let tmp = TmpDir::new("commit-fsync-bad-config");
    let base = tmp.path();
    let tree = base.join("tree");
    ostrya_conformance::corpus::materialize("C0", &tree).unwrap();
    let source = tree.to_str().unwrap();
    let tool = ostree_available();

    let port_repo = base.join("port");
    let tool_repo = base.join("tool");
    for repo in [&port_repo, &tool_repo] {
        block_on(async {
            Repo::create(repo, CreateOptions::new(RepoMode::Archive))
                .await
                .unwrap();
        });
        let config = repo.join("config");
        let mut text = std::fs::read_to_string(&config).unwrap();
        text.push_str("fsync=bogus\n");
        std::fs::write(&config, text).unwrap();
    }

    for option in [None, Some("--fsync=true"), Some("--fsync=false")] {
        let mut args = vec!["commit", "-b", "f", "-s", "x", "--timestamp=@1700000000"];
        args.extend(option);
        args.push(source);

        let mut argv = vec!["--repo", port_repo.to_str().unwrap()];
        argv.extend(args.iter().copied());
        let run = ostrya(&argv, None, &[]);
        assert_eq!(
            run.status.code(),
            Some(1),
            "`{option:?}` committed over a bad `[core] fsync`:\n{}",
            String::from_utf8_lossy(&run.stderr),
        );
        assert!(run.stdout.is_empty(), "`{option:?}` printed output");
        assert!(
            String::from_utf8_lossy(&run.stderr).contains("core.fsync"),
            "`{option:?}` was refused for another reason:\n{}",
            String::from_utf8_lossy(&run.stderr),
        );
        assert!(
            !port_repo.join("refs/heads/f").exists(),
            "`{option:?}` wrote a ref",
        );

        // ostrya and the `ostree` command differ only in the wording. `ostree`
        // names its key file, and ostrya names the key. The claim is the exit
        // status, the empty standard output, and the ref that neither command
        // writes.
        if tool {
            let (_, tool_run) = run_both(&port_repo, &tool_repo, &args);
            assert_eq!(
                tool_run.status.code(),
                Some(1),
                "the tool accepted a bad `[core] fsync` under `{option:?}`",
            );
            assert!(tool_run.stdout.is_empty(), "the tool printed output");
            assert!(
                !tool_repo.join("refs/heads/f").exists(),
                "the tool wrote a ref",
            );
        }
    }
}

/// Returns `true` if `strace` is installed and can trace a child of this
/// process with the options of the two syscall tests. These options include
/// `-y`, because both tests read the path behind a descriptor. The syscall
/// tests make their claims only where `strace` can measure them.
fn strace_available() -> bool {
    std::process::Command::new("strace")
        .args(["-y", "-f", "-e", "trace=fsync", "-o", "/dev/null", "true"])
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

/// The `fsync`, `fdatasync`, and `syncfs` calls of one `commit`, in call order.
/// Each call is a pair of the call name and the path that `strace -y` prints
/// for the descriptor. The path is relative to the repository, and `.` is the
/// repository itself. The function also returns the run, so the caller reads
/// the streams and the exit status of the same invocation.
///
/// The tracer can split a call across an `<unfinished ...>` line and a
/// `resumed` line. The function reads such a call from the entry line, which
/// carries the descriptor, so it reads each call once.
fn sync_calls(
    binary: &str,
    repo: &std::path::Path,
    trace: &std::path::Path,
    args: &[&str],
) -> (Run, Vec<(&'static str, String)>) {
    let out = std::process::Command::new("strace")
        .args(["-y", "-f", "-e", "trace=fsync,fdatasync,syncfs", "-o"])
        .arg(trace)
        .arg(binary)
        .args(args)
        .env("SOURCE_DATE_EPOCH", "1700000000")
        .output()
        .expect("strace runs");
    let text = std::fs::read_to_string(trace).expect("the trace is written");
    let root = repo.to_str().expect("the repository path is text");
    let prefix = format!("{root}/");
    let calls = text
        .lines()
        .filter_map(|line| {
            let kind = ["fsync", "fdatasync", "syncfs"].into_iter().find(|call| {
                line.split_whitespace()
                    .any(|word| word.starts_with(&format!("{call}(")))
            })?;
            let at = line.find(&format!("{kind}("))? + kind.len() + 1;
            let open = at + line[at..].find('<')? + 1;
            let close = open + line[open..].find('>')?;
            let path = &line[open..close];
            let named = match path.strip_prefix(&prefix) {
                Some(rest) => rest,
                None if path == root => ".",
                None => path,
            };
            Some((kind, named.to_owned()))
        })
        .collect();
    let run = Run {
        status: out.status,
        stdout: out.stdout,
        stderr: out.stderr,
    };
    (run, calls)
}

/// The fanout directories under `objects/`, relative to the repository. In a
/// repository created for one commit, these are the fanouts that the commit
/// wrote into. The caller reads the expected `fsync` targets from the tree that
/// the run made, and does not need to name checksums.
fn object_fanouts(repo: &std::path::Path) -> Vec<String> {
    let mut names: Vec<String> = std::fs::read_dir(repo.join("objects"))
        .expect("the object store is readable")
        .map(|entry| entry.expect("the entry reads").file_name())
        .filter_map(|name| name.to_str().map(str::to_owned))
        .filter(|name| name.len() == 2 && name.chars().all(|c| c.is_ascii_hexdigit()))
        .map(|name| format!("objects/{name}"))
        .collect();
    names.sort();
    names
}

/// `commit` resolves the `--fsync=POLICY` policy from the repository
/// configuration, narrowed by the option. The resolved value reaches every
/// write of the transaction, the ref write included. No stored byte shows
/// these two facts, so the test states them in syscalls. It measures ostrya
/// and the `ostree` command over corpus `C0`, with the single-component branch
/// name `main`, in four rows:
///
/// - `[core] fsync` unset, with `--fsync=true`
/// - `[core] fsync=true`, with `--fsync=false`
/// - `[core] fsync=false`, with no option
/// - `[core] fsync=false`, with `--fsync=true`
///
/// Three of the four rows must issue no sync call.
///
/// The test holds the row that syncs to the full call inventory, so the
/// absence of any one sync fails it. It reads the `fsync` targets from the
/// tree that the run made: every fanout directory under `objects/`, `objects/`
/// itself, and `refs/heads` for ostrya only. As a result, the test follows the
/// corpus if the corpus changes. The test also asserts the totals: 11 for
/// `ostree` and 12 for ostrya.
///
/// This test reads the single-component ref name, where the ref write creates
/// no directory. `commit_syncs_every_created_ref_directory` reads the names
/// that carry `/`, where the ref write creates directories. It holds the
/// created directories and their call order. The test runs where `strace` is
/// installed.
#[test]
fn commit_fsync_policy_controls_the_syscalls() {
    if !strace_available() {
        return;
    }
    let tmp = TmpDir::new("commit-fsync-syscalls");
    // `strace -y` prints the resolved path of a descriptor. The targets are
    // relative to the repository path, so that path must be resolved too.
    let base = &tmp.path().canonicalize().expect("the temp dir resolves");
    let tree = base.join("tree");
    ostrya_conformance::corpus::materialize("C0", &tree).unwrap();
    let source = tree.to_str().unwrap();
    let port = env!("CARGO_BIN_EXE_ostrya");

    // (tag, configured `[core] fsync`, option, `true` if a sync call is
    // expected). The test also measures the `ostree` command where it is
    // installed.
    let rows: [(&str, Option<&str>, Option<&str>, bool); 4] = [
        ("unset-on", None, Some("--fsync=true"), true),
        ("on-off", Some("true"), Some("--fsync=false"), false),
        ("off-plain", Some("false"), None, false),
        ("off-on", Some("false"), Some("--fsync=true"), false),
    ];

    let mut binaries: Vec<(&str, String)> = vec![("port", port.to_owned())];
    if ostree_available() {
        binaries.push(("tool", "ostree".to_owned()));
    }

    // Every row of each binary must give the same result as the first row. The
    // policy changes the sync calls, and leaves standard output, standard
    // error, the exit status, and the object store unchanged.
    let mut answer: Option<(String, String, Option<i32>, Vec<String>)> = None;
    for (who, binary) in &binaries {
        for (tag, configured, option, expect_sync) in rows {
            let repo = base.join(format!("{who}-{tag}"));
            block_on(async {
                Repo::create(&repo, CreateOptions::new(RepoMode::Archive))
                    .await
                    .unwrap();
            });
            if let Some(value) = configured {
                let config = repo.join("config");
                let text = std::fs::read_to_string(&config).unwrap();
                std::fs::write(
                    &config,
                    text.replacen("[core]\n", &format!("[core]\nfsync={value}\n"), 1),
                )
                .unwrap();
            }
            // The global `--repo` uses the `=` form. This is the one form that
            // both binaries read before the subcommand.
            let repo_arg = format!("--repo={}", repo.display());
            let mut args = vec![
                repo_arg.as_str(),
                "commit",
                "-b",
                "main",
                "-s",
                "x",
                "--timestamp=@1700000000",
            ];
            if let Some(option) = option {
                args.push(option);
            }
            args.push(source);
            let trace = base.join(format!("trace-{who}-{tag}"));
            let (run, calls) = sync_calls(binary, &repo, &trace, &args);
            assert!(
                run.status.success(),
                "`{who}` failed the `{tag}` row: {args:?}\n{}",
                String::from_utf8_lossy(&run.stderr),
            );
            assert!(
                repo.join("refs/heads/main").exists(),
                "`{who}` wrote no ref in the `{tag}` row, so the ref write went unmeasured",
            );
            if expect_sync {
                // One `fsync` for each fanout that the commit wrote into, and
                // one for `objects/`. ostrya also issues one for the directory
                // that holds the ref, and the `ostree` command does not.
                let mut expected = object_fanouts(&repo);
                expected.push("objects".to_owned());
                if *who == "port" {
                    expected.push("refs/heads".to_owned());
                }
                expected.sort();
                let mut fsyncs: Vec<String> = calls
                    .iter()
                    .filter(|(kind, _)| *kind == "fsync")
                    .map(|(_, path)| path.clone())
                    .collect();
                fsyncs.sort();
                assert_eq!(
                    fsyncs, expected,
                    "`{who}` did not `fsync` the directories the `{tag}` row expects",
                );

                let ref_syncs: Vec<&String> = calls
                    .iter()
                    .filter(|(kind, _)| *kind == "fdatasync")
                    .map(|(_, path)| path)
                    .collect();
                assert_eq!(
                    ref_syncs.len(),
                    1,
                    "`{who}` issued {} `fdatasync` calls in the `{tag}` row, where the \
                     ref's temp file takes one: {calls:?}",
                    ref_syncs.len(),
                );
                // ostrya creates the temp file of the ref in `tmp/`. The
                // `ostree` command creates it in the directory that holds the
                // ref.
                let ref_temp = if *who == "port" {
                    "tmp/.ostrya-ref-"
                } else {
                    "refs/heads/"
                };
                assert!(
                    ref_syncs[0].starts_with(ref_temp),
                    "`{who}` did not `fdatasync` the ref's temp file in the `{tag}` row: {}",
                    ref_syncs[0],
                );

                let repo_syncs: Vec<&String> = calls
                    .iter()
                    .filter(|(kind, _)| *kind == "syncfs")
                    .map(|(_, path)| path)
                    .collect();
                assert_eq!(
                    repo_syncs,
                    ["."],
                    "`{who}` did not `syncfs` the repository once in the `{tag}` row: {calls:?}",
                );

                // The totals for corpus `C0`. They follow from these rules and
                // from the eight objects that the corpus commits.
                let total = if *who == "port" { 12 } else { 11 };
                assert_eq!(
                    calls.len(),
                    total,
                    "`{who}` issued {} sync calls in the `{tag}` row, where the table in \
                     `docs/conformance/cli-behavior.md`, \"The fsync vocabulary\", records \
                     {total}: {calls:?}",
                    calls.len(),
                );
            } else {
                assert!(
                    calls.is_empty(),
                    "`{who}` issued {} sync calls in the `{tag}` row, \
                     where the configured policy is off: {calls:?}",
                    calls.len(),
                );
            }

            // The sync calls are the only difference. Every row prints the same
            // checksum and writes nothing to standard error. It exits the same
            // way and leaves the same object store, for the four policies and
            // the two binaries.
            let observed = (
                String::from_utf8_lossy(&run.stdout).into_owned(),
                String::from_utf8_lossy(&run.stderr).into_owned(),
                run.status.code(),
                describe_tree(&repo.join("objects")),
            );
            match &answer {
                None => answer = Some(observed),
                Some(first) => assert_eq!(
                    &observed, first,
                    "`{who}` answered the `{tag}` row differently from the first row",
                ),
            }
        }
    }
}

/// Under `[core] per-object-fsync=true`, `commit` syncs the file of each
/// content object stored as a regular file, and no metadata object. This is
/// true for ostrya and for the `ostree` command over corpus `C0`. The count is
/// four in `archive` and `bare-user`, and three in `bare`, where the symlink
/// object is a symlink inode. The rest of the inventory is the inventory of
/// `commit_fsync_policy_controls_the_syscalls`. The totals are 15, 15, and 14
/// for `ostree`, and 16, 16, and 15 for ostrya. The test runs where `strace`
/// is installed.
#[test]
fn commit_per_object_fsync_syncs_content_objects_alone() {
    if !strace_available() {
        return;
    }
    let tmp = TmpDir::new("commit-per-object-fsync");
    let base = &tmp.path().canonicalize().expect("the temp dir resolves");
    let tree = base.join("tree");
    ostrya_conformance::corpus::materialize("C0", &tree).unwrap();
    let source = tree.to_str().unwrap();
    for (who, binary) in &durability_binaries() {
        for (mode, content) in [
            (RepoMode::Archive, 4),
            (RepoMode::BareUser, 4),
            (RepoMode::Bare, 3),
        ] {
            let label = format!("`{who}` {mode:?}");
            let repo = base.join(format!("{who}-{mode:?}"));
            block_on(async {
                Repo::create(&repo, CreateOptions::new(mode)).await.unwrap();
            });
            set_core_key(&repo, "per-object-fsync=true");
            let repo_arg = format!("--repo={}", repo.display());
            let args = [
                repo_arg.as_str(),
                "commit",
                "-b",
                "main",
                "-s",
                "x",
                "--timestamp=@1700000000",
                source,
            ];
            let trace = base.join(format!("trace-{who}-{mode:?}"));
            let (run, calls) = sync_calls(binary, &repo, &trace, &args);
            assert!(
                run.status.success(),
                "{label} failed: {}",
                String::from_utf8_lossy(&run.stderr),
            );
            assert_eq!(regular_content_objects(&repo), content, "{label}");
            let (ref_temp, extra, total): (&str, &[&str], usize) = if *who == "port" {
                ("tmp/.ostrya-ref-", &["refs/heads"], 12 + content)
            } else {
                ("refs/heads/", &[], 11 + content)
            };
            assert_durability_syncs(&label, &repo, &calls, content, ref_temp, extra, total);
        }
    }
}

/// The directories under `refs/` that one traced run passes to `fsync`, in
/// call order, relative to the repository. `strace -y` prints the path behind
/// a descriptor, so the target of each call is readable.
fn ref_dir_fsyncs(
    binary: &str,
    repo: &std::path::Path,
    trace: &std::path::Path,
    args: &[&str],
) -> Vec<String> {
    let run = std::process::Command::new("strace")
        .args(["-y", "-f", "-e", "trace=fsync", "-o"])
        .arg(trace)
        .arg(binary)
        .args(args)
        .output()
        .expect("strace runs");
    assert!(
        run.status.success(),
        "the traced run failed: {args:?}\n{}",
        String::from_utf8_lossy(&run.stderr),
    );
    let text = std::fs::read_to_string(trace).expect("the trace is written");
    let prefix = format!("{}/", repo.display());
    text.lines()
        .filter_map(|line| {
            let call = line.find("fsync(")?;
            let open = call + line[call..].find('<')? + 1;
            let close = open + line[open..].find('>')?;
            line[open..close].strip_prefix(&prefix).map(str::to_owned)
        })
        .filter(|path| path.starts_with("refs/"))
        .collect()
}

/// A ref name with `/` is durable as a full path. A commit of
/// `deep/nest/branch` into a repository with neither directory creates
/// `refs/heads/deep` and `refs/heads/deep/nest`. Each created name is in the
/// directory one level up, so an `fsync` of that directory records the name.
/// The calls run deepest first, in the order of the object fanout: the name of
/// the ref file, then the name of the directory that holds it, then the next
/// name up. A directory that already exists gets no sync, and `--fsync=false`
/// reaches none of them.
///
/// The `ostree` command issues no directory `fsync` for a ref. As a result,
/// this test states a rule of ostrya alone, and no interop cell reads it. It
/// reads only the `fsync` targets under `refs/`, and only for ostrya.
/// `commit_fsync_policy_controls_the_syscalls` holds the full call inventory
/// of one commit for both binaries. The test runs where `strace` is installed.
#[test]
fn commit_syncs_every_created_ref_directory() {
    if !strace_available() {
        return;
    }
    let tmp = TmpDir::new("ref-parent-fsync");
    let base = tmp.path().canonicalize().expect("the temp dir resolves");
    let tree = base.join("tree");
    ostrya_conformance::corpus::materialize("C0", &tree).unwrap();
    let source = tree.to_str().unwrap();
    let port = env!("CARGO_BIN_EXE_ostrya");

    let repo = create_repo(&base, RepoMode::Archive);
    let repo_arg = format!("--repo={}", repo.display());
    let commit = |branch: &str, fsync: &str, trace: &str| -> Vec<String> {
        ref_dir_fsyncs(
            port,
            &repo,
            &base.join(trace),
            &[
                repo_arg.as_str(),
                "commit",
                "-b",
                branch,
                "-s",
                "x",
                "--timestamp=@1700000000",
                fsync,
                source,
            ],
        )
    };

    assert_eq!(
        commit("deep/nest/branch", "--fsync=true", "trace-created"),
        ["refs/heads/deep/nest", "refs/heads/deep", "refs/heads"],
        "a fresh multi-component ref must sync the holder of every name it created",
    );

    // Every directory of the path exists now. The second commit on the branch
    // creates no directory and syncs only the directory that holds the ref.
    assert_eq!(
        commit("deep/nest/other", "--fsync=true", "trace-existing"),
        ["refs/heads/deep/nest"],
        "a directory already in place needs no sync",
    );

    assert_eq!(
        commit("other/path/branch", "--fsync=false", "trace-off"),
        Vec::<String>::new(),
        "`--fsync=false` must issue no directory sync",
    );
    assert!(
        repo.join("refs/heads/other/path/branch").exists(),
        "the `--fsync=false` row wrote no ref, so it measured nothing",
    );
}

/// The three tree-shaping options reach the tar stream that `commit` reads
/// from standard input. As a result, a tar of a tree and the tree itself
/// commit alike under them. The `ostree` command takes its tar through
/// `--tree=tar=PATH`.
/// This test compares two input paths of ostrya with each other: the tar
/// stream on standard input and the tree on disk.
#[test]
fn commit_tar_stream_honours_the_tree_options() {
    let tmp = TmpDir::new("commit-tar-flags");
    let base = tmp.path();
    build_fixture_source(base);
    let repo = create_repo(base, RepoMode::Archive);
    let src = base.join("src");

    let plain = ostrya(
        &[
            "commit",
            "--repo",
            repo.to_str().unwrap(),
            "-b",
            "plain",
            "-s",
            SUBJECT,
            "--timestamp=@1700000000",
            src.to_str().unwrap(),
        ],
        None,
        &[],
    );
    let plain = plain.ok().stdout_trimmed();
    let tar = ostrya(
        &["export", "--repo", repo.to_str().unwrap(), &plain],
        None,
        &[],
    );
    let tar = tar.ok().stdout.clone();

    let options = [
        "--owner-uid=42",
        "--owner-gid=43",
        "--no-xattrs",
        "--timestamp=@1700000000",
    ];
    let mut from_dir = vec![
        "commit",
        "--repo",
        repo.to_str().unwrap(),
        "-b",
        "declared",
        "-s",
        SUBJECT,
        "--parent=none",
    ];
    from_dir.extend(options);
    let from_tar = from_dir.clone();
    from_dir.push(src.to_str().unwrap());

    assert_eq!(
        ostrya(&from_tar, Some(&tar), &[]).ok().stdout_trimmed(),
        ostrya(&from_dir, None, &[]).ok().stdout_trimmed(),
        "the tar stream and the tree it came from commit alike under the options",
    );
}

#[test]
fn tar_roundtrip_via_stdin_reproduces_tree() {
    let tmp = TmpDir::new("tar");
    let base = tmp.path();
    build_fixture_source(base);

    // Commit the fixture tree from disk, then export it to a tar stream.
    let dir_a = base.join("a");
    std::fs::create_dir_all(&dir_a).unwrap();
    let repo1 = create_repo(&dir_a, RepoMode::Archive);
    let src = base.join("src");
    let commit_disk = ostrya(
        &[
            "commit",
            "--repo",
            repo1.to_str().unwrap(),
            "-b",
            BRANCH,
            "-s",
            SUBJECT,
            "--canonical-permissions",
            src.to_str().unwrap(),
        ],
        None,
        &[("SOURCE_DATE_EPOCH", SOURCE_DATE_EPOCH)],
    );
    commit_disk.ok();
    assert_eq!(
        commit_disk.stdout_trimmed(),
        COMMIT,
        "disk-ingest commit id"
    );

    let export = ostrya(
        &["export", "--repo", repo1.to_str().unwrap(), COMMIT],
        None,
        &[],
    );
    export.ok();
    let tar = export.stdout.clone();
    assert!(!tar.is_empty(), "export produced a tar stream");

    // Feed the same tar stream to `commit` on stdin (no path). The tar carries
    // owner 0:0, so no canonicalization is needed to reproduce the tree.
    let dir_b = base.join("b");
    std::fs::create_dir_all(&dir_b).unwrap();
    let repo2 = create_repo(&dir_b, RepoMode::Archive);
    let commit_tar = ostrya(
        &[
            "commit",
            "--repo",
            repo2.to_str().unwrap(),
            "-b",
            BRANCH,
            "-s",
            SUBJECT,
        ],
        Some(&tar),
        &[("SOURCE_DATE_EPOCH", SOURCE_DATE_EPOCH)],
    );
    commit_tar.ok();
    assert_eq!(
        commit_tar.stdout_trimmed(),
        COMMIT,
        "a tar stream on stdin commits the same tree as its unpacked form",
    );
}

// --- `export` option comparison ----------------------------------------------

/// One member of a tar stream, with only the fields that the `export`
/// comparison reads. The struct holds the full payload, because every member
/// of the corpus is small.
#[derive(Clone, Debug, PartialEq, Eq)]
struct TarMember {
    name: String,
    kind: u8,
    mode: u32,
    uid: u32,
    gid: u32,
    size: u64,
    mtime: u64,
    link: String,
    payload: Vec<u8>,
    xattrs: Vec<(String, Vec<u8>)>,
}

/// The `key=value` records that a PAX extended header holds. Each record is
/// `LENGTH SPACE key=value NEWLINE`, and `LENGTH` counts the whole record.
fn pax_records(body: &[u8]) -> Vec<(String, Vec<u8>)> {
    let mut out = Vec::new();
    let mut at = 0;
    while at < body.len() && body[at] != 0 {
        let space = at
            + body[at..]
                .iter()
                .position(|byte| *byte == b' ')
                .expect("a PAX record states its length");
        let len: usize = std::str::from_utf8(&body[at..space])
            .expect("a PAX record length is text")
            .parse()
            .expect("a PAX record length is a number");
        let record = &body[space + 1..at + len - 1];
        let split = record
            .iter()
            .position(|byte| *byte == b'=')
            .expect("a PAX record holds a key");
        out.push((
            String::from_utf8(record[..split].to_vec()).expect("a PAX key is UTF-8"),
            record[split + 1..].to_vec(),
        ));
        at += len;
    }
    out
}

/// The members of a tar stream, in stream order. The function merges a PAX
/// extended header (typeflag `x`) into the member after it, so a
/// `SCHILY.xattr.*` record gives the extended attributes of that member. The
/// stream ends at the first header block whose name field starts with a NUL.
/// This rule covers the tar dialects of both ostrya and the `ostree` command.
fn tar_members(bytes: &[u8]) -> Vec<TarMember> {
    let octal = |field: &[u8]| -> u64 {
        let digits: Vec<u8> = field
            .iter()
            .copied()
            .take_while(|byte| *byte != 0 && *byte != b' ')
            .collect();
        if digits.is_empty() {
            return 0;
        }
        let text = std::str::from_utf8(&digits).expect("an octal header field is text");
        u64::from_str_radix(text, 8).expect("an octal header field is octal")
    };
    let text = |field: &[u8]| -> String {
        let end = field
            .iter()
            .position(|byte| *byte == 0)
            .unwrap_or(field.len());
        String::from_utf8(field[..end].to_vec()).expect("a header field is UTF-8")
    };
    let mut out = Vec::new();
    let mut pending: Vec<(String, Vec<u8>)> = Vec::new();
    let mut at = 0;
    while at + 512 <= bytes.len() {
        let head = &bytes[at..at + 512];
        if head[0] == 0 {
            break;
        }
        at += 512;
        let size = usize::try_from(octal(&head[124..136])).expect("a member size fits");
        let body = &bytes[at..at + size];
        at += size.next_multiple_of(512);
        let kind = head[156];
        if kind == b'x' || kind == b'g' {
            pending = pax_records(body);
            continue;
        }
        out.push(TarMember {
            name: text(&head[0..100]),
            kind,
            mode: u32::try_from(octal(&head[100..108])).expect("a mode fits"),
            uid: u32::try_from(octal(&head[108..116])).expect("a uid fits"),
            gid: u32::try_from(octal(&head[116..124])).expect("a gid fits"),
            size: u64::try_from(size).expect("a member size fits"),
            mtime: octal(&head[136..148]),
            link: text(&head[157..257]),
            payload: body.to_vec(),
            xattrs: std::mem::take(&mut pending)
                .into_iter()
                .filter_map(|(key, value)| {
                    key.strip_prefix("SCHILY.xattr.")
                        .map(|name| (name.to_owned(), value))
                })
                .collect(),
        });
    }
    out
}

/// The member names of a stream, in stream order.
fn tar_names(members: &[TarMember]) -> Vec<String> {
    members.iter().map(|member| member.name.clone()).collect()
}

/// The tree that a tar stream extracts to, one sorted line for each path. A
/// hardlink member takes the metadata and the content of its target member.
/// As a result, the description is the same for each choice of the member
/// that a command writes in full. The function normalizes the trailing slash
/// of a directory and the name of the root member. The two dialects agree on
/// the content of a tree and differ in the spelling of a name.
fn tar_extracted(members: &[TarMember]) -> Vec<String> {
    let mut out = Vec::new();
    for member in members {
        let source = if member.kind == b'1' {
            members
                .iter()
                .find(|other| other.name == member.link)
                .expect("a hardlink names a member of the same stream")
        } else {
            member
        };
        let kind = match source.kind {
            b'0' | 0 => "file",
            b'2' => "symlink",
            b'5' => "dir",
            other => panic!("unexpected tar typeflag {other:#04x}"),
        };
        let path = member.name.trim_end_matches('/');
        let path = if path.is_empty() { "." } else { path };
        let target = if source.kind == b'2' {
            source.link.as_str()
        } else {
            ""
        };
        out.push(format!(
            "{path} {kind} {:04o} {}:{} -> {target} {:?}",
            source.mode & 0o7777,
            source.uid,
            source.gid,
            source.payload,
        ));
    }
    out.sort();
    out
}

/// The member names that `--subpath` and `--prefix` make from the names of a
/// plain export.
///
/// `--subpath` keeps the names under its directory and rebases them on the
/// archive root. `--prefix` puts its value in front of every name with no
/// separator. If the value does not end in a slash, the root member gets one
/// trailing slash. The function keeps the order of the plain export, because
/// the claim is that neither option reorders a stream.
fn transformed_names(base: &[String], subpath: Option<&str>, prefix: Option<&str>) -> Vec<String> {
    let under = subpath
        .map(|path| path.trim_matches('/').to_owned())
        .filter(|path| !path.is_empty());
    let root = match prefix.filter(|value| !value.is_empty()) {
        None => "./".to_owned(),
        Some(value) if value.ends_with('/') => value.to_owned(),
        Some(value) => format!("{value}/"),
    };
    let mut names = vec![root];
    for name in base.iter().filter(|name| name.as_str() != "./") {
        let relative = match &under {
            None => name.clone(),
            Some(dir) => match name.strip_prefix(&format!("{dir}/")) {
                Some(rest) if !rest.is_empty() => rest.to_owned(),
                _ => continue,
            },
        };
        names.push(format!("{}{relative}", prefix.unwrap_or("")));
    }
    names
}

/// The members of a stream sorted by name, with no hardlink members. The
/// header of a hardlink carries no metadata in ostrya. In the `ostree`
/// command, it carries the metadata of the target member. The walk order of
/// each command selects which member of a content-sharing group becomes the
/// hardlink. As a result, the metadata claim covers the members written in
/// full, and `tar_extracted` covers the hardlinks.
fn tar_metadata(members: &[TarMember]) -> Vec<String> {
    let mut out: Vec<String> = members
        .iter()
        .filter(|member| member.kind != b'1')
        .map(|member| {
            format!(
                "{} {} {:04o} {}:{} {} {} {} {:?}",
                member.name,
                char::from(if member.kind == 0 { b'0' } else { member.kind }),
                member.mode & 0o7777,
                member.uid,
                member.gid,
                member.size,
                member.mtime,
                member.link,
                member.payload,
            )
        })
        .collect();
    out.sort();
    out
}

/// One `export` case: its name, its options, and the `--subpath` and
/// `--prefix` values of those options. [`transformed_names`] reads these
/// values to give the member names that the case must produce.
type ExportCase<'a> = (&'a str, &'a [&'a str], Option<&'a str>, Option<&'a str>);

/// Run `export` with ostrya and with the `ostree` command over one repository,
/// and return the two tar streams.
fn export_both(repo: &Path, options: &[&str], rev: &str) -> (Vec<u8>, Vec<u8>) {
    let mut args = vec!["export", "--repo", repo.to_str().unwrap()];
    args.extend(options.iter().copied());
    args.push(rev);
    let port = ostrya(&args, None, &[]);
    port.ok();
    let tool = ostree(&args);
    tool.ok();
    (port.stdout.clone(), tool.stdout.clone())
}

/// `export --no-xattrs`, `--subpath=PATH`, and `--prefix=PATH` against the
/// export of the same commit by the `ostree` command.
///
/// The two commands write different tar dialects. As a result, the claim is
/// the member list, the member metadata, and the extracted tree, and not the
/// bytes. The member order of each command must be the order of its plain
/// export, so the test states that no option reorders a stream.
#[test]
fn export_options_match_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("export-options");
    let base = tmp.path();
    let tree = base.join("tree");
    ostrya_conformance::corpus::materialize("C0", &tree).unwrap();
    ostrya_conformance::corpus::materialize("C4", &tree.join("attrs")).unwrap();
    ostrya_conformance::corpus::materialize("C8", &tree.join("links")).unwrap();
    let repo = create_repo(base, RepoMode::BareUser);
    let rev = ostrya(
        &[
            "commit",
            "--repo",
            repo.to_str().unwrap(),
            "-b",
            BRANCH,
            "-s",
            SUBJECT,
            "--timestamp=@1700000000",
            tree.to_str().unwrap(),
        ],
        None,
        &[],
    );
    let rev = rev.ok().stdout_trimmed();

    let (port_base, tool_base) = export_both(&repo, &[], &rev);
    let port_base = tar_names(&tar_members(&port_base));
    let tool_base = tar_names(&tar_members(&tool_base));

    let cases: [ExportCase; 12] = [
        ("plain", &[], None, None),
        ("no-xattrs", &["--no-xattrs"], None, None),
        ("prefix-bare", &["--prefix=pre"], None, Some("pre")),
        ("prefix-slash", &["--prefix=pre/"], None, Some("pre/")),
        ("prefix-two", &["--prefix=a/b"], None, Some("a/b")),
        ("prefix-dot", &["--prefix=."], None, Some(".")),
        ("prefix-dot-slash", &["--prefix=./"], None, Some("./")),
        ("prefix-empty", &["--prefix="], None, Some("")),
        ("subpath-absolute", &["--subpath=/dir"], Some("/dir"), None),
        ("subpath-relative", &["--subpath=dir"], Some("dir"), None),
        ("subpath-root", &["--subpath=/"], Some("/"), None),
        (
            "subpath-and-prefix",
            &["--subpath=/dir", "--prefix=pfx/"],
            Some("/dir"),
            Some("pfx/"),
        ),
    ];

    for (case, options, subpath, prefix) in cases {
        let (port, tool) = export_both(&repo, options, &rev);
        let port = tar_members(&port);
        let tool = tar_members(&tool);

        let mut port_names = tar_names(&port);
        let mut tool_names = tar_names(&tool);
        assert_eq!(
            transformed_names(&port_base, subpath, prefix),
            port_names,
            "case `{case}`: the port's member order under the options",
        );
        assert_eq!(
            transformed_names(&tool_base, subpath, prefix),
            tool_names,
            "case `{case}`: the tool's member order under the options",
        );
        port_names.sort();
        tool_names.sort();
        assert_eq!(
            tool_names, port_names,
            "case `{case}`: the two member lists differ",
        );
        assert_eq!(
            tar_metadata(&tool),
            tar_metadata(&port),
            "case `{case}`: the two member metadata sets differ",
        );
        assert_eq!(
            tar_extracted(&tool),
            tar_extracted(&port),
            "case `{case}`: the two streams extract to different trees",
        );

        // The `ostree` command writes no xattr record. ostrya writes one record
        // for each stored xattr, except under `--no-xattrs`.
        assert!(
            tool.iter().all(|member| member.xattrs.is_empty()),
            "case `{case}`: the tool emitted an xattr record",
        );
        let port_xattrs: Vec<&(String, Vec<u8>)> =
            port.iter().flat_map(|member| &member.xattrs).collect();
        // Only the full tree carries the `C4` names. The `dir` subtree holds
        // one file with no extended attribute.
        let carries_xattrs = !options.contains(&"--no-xattrs")
            && subpath.is_none_or(|path| path.trim_matches('/').is_empty());
        if carries_xattrs {
            assert!(
                port_xattrs
                    .iter()
                    .any(|(name, value)| name == "user.demo" && value == b"value"),
                "case `{case}`: the port emitted no `user.demo` record",
            );
        } else {
            assert!(
                port_xattrs.is_empty(),
                "case `{case}`: {} xattr records were left",
                port_xattrs.len(),
            );
        }
    }

    // A hardlink member shows which content-sharing path each command wrote in
    // full. The two commands differ here, because their walk orders differ.
    let (port, tool) = export_both(&repo, &[], &rev);
    let port_links: Vec<String> = tar_members(&port)
        .iter()
        .filter(|member| member.kind == b'1')
        .map(|member| format!("{} -> {}", member.name, member.link))
        .collect();
    let tool_links: Vec<String> = tar_members(&tool)
        .iter()
        .filter(|member| member.kind == b'1')
        .map(|member| format!("{} -> {}", member.name, member.link))
        .collect();
    assert_eq!(
        port_links.len(),
        2,
        "two of the three shared paths coalesce"
    );
    assert_eq!(
        tool_links.len(),
        2,
        "two of the three shared paths coalesce"
    );
}

/// The stream of `export --no-xattrs` carries every fact of an ostree tree in
/// a dialect that ostrya and the `ostree` command agree on. As a result, the
/// import by `ostree` of the archive of each command is a checksum oracle. The
/// commit checksum that the import prints states the tree of the archive.
#[test]
fn export_no_xattrs_imports_to_one_commit() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("export-import");
    let base = tmp.path();
    let tree = base.join("tree");
    ostrya_conformance::corpus::materialize("C0", &tree).unwrap();
    ostrya_conformance::corpus::materialize("C8", &tree.join("links")).unwrap();
    let repo = create_repo(base, RepoMode::Archive);
    let rev = ostrya(
        &[
            "commit",
            "--repo",
            repo.to_str().unwrap(),
            "-b",
            BRANCH,
            "-s",
            SUBJECT,
            "--timestamp=@1700000000",
            tree.to_str().unwrap(),
        ],
        None,
        &[],
    );
    let rev = rev.ok().stdout_trimmed();

    // `--prefix=./` is the one prefix whose names normalize back to the bare
    // names on import, so it gives the same tree as the plain export. Every
    // other prefix gives an archive with no root member, and the import
    // refuses it.
    let cases: [(&str, &[&str]); 3] = [
        ("whole-tree", &["--no-xattrs"]),
        ("subpath", &["--no-xattrs", "--subpath=/dir"]),
        ("prefix-dot-slash", &["--no-xattrs", "--prefix=./"]),
    ];
    for (case, options) in cases {
        let (port_tar, tool_tar) = export_both(&repo, options, &rev);
        let port_path = base.join(format!("{case}-port.tar"));
        let tool_path = base.join(format!("{case}-tool.tar"));
        std::fs::write(&port_path, &port_tar).unwrap();
        std::fs::write(&tool_path, &tool_tar).unwrap();

        // One destination repository for each archive, under one branch name.
        // The ref binding of each commit is then the same, so the checksum
        // states only the tree.
        let mut checksums = Vec::new();
        for (importer, archive) in [("port", &port_path), ("tool", &tool_path)] {
            for reader in ["port", "tool"] {
                let dest = base.join(format!("{case}-{importer}-{reader}"));
                block_on(async {
                    Repo::create(&dest, CreateOptions::new(RepoMode::Archive))
                        .await
                        .unwrap();
                });
                let args = [
                    "commit".to_owned(),
                    format!("--repo={}", dest.display()),
                    "-b".to_owned(),
                    BRANCH.to_owned(),
                    "-s".to_owned(),
                    SUBJECT.to_owned(),
                    format!("--tree=tar={}", archive.display()),
                    "--timestamp=@1700000000".to_owned(),
                ];
                let args: Vec<&str> = args.iter().map(String::as_str).collect();
                let run = if reader == "port" {
                    ostrya(&args, None, &[])
                } else {
                    ostree(&args)
                };
                checksums.push(format!("{importer}/{reader} {}", run.ok().stdout_trimmed()));
            }
        }
        let checksum = checksums[0]
            .split_once(' ')
            .expect("a checksum line")
            .1
            .to_owned();
        for line in &checksums {
            assert_eq!(
                line.split_once(' ').expect("a checksum line").1,
                checksum,
                "case `{case}`: the four imports of the two archives differ: {checksums:?}",
            );
        }
    }
}

/// `export -o PATH` and `export --output=PATH`: the archive in the
/// destination, the mode of a new destination, and what an existing
/// destination keeps.
#[test]
fn export_output_switch_matches_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("export-output");
    let base = tmp.path();
    let tree = base.join("tree");
    ostrya_conformance::corpus::materialize("C0", &tree).unwrap();
    let repo = create_repo(base, RepoMode::Archive);
    let rev = ostrya(
        &[
            "commit",
            "--repo",
            repo.to_str().unwrap(),
            "-b",
            BRANCH,
            "-s",
            SUBJECT,
            "--timestamp=@1700000000",
            tree.to_str().unwrap(),
        ],
        None,
        &[],
    );
    let rev = rev.ok().stdout_trimmed();
    let repo_arg = repo.to_str().unwrap().to_owned();

    // A new destination gets the mode of an ordinary create on this host,
    // which is `0o666` reduced by the umask. The test compares with a plain
    // create in the same directory, so it does not set the umask.
    let reference = base.join("umask-probe");
    std::fs::write(&reference, b"").unwrap();
    let expected_mode = std::fs::metadata(&reference).unwrap().permissions().mode() & 0o7777;

    let mut streams = Vec::new();
    for (side, switch) in [("port", "-o"), ("port", "--output"), ("tool", "-o")] {
        let dest = base.join(format!("{side}{switch}.tar"));
        let arg = if switch == "-o" {
            vec![
                "export".to_owned(),
                format!("--repo={repo_arg}"),
                "-o".to_owned(),
                dest.display().to_string(),
                rev.clone(),
            ]
        } else {
            vec![
                "export".to_owned(),
                format!("--repo={repo_arg}"),
                format!("--output={}", dest.display()),
                rev.clone(),
            ]
        };
        let args: Vec<&str> = arg.iter().map(String::as_str).collect();
        if side == "port" {
            ostrya(&args, None, &[]).ok();
        } else {
            ostree(&args).ok();
        }
        assert_eq!(
            std::fs::metadata(&dest).unwrap().permissions().mode() & 0o7777,
            expected_mode,
            "{side} {switch}: a fresh destination takes the umask's mode",
        );
        streams.push(tar_members(&std::fs::read(&dest).unwrap()));
    }
    assert_eq!(
        tar_metadata(&streams[0]),
        tar_metadata(&streams[1]),
        "the port's `-o` and `--output` write one archive",
    );
    assert_eq!(
        tar_metadata(&streams[2]),
        tar_metadata(&streams[0]),
        "the two implementations' `-o` archives hold the same members",
    );

    // Each command opens the destination for writing in place. An existing
    // destination keeps its inode and its mode, and its contents are
    // truncated. Both commands write the same archive into it. Each command
    // pads its own stream, so the test reads the size for each command.
    for side in ["port", "tool"] {
        let dest = base.join(format!("{side}-existing.tar"));
        std::fs::write(&dest, b"pre-existing content").unwrap();
        std::fs::set_permissions(&dest, std::fs::Permissions::from_mode(0o600)).unwrap();
        let inode = std::fs::metadata(&dest).unwrap().ino();
        let args = [
            "export".to_owned(),
            format!("--repo={repo_arg}"),
            "-o".to_owned(),
            dest.display().to_string(),
            rev.clone(),
        ];
        let args: Vec<&str> = args.iter().map(String::as_str).collect();
        if side == "port" {
            ostrya(&args, None, &[]).ok();
        } else {
            ostree(&args).ok();
        }
        let meta = std::fs::metadata(&dest).unwrap();
        assert_eq!(meta.ino(), inode, "{side}: the destination keeps its inode");
        assert_eq!(
            meta.permissions().mode() & 0o7777,
            0o600,
            "{side}: the destination keeps its mode",
        );
        assert_eq!(
            tar_metadata(&tar_members(&std::fs::read(&dest).unwrap())),
            tar_metadata(&streams[0]),
            "{side}: the destination holds the archive",
        );
    }

    // If the destination cannot be opened, both commands exit 1, and neither
    // creates anything on the path to it.
    let missing = base.join("nodir").join("out.tar");
    for side in ["port", "tool"] {
        let args = [
            "export".to_owned(),
            format!("--repo={repo_arg}"),
            "-o".to_owned(),
            missing.display().to_string(),
            rev.clone(),
        ];
        let args: Vec<&str> = args.iter().map(String::as_str).collect();
        let run = if side == "port" {
            ostrya(&args, None, &[])
        } else {
            ostree(&args)
        };
        assert_eq!(run.status.code(), Some(1), "{side}: a missing parent");
        assert!(run.stdout.is_empty(), "{side}: nothing on standard output");
        assert!(!base.join("nodir").exists(), "{side}: no directory created");
    }

    // Each command opens the destination before the revision resolves. A
    // revision that names nothing leaves the destination truncated, with its
    // own mode and inode. Neither command writes an archive into it. The
    // `ostree` command leaves the 1024 bytes that its writer buffered, and
    // ostrya leaves the destination empty.
    for (side, size) in [("port", 0), ("tool", 1024)] {
        let dest = base.join(format!("{side}-refused.tar"));
        std::fs::write(&dest, b"pre-existing content").unwrap();
        std::fs::set_permissions(&dest, std::fs::Permissions::from_mode(0o640)).unwrap();
        let inode = std::fs::metadata(&dest).unwrap().ino();
        let args = [
            "export".to_owned(),
            format!("--repo={repo_arg}"),
            "-o".to_owned(),
            dest.display().to_string(),
            "no-such-ref".to_owned(),
        ];
        let args: Vec<&str> = args.iter().map(String::as_str).collect();
        let run = if side == "port" {
            ostrya(&args, None, &[])
        } else {
            ostree(&args)
        };
        assert_eq!(run.status.code(), Some(1), "{side}: a refused revision");
        let meta = std::fs::metadata(&dest).unwrap();
        assert_eq!(meta.ino(), inode, "{side}: the destination keeps its inode");
        assert_eq!(
            meta.permissions().mode() & 0o7777,
            0o640,
            "{side}: the destination keeps its mode",
        );
        assert_eq!(meta.len(), size, "{side}: the truncated destination's size");
        let held = std::fs::read(&dest).unwrap();
        assert!(
            held.iter().all(|byte| *byte == 0),
            "{side}: the destination holds no archive",
        );
    }

    // Standard output is the same destination under another name. A refusal
    // after the archive opens leaves the padding of the `ostree` command on
    // standard output, and leaves the stream of ostrya empty.
    for (side, size) in [("port", 0), ("tool", 10240)] {
        for revision in ["no-such-ref", &rev] {
            let mut args = vec!["export", "--repo", &repo_arg, revision];
            if revision == rev {
                args.insert(3, "--subpath=/nope");
            }
            let run = if side == "port" {
                ostrya(&args, None, &[])
            } else {
                ostree(&args)
            };
            assert_eq!(run.status.code(), Some(1), "{side}: {revision} is refused");
            assert_eq!(
                run.stdout.len(),
                size,
                "{side}: the refused stream's length over {revision}",
            );
            assert!(
                run.stdout.iter().all(|byte| *byte == 0),
                "{side}: the refused stream holds no archive",
            );
        }
    }
}

/// The `--subpath` values where ostrya and the `ostree` command differ.
/// `ostree` reads a trailing slash as part of a name, and it dies on a subpath
/// that names a file or a symlink. Both commands agree on a `..` component
/// inside a value. This test states the differences and the agreement.
#[test]
fn export_subpath_refusals_match_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("export-subpath");
    let base = tmp.path();
    let tree = base.join("tree");
    ostrya_conformance::corpus::materialize("C0", &tree).unwrap();
    let repo = create_repo(base, RepoMode::Archive);
    let rev = ostrya(
        &[
            "commit",
            "--repo",
            repo.to_str().unwrap(),
            "-b",
            BRANCH,
            "-s",
            SUBJECT,
            "--timestamp=@1700000000",
            tree.to_str().unwrap(),
        ],
        None,
        &[],
    );
    let rev = rev.ok().stdout_trimmed();
    let repo_arg = repo.to_str().unwrap();

    // If a subpath names nothing, both commands end the export at exit 1, each
    // in its own words.
    for subpath in ["--subpath=/nope", "--subpath=/dir/nope"] {
        let args = ["export", "--repo", repo_arg, subpath, &rev];
        let port = ostrya(&args, None, &[]);
        let tool = ostree(&args);
        assert_eq!(port.status.code(), Some(1), "the port refuses {subpath}");
        assert_eq!(tool.status.code(), Some(1), "the tool refuses {subpath}");
        assert!(
            String::from_utf8_lossy(&port.stderr).contains("subpath not found"),
            "the port names the cause: {}",
            String::from_utf8_lossy(&port.stderr),
        );
        assert!(
            String::from_utf8_lossy(&tool.stderr).contains("No such file or directory"),
            "the tool names the cause: {}",
            String::from_utf8_lossy(&tool.stderr),
        );
    }

    // A subpath that names a file or a symlink has no tree to walk. ostrya
    // refuses it at exit 1. The `ostree` command dies on SIGABRT and writes no
    // archive. This crash states nothing about ostrya.
    for subpath in ["--subpath=/file.txt", "--subpath=/link"] {
        let args = ["export", "--repo", repo_arg, subpath, &rev];
        let port = ostrya(&args, None, &[]);
        assert_eq!(port.status.code(), Some(1), "the port refuses {subpath}");
        assert!(
            String::from_utf8_lossy(&port.stderr).contains("subpath is not a directory"),
            "the port names the cause: {}",
            String::from_utf8_lossy(&port.stderr),
        );
        let tool = ostree(&args);
        assert!(!tool.status.success(), "the tool refuses {subpath}");
        assert!(
            tar_members(&tool.stdout).is_empty(),
            "the tool writes no archive for {subpath}",
        );
        assert!(
            String::from_utf8_lossy(&tool.stderr)
                .contains("ostree_repo_file_tree_query_child: assertion failed"),
            "the reference build states the assertion it died on: {}",
            String::from_utf8_lossy(&tool.stderr),
        );
        // The crash puts a `Bail out!` line on standard output, in the place of
        // a tar member.
        let out = String::from_utf8_lossy(&tool.stdout);
        assert!(
            out.starts_with("Bail out! ")
                && out.contains("ostree_repo_file_tree_query_child: assertion failed"),
            "the reference build bails out on standard output: {out}",
        );
    }

    // The `ostree` command reads each `/`-separated span of the value as a
    // child name. As a result, a trailing slash and the spans `.` and `..` all
    // name nothing. ostrya reads a path. A `..` component inside a value also
    // names nothing in ostrya, so the two commands agree on it. In ostrya, a
    // trailing slash names the same directory, and a `.` component has no
    // effect. ostrya accepts these two forms, and `ostree` refuses them.
    for (subpath, named, port_status) in [
        ("--subpath=/dir/", "/dir/", 0),
        ("--subpath=.", "/.", 0),
        ("--subpath=..", "/..", 0),
        ("--subpath=/./dir", "/.", 0),
        ("--subpath=/dir/..", "/dir/..", 1),
        ("--subpath=/dir/../file.txt", "/dir/..", 1),
    ] {
        let args = ["export", "--repo", repo_arg, subpath, &rev];
        let tool = ostree(&args);
        assert_eq!(tool.status.code(), Some(1), "the tool refuses {subpath}");
        assert!(
            String::from_utf8_lossy(&tool.stderr)
                .contains(&format!("No such file or directory: {named}")),
            "the tool names the span it looked up: {}",
            String::from_utf8_lossy(&tool.stderr),
        );
        let port = ostrya(&args, None, &[]);
        assert_eq!(
            port.status.code(),
            Some(port_status),
            "the port's status for {subpath}: {}",
            String::from_utf8_lossy(&port.stderr),
        );
        if port_status == 1 {
            assert!(
                String::from_utf8_lossy(&port.stderr).contains("subpath not found"),
                "the port names the cause: {}",
                String::from_utf8_lossy(&port.stderr),
            );
            assert!(
                tar_members(&port.stdout).is_empty(),
                "the port writes no archive for {subpath}",
            );
        }
    }

    // With the trailing slash, ostrya writes the same archive as without it,
    // and `.` and `..` name the full tree. The value `..` reaches the full tree
    // through the no-component check, which the subpath takes first. The path
    // walk that refuses a `..` inside a value comes after that check.
    let dir_args = ["export", "--repo", repo_arg, "--subpath=/dir", &rev];
    let plain_dir = ostrya(&dir_args, None, &[]).ok().stdout.clone();
    let plain_root = ostrya(&["export", "--repo", repo_arg, &rev], None, &[])
        .ok()
        .stdout
        .clone();
    for (subpath, expected) in [
        ("--subpath=/dir/", &plain_dir),
        ("--subpath=/./dir", &plain_dir),
        ("--subpath=.", &plain_root),
        ("--subpath=..", &plain_root),
    ] {
        let run = ostrya(&["export", "--repo", repo_arg, subpath, &rev], None, &[]);
        assert_eq!(&run.ok().stdout, expected, "the port's `{subpath}` archive",);
    }
}

/// A repeated `--subpath`, `--prefix`, or `-o` takes the last occurrence in
/// ostrya and in the `ostree` command.
#[test]
fn export_repeated_options_take_the_last_value() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("export-repeated");
    let base = tmp.path();
    let tree = base.join("tree");
    ostrya_conformance::corpus::materialize("C0", &tree).unwrap();
    let repo = create_repo(base, RepoMode::BareUser);
    let rev = ostrya(
        &[
            "commit",
            "--repo",
            repo.to_str().unwrap(),
            "-b",
            BRANCH,
            "-s",
            SUBJECT,
            "--timestamp=@1700000000",
            tree.to_str().unwrap(),
        ],
        None,
        &[],
    );
    let rev = rev.ok().stdout_trimmed();

    // The last value decides. The repeated form names the members that the
    // last value alone names, and the first value has no effect.
    for (repeated, once) in [
        (
            ["--prefix=first/", "--prefix=second/"].as_slice(),
            ["--prefix=second/"].as_slice(),
        ),
        (
            ["--subpath=/nope", "--subpath=/dir"].as_slice(),
            ["--subpath=/dir"].as_slice(),
        ),
    ] {
        let (port_repeated, tool_repeated) = export_both(&repo, repeated, &rev);
        let (port_once, tool_once) = export_both(&repo, once, &rev);
        assert_eq!(
            tar_names(&tar_members(&port_repeated)),
            tar_names(&tar_members(&port_once)),
            "the port takes the last of {repeated:?}",
        );
        assert_eq!(
            tar_names(&tar_members(&tool_repeated)),
            tar_names(&tar_members(&tool_once)),
            "the tool takes the last of {repeated:?}",
        );
    }

    // A repeated `-o` writes the last destination and creates no other.
    for side in ["port", "tool"] {
        let first = base.join(format!("{side}-first.tar"));
        let last = base.join(format!("{side}-last.tar"));
        let args = [
            "export".to_owned(),
            format!("--repo={}", repo.display()),
            "-o".to_owned(),
            first.display().to_string(),
            "-o".to_owned(),
            last.display().to_string(),
            rev.clone(),
        ];
        let args: Vec<&str> = args.iter().map(String::as_str).collect();
        if side == "port" {
            ostrya(&args, None, &[]).ok();
        } else {
            ostree(&args).ok();
        }
        assert!(
            !first.exists(),
            "{side}: the first `-o` value is passed over"
        );
        assert!(
            !tar_members(&std::fs::read(&last).unwrap()).is_empty(),
            "{side}: the last `-o` value holds the archive",
        );
    }
}

/// The walk order of each command selects the path of a content-sharing group
/// that the command writes in full. As a result, a group with paths in two
/// directories coalesces in opposite directions.
#[test]
fn export_hardlink_direction_parts_from_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("export-hardlink-direction");
    let base = tmp.path();
    let tree = base.join("tree");
    std::fs::create_dir_all(tree.join("adir")).unwrap();
    std::fs::write(tree.join("z.txt"), b"shared content\n").unwrap();
    std::fs::write(tree.join("adir/a.txt"), b"shared content\n").unwrap();
    let repo = create_repo(base, RepoMode::BareUser);
    let rev = ostrya(
        &[
            "commit",
            "--repo",
            repo.to_str().unwrap(),
            "-b",
            BRANCH,
            "-s",
            SUBJECT,
            "--timestamp=@1700000000",
            tree.to_str().unwrap(),
        ],
        None,
        &[],
    );
    let rev = rev.ok().stdout_trimmed();

    let (port, tool) = export_both(&repo, &[], &rev);
    let port = tar_members(&port);
    let tool = tar_members(&tool);
    let links = |members: &[TarMember]| -> Vec<String> {
        members
            .iter()
            .filter(|member| member.kind == b'1')
            .map(|member| format!("{} -> {}", member.name, member.link))
            .collect()
    };
    // The `ostree` command reaches `z.txt` first, because its walk takes the
    // non-directory entries of a directory before its subdirectories. ostrya
    // reaches `adir/a.txt` first, because its walk takes every entry in one
    // name order.
    assert_eq!(
        links(&tool),
        vec!["adir/a.txt -> z.txt".to_owned()],
        "the tool writes the top-level path in full",
    );
    assert_eq!(
        links(&port),
        vec!["z.txt -> adir/a.txt".to_owned()],
        "the port writes the nested path in full",
    );
    // The direction leaves the tree the stream extracts to unchanged.
    assert_eq!(
        tar_extracted(&tool),
        tar_extracted(&port),
        "the two streams extract to different trees",
    );
}

#[test]
fn checkout_roundtrips_and_matches_tool() {
    let tmp = TmpDir::new("checkout");
    let base = tmp.path();
    build_fixture_source(base);
    // `bare-user-only` discards ownership and xattrs and caps the mode. A
    // checkout then applies no chown and runs unprivileged. A commit ->
    // checkout -> commit round-trip is stable for any labels that the host
    // applies.
    let repo = create_repo(base, RepoMode::BareUserOnly);
    let src = base.join("src");

    let commit = ostrya(
        &[
            "commit",
            "--repo",
            repo.to_str().unwrap(),
            "-b",
            BRANCH,
            "-s",
            SUBJECT,
            "--canonical-permissions",
            src.to_str().unwrap(),
        ],
        None,
        &[("SOURCE_DATE_EPOCH", SOURCE_DATE_EPOCH)],
    );
    let commit = commit.ok().stdout_trimmed();

    let dest_port = base.join("co-port");
    ostrya(
        &[
            "checkout",
            "--repo",
            repo.to_str().unwrap(),
            &commit,
            dest_port.to_str().unwrap(),
        ],
        None,
        &[],
    )
    .ok();

    // A new commit of the checkout with the same options gives the same
    // commit, so checkout is stable. `--parent=none` keeps the second commit a
    // root commit. Without it, the commit takes the current tip of its branch
    // as its parent.
    let recommit = ostrya(
        &[
            "commit",
            "--repo",
            repo.to_str().unwrap(),
            "-b",
            BRANCH,
            "-s",
            SUBJECT,
            "--parent=none",
            "--canonical-permissions",
            dest_port.to_str().unwrap(),
        ],
        None,
        &[("SOURCE_DATE_EPOCH", SOURCE_DATE_EPOCH)],
    );
    assert_eq!(
        recommit.ok().stdout_trimmed(),
        commit,
        "commit -> checkout -> commit is stable",
    );

    // The checkout of ostrya matches the checkout of the same commit by the
    // `ostree` command.
    if ostree_available() {
        let dest_tool = base.join("co-tool");
        let out = Command::new("ostree")
            .arg(format!("--repo={}", repo.display()))
            .args(["checkout", &commit, dest_tool.to_str().unwrap()])
            .output()
            .unwrap();
        assert!(
            out.status.success(),
            "ostree checkout failed:\n{}",
            String::from_utf8_lossy(&out.stderr),
        );
        assert_eq!(
            describe_tree(&dest_port),
            describe_tree(&dest_tool),
            "port and tool checkouts agree",
        );
    }
}

/// `checkout -U` and `checkout --subpath=PATH` against the checkout of the same
/// commit by the `ostree` command. The tree carries a setuid file, a setgid
/// directory, a nested directory, and a symlink. The test runs the modes whose
/// checkout path differs: `archive` copies, `bare-user` hardlinks under `-U`,
/// and `bare` copies under `-U` and hardlinks without it.
#[test]
fn checkout_user_mode_and_subpath_match_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("checkout-user");
    let base = tmp.path();
    let tree = base.join("tree");
    ostrya_conformance::corpus::materialize("C0", &tree).unwrap();
    ostrya_conformance::corpus::materialize("C2", &tree.join("bits")).unwrap();

    let cases: [(&str, Vec<&str>); 6] = [
        ("user-mode", vec!["-U"]),
        ("subpath-dir", vec!["-U", "--subpath=/dir"]),
        ("subpath-relative", vec!["-U", "--subpath=dir"]),
        ("subpath-file", vec!["-U", "--subpath=/file.txt"]),
        ("subpath-symlink", vec!["-U", "--subpath=/link"]),
        ("subpath-root", vec!["-U", "--subpath=/"]),
    ];

    for (mode_name, mode) in [
        ("archive", RepoMode::Archive),
        ("bare-user", RepoMode::BareUser),
        ("bare", RepoMode::Bare),
    ] {
        let repo = base.join(format!("repo-{mode_name}"));
        block_on(async {
            Repo::create(&repo, CreateOptions::new(mode)).await.unwrap();
        });
        let commit = ostrya(
            &[
                "commit",
                "--repo",
                repo.to_str().unwrap(),
                "-b",
                BRANCH,
                "-s",
                SUBJECT,
                "--timestamp=@1700000000",
                tree.to_str().unwrap(),
            ],
            None,
            &[],
        );
        let commit = commit.ok().stdout_trimmed();

        for (case, options) in &cases {
            let dest_port = base.join(format!("port-{mode_name}-{case}"));
            let mut args = vec!["checkout", "--repo", repo.to_str().unwrap()];
            args.extend(options.iter().copied());
            args.push(&commit);
            args.push(dest_port.to_str().unwrap());
            ostrya(&args, None, &[]).ok();

            let dest_tool = base.join(format!("tool-{mode_name}-{case}"));
            let out = Command::new("ostree")
                .arg(format!("--repo={}", repo.display()))
                .arg("checkout")
                .args(options)
                .args([&commit, &dest_tool.display().to_string()])
                .output()
                .unwrap();
            assert!(
                out.status.success(),
                "ostree checkout {case} in {mode_name} failed:\n{}",
                String::from_utf8_lossy(&out.stderr),
            );
            assert_eq!(
                describe_tree(&dest_port),
                describe_tree(&dest_tool),
                "case `{case}` in {mode_name}: the two checkouts differ",
            );
        }

        // The checkout creates a destination directory and puts a file or
        // symlink subpath inside it.
        let inside = base.join(format!("port-{mode_name}-subpath-file"));
        assert!(
            inside.join("file.txt").is_file(),
            "a file subpath lands inside the destination directory",
        );
    }
}

/// The subpaths that `checkout` refuses. ostrya and the `ostree` command exit
/// 1 and leave no destination. The words differ, and this is a recorded
/// divergence.
#[test]
fn checkout_refuses_a_subpath_that_names_nothing() {
    let tmp = TmpDir::new("checkout-subpath-refuse");
    let base = tmp.path();
    build_fixture_source(base);
    let repo = create_repo(base, RepoMode::Archive);
    let src = base.join("src");
    let commit = ostrya(
        &[
            "commit",
            "--repo",
            repo.to_str().unwrap(),
            "-b",
            BRANCH,
            "-s",
            SUBJECT,
            "--timestamp=@1700000000",
            src.to_str().unwrap(),
        ],
        None,
        &[],
    );
    let commit = commit.ok().stdout_trimmed();
    let tool = ostree_available();

    for subpath in ["/nope", "/subdir/nope", "/hello.txt/deeper"] {
        let dest = base.join(format!("dest{}", subpath.replace('/', "-")));
        let run = ostrya(
            &[
                "checkout",
                "--repo",
                repo.to_str().unwrap(),
                &format!("--subpath={subpath}"),
                &commit,
                dest.to_str().unwrap(),
            ],
            None,
            &[],
        );
        assert_eq!(
            run.status.code(),
            Some(1),
            "`{subpath}` was not refused:\n{}",
            String::from_utf8_lossy(&run.stderr),
        );
        assert!(!dest.exists(), "`{subpath}` left a destination behind",);

        if tool {
            let dest_tool = base.join(format!("tool{}", subpath.replace('/', "-")));
            let out = Command::new("ostree")
                .arg(format!("--repo={}", repo.display()))
                .args([
                    "checkout",
                    &format!("--subpath={subpath}"),
                    &commit,
                    &dest_tool.display().to_string(),
                ])
                .output()
                .unwrap();
            assert_eq!(out.status.code(), Some(1), "the tool accepted `{subpath}`",);
            assert!(
                !dest_tool.exists(),
                "the tool left a destination behind for `{subpath}`",
            );
        }
    }
}

#[test]
fn composefs_checkout_matches_library() {
    let tmp = TmpDir::new("composefs");
    let base = tmp.path();
    build_fixture_source(base);
    let repo = create_repo(base, RepoMode::BareUser);
    let src = base.join("src");

    let commit = ostrya(
        &[
            "commit",
            "--repo",
            repo.to_str().unwrap(),
            "-b",
            BRANCH,
            "-s",
            SUBJECT,
            "--canonical-permissions",
            src.to_str().unwrap(),
        ],
        None,
        &[("SOURCE_DATE_EPOCH", SOURCE_DATE_EPOCH)],
    );
    let commit = commit.ok().stdout_trimmed();
    assert_eq!(commit, COMMIT, "bare-user commit id matches the fixture");

    let image_path = base.join("out.cfs");
    ostrya(
        &[
            "checkout",
            "--repo",
            repo.to_str().unwrap(),
            "--composefs",
            &commit,
            image_path.to_str().unwrap(),
        ],
        None,
        &[],
    )
    .ok();

    let cli_bytes = std::fs::read(&image_path).unwrap();
    let lib_bytes = block_on(async {
        let repo = Repo::open(&repo).await.unwrap();
        let checksum = repo.resolve_rev(&commit, false).await.unwrap().unwrap();
        repo.export_composefs(&checksum, &ComposefsOptions::default())
            .await
            .unwrap()
            .bytes
    });
    assert_eq!(
        cli_bytes, lib_bytes,
        "--composefs writes the library's EROFS image bytes",
    );
    assert!(!cli_bytes.is_empty(), "composefs image is non-empty");
}

/// The two composefs switches of `checkout`, over a repository with one tree,
/// in each mode that ostrya and the `ostree` command can both commit into.
/// `--composefs` writes the verity image, and `--composefs-noverity` writes
/// the image whose metacopy xattr carries no digest. The switches are
/// independent, and the no-verity switch decides. As a result, the two
/// combined forms write the no-verity image in either order. The test compares
/// each form with the image of `ostree` for the same commit.
///
/// The test creates every destination at mode 0600 first. Each form then also
/// states that both commands replace an existing destination with a new file.
/// The image gets mode 0644 for both commands at the umask of the run. The
/// `ostree` command gives the image mode 0644 for any umask. This is an
/// observed fact. ostrya gets the same mode with `fchmod` on the open
/// descriptor, which ignores the umask.
#[test]
fn checkout_composefs_switches_match_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("checkout-composefs-switches");
    for (name, mode) in [
        ("bare-user", RepoMode::BareUser),
        ("archive", RepoMode::Archive),
        ("bare", RepoMode::Bare),
        ("bare-user-only", RepoMode::BareUserOnly),
    ] {
        let base = tmp.path().join(name);
        std::fs::create_dir_all(&base).unwrap();
        composefs_switches_match_the_tool(&base, mode);
    }
}

/// [`checkout_composefs_switches_match_the_tool`] over a repository pair in
/// `mode` under `base`.
fn composefs_switches_match_the_tool(base: &Path, mode: RepoMode) {
    let (port_repo, tool_repo, tree) = commit_pair(base, mode);
    assert_agrees(
        &port_repo,
        &tool_repo,
        &[
            "commit",
            "-b",
            BRANCH,
            "-s",
            SUBJECT,
            FIXED_TIMESTAMP,
            "--orphan",
            tree.to_str().unwrap(),
        ],
    );
    let rev = ostrya(
        &[
            "rev-parse",
            &format!("--repo={}", port_repo.display()),
            BRANCH,
        ],
        None,
        &[],
    )
    .ok()
    .stdout_trimmed();

    // The `ostree` command writes the image through a temporary file in the
    // working directory, and then links the file to the destination. As a
    // result, both commands run from the directory of the destinations. One
    // image for each form and each command gives eight files to compare.
    let mut written = Vec::new();
    for (n, flags) in [
        ["--composefs"].as_slice(),
        ["--composefs-noverity"].as_slice(),
        ["--composefs", "--composefs-noverity"].as_slice(),
        ["--composefs-noverity", "--composefs"].as_slice(),
    ]
    .iter()
    .enumerate()
    {
        let label = format!("{} ({mode:?})", flags.join(" "));
        let port_image = base.join(format!("port{n}.cfs"));
        let tool_image = base.join(format!("tool{n}.cfs"));
        for dest in [&port_image, &tool_image] {
            std::fs::write(dest, b"stale destination").unwrap();
            std::fs::set_permissions(dest, PermissionsExt::from_mode(0o600)).unwrap();
        }
        let line = |repo: &Path, dest: &Path| {
            let mut args = vec!["checkout".to_owned(), format!("--repo={}", repo.display())];
            args.extend(flags.iter().map(|flag| (*flag).to_owned()));
            args.push(rev.clone());
            args.push(dest.display().to_string());
            args
        };
        let port_args = line(&port_repo, &port_image);
        let tool_args = line(&tool_repo, &tool_image);
        let port = ostrya_in(
            Some(base),
            &port_args.iter().map(String::as_str).collect::<Vec<_>>(),
            None,
            &[],
        );
        let tool = ostree_in(
            base,
            &tool_args.iter().map(String::as_str).collect::<Vec<_>>(),
        );
        assert_runs_agree(&port, &tool, &format!("checkout {label}"));
        let port_bytes = std::fs::read(&port_image).unwrap();
        let tool_bytes = std::fs::read(&tool_image).unwrap();
        assert!(!port_bytes.is_empty(), "`{label}` wrote an empty image");
        assert_eq!(
            port_bytes, tool_bytes,
            "`checkout {label}` and the tool wrote different image bytes",
        );
        let mode = |path: &Path| std::fs::metadata(path).unwrap().permissions().mode() & 0o777;
        assert_eq!(
            mode(&port_image),
            mode(&tool_image),
            "`checkout {label}` and the tool left the replaced destination at \
             different modes",
        );
        assert_ne!(
            mode(&port_image),
            0o600,
            "`checkout {label}` wrote into the destination instead of \
             replacing it",
        );
        assert_eq!(
            mode(&port_image),
            0o644,
            "`checkout {label}` left the replaced destination at a mode \
             other than 0644",
        );
        assert_eq!(
            mode(&tool_image),
            0o644,
            "the tool left the replaced destination of `checkout {label}` at \
             a mode other than 0644",
        );
        written.push(port_bytes);
    }
    assert_ne!(
        written[0], written[1],
        "the verity image and the no-verity image are the same bytes",
    );
    assert_eq!(
        written[1], written[2],
        "`--composefs --composefs-noverity` did not write the no-verity image",
    );
    assert_eq!(
        written[1], written[3],
        "`--composefs-noverity --composefs` did not write the no-verity image",
    );
}

/// A composefs image holds a child name of at most 255 bytes. A filesystem
/// holds no longer name, so each command commits a tar archive whose member
/// name comes from a pax `path` record. Both commands commit the 255-byte and
/// the 256-byte name to the same checksum. At 255 bytes, both composefs
/// switches write the same image bytes, and
/// `commit --generate-composefs-metadata` writes the same commit. At 256 bytes,
/// both commands refuse each form at exit 1 and write no image, no commit, and
/// no ref. The two refusals have different words, so the test compares only the
/// exit status and standard output.
#[test]
fn checkout_composefs_child_name_bound_matches_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("checkout-composefs-name");
    let base = tmp.path();
    let (port_repo, tool_repo) = create_repo_pair(base, RepoMode::BareUser);
    for len in [255, 256] {
        let archive = base.join(format!("name{len}.tar"));
        pack_long_name(&archive, len);
        let source = format!("--tree=tar={}", archive.display());
        let branch = format!("name{len}");
        assert_agrees(
            &port_repo,
            &tool_repo,
            &["commit", "-b", &branch, FIXED_TIMESTAMP, &source],
        );

        // The `ostree` command writes the image through a temporary file in the
        // working directory, so both commands run from the directory of the
        // destinations.
        for flag in ["--composefs", "--composefs-noverity"] {
            let label = format!("checkout {flag} over a {len}-byte name");
            let port_image = base.join(format!("port{len}{flag}.cfs"));
            let tool_image = base.join(format!("tool{len}{flag}.cfs"));
            let line = |repo: &Path, dest: &Path| {
                vec![
                    "checkout".to_owned(),
                    format!("--repo={}", repo.display()),
                    flag.to_owned(),
                    branch.clone(),
                    dest.display().to_string(),
                ]
            };
            let port_args = line(&port_repo, &port_image);
            let tool_args = line(&tool_repo, &tool_image);
            let port = ostrya_in(
                Some(base),
                &port_args.iter().map(String::as_str).collect::<Vec<_>>(),
                None,
                &[],
            );
            let tool = ostree_in(
                base,
                &tool_args.iter().map(String::as_str).collect::<Vec<_>>(),
            );
            if len == 255 {
                assert_runs_agree(&port, &tool, &label);
                assert_eq!(
                    std::fs::read(&port_image).unwrap(),
                    std::fs::read(&tool_image).unwrap(),
                    "`{label}` and the tool wrote different image bytes",
                );
            } else {
                assert_eq!(port.status.code(), Some(1), "`{label}` exit status");
                assert_eq!(tool.status.code(), Some(1), "the tool's `{label}`");
                assert!(port.stdout.is_empty() && tool.stdout.is_empty());
                assert!(!port_image.exists(), "`{label}` left an image");
                assert!(!tool_image.exists(), "the tool's `{label}` left an image");
            }
        }

        let generated = format!("generated{len}");
        let args = [
            "commit",
            "-b",
            &generated,
            "--generate-composefs-metadata",
            FIXED_TIMESTAMP,
            &source,
        ];
        if len == 255 {
            assert_agrees(&port_repo, &tool_repo, &args);
        } else {
            let commits = |repo: &Path| {
                loose_objects(repo)
                    .into_iter()
                    .filter(|(_, ext)| ext == "commit")
                    .count()
            };
            let before = [commits(&port_repo), commits(&tool_repo)];
            let (port, tool) = run_both(&port_repo, &tool_repo, &args);
            assert_eq!(port.status.code(), Some(1), "the port's commit exit");
            assert_eq!(tool.status.code(), Some(1), "the tool's commit exit");
            assert!(port.stdout.is_empty() && tool.stdout.is_empty());
            for (repo, before) in [&port_repo, &tool_repo].into_iter().zip(before) {
                assert_eq!(
                    commits(repo),
                    before,
                    "{} holds a commit object for the refused commit",
                    repo.display()
                );
                assert!(
                    !repo.join("refs/heads").join(&generated).exists(),
                    "{} holds a ref for the refused commit",
                    repo.display()
                );
            }
        }
    }
}

/// If a composefs export fails part way, it writes no destination. It leaves a
/// destination that already exists as it was, byte for byte and with the same
/// mode. The failure comes from a content object that the test removes from
/// the repository after the commit. The export reaches that object only while
/// it builds the image.
#[test]
fn checkout_composefs_failure_leaves_no_destination() {
    let tmp = TmpDir::new("checkout-composefs-failure");
    let base = tmp.path();
    let tree = base.join("tree");
    ostrya_conformance::corpus::materialize("C0", &tree).unwrap();
    let repo = create_repo(base, RepoMode::Archive);
    ostrya(
        &[
            "commit",
            &format!("--repo={}", repo.display()),
            "-b",
            BRANCH,
            "-s",
            SUBJECT,
            FIXED_TIMESTAMP,
            tree.to_str().unwrap(),
        ],
        None,
        &[],
    )
    .ok();
    let checksum = fsck_reachable_object(&repo, BRANCH, ObjectType::File);
    std::fs::remove_file(fsck_object_path(
        &repo,
        &checksum,
        ObjectType::File,
        RepoMode::Archive,
    ))
    .unwrap();

    for flag in ["--composefs", "--composefs-noverity"] {
        let name = flag.trim_start_matches('-');
        let fail = |dest: &Path| {
            let port = ostrya_in(
                Some(base),
                &[
                    "checkout",
                    &format!("--repo={}", repo.display()),
                    flag,
                    BRANCH,
                    dest.to_str().unwrap(),
                ],
                None,
                &[],
            );
            assert_ne!(
                port.status.code(),
                Some(0),
                "`{flag}` exported a tree with a missing object",
            );
            let stderr = String::from_utf8_lossy(&port.stderr).into_owned();
            assert!(
                stderr.contains("object not found"),
                "`{flag}` failed for a reason other than the missing object:\n{stderr}",
            );
        };

        // If the destination does not exist, the failed export does not create
        // it.
        let port_image = base.join(format!("port-{name}.cfs"));
        fail(&port_image);
        assert!(
            !port_image.exists(),
            "the failed `{flag}` left a destination behind",
        );

        // The failed export leaves a destination that already exists as it
        // was. The export serializes the image while it builds it. An export
        // that opens the destination directly truncates it before the failure.
        let kept = base.join(format!("kept-{name}.cfs"));
        std::fs::write(&kept, b"a file the export has no claim on").unwrap();
        std::fs::set_permissions(&kept, PermissionsExt::from_mode(0o600)).unwrap();
        fail(&kept);
        assert_eq!(
            std::fs::read(&kept).unwrap(),
            b"a file the export has no claim on",
            "the failed `{flag}` changed a destination that already existed",
        );
        assert_eq!(
            std::fs::metadata(&kept).unwrap().permissions().mode() & 0o777,
            0o600,
            "the failed `{flag}` changed the destination's mode",
        );
    }

    // ostrya exports through a temporary file in the directory of the
    // destination. A failure removes this file, so after four failures the
    // directory holds no temporary file.
    let leftover: Vec<_> = std::fs::read_dir(base)
        .unwrap()
        .map(|entry| entry.unwrap().file_name())
        .filter(|name| name.to_string_lossy().starts_with(".ostrya-composefs-"))
        .collect();
    assert!(
        leftover.is_empty(),
        "the failed exports left temporary files behind: {leftover:?}",
    );
}

/// Commit the fixture tree into a new archive repository and return its path.
fn commit_fixture(base: &Path) -> PathBuf {
    build_fixture_source(base);
    let repo = create_repo(base, RepoMode::Archive);
    let src = base.join("src");
    let commit = ostrya(
        &[
            "commit",
            "--repo",
            repo.to_str().unwrap(),
            "-b",
            BRANCH,
            "-s",
            SUBJECT,
            "--canonical-permissions",
            src.to_str().unwrap(),
        ],
        None,
        &[("SOURCE_DATE_EPOCH", SOURCE_DATE_EPOCH)],
    );
    assert_eq!(commit.ok().stdout_trimmed(), COMMIT, "fixture commit id");
    repo
}

#[test]
fn sign_verify_delete_ed25519() {
    let tmp = TmpDir::new("sign-ed25519");
    let base = tmp.path();
    let repo = commit_fixture(base);
    let repo_s = repo.to_str().unwrap();

    // Sign with the default engine (ed25519) and the base64 secret key.
    ostrya(
        &["sign", "--repo", repo_s, COMMIT, ED25519_SECRET_B64],
        None,
        &[],
    )
    .ok();

    // The public key verifies the signature. A wrong key does not.
    let good = ostrya(
        &[
            "sign",
            "--verify",
            "--repo",
            repo_s,
            COMMIT,
            ED25519_PUBLIC_B64,
        ],
        None,
        &[],
    );
    good.ok();
    assert!(good.stdout_trimmed().contains("verification OK"));
    let wrong = base64::encode(&[0u8; 32]);
    let bad = ostrya(
        &["sign", "--verify", "--repo", repo_s, COMMIT, wrong.as_str()],
        None,
        &[],
    );
    assert!(!bad.status.success(), "a wrong key must not verify");

    // The `ostree` command verifies the signature that ostrya wrote.
    if ostree_supports_ed25519() {
        let out = Command::new("ostree")
            .arg(format!("--repo={}", repo.display()))
            .args([
                "sign",
                "--verify",
                "--sign-type=ed25519",
                COMMIT,
                ED25519_PUBLIC_B64,
            ])
            .output()
            .unwrap();
        assert!(
            out.status.success(),
            "tool rejected the port's ed25519 signature:\n{}",
            String::from_utf8_lossy(&out.stderr),
        );
    }

    // Delete the signature by the public key. Verification then fails.
    let del = ostrya(
        &[
            "sign",
            "-d",
            "--repo",
            repo_s,
            "-s",
            "ed25519",
            COMMIT,
            ED25519_PUBLIC_B64,
        ],
        None,
        &[],
    );
    assert!(del.ok().stdout_trimmed().contains("Deleted 1"));
    let after = ostrya(
        &[
            "sign",
            "--verify",
            "--repo",
            repo_s,
            COMMIT,
            ED25519_PUBLIC_B64,
        ],
        None,
        &[],
    );
    assert!(
        !after.status.success(),
        "verification must fail after deletion"
    );
}

/// Each command that writes refs, `config`, a remote keyring, `summary`, or
/// detached metadata takes the update lock once. With `lock-timeout-secs=0`, a
/// command that waits for a lock that it holds fails at once. If each command
/// completes, no command waits for itself.
#[test]
fn writers_take_the_update_lock_once() {
    let tmp = TmpDir::new("writers-update-lock");
    let base = tmp.path();
    let repo = commit_fixture(base);
    let config = repo.join("config");
    let mut text = std::fs::read_to_string(&config).unwrap();
    text.push_str("lock-timeout-secs=0\n");
    std::fs::write(&config, text).unwrap();
    let repo_arg = format!("--repo={}", repo.display());
    let sign = format!("--sign={ED25519_SECRET_B64}");
    let src = base.join("src");

    let runs: Vec<Vec<&str>> = vec![
        vec!["sign", COMMIT, ED25519_SECRET_B64, ED25519_SECRET2_B64],
        vec!["sign", "-d", "-s", "ed25519", COMMIT, ED25519_PUBLIC_B64],
        vec!["summary", "-u", &sign],
        vec!["refs", "--create=other", BRANCH],
        vec!["refs", "-A", "--create=alias", BRANCH],
        vec!["refs", "--delete", "other"],
        vec!["config", "set", "core.newkey", "value"],
        vec!["config", "unset", "core.newkey"],
        vec!["remote", "add", "origin", "https://example.invalid/repo"],
        vec!["remote", "delete", "origin"],
        vec![
            "commit",
            "-b",
            BRANCH,
            "-s",
            "signed",
            &sign,
            src.to_str().unwrap(),
        ],
    ];
    // A remote with a keyring that the command imports, and the removal of the
    // remote, which also removes the keyring.
    #[cfg(feature = "gpg")]
    let (_home, import) = if gpg_available() {
        let home = GpgHome::create(base, "Writers <writers@example.invalid>");
        let keyring = base.join("export.gpg");
        home.export_to(&keyring);
        (Some(home), format!("--gpg-import={}", keyring.display()))
    } else {
        (None, String::new())
    };
    #[cfg(feature = "gpg")]
    let keyed: Vec<Vec<&str>> = if import.is_empty() {
        Vec::new()
    } else {
        vec![
            vec![
                "remote",
                "add",
                &import,
                "keyed",
                "https://example.invalid/repo",
            ],
            vec!["remote", "delete", "keyed"],
        ]
    };
    #[cfg(not(feature = "gpg"))]
    let keyed: Vec<Vec<&str>> = Vec::new();
    for args in runs.iter().chain(&keyed) {
        let mut full = vec![repo_arg.as_str()];
        full.extend_from_slice(args);
        let run = ostrya(&full, None, &[]);
        assert!(
            run.status.success(),
            "{args:?}: {}",
            String::from_utf8_lossy(&run.stderr)
        );
    }
    assert!(!repo.join("keyed.trustedkeys.gpg").exists());
    assert_eq!(
        resolve(&repo, "alias").as_deref(),
        resolve(&repo, BRANCH).as_deref()
    );
}

