/// The no-op paths and the refusals of `config set`, `config unset`, `remote
/// add`, and `remote delete` decide from the configuration read at open, and
/// take no lock. Another holder of the update lock and `lock-timeout-secs=0`
/// do not change their exit status or their output.
#[test]
fn config_no_ops_and_refusals_take_no_lock() {
    let tmp = TmpDir::new("config-no-lock");
    let repo = create_repo(tmp.path(), RepoMode::Archive);
    let repo_arg = format!("--repo={}", repo.display());
    ostrya(
        &[&repo_arg, "remote", "add", "o", "https://example.invalid/o"],
        None,
        &[],
    )
    .ok();
    set_core_key(&repo, "lock-timeout-secs=0");
    let before = config_text(&repo);

    let cases: &[(&[&str], i32, &str)] = &[
        (&["config", "unset", "core.absent"], 0, ""),
        (
            &["config", "set", "core.a=b", "v"],
            1,
            "error: keyfile: key 'a=b' contains a structural character\n",
        ),
        (&["remote", "delete", "--if-exists", "absent"], 0, ""),
        (
            &["remote", "delete", "absent"],
            1,
            "error: Remote \"absent\" not found\n",
        ),
        (
            &[
                "remote",
                "add",
                "--if-not-exists",
                "o",
                "https://example.invalid/other",
            ],
            0,
            "",
        ),
        (
            &["remote", "add", "o", "https://example.invalid/other"],
            1,
            "error: Remote configuration for \"o\" already exists: (in config)\n",
        ),
        (
            &[
                "remote",
                "add",
                "p",
                "https://example.invalid/p",
                "--set",
                "foo",
            ],
            1,
            "error: Missing '=' in KEY=VALUE for --set\n",
        ),
        (
            &[
                "remote",
                "add",
                "p",
                "https://example.invalid/p",
                "--sign-verify=bad",
            ],
            1,
            "error: Failed to parse KEYTYPE=[inline|file]:DATA in bad\n",
        ),
    ];
    let handle = block_on(Repo::open(&repo)).unwrap();
    let guard = block_on(handle.begin_update()).unwrap();
    let mut wrong = Vec::new();
    for (args, code, stderr) in cases {
        let mut full = vec![repo_arg.as_str()];
        full.extend_from_slice(args);
        let run = ostrya(&full, None, &[]);
        let got = (
            run.status.code(),
            String::from_utf8_lossy(&run.stdout).into_owned(),
            String::from_utf8_lossy(&run.stderr).into_owned(),
        );
        if got != (Some(*code), String::new(), (*stderr).to_owned()) {
            wrong.push(format!("{args:?}: {got:?}"));
        }
    }
    block_on(guard.finish()).unwrap();
    assert!(wrong.is_empty(), "wrong results:\n{}", wrong.join("\n"));
    assert_eq!(config_text(&repo), before, "a command wrote `config`");
}

/// `remote refs` and `remote summary` read a live remote over HTTP: the ref
/// listing, the report, the raw variant, and the metadata forms.
#[test]
fn remote_refs_and_summary_match_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("remote-live");
    let base = tmp.path();
    let remote = build_remote(base, "remote");
    let server = FileServer::start(&remote);
    let (port, tool) = create_repo_pair(base, RepoMode::Archive);
    for repo in [&port, &tool] {
        configure_remote(repo, &server.url(), "gpg-verify=false\n");
    }
    // The `last-modified` value of the summary comes from the remote, so both
    // commands read one value. `TZ` sets the zone in which the `ostree` command
    // shows it. ostrya shows it in UTC in every zone.
    let env = &[("TZ", "UTC")];
    for args in [
        vec!["remote", "refs", "origin"],
        vec!["remote", "refs", "origin", "-r"],
        vec!["remote", "refs", "origin", "--revision"],
        vec!["remote", "summary", "origin"],
        vec!["remote", "summary", "origin", "--raw"],
        vec!["remote", "summary", "origin", "--list-metadata-keys"],
        vec![
            "remote",
            "summary",
            "origin",
            "--print-metadata-key=ostree.summary.mode",
        ],
        vec![
            "remote",
            "summary",
            "origin",
            "--print-metadata-key=ostree.summary.last-modified",
        ],
        vec![
            "remote",
            "summary",
            "origin",
            "--print-metadata-key=ostree.summary.tombstone-commits",
        ],
        vec!["remote", "summary", "origin", "--print-metadata-key=absent"],
        vec!["remote", "refs", "absent"],
        vec!["remote", "summary", "absent"],
    ] {
        let (port_run, tool_run) = run_remote_both(&port, &tool, &args, env);
        assert_runs_agree(&port_run, &tool_run, &args.join(" "));
    }
    // Each command prints its own usage text before the refusal of a missing
    // operand.
    for args in [vec!["remote", "refs"], vec!["remote", "summary"]] {
        let (port_run, tool_run) = run_remote_both(&port, &tool, &args, env);
        assert_runs_agree_on_error(
            &port_run,
            &tool_run,
            &args.join(" "),
            "error: NAME must be specified",
        );
    }

    // If a remote publishes no summary, each subcommand refuses it with its own
    // words.
    let bare = build_dest(base, "bare-remote");
    let bare_server = FileServer::start(&bare);
    for repo in [&port, &tool] {
        let config = repo.join("config");
        let mut text = std::fs::read_to_string(&config).unwrap();
        text.push_str(&format!(
            "\n[remote \"nosummary\"]\nurl={}\ngpg-verify=false\n",
            bare_server.url()
        ));
        std::fs::write(&config, text).unwrap();
    }
    for args in [
        vec!["remote", "refs", "nosummary"],
        vec!["remote", "summary", "nosummary"],
    ] {
        let (port_run, tool_run) = run_remote_both(&port, &tool, &args, env);
        assert_runs_agree(&port_run, &tool_run, &args.join(" "));
    }
}

/// `remote gpg-import` writes a keyring that the `ostree` command reads, and
/// reads a keyring that `ostree` wrote. It counts the added keys as `ostree`
/// counts them. The key that it imports verifies a commit signed with that key.
/// `gpg-list-keys` reports the keys that each command imported.
#[cfg(feature = "gpg")]
#[test]
fn remote_gpg_keyring_round_trips_with_the_tool() {
    if !ostree_available() || !gpg_available() {
        return;
    }
    let tmp = TmpDir::new("remote-gpg");
    let base = tmp.path();
    let home = GpgHome::create(base, "Ostrya Remote <remote-gpg@ostrya.example>");
    let fpr = home.fingerprint();
    let public = base.join("public.gpg");
    home.export_to(&public);
    let public_s = public.to_str().unwrap();
    let keyring_arg = format!("--keyring={public_s}");

    let (port, tool) = create_repo_pair(base, RepoMode::Archive);
    for repo in [&port, &tool] {
        configure_remote(repo, "https://example.invalid/r", "");
    }
    // The import reports the same count in both commands. A repeated import
    // adds nothing, and a `KEY-ID` selection takes only the key that it names.
    for args in [
        vec!["remote", "gpg-import", "origin", &keyring_arg],
        vec!["remote", "gpg-import", "origin", &keyring_arg],
        vec!["remote", "gpg-import", "origin", &keyring_arg, &fpr],
        vec!["remote", "gpg-import", "absent", &keyring_arg],
        vec!["remote", "gpg-import", "origin", "--keyring=/nonexistent"],
    ] {
        let (port_run, tool_run) = run_remote_both(&port, &tool, &args, &[]);
        assert_runs_agree(&port_run, &tool_run, &args.join(" "));
    }
    // Both commands refuse a call that names both key sources, before the
    // usage text.
    let both_sources = vec!["remote", "gpg-import", "origin", &keyring_arg, "--stdin"];
    let (port_run, tool_run) = run_remote_both(&port, &tool, &both_sources, &[]);
    assert_runs_agree_on_error(
        &port_run,
        &tool_run,
        "remote gpg-import --keyring --stdin",
        "error: --keyring and --stdin are mutually exclusive",
    );

    // Each command reads the keyring that the other command wrote. The listings
    // differ in two lines that ostrya does not print, so the test asserts the
    // fingerprint and the user id. This is a recorded divergence.
    for repo in [&port, &tool] {
        let repo_arg = format!("--repo={}", repo.display());
        let listing = ostrya(&[&repo_arg, "remote", "gpg-list-keys", "origin"], None, &[]);
        let text = listing.ok().stdout_trimmed();
        assert!(
            text.contains(&format!("Key: {fpr}")) && text.contains("  UID: Ostrya Remote"),
            "the port's listing of {repo:?} lacks the imported key:\n{text}"
        );
        let tool_listing = ostree(&[&repo_arg, "remote", "gpg-list-keys", "origin"]);
        let tool_text = tool_listing.ok().stdout_trimmed();
        assert!(
            tool_text.contains(&format!("Key: {fpr}")),
            "the tool's listing of {repo:?} lacks the imported key:\n{tool_text}"
        );
    }

    // The imported key verifies a commit that the `ostree` command signed with
    // it, through the remote that owns the keyring.
    let signed = commit_fixture(base);
    let signed_s = signed.to_str().unwrap();
    configure_remote(&signed, "https://example.invalid/r", "");
    ostree(&[
        "gpg-sign",
        "--repo",
        signed_s,
        "--gpg-homedir",
        home.dir.to_str().unwrap(),
        COMMIT,
        &fpr,
    ])
    .ok();
    ostrya(
        &[
            &format!("--repo={signed_s}"),
            "remote",
            "gpg-import",
            "origin",
            &keyring_arg,
        ],
        None,
        &[],
    )
    .ok();
    let verified = ostrya(
        &[
            "sign", "--verify", "--repo", signed_s, "-s", "gpg", "--remote", "origin", COMMIT,
        ],
        None,
        &[],
    );
    assert!(
        verified.ok().stdout_trimmed().contains("verification OK"),
        "the imported keyring must verify the commit it signed"
    );

    // In both commands, the deletion of the remote also deletes its keyring.
    for repo in [&port, &tool] {
        assert!(repo.join("origin.trustedkeys.gpg").exists());
    }
    let (port_run, tool_run) = run_remote_both(&port, &tool, &["remote", "delete", "origin"], &[]);
    assert_runs_agree(&port_run, &tool_run, "remote delete origin");
    for repo in [&port, &tool] {
        assert!(
            !repo.join("origin.trustedkeys.gpg").exists(),
            "{repo:?} kept the deleted remote's keyring"
        );
    }
}

/// In ostrya and the `ostree` command, a re-export with a later key expiry
/// reaches the trusted keyring of a remote:
///
/// - the count stays at zero
/// - the expired key verifies the commit again
/// - each command reads the keyring that the other command wrote
///
/// The key has a lifetime of one day, and it signed the commit while it was
/// valid. The keyring that the first import writes states an expiry in the
/// past, so both commands refuse the signature.
///
/// The bytes that the second import writes differ. ostrya writes the offered
/// certificate in the place of the held one. `ostree` merges the offered
/// packets into the held one. This is a recorded divergence.
#[cfg(feature = "gpg")]
#[test]
fn remote_gpg_import_carries_a_key_expiry_extension() {
    if !ostree_available() || !gpg_available() {
        return;
    }
    let tmp = TmpDir::new("remote-gpg-expiry");
    let base = tmp.path();
    let home = GpgHome::expiring(base, "Renew <renew@ostrya.example>", "1d");
    let fpr = home.fingerprint();
    let expiring = base.join("expiring.gpg");
    home.export_to(&expiring);
    let expiring_arg = format!("--keyring={}", expiring.display());

    // One repository for each command. Each holds the same commit, signed with
    // that key, and each command reads it through the remote that owns the
    // keyring.
    build_fixture_source(base);
    let src = base.join("src");
    let mut repos = Vec::new();
    for name in ["port", "tool"] {
        let dir = base.join(name);
        std::fs::create_dir_all(&dir).unwrap();
        let repo = create_repo(&dir, RepoMode::Archive);
        let repo_s = repo.to_str().unwrap().to_owned();
        ostrya(
            &[
                "commit",
                "--repo",
                &repo_s,
                "-b",
                BRANCH,
                "-s",
                SUBJECT,
                "--canonical-permissions",
                src.to_str().unwrap(),
            ],
            None,
            &[("SOURCE_DATE_EPOCH", SOURCE_DATE_EPOCH)],
        )
        .ok();
        configure_remote(&repo, "https://example.invalid/r", "");
        ostree(&[
            "gpg-sign",
            "--repo",
            &repo_s,
            "--gpg-homedir",
            home.dir.to_str().unwrap(),
            COMMIT,
            &fpr,
        ])
        .ok();
        repos.push(repo);
    }
    let (port, tool) = (repos[0].clone(), repos[1].clone());

    // The keyring with the expiry in the past. Both commands count the key and
    // then refuse the signature that it made.
    let args = ["remote", "gpg-import", "origin", &expiring_arg];
    let (port_run, tool_run) = run_remote_both(&port, &tool, &args, &[]);
    assert_runs_agree(&port_run, &tool_run, "remote gpg-import, the first import");
    let show = ["show", "--gpg-verify-remote=origin", BRANCH];
    let (port_run, tool_run) = run_remote_both(&port, &tool, &show, &[]);
    for (label, run) in [("the port", &port_run), ("the tool", &tool_run)] {
        let text = run.ok().stdout_trimmed();
        assert!(
            text.contains("BAD signature from") && !text.contains("Good signature from"),
            "{label} accepted a signature by an expired key:\n{text}"
        );
    }

    // The re-export with a lifetime of ten years. Both commands count no key,
    // and then both report a good signature.
    home.set_expire_at("20250102T000000!", "10y");
    let extended = base.join("extended.gpg");
    home.export_to(&extended);
    let extended_arg = format!("--keyring={}", extended.display());
    let args = ["remote", "gpg-import", "origin", &extended_arg];
    let (port_run, tool_run) = run_remote_both(&port, &tool, &args, &[]);
    assert_runs_agree(&port_run, &tool_run, "remote gpg-import, the extension");
    assert!(
        port_run
            .ok()
            .stdout_trimmed()
            .contains("Imported 0 GPG keys"),
        "the extension must count no key"
    );
    let (port_run, tool_run) = run_remote_both(&port, &tool, &show, &[]);
    for (label, run) in [("the port", &port_run), ("the tool", &tool_run)] {
        let text = run.ok().stdout_trimmed();
        assert!(
            text.contains("Good signature from"),
            "{label} refused a signature by a key whose expiry was extended:\n{text}"
        );
    }

    // The bytes differ. The keyring of ostrya is the offered export. The merge
    // of the `ostree` command keeps the packets of the earlier export and its
    // own Trust packets, so its file is longer.
    let name = "origin.trustedkeys.gpg";
    let port_ring = std::fs::read(port.join(name)).unwrap();
    let tool_ring = std::fs::read(tool.join(name)).unwrap();
    assert_eq!(port_ring, std::fs::read(&extended).unwrap());
    assert!(
        tool_ring.len() > port_ring.len(),
        "the tool's merged keyring must carry more than the offered export"
    );

    // Each command reads the keyring that the other command wrote and reports a
    // good signature over it.
    std::fs::write(port.join(name), &tool_ring).unwrap();
    std::fs::write(tool.join(name), &port_ring).unwrap();
    let (port_run, tool_run) = run_remote_both(&port, &tool, &show, &[]);
    for (label, run) in [("the port", &port_run), ("the tool", &tool_run)] {
        let text = run.ok().stdout_trimmed();
        assert!(
            text.contains("Good signature from"),
            "{label} refused the keyring the other implementation wrote:\n{text}"
        );
    }
}

/// A re-export with a key revocation by a designated revoker reaches the
/// trusted keyring of a remote in ostrya and in the `ostree` command. This
/// holds if the keyring under edit or the offered stream states the revoker.
/// Then each command refuses the signature of the revoked key.
///
/// Two states, measured against `ostree` 2026.1 and `gpg` 2.4.9:
///
/// - H: the keyring holds the signing key K and the revoker R, and the offered
///   stream holds the re-export of K. Both commands count no key, and then both
///   refuse the signature.
/// - J: the keyring holds only K, and the offered stream holds the re-export of
///   K and the certificate of R. Both commands count one key, R, and then both
///   refuse the signature. If the selector names only K, the commands do not
///   write R. Then both count no key and both report a good signature, because
///   no key in the keyring resolves the revoker.
///
/// The wording of the two verdict lines differs. ostrya reports
/// `BAD signature from`, and `ostree` reports `Key revoked`. The bytes also
/// differ, because each command adds the revocation in its own way. ostrya
/// writes the offered certificate in the place of the held one. `ostree` merges
/// the offered packets into the held one. Both are recorded divergences.
#[cfg(feature = "gpg")]
#[test]
fn remote_gpg_import_carries_a_designated_revokers_revocation() {
    if !ostree_available() || !gpg_available() {
        return;
    }
    let tmp = TmpDir::new("remote-gpg-desig-revoke");
    let base = tmp.path();
    let state = RevokedKey::build(base);

    // State H. The keyring the seed import writes holds K and R.
    let (port, tool) = state.repositories(base, "h");
    let (port_run, tool_run) = state.import(&port, &tool, &state.pair);
    assert_runs_agree(&port_run, &tool_run, "remote gpg-import, K and R");
    state.assert_good(&port, &tool);
    let (port_run, tool_run) = state.import(&port, &tool, &state.revoked);
    assert_runs_agree(&port_run, &tool_run, "remote gpg-import, the revocation");
    assert!(
        port_run
            .ok()
            .stdout_trimmed()
            .contains("Imported 0 GPG keys"),
        "the revocation must count no key"
    );
    state.assert_revoked(&port, &tool);

    // State J. The keyring holds K alone, and the offered stream states R.
    let (port, tool) = state.repositories(base, "j");
    let (port_run, tool_run) = state.import(&port, &tool, &state.designating);
    assert_runs_agree(&port_run, &tool_run, "remote gpg-import, K alone");
    state.assert_good(&port, &tool);
    let (port_run, tool_run) = state.import(&port, &tool, &state.revoked_pair);
    assert_runs_agree(
        &port_run,
        &tool_run,
        "remote gpg-import, the revocation and R",
    );
    assert!(
        port_run
            .ok()
            .stdout_trimmed()
            .contains("Imported 1 GPG key"),
        "the revoker must count as the one key added"
    );
    state.assert_revoked(&port, &tool);

    // The same offered stream, with a selector that names only K. The commands
    // do not write R, so the keyring states a revocation that no key in it
    // resolves.
    let (port, tool) = state.repositories(base, "j2");
    let (port_run, tool_run) = state.import(&port, &tool, &state.designating);
    assert_runs_agree(&port_run, &tool_run, "remote gpg-import, K alone");
    let keyring = format!("--keyring={}", state.revoked_pair.display());
    let args = ["remote", "gpg-import", "origin", &keyring, &state.key];
    let (port_run, tool_run) = run_remote_both(&port, &tool, &args, &[]);
    assert_runs_agree(&port_run, &tool_run, "remote gpg-import, K selected");
    assert!(
        port_run
            .ok()
            .stdout_trimmed()
            .contains("Imported 0 GPG keys"),
        "the selected key must count as one the keyring held"
    );
    for repo in [&port, &tool] {
        assert_eq!(
            state.keys_in(repo).len(),
            1,
            "{repo:?} wrote a key the selector did not name"
        );
    }
    state.assert_good(&port, &tool);
}

/// The two states in which the revocation reaches the keyring of the `ostree`
/// command and not the keyring of ostrya. The revoked key then stays valid for
/// the remote of ostrya.
///
/// The import of ostrya uses only the two byte streams that it gets. It writes
/// no revocation that it cannot verify. `ostree` merges the offered packets
/// into its keyblock, also if it cannot verify them. If a revoker then arrives
/// by another route, the merged packet takes effect.
///
/// Measured against `ostree` 2026.1 and `gpg` 2.4.9:
///
/// - I: the certificate of R is in the global trusted directory, and the
///   keyring of the remote holds only K. ostrya writes nothing, and `ostree`
///   merges the revocation. Both report a good signature, because neither
///   command resolves a revoker across the boundary between two keyring
///   sources.
/// - K: R is in no keyring when the test offers the re-export, and the test
///   imports R after that. ostrya writes nothing for the re-export, so the
///   later import of R revokes nothing. ostrya reports a good signature, and
///   `ostree` reports `Key revoked`.
///
/// Both states follow from this import rule of ostrya. Both are recorded
/// divergences.
#[cfg(feature = "gpg")]
#[test]
fn remote_gpg_import_leaves_an_unverifiable_revocation_out() {
    if !ostree_available() || !gpg_available() {
        return;
    }
    let tmp = TmpDir::new("remote-gpg-desig-unreached");
    let base = tmp.path();
    let state = RevokedKey::build(base);
    let global = base.join("global");
    std::fs::create_dir_all(&global).unwrap();
    std::fs::copy(&state.revoker, global.join("r.gpg")).unwrap();
    let env = [("OSTREE_GPG_HOME", global.to_str().unwrap())];

    // State I. The import reads only the two streams, so R in the global
    // trusted directory reaches the import of neither command.
    let (port, tool) = state.repositories(base, "i");
    let (port_run, tool_run) = state.import(&port, &tool, &state.designating);
    assert_runs_agree(&port_run, &tool_run, "remote gpg-import, K alone");
    let keyring = format!("--keyring={}", state.revoked.display());
    let args = ["remote", "gpg-import", "origin", &keyring];
    let (port_run, tool_run) = run_remote_both(&port, &tool, &args, &env);
    assert_runs_agree(&port_run, &tool_run, "remote gpg-import, the revocation");
    // The bytes differ: the keyring of ostrya is the one that it held, and the
    // keyring of the `ostree` command holds the merged revocation.
    let name = "origin.trustedkeys.gpg";
    let held = std::fs::read(&state.designating).unwrap();
    assert_eq!(std::fs::read(port.join(name)).unwrap(), held);
    assert!(std::fs::read(tool.join(name)).unwrap().len() > held.len());
    // The verdict agrees, for different reasons. The keyring of ostrya states
    // no revocation. `ostree` holds one and does not apply it.
    for (label, repo, is_port) in [("the port", &port, true), ("the tool", &tool, false)] {
        let text = state.show(repo, is_port, &env);
        assert!(
            text.contains("Good signature from"),
            "{label} resolved a revoker out of the global trusted directory:\n{text}"
        );
    }

    // Over the keyring that the import of `ostree` wrote, the two verdicts
    // differ, and ostrya is the stricter command. The verify path of ostrya
    // resolves a revoker among all certificates that it loads, from any
    // source. `ostree` resolves no revoker that is in another keyring source.
    let merged = std::fs::read(tool.join(name)).unwrap();
    std::fs::write(port.join(name), &merged).unwrap();
    let port_text = state.show(&port, true, &env);
    assert!(
        port_text.contains("BAD signature from"),
        "the port passed over a revocation its own keyring states:\n{port_text}"
    );
    let tool_text = state.show(&tool, false, &env);
    assert!(
        tool_text.contains("Good signature from"),
        "the tool resolved a revoker out of the global trusted directory:\n{tool_text}"
    );

    // State K. The test offers the re-export while R is in no keyring, and
    // imports R after that. The merged packet of the `ostree` command then
    // takes effect. ostrya wrote no such packet.
    let (port, tool) = state.repositories(base, "k");
    let (port_run, tool_run) = state.import(&port, &tool, &state.designating);
    assert_runs_agree(&port_run, &tool_run, "remote gpg-import, K alone");
    let (port_run, tool_run) = state.import(&port, &tool, &state.revoked);
    assert_runs_agree(&port_run, &tool_run, "remote gpg-import, the revocation");
    let (port_run, tool_run) = state.import(&port, &tool, &state.revoker);
    assert_runs_agree(&port_run, &tool_run, "remote gpg-import, R after the fact");
    let port_text = state.show(&port, true, &[]);
    assert!(
        port_text.contains("Good signature from"),
        "the port refused a revocation it never wrote:\n{port_text}"
    );
    let tool_text = state.show(&tool, false, &[]);
    assert!(
        tool_text.contains("Key revoked"),
        "the tool accepted a revocation it merged:\n{tool_text}"
    );
}

/// A signing key K that designates a revoker R, and the certificate streams of
/// the tests that state a revocation of K by R. Each stream is a file, because
/// an import names its stream with `--keyring`.
#[cfg(feature = "gpg")]
struct RevokedKey {
    /// The home with both secret keys. It signs each commit.
    home: GpgHome,
    /// The fingerprint of the primary key of K, in uppercase hex.
    key: String,
    /// K with the designation and no revocation.
    designating: PathBuf,
    /// The certificate of R.
    revoker: PathBuf,
    /// The two of them, in that order.
    pair: PathBuf,
    /// The re-export of K with the revocation that R made.
    revoked: PathBuf,
    /// That re-export and the certificate of R, in that order.
    revoked_pair: PathBuf,
}

#[cfg(feature = "gpg")]
impl RevokedKey {
    /// Build the keys and the streams under `base`. The home still signs with
    /// K, because the merge of the revocation runs in a separate home (see
    /// [`merged_export`]).
    fn build(base: &Path) -> RevokedKey {
        let home = GpgHome::create(base, "Signing K <k@ostrya.example>");
        home.add_key("Revoker R <r@ostrya.example>");
        let key = home.fingerprint_of("k@ostrya.example");
        let revoker_key = home.fingerprint_of("r@ostrya.example");
        home.add_revoker(&key, &revoker_key);
        let designating = base.join("k-designating.gpg");
        home.export_one_to(&key, &designating);
        let revoker = base.join("r.gpg");
        home.export_one_to(&revoker_key, &revoker);
        let pair = base.join("k-and-r.gpg");
        Self::concat(&pair, &[&designating, &revoker]);
        let revocation = base.join("rev-by-r.asc");
        home.desig_revoke(&key, &revocation);
        let revoked = base.join("k-revoked.gpg");
        merged_export(
            &base.join("merge-home"),
            &key,
            &[&designating, &revocation],
            &revoked,
        );
        let revoked_pair = base.join("k-revoked-and-r.gpg");
        Self::concat(&revoked_pair, &[&revoked, &revoker]);
        build_fixture_source(base);
        RevokedKey {
            home,
            key,
            designating,
            revoker,
            pair,
            revoked,
            revoked_pair,
        }
    }

    /// One repository for each command under `base/<tag>-<name>`. Each holds
    /// the same commit, signed with K, and the remote `origin`.
    fn repositories(&self, base: &Path, tag: &str) -> (PathBuf, PathBuf) {
        let src = base.join("src");
        let mut repos = Vec::new();
        for name in ["port", "tool"] {
            let dir = base.join(format!("{tag}-{name}"));
            std::fs::create_dir_all(&dir).unwrap();
            let repo = create_repo(&dir, RepoMode::Archive);
            let repo_s = repo.to_str().unwrap().to_owned();
            ostrya(
                &[
                    "commit",
                    "--repo",
                    &repo_s,
                    "-b",
                    BRANCH,
                    "-s",
                    SUBJECT,
                    "--canonical-permissions",
                    src.to_str().unwrap(),
                ],
                None,
                &[("SOURCE_DATE_EPOCH", SOURCE_DATE_EPOCH)],
            )
            .ok();
            configure_remote(&repo, "https://example.invalid/r", "");
            ostree(&[
                "gpg-sign",
                "--repo",
                &repo_s,
                "--gpg-homedir",
                self.home.dir.to_str().unwrap(),
                COMMIT,
                &self.key,
            ])
            .ok();
            repos.push(repo);
        }
        (repos[0].clone(), repos[1].clone())
    }

    /// One `remote gpg-import` of the stream at `keyring` in both commands.
    fn import(&self, port: &Path, tool: &Path, keyring: &Path) -> (Run, Run) {
        let arg = format!("--keyring={}", keyring.display());
        run_remote_both(port, tool, &["remote", "gpg-import", "origin", &arg], &[])
    }

    /// What `show --gpg-verify-remote=origin` reports over `repo`. If `port` is
    /// set, ostrya reads it. If not, the `ostree` command reads it.
    fn show(&self, repo: &Path, port: bool, env: &[(&str, &str)]) -> String {
        let args = ["show", "--gpg-verify-remote=origin", BRANCH];
        let mut all = vec![format!("--repo={}", repo.display())];
        all.extend(args.iter().map(|arg| (*arg).to_owned()));
        let all: Vec<&str> = all.iter().map(String::as_str).collect();
        let run = if port {
            ostrya(&all, None, env)
        } else {
            ostree_env(&all, env)
        };
        run.ok().stdout_trimmed()
    }

    /// Assert that each command reports a good signature.
    fn assert_good(&self, port: &Path, tool: &Path) {
        for (label, repo, is_port) in [("the port", port, true), ("the tool", tool, false)] {
            let text = self.show(repo, is_port, &[]);
            assert!(
                text.contains("Good signature from"),
                "{label} refused a signature by a live key:\n{text}"
            );
        }
    }

    /// Assert that each command refuses the signature, each with its own words.
    fn assert_revoked(&self, port: &Path, tool: &Path) {
        let text = self.show(port, true, &[]);
        assert!(
            text.contains("BAD signature from") && !text.contains("Good signature"),
            "the port accepted a signature by a revoked key:\n{text}"
        );
        let text = self.show(tool, false, &[]);
        assert!(
            text.contains("Key revoked") && !text.contains("Good signature"),
            "the tool accepted a signature by a revoked key:\n{text}"
        );
    }

    /// The primary-key fingerprints in the trusted keyring of the remote, as
    /// `gpg` reports them.
    fn keys_in(&self, repo: &Path) -> Vec<String> {
        let out = self
            .home
            .gpg()
            .arg("--no-default-keyring")
            .arg("--keyring")
            .arg(repo.join("origin.trustedkeys.gpg"))
            .args(["--with-colons", "--list-keys"])
            .output()
            .unwrap();
        assert!(
            out.status.success(),
            "gpg --list-keys over a keyring failed"
        );
        String::from_utf8_lossy(&out.stdout)
            .lines()
            .filter_map(|line| line.strip_prefix("fpr:"))
            .filter_map(|rest| rest.split(':').nth(8).map(str::to_owned))
            .collect()
    }

    /// Write the concatenation of `parts` to `path`.
    fn concat(path: &Path, parts: &[&Path]) {
        let mut bytes = Vec::new();
        for part in parts {
            bytes.extend_from_slice(&std::fs::read(part).unwrap());
        }
        std::fs::write(path, bytes).unwrap();
    }
}

/// A repository with two GPG signatures that do not verify. The signing key is
/// in the trusted keyring of the remote `origin`.
///
/// The commit on `bad/one` is signed. The commits on `bad/two` and `bad/three`
/// each hold a copy of the detached metadata of that commit. Each of these two
/// stored signatures belongs to a different payload, so the cryptography
/// refuses it. The issuer stays resolvable, so the report names the signing
/// key.
///
/// The return value is the repository and the checksums of the commits on
/// `bad/two` and `bad/three`, with one refused signature each.
#[cfg(feature = "gpg")]
fn bad_signature_repo(base: &Path, home: &GpgHome, keyring: &Path) -> (PathBuf, String, String) {
    build_fixture_source(base);
    let src = base.join("src");
    let repo = create_repo(base, RepoMode::Archive);
    let repo_s = repo.to_str().unwrap().to_owned();
    let mut checksums: Vec<String> = Vec::new();
    for (branch, subject) in [
        ("bad/one", "signed commit"),
        ("bad/two", "other commit"),
        ("bad/three", "third commit"),
    ] {
        let run = ostrya(
            &[
                "commit",
                "--repo",
                &repo_s,
                "-b",
                branch,
                "-s",
                subject,
                "--canonical-permissions",
                src.to_str().unwrap(),
            ],
            None,
            &[("SOURCE_DATE_EPOCH", SOURCE_DATE_EPOCH)],
        );
        checksums.push(run.ok().stdout_trimmed());
    }
    ostrya(
        &[
            "sign",
            "--repo",
            &repo_s,
            "-s",
            "gpg",
            "--gpg-homedir",
            home.dir.to_str().unwrap(),
            &checksums[0],
            &home.fingerprint(),
        ],
        None,
        &[],
    )
    .ok();
    let meta = |checksum: &str| {
        repo.join(format!(
            "objects/{}/{}.commitmeta",
            &checksum[..2],
            &checksum[2..]
        ))
    };
    std::fs::copy(meta(&checksums[0]), meta(&checksums[1])).unwrap();
    std::fs::copy(meta(&checksums[0]), meta(&checksums[2])).unwrap();
    configure_remote(&repo, "https://example.invalid/r", "");
    ostrya(
        &[
            &format!("--repo={repo_s}"),
            "remote",
            "gpg-import",
            "origin",
            &format!("--keyring={}", keyring.display()),
        ],
        None,
        &[],
    )
    .ok();
    let third = checksums.remove(2);
    (repo, checksums.remove(1), third)
}

/// The one `Signature made` line of a signature report, with the leading
/// indent removed.
#[cfg(feature = "gpg")]
fn signature_made_line(report: &str) -> &str {
    report
        .lines()
        .map(str::trim)
        .find(|line| line.starts_with("Signature made"))
        .unwrap_or_else(|| panic!("no `Signature made` line in the report:\n{report}"))
}

/// The `key ID` field of that line.
#[cfg(feature = "gpg")]
fn reported_key_id(report: &str) -> &str {
    let line = signature_made_line(report);
    line.split(" key ID")
        .nth(1)
        .map(str::trim)
        .unwrap_or_else(|| panic!("no `key ID` field in `{line}`"))
}

/// For a signature that does not verify, the signature report line of `show`
/// names the same key in ostrya and in the `ostree` command. Both commands
/// refuse the signature with the same words.
///
/// A signing subkey made the signature, so the report names two keys. The
/// report line names the subkey. The `Primary key ID` line of `ostree` names
/// the primary key that binds the subkey.
///
/// Three differences are recorded divergences:
///
/// - The instant: `ostree` holds no instant for a signature that the
///   cryptography refused, so it prints the Unix epoch. ostrya prints an empty
///   instant.
/// - The algorithm: `ostree` holds no algorithm for such a signature, so it
///   prints `[unknown name]`. ostrya prints `unknown`.
/// - The `Primary key ID` line: ostrya prints this line nowhere. The key that
///   the line names is in the record of ostrya, where `sign --delete` reads it
///   (`sign_delete_reaches_a_signature_that_does_not_verify`).
///
/// The host time zone and locale decide how `ostree` shows the instant, so the
/// test checks only the year of the epoch. `TZ=UTC` keeps the run inside 1970.
#[cfg(feature = "gpg")]
#[test]
fn show_reports_a_bad_signature_like_the_tool() {
    if !ostree_available() || !gpg_available() {
        return;
    }
    let tmp = TmpDir::new("show-bad-sig");
    let base = tmp.path();
    let home = GpgHome::create(base, "Badsig <badsig@ostrya.example>");
    let subkey = home.add_signing_subkey();
    let keyring = base.join("public.gpg");
    home.export_to(&keyring);
    let (repo, checksum, _) = bad_signature_repo(base, &home, &keyring);
    let repo_arg = format!("--repo={}", repo.display());
    let args = [
        repo_arg.as_str(),
        "show",
        "--gpg-verify-remote=origin",
        &checksum,
    ];
    let port = ostrya(&args, None, &[]).ok().stdout_trimmed();
    let tool = ostree_env(&args, &[("TZ", "UTC")]).ok().stdout_trimmed();

    // Both commands refuse the signature with the same words.
    let verdict = "BAD signature from \"Badsig <badsig@ostrya.example>\"";
    for (label, report) in [("the port", &port), ("the tool", &tool)] {
        assert!(
            report.contains(verdict),
            "{label} drew no `{verdict}` line:\n{report}"
        );
    }

    // Both commands name the signing subkey on the line before the verdict.
    let key_id = &subkey[subkey.len() - 16..];
    assert_eq!(reported_key_id(&port), key_id, "the port's key ID");
    assert_eq!(reported_key_id(&tool), key_id, "the tool's key ID");

    // The recorded divergences, asserted so that the test reports a change in
    // either command. The test reads the instant and the algorithm from the
    // report line, so no other line of the report can satisfy these
    // assertions.
    assert_eq!(
        signature_made_line(&port),
        format!("Signature made  using unknown key ID {key_id}"),
        "the port now states an instant or an algorithm here"
    );
    let tool_line = signature_made_line(&tool);
    assert!(
        tool_line.contains("1970") && tool_line.contains("[unknown name]"),
        "the tool now states an instant or an algorithm here: `{tool_line}`"
    );
    let primary = home.fingerprint();
    assert!(
        tool.contains(&format!(
            "Primary key ID {}",
            &primary[primary.len() - 16..]
        )),
        "the tool drew no `Primary key ID` line:\n{tool}"
    );
    assert!(
        !port.contains("Primary key ID"),
        "the port now draws a `Primary key ID` line:\n{port}"
    );
}

/// `sign --delete KEY-ID` removes a signature if the trusted set holds its
/// issuer and its cryptography fails. The KEY-ID can be the key id of the
/// signing key or the key id of the certificate that holds that key. A signing
/// subkey made the signature here, so these two key ids differ.
///
/// The record of such a signature names both keys, and the delete matches a
/// KEY-ID against either field. Over the same commit,
/// `ostree gpg-sign --delete` removes the signature by either key id and by
/// either whole fingerprint. This is measured against `ostree` 2026.1.
#[cfg(feature = "gpg")]
#[test]
fn sign_delete_reaches_a_signature_that_does_not_verify() {
    if !gpg_available() {
        eprintln!("skipping: gpg not available");
        return;
    }
    let tmp = TmpDir::new("sign-delete-bad-sig");
    let base = tmp.path();
    let home = GpgHome::create(base, "Doomed <doomed@ostrya.example>");
    let subkey = home.add_signing_subkey();
    let keyring = base.join("public.gpg");
    home.export_to(&keyring);
    let (repo, by_subkey, by_primary) = bad_signature_repo(base, &home, &keyring);
    let repo_arg = format!("--repo={}", repo.display());
    let primary = home.fingerprint();
    let signing_key_id = subkey[subkey.len() - 16..].to_owned();
    let primary_key_id = primary[primary.len() - 16..].to_owned();
    let report = |checksum: &str| {
        ostrya(
            &[
                repo_arg.as_str(),
                "show",
                "--gpg-verify-remote=origin",
                checksum,
            ],
            None,
            &[],
        )
        .ok()
        .stdout_trimmed()
    };

    // One commit for each KEY-ID, so each delete runs over a separate
    // signature.
    for (checksum, key_id, named) in [
        (&by_subkey, &signing_key_id, "the signing subkey"),
        (&by_primary, &primary_key_id, "the primary key"),
    ] {
        // The commit holds one signature, the trusted set resolves its issuer,
        // and the cryptography refuses it.
        let before = report(checksum);
        assert!(
            before.contains("Found 1 signature:") && before.contains("BAD signature from"),
            "the fixture holds no refused signature:\n{before}"
        );
        assert_eq!(reported_key_id(&before), signing_key_id);

        let deleted = ostrya(
            &[
                repo_arg.as_str(),
                "sign",
                "-d",
                "-s",
                "gpg",
                "--remote",
                "origin",
                checksum,
                key_id,
            ],
            None,
            &[],
        );
        assert!(
            deleted.ok().stdout_trimmed().contains("Deleted 1"),
            "the KEY-ID of {named} reached no signature"
        );

        // Nothing is left to report over the commit.
        let after = report(checksum);
        assert!(
            !after.contains("signature"),
            "the commit kept a signature:\n{after}"
        );
    }
}

/// `show --print-variant-type` reads a file as a value of a named type. This
/// makes the `ostree` command a byte-exact oracle for the GVariant text form.
/// Each case is a hand-written serialized value for one rule of the form.
#[test]
fn variant_text_matches_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("variant-text");
    let base = tmp.path();
    let repo = create_repo(base, RepoMode::Archive);
    let cases: &[(&str, &str, &[u8])] = &[
        // Byte arrays: the bytestring form, its escapes, and the list form.
        ("nul", "ay", &[0x00]),
        ("bytestring", "ay", b"b\0"),
        ("unterminated", "ay", &[0x62]),
        ("interior_nul", "ay", &[0x62, 0x00, 0x63, 0x00]),
        ("hi", "ay", b"hi\0"),
        ("high_byte", "ay", &[0xff, 0x00]),
        ("tab", "ay", b"a\tb\0"),
        ("single_quote", "ay", b"a'b\0"),
        ("double_quote", "ay", b"a\"b\0"),
        ("both_quotes", "ay", b"a'\"b\0"),
        ("utf8", "ay", "hé\0".as_bytes()),
        ("del", "ay", &[0x7f, 0x00]),
        ("escape", "ay", &[0x1b, 0x00]),
        ("empty", "ay", b""),
        ("bytes", "ay", &[0x01, 0x02, 0xff]),
        // Strings and their escapes.
        ("s_plain", "s", b"abc\0"),
        ("s_empty", "s", b"\0"),
        ("s_squote", "s", b"a'b\0"),
        ("s_dquote", "s", b"a\"b\0"),
        ("s_both", "s", b"a'\"b\0"),
        ("s_tab", "s", b"a\tb\0"),
        ("s_newline", "s", b"a\nb\0"),
        ("s_return", "s", b"a\rb\0"),
        ("s_bell", "s", b"a\x07b\0"),
        ("s_backspace", "s", b"a\x08b\0"),
        ("s_vtab", "s", b"a\x0bb\0"),
        ("s_formfeed", "s", b"a\x0cb\0"),
        ("s_escape", "s", b"a\x1bb\0"),
        ("s_del", "s", b"a\x7fb\0"),
        ("s_backslash", "s", b"a\\b\0"),
        ("s_utf8", "s", "héllo\0".as_bytes()),
        // Scalars, which the numeric conversion reaches.
        ("u32", "u", &[0x01, 0x02, 0x03, 0x04]),
        ("u64", "t", &[1, 2, 3, 4, 5, 6, 7, 8]),
        ("bool_false", "b", &[0x00]),
        ("bool_true", "b", &[0x01]),
        ("byte", "y", &[0x2a]),
        // Containers: the position of the type annotation, and the empty forms.
        ("as", "as", b"a\0bb\0\x02\x05"),
        (
            "aay_first_bytestring",
            "aay",
            &[0x62, 0x00, 0x63, 0x02, 0x03],
        ),
        (
            "aay_second_bytestring",
            "aay",
            &[0x63, 0x62, 0x00, 0x01, 0x03],
        ),
        ("aay_first_empty", "aay", &[0x63, 0x00, 0x01]),
        ("aay_second_empty", "aay", &[0x63, 0x01, 0x01]),
        ("aay_empty", "aay", b""),
        (
            "dict",
            "a{sy}",
            &[0x61, 0x00, 0x01, 0x02, 0x62, 0x00, 0x02, 0x02, 0x04, 0x08],
        ),
        ("dict_empty", "a{sy}", b""),
        ("dict_entry", "{sy}", &[0x61, 0x00, 0x01, 0x02]),
        ("tuple_one", "(y)", &[0x01]),
        ("tuple_empty", "()", &[0x00]),
        ("tuple_two", "(yy)", &[0x01, 0x02]),
        ("tuple_strings", "(ss)", b"a\0b\0\x02"),
        ("variant_byte", "v", &[0x2a, 0x00, 0x79]),
        ("variant_bytestring", "v", &[0x62, 0x00, 0x00, 0x61, 0x79]),
        ("aab", "aab", &[0x01, 0x00, 0x01, 0x02]),
    ];
    for (name, signature, bytes) in cases {
        let path = base.join(name);
        std::fs::write(&path, bytes).unwrap();
        let arg = format!("--print-variant-type={signature}");
        assert_agrees(&repo, &repo, &["show", &arg, path.to_str().unwrap()]);
    }
    // ostrya refuses a path that does not open with the words of the `ostree`
    // command.
    let missing = base.join("nosuchfile");
    assert_agrees(
        &repo,
        &repo,
        &["show", "--print-variant-type=u", missing.to_str().unwrap()],
    );
}

/// ostrya refuses a signature that names no type. The `ostree` command ends on
/// a signal for this shape: `SIGSEGV` for `(s`, `zz`, and `m`, and `SIGABRT`
/// for `r`, `*`, and `?`. Measured against `ostree` 2026.1. This is a recorded
/// divergence.
#[test]
fn show_refuses_a_variant_type_that_is_not_a_type() {
    let tmp = TmpDir::new("variant-type-refused");
    let base = tmp.path();
    let repo = create_repo(base, RepoMode::Archive);
    let path = base.join("value");
    std::fs::write(&path, [0x01, 0x02]).unwrap();
    for signature in ["(s", "zz", "r", "*", "?", "m"] {
        let run = ostrya(
            &[
                &format!("--repo={}", repo.display()),
                "show",
                &format!("--print-variant-type={signature}"),
                path.to_str().unwrap(),
            ],
            None,
            &[],
        );
        assert_eq!(
            run.status.code(),
            Some(1),
            "the port accepted the type {signature:?}"
        );
        assert!(
            String::from_utf8_lossy(&run.stderr).contains("invalid type signature"),
            "the refusal of {signature:?} does not name the signature"
        );
        assert!(run.stdout.is_empty(), "{signature:?} wrote to stdout");
    }
}

// --- `commit` message, metadata, and ref bindings ----------------------------
//
// Each test builds one repository for each command, runs the same invocation
// against both, and compares the exit status and both streams. `commit` prints
// the checksum of the commit that it made. If the standard output agrees, the
// checksum of the commit object agrees. The subject, the body, the metadata
// dict, and its entry order all go into that checksum.

/// A repository pair in `mode` and the materialized corpus, for the tests of
/// the `commit` option families.
fn commit_pair(base: &Path, mode: RepoMode) -> (PathBuf, PathBuf, PathBuf) {
    let tree = base.join("tree");
    ostrya_conformance::corpus::materialize("C0", &tree).unwrap();
    let (port_repo, tool_repo) = create_repo_pair(base, mode);
    (port_repo, tool_repo, tree)
}

/// The fixed timestamp of the commits in the `commit` tests. With it, both
/// commands make a commit with the same checksum.
const FIXED_TIMESTAMP: &str = "--timestamp=@1700000000";

/// `commit -m/--body` and `-F/--body-file` set the body field of the commit.
/// `-F` wins over `-m` in either order. If neither command can read a body
/// file, both refuse it with the same words.
#[test]
fn commit_body_forms_match_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("commit-body");
    let base = tmp.path();
    let (port_repo, tool_repo, tree) = commit_pair(base, RepoMode::Archive);
    let src = tree.to_str().unwrap();

    let write = |name: &str, bytes: &[u8]| {
        let path = base.join(name);
        std::fs::write(&path, bytes).unwrap();
        path
    };
    let body_file = write("body.txt", b"from file line1\nline2\n");
    let empty = write("empty.txt", b"");
    let trailing = write("trail.txt", b"trailing\n\n\n");
    let no_newline = write("nonl.txt", b"no newline at end");
    let spaces = write("ws.txt", b"  leading and trailing  \n");
    let bad_utf8 = write("bad.txt", b"bad\xff\xfebytes\n");
    let with_nul = write("nul.txt", b"a\0b\n");
    let absent = base.join("nope.txt");

    let mut cell = 0;
    let mut agrees = |extra: &[&str]| {
        cell += 1;
        let branch = format!("body{cell}");
        let mut args = vec!["commit", "-b", &branch, FIXED_TIMESTAMP];
        args.extend_from_slice(extra);
        args.push(src);
        assert_agrees(&port_repo, &tool_repo, &args);
    };

    // The commit stores the body as given, with no trimming and no newline
    // normalization. A body with no subject is accepted.
    agrees(&["-m", "body text"]);
    agrees(&["-s", "subj", "-m", "body text"]);
    agrees(&["-s", "s", "-m", "line1\nline2"]);
    // If the option is given more than once, the last value wins.
    agrees(&["-m", "one", "-m", "two"]);
    // The commit takes a body file byte for byte, with its trailing newlines
    // and its surrounding spaces. An empty file gives an empty body.
    for path in [&body_file, &empty, &trailing, &no_newline, &spaces] {
        agrees(&["-F", path.to_str().unwrap()]);
    }
    // `-F` wins over `-m`, whichever comes first.
    agrees(&["-m", "inline", "-F", body_file.to_str().unwrap()]);
    agrees(&["-F", body_file.to_str().unwrap(), "-m", "inline"]);
    // The refusals: a path that does not open, a directory, and content that is
    // not UTF-8 or holds a NUL.
    agrees(&["-F", absent.to_str().unwrap()]);
    agrees(&["-F", "-"]);
    agrees(&["-F", src]);
    // Both commands give the two content refusals as `error: Invalid UTF-8` at
    // exit 1, as the record states. The test asserts these words and this
    // status, so an agreement of both commands on another answer fails.
    for (branch, path) in [("bodybad", &bad_utf8), ("bodynul", &with_nul)] {
        let args = [
            "commit",
            "-b",
            branch,
            FIXED_TIMESTAMP,
            "-F",
            path.to_str().unwrap(),
            src,
        ];
        let (port, tool) = run_both(&port_repo, &tool_repo, &args);
        let label = args.join(" ");
        assert_runs_agree(&port, &tool, &label);
        assert_runs_agree_on_error(&port, &tool, &label, "error: Invalid UTF-8");
    }
}

/// Write an executable shell script and return its path.
fn write_script(path: &Path, body: &str) -> PathBuf {
    std::fs::write(path, body).unwrap();
    std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o755)).unwrap();
    path.to_owned()
}

/// `commit -e/--editor` writes the template of the `ostree` command into a
/// temporary file. It runs the editor that the environment names as a shell
/// command line. Then it reads the subject and the body from the file that the
/// editor left.
#[test]
fn commit_editor_matches_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("commit-editor");
    let base = tmp.path();
    let (port_repo, tool_repo, tree) = commit_pair(base, RepoMode::Archive);
    let src = tree.to_str().unwrap();

    // An editor that copies its template to `$DUMP`, so that the test can
    // compare the two templates byte for byte.
    let dump = write_script(&base.join("dump.sh"), "#!/bin/sh\ncp \"$1\" \"$DUMP\"\n");
    // An editor that replaces the template, one that leaves it alone, one that
    // writes a message and then fails, and one that fails at once.
    let writer = write_script(
        &base.join("write.sh"),
        "#!/bin/sh\nprintf 'EdSubject\\nEdBody\\n' > \"$1\"\n",
    );
    let untouched = write_script(&base.join("noop.sh"), "#!/bin/sh\nexit 0\n");
    let failing = write_script(&base.join("fail.sh"), "#!/bin/sh\nexit 3\n");
    let write_then_fail = write_script(
        &base.join("writefail.sh"),
        "#!/bin/sh\nprintf 'GoodSubject\\nGoodBody\\n' > \"$1\"\nexit 3\n",
    );
    // An editor that writes the text of `$EDCONTENT`, for the parse rules.
    let content = write_script(
        &base.join("content.sh"),
        "#!/bin/sh\nprintf '%b' \"$EDCONTENT\" > \"$1\"\n",
    );
    // An editor that writes a byte that is not UTF-8, one that writes a NUL,
    // and one that removes the file it was given.
    let invalid_utf8 = write_script(
        &base.join("badutf8.sh"),
        "#!/bin/sh\nprintf 'Sub\\377ject\\nbody\\n' > \"$1\"\n",
    );
    let nul_byte = write_script(
        &base.join("nulbyte.sh"),
        "#!/bin/sh\nprintf 'Sub\\000ject\\nbody\\n' > \"$1\"\n",
    );
    let removes = write_script(&base.join("remove.sh"), "#!/bin/sh\nrm -f \"$1\"\n");

    // The template bytes. Each command dumps its own copy, and the test
    // compares the two copies directly. The cases are the branch block, no
    // branch block under `--orphan`, and a `-s` value after the block.
    let template = |label: &str, extra: &[&str]| {
        let mut written = Vec::new();
        for (name, repo) in [("port", &port_repo), ("tool", &tool_repo)] {
            let target = base.join(format!("template-{label}-{name}"));
            let mut args = vec![
                "commit".to_owned(),
                format!("--repo={}", repo.display()),
                FIXED_TIMESTAMP.to_owned(),
                "-e".to_owned(),
            ];
            args.extend(extra.iter().map(|arg| (*arg).to_owned()));
            args.push(src.to_owned());
            let borrowed: Vec<&str> = args.iter().map(String::as_str).collect();
            // The two variables that come before `EDITOR` must be absent. An
            // empty variable is set, so the command chooses it.
            let env: Vec<(&str, &str)> = vec![
                ("EDITOR", dump.to_str().unwrap()),
                ("DUMP", target.to_str().unwrap()),
            ];
            if name == "port" {
                ostrya_no_editor(&borrowed, &env);
            } else {
                ostree_no_editor(&borrowed, &env);
            }
            written.push(std::fs::read(&target).unwrap_or_default());
        }
        assert_eq!(
            String::from_utf8_lossy(&written[0]),
            String::from_utf8_lossy(&written[1]),
            "the {label} template differs",
        );
        assert!(!written[0].is_empty(), "the {label} template is empty");
    };
    template("branch", &["-b", "BR"]);
    template("orphan", &["--orphan"]);
    template(
        "prefill",
        &["-b", "BR", "-s", "Pre subject", "-m", "Pre body"],
    );
    template("multiline", &["-b", "BR", "-s", "S1\nS2"]);

    // The result of the editor, and the fault that it reports. Each case runs
    // the same invocation in both commands with the same environment.
    let mut cell = 0;
    let mut agrees = |editor: &Path, edcontent: &str, extra: &[&str]| {
        cell += 1;
        let branch = format!("ed{cell}");
        let mut args = vec!["commit", "-b", &branch, FIXED_TIMESTAMP, "-e"];
        args.extend_from_slice(extra);
        args.push(src);
        let env = [
            ("EDITOR", editor.to_str().unwrap()),
            ("EDCONTENT", edcontent),
        ];
        let (port, tool) = run_both_no_editor(&port_repo, &tool_repo, &args, &env);
        // Each command gives the temporary file its own name, so the test masks
        // the name in a message before the comparison.
        assert_runs_agree(&mask_temp(&port), &mask_temp(&tool), &args.join(" "));
    };
    agrees(&writer, "", &[]);
    agrees(&untouched, "", &[]);
    agrees(&untouched, "", &["-s", "PreSubject", "-m", "PreBody"]);
    agrees(&writer, "", &["-s", "CliSubject"]);
    agrees(&writer, "", &["-m", "CliBody"]);
    agrees(&writer, "", &["-s", "CliS", "-m", "CliB"]);
    // `-e` replaces the whole body, so the command never reads `-F`. A body
    // file that does not open does not stop the commit.
    agrees(
        &writer,
        "",
        &["-F", base.join("nope.txt").to_str().unwrap()],
    );
    // A non-zero exit of the editor aborts the commit, and the command discards
    // what the editor wrote.
    agrees(&failing, "", &[]);
    agrees(&write_then_fail, "", &[]);
    agrees(Path::new("/nonexistent/editor"), "", &[]);
    // The command reads the file that the editor left with the rules of
    // `-F/--body-file`. A byte that is not UTF-8 and a NUL both report
    // `Invalid UTF-8`. A file that the editor removed reports
    // `openat(<path>): <reason>`.
    agrees(&invalid_utf8, "", &[]);
    agrees(&nul_byte, "", &[]);
    agrees(&removes, "", &[]);

    // The parse rules over the edited text, one case for each text.
    for text in [
        "Subject line\\n",
        "Subject line\\n\\nBody line 1\\nBody line 2\\n",
        "Subject\\nimmediate body\\n",
        "Subject\\n# a comment\\nbody\\n",
        "\\n\\nSubject after blanks\\nbody\\n",
        "Subject with trailing   \\n\\n\\nbody\\n\\n\\n",
        "Subject\\n\\n\\n\\nbody\\n",
        "   Subject indented\\nbody\\n",
        "Subject\\n\\npara1 line1\\npara1 line2\\n\\npara2\\n",
        "Subject\\nbody\\n   \\n",
        "Subject\\nbody with # hash inside\\n",
        "  # indented comment\\nSubject\\n",
        "Subject\\n\\tTabbed body\\n",
        "Subject only no newline",
        "Subject\\r\\nCRLF body\\r\\n",
        "Sub\\n\\n\\n",
        "#comment\\n\\nSubject\\n\\nbody\\n#trailing comment\\n",
        "Subject\\nline1   \\nline2\\n",
        "Subject\\nline1\\n   \\nline2\\n",
        "Subject\\n\\n   \\n\\nline2\\n",
        // An empty subject aborts.
        "# only comments\\n#\\n",
        "   \\n",
        "",
    ] {
        agrees(&content, text, &[]);
    }

    // The command creates the temporary file with read and write permission
    // for its owner only.
    let stat = "stat -c %a";
    let (port, tool) = run_both_no_editor(
        &port_repo,
        &tool_repo,
        &["commit", "-b", "edmode", FIXED_TIMESTAMP, "-e", src],
        &[("EDITOR", stat), ("EDCONTENT", "")],
    );
    assert_eq!(
        String::from_utf8_lossy(&port.stdout).lines().next(),
        Some("600"),
        "the port's editor file mode"
    );
    assert_eq!(
        String::from_utf8_lossy(&tool.stdout).lines().next(),
        Some("600"),
        "the tool's editor file mode"
    );

    // The position of the editor in the fault order. A marker file that the
    // editor writes shows if the editor ran. The command reads the metadata
    // options before the editor, and the tree and the timestamp after it.
    let marker = write_script(
        &base.join("marker.sh"),
        "#!/bin/sh\ntouch \"$MARK\"\nprintf 'S\\nB\\n' > \"$1\"\n",
    );
    let mut order = 0;
    let mut order_agrees = |extra: &[&str], path: &str, ran: bool| {
        order += 1;
        let branch = format!("edorder{order}");
        let mut args = vec!["commit", "-b", &branch, "-e"];
        args.extend_from_slice(extra);
        args.push(path);
        for (name, repo) in [("port", &port_repo), ("tool", &tool_repo)] {
            let mark = base.join(format!("mark-{order}-{name}"));
            let _ = std::fs::remove_file(&mark);
            let env = [
                ("EDITOR", marker.to_str().unwrap()),
                ("MARK", mark.to_str().unwrap()),
            ];
            let mut all = vec!["commit".to_owned(), "--repo".to_owned()];
            all.push(repo.display().to_string());
            all.extend(args[1..].iter().map(|arg| (*arg).to_owned()));
            let all: Vec<&str> = all.iter().map(String::as_str).collect();
            let run = if name == "port" {
                ostrya_no_editor(&all, &env)
            } else {
                ostree_no_editor(&all, &env)
            };
            assert!(!run.status.success(), "{name} accepted {args:?}");
            assert_eq!(mark.exists(), ran, "{name} editor ran for {args:?}");
        }
    };
    // A metadata value that the reader refuses comes before the editor.
    order_agrees(&["--add-metadata=k=[]", FIXED_TIMESTAMP], src, false);
    order_agrees(
        &["--add-metadata-string=noequals", FIXED_TIMESTAMP],
        src,
        false,
    );
    // A timestamp that the reader refuses and a tree that does not open come
    // after it. Each command uses its own words for the tree refusal, so the
    // test compares only the order. This is a recorded divergence.
    order_agrees(&["--timestamp=notatime"], src, true);
    order_agrees(
        &[FIXED_TIMESTAMP],
        base.join("nosuchtree").to_str().unwrap(),
        true,
    );
}

/// ostrya reads the `-e/--editor` file to at most 128 mebibytes, the same
/// bound as for `-F/--body-file`. A file of exactly that size commits, and the
/// `ostree` command makes the same commit. One byte more reports
/// `Commit message larger than 134217728 bytes` at exit 1 and writes no ref.
/// This bound belongs to ostrya. For a larger file, `ostree` writes the commit.
/// This is a recorded divergence, and the test does not run `ostree` on it.
///
/// The test is ignored by default, because it writes a 128 mebibyte file and
/// copies it once for each case. To run it, use
/// `cargo test -p ostrya-cli --test cli -- --ignored`.
#[test]
#[ignore = "writes a 128 MiB editor file; run with --ignored"]
fn commit_editor_file_is_capped() {
    use std::io::Write as _;

    const LIMIT: usize = 128 * 1024 * 1024;

    let tmp = TmpDir::new("editor-cap");
    let base = tmp.path();
    let (port_repo, tool_repo, tree) = commit_pair(base, RepoMode::Archive);
    let src = tree.to_str().unwrap();

    // The source file of the editor, one byte more than the limit: a subject
    // line and a comment line with the bulk of the bytes. The parsed message
    // stays small at both sizes, so the commit writes little data.
    let big = base.join("big");
    let mut out = std::io::BufWriter::new(std::fs::File::create(&big).unwrap());
    out.write_all(b"S\n#").unwrap();
    let chunk = vec![b'a'; 1024 * 1024];
    let mut left = LIMIT - 3;
    while left > 0 {
        let take = left.min(chunk.len());
        out.write_all(&chunk[..take]).unwrap();
        left -= take;
    }
    out.write_all(b"\n").unwrap();
    drop(out);
    assert_eq!(
        std::fs::metadata(&big).unwrap().len(),
        LIMIT as u64 + 1,
        "the source file is the wrong size"
    );

    // The editor writes the first `$SIZE` bytes of that file, so one source
    // file serves both sizes.
    let editor = write_script(
        &base.join("copy.sh"),
        "#!/bin/sh\nhead -c \"$SIZE\" \"$BIG\" > \"$1\"\n",
    );
    let invoke = |program: &str, repo: &Path, size: usize, branch: &str| -> Run {
        let repo_arg = format!("--repo={}", repo.display());
        let size = size.to_string();
        let args = [
            "commit",
            &repo_arg,
            "-b",
            branch,
            FIXED_TIMESTAMP,
            "-e",
            src,
        ];
        let env = [
            ("EDITOR", editor.to_str().unwrap()),
            ("BIG", big.to_str().unwrap()),
            ("SIZE", size.as_str()),
        ];
        run_cleared(program, &args, &env)
    };

    // A file of exactly the limit is accepted. If the `ostree` command is
    // installed, both commands make the same commit.
    let port = invoke(env!("CARGO_BIN_EXE_ostrya"), &port_repo, LIMIT, "atlimit");
    assert!(
        port.status.success(),
        "the port refused a {LIMIT}-byte editor file: {}",
        String::from_utf8_lossy(&port.stderr)
    );
    let checksum = port.stdout_trimmed();
    assert_eq!(checksum.len(), 64, "the port printed `{checksum}`");
    if ostree_available() {
        let tool = invoke("ostree", &tool_repo, LIMIT, "atlimit");
        assert!(
            tool.status.success(),
            "the tool refused a {LIMIT}-byte editor file: {}",
            String::from_utf8_lossy(&tool.stderr)
        );
        assert_eq!(
            checksum,
            tool.stdout_trimmed(),
            "the commit checksums differ at the limit"
        );
    }

    // ostrya refuses one byte more and writes nothing.
    let port = invoke(
        env!("CARGO_BIN_EXE_ostrya"),
        &port_repo,
        LIMIT + 1,
        "overlimit",
    );
    assert_eq!(port.status.code(), Some(1), "the port accepted the file");
    assert_eq!(
        String::from_utf8_lossy(&port.stderr).trim_end(),
        format!("error: Commit message larger than {LIMIT} bytes"),
        "the refusal is worded differently"
    );
    assert!(port.stdout.is_empty(), "the refusal printed a checksum");
    let listed = ostrya(&["refs", "--repo", port_repo.to_str().unwrap()], None, &[])
        .ok()
        .stdout_trimmed();
    assert!(
        !listed.lines().any(|line| line == "overlimit"),
        "the refused commit left a ref: {listed}"
    );
}

/// `commit -e` holds no repository lock while the user writes the message. The
/// transaction opens when the editor returns, so an exclusive operation on the
/// same repository can run during the editing session.
///
/// The repository states `lock-timeout-secs=1`. If an acquisition waits for
/// the editing session, it fails within one second, and the test reports the
/// failure. The test does not wait for the default timeout of five minutes.
#[test]
fn commit_editor_holds_no_repository_lock() {
    use std::time::{Duration, Instant};

    let tmp = TmpDir::new("editor-lock");
    let base = tmp.path();
    let tree = base.join("tree");
    ostrya_conformance::corpus::materialize("C0", &tree).unwrap();
    let repo = create_repo(base, RepoMode::Archive);
    let mut config = config_text(&repo);
    config.push_str("lock-timeout-secs=1\n");
    std::fs::write(repo.join("config"), config).unwrap();

    // The editor marks its start and waits 4 seconds, so that the acquisition
    // of this test runs inside the session. Then it writes the message.
    let started_marker = base.join("editing");
    let editor = write_script(
        &base.join("slow.sh"),
        "#!/bin/sh\ntouch \"$STARTED\"\nsleep 4\nprintf 'S\\nB\\n' > \"$1\"\n",
    );

    let mut command = Command::new(env!("CARGO_BIN_EXE_ostrya"));
    command
        .args([
            "commit",
            "--repo",
            repo.to_str().unwrap(),
            "-b",
            "locked",
            "-e",
            FIXED_TIMESTAMP,
            tree.to_str().unwrap(),
        ])
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .env("STARTED", &started_marker);
    for name in EDITOR_VARIABLES {
        command.env_remove(name);
    }
    command.env("OSTREE_EDITOR", &editor);
    let child = command.spawn().expect("spawn the port");

    // Wait for the editing session to open. The wait has a limit of 30
    // seconds, so a child that never runs the editor fails here and does not
    // hang.
    let deadline = Instant::now() + Duration::from_secs(30);
    while !started_marker.exists() {
        assert!(Instant::now() < deadline, "the editor never started");
        std::thread::sleep(Duration::from_millis(10));
    }

    // An exclusive hold excludes every other holder, so it succeeds only if
    // the editing session holds no lock. The test releases the hold at once,
    // early in the session, so the commit takes its own lock with no wait.
    let (acquired, waited) = block_on(async {
        let repo = Repo::open(&repo).await.unwrap();
        let started = Instant::now();
        let acquired = repo
            .transaction_with_lock(LockKind::Exclusive)
            .await
            .is_ok();
        (acquired, started.elapsed())
    });
    assert!(
        acquired,
        "an exclusive hold was refused while the editor was running"
    );
    assert!(
        waited < Duration::from_secs(1),
        "an exclusive hold waited {waited:?} for the editing session"
    );

    // The commit itself still takes the lock and writes the ref.
    let out = child.wait_with_output().expect("wait for the port");
    assert!(
        out.status.success(),
        "the commit failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    let printed = String::from_utf8_lossy(&out.stdout);
    let checksum = printed.trim();
    assert_eq!(checksum.len(), 64, "the commit printed `{printed}`");
    let listed = ostrya(&["refs", "--repo", repo.to_str().unwrap()], None, &[])
        .ok()
        .stdout_trimmed();
    assert!(
        listed.lines().any(|line| line == "locked"),
        "the branch is missing: {listed}"
    );
}

/// The environment variables that name the editor. A case that controls one of
/// them must clear them in both commands, so that a value of the host cannot
/// reach the invocation.
const EDITOR_VARIABLES: [&str; 4] = ["OSTREE_EDITOR", "VISUAL", "EDITOR", "GIT_EDITOR"];

/// Run ostrya with the editor variables cleared and `env` applied over them.
fn ostrya_no_editor(args: &[&str], env: &[(&str, &str)]) -> Run {
    run_cleared(env!("CARGO_BIN_EXE_ostrya"), args, env)
}

/// Run the `ostree` command with the editor variables cleared and `env`
/// applied over them.
fn ostree_no_editor(args: &[&str], env: &[(&str, &str)]) -> Run {
    run_cleared("ostree", args, env)
}

/// Run `program` with every editor variable removed from the environment and
/// `env` set over the result.
fn run_cleared(program: &str, args: &[&str], env: &[(&str, &str)]) -> Run {
    let mut command = Command::new(program);
    command.args(args).stdin(Stdio::null());
    for name in EDITOR_VARIABLES {
        command.env_remove(name);
    }
    for (key, value) in env {
        command.env(key, value);
    }
    let out = command.output().expect("spawn the implementation");
    Run {
        status: out.status,
        stdout: out.stdout,
        stderr: out.stderr,
    }
}

/// Run `args` against the repository of each command with the editor
/// environment cleared. The repository goes in a `--repo` after the
/// subcommand name.
fn run_both_no_editor(
    port_repo: &Path,
    tool_repo: &Path,
    args: &[&str],
    env: &[(&str, &str)],
) -> (Run, Run) {
    let with_repo = |repo: &Path| {
        let mut all = vec![args[0].to_owned(), "--repo".to_owned()];
        all.push(repo.display().to_string());
        all.extend(args[1..].iter().map(|arg| (*arg).to_owned()));
        all
    };
    let port_args = with_repo(port_repo);
    let tool_args = with_repo(tool_repo);
    let port = ostrya_no_editor(
        &port_args.iter().map(String::as_str).collect::<Vec<_>>(),
        env,
    );
    let tool = ostree_no_editor(
        &tool_args.iter().map(String::as_str).collect::<Vec<_>>(),
        env,
    );
    (port, tool)
}

/// The same run with the temporary-file name of the editor masked, because
/// each command gives that file its own name.
fn mask_temp(run: &Run) -> Run {
    fn mask(bytes: &[u8]) -> Vec<u8> {
        let text = String::from_utf8_lossy(bytes);
        let mut out = String::new();
        for (index, part) in text.split('/').enumerate() {
            if index > 0 {
                out.push('/');
            }
            // A temporary name is a dot and six characters. Both commands give
            // it this shape.
            let temp = part.len() >= 7
                && part.starts_with('.')
                && part[1..7].chars().all(|c| c.is_ascii_alphanumeric());
            if temp {
                out.push_str("<TMP>");
                out.push_str(&part[7..]);
            } else {
                out.push_str(part);
            }
        }
        out.into_bytes()
    }
    Run {
        status: run.status,
        stdout: mask(&run.stdout),
        stderr: mask(&run.stderr),
    }
}

/// `commit --add-metadata-string` and `--add-metadata` write the commit
/// metadata dict in the entry order that the commit checksum states. Both
/// commands refuse the same arguments with the same words.
#[test]
fn commit_metadata_matches_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("commit-metadata");
    let base = tmp.path();
    let (port_repo, tool_repo, tree) = commit_pair(base, RepoMode::Archive);
    let src = tree.to_str().unwrap();

    let mut cell = 0;
    let mut agrees = |extra: &[&str]| -> (Run, Run) {
        cell += 1;
        let branch = format!("meta{cell}");
        let mut args = vec!["commit", "-b", &branch, FIXED_TIMESTAMP];
        args.extend_from_slice(extra);
        args.push(src);
        let (port, tool) = run_both(&port_repo, &tool_repo, &args);
        assert_runs_agree(&port, &tool, &args.join(" "));
        (port, tool)
    };
    // The exit status that the reader gives a value, asserted for each command.
    // This keeps a value that both commands refuse out of the accepted set.
    let landed = |port: &Run, tool: &Run, value: &str, code: i32| {
        for (who, run) in [("port", port), ("tool", tool)] {
            assert_eq!(
                run.status.code(),
                Some(code),
                "the {who} answered `{value}` with another status:\n{}",
                String::from_utf8_lossy(&run.stderr),
            );
        }
    };

    // `--add-metadata-string` splits at the first `=`, so a value can hold more
    // `=` characters. An empty value is accepted.
    agrees(&["--add-metadata-string=foo=bar"]);
    agrees(&["--add-metadata-string=foo=has=equals=in=value"]);
    agrees(&["--add-metadata-string=key="]);
    // A key given twice is written twice.
    agrees(&[
        "--add-metadata-string=foo=bar",
        "--add-metadata-string=foo=second",
    ]);
    // The entry order goes by option group: first every
    // `--add-metadata-string`, then every `--add-metadata`. The command-line
    // position has no effect on it.
    agrees(&[
        "--add-metadata-string=s1=A",
        "--add-metadata=m1='B'",
        "--add-metadata-string=s2=C",
        "--add-metadata=m2='D'",
    ]);
    agrees(&["--add-metadata-string=dup=str", "--add-metadata=dup='var'"]);
    agrees(&["--add-metadata=dup='var'", "--add-metadata-string=dup=str"]);
    // A user key can have a name that the binding keys use. The command writes
    // the automatic entry next to it.
    agrees(&["--add-metadata-string=ostree.ref-binding=hijack"]);

    // Every value form that the GVariant text reader accepts, one commit for
    // each. The agreeing checksum shows that the value serialized to the same
    // bytes, with the host byte order.
    for value in [
        "'a string'",
        "\"double quoted\"",
        "uint32 42",
        "42",
        "-42",
        "int64 -5",
        "@x 5",
        "uint64 99",
        "byte 0x41",
        "true",
        "false",
        "1.5",
        "0.1",
        "1.0",
        "1e3",
        "-0.0",
        "1.7976931348623157e308",
        "int16 -5",
        "uint16 5",
        "handle 5",
        "objectpath '/a/b'",
        "signature 'ay'",
        "@o '/a/b'",
        "@g 'ay'",
        "['a','b']",
        "@as ['a','b']",
        "@ay [1,2,3]",
        "b'bytes'",
        "b\"double\"",
        "{'x': 'y'}",
        "@a{ss} {'x': 'y'}",
        "('a', 5)",
        "<'nested variant'>",
        "<<'x'>>",
        "@v <'x'>",
        "@ms 'just'",
        "@ms nothing",
        "just 'x'",
        "@mi 5",
        "@mu 7",
        // A nested maybe. The set levels and the value are both part of the
        // stored bytes.
        "@mmi nothing",
        "@mmi just nothing",
        "@mmi just 5",
        "@mmi 5",
        "@mmmi just just nothing",
        "@mmmi just nothing",
        "@mmmmi just just just nothing",
        "@mms just nothing",
        "@mmv just nothing",
        "@mmv just just <5>",
        "@mmay just nothing",
        "@mm() just nothing",
        "@mammi just [just nothing]",
        "@ammi [just nothing, nothing, just just 5]",
        "@ammmi [just just nothing, just nothing, nothing, just just just 5]",
        "@a{smmi} {'a': just nothing, 'b': nothing, 'c': just just 5}",
        "@{smmi} {'a', just nothing}",
        "@(mmimmimmi) (just nothing, nothing, just just 5)",
        "'a=b'",
        "[2, 1.5]",
        "[1.5, 2]",
        "[[1],[2]]",
        "{'a': 1, 'b': 2}",
        "{1: 'a'}",
        "{'a', 5}",
        "[@ms 'a', 'b']",
        "['a', @ms 'b']",
        "[nothing, 'a']",
        "[just 'a', nothing]",
        "@(si) ('a', 5)",
        "@ai []",
        "@as []",
        "@a{sv} {}",
        "[b'x', b'y']",
        "[@o '/a', '/b']",
        "@ao ['/a','/b']",
        "'\\x41'",
        "  42  ",
        "@i 42",
        "@au [1,2]",
        "[<'a'>, <5>]",
        "0x41",
        "017",
        "(1,)",
        "()",
        "[1,2,3]",
        // A bytestring ends at the first NUL that its escapes make.
        "b'\\0'",
        "b''",
        "b'\\400'",
        "b'\\0001'",
        "b'a\\0b'",
        "b'\\101'",
        // A bytestring has no `\u` escape, so the reader drops the backslash
        // and keeps the digits.
        "b'\\u0000'",
        "b'a\\u0000b'",
        // Every escape that a string literal takes:
        // - the short forms
        // - the quote in use
        // - an unknown escape, which drops the backslash and keeps the byte
        // - the line continuation of a backslash before a line feed
        "'a\\ab'",
        "'a\\bb'",
        "'a\\fb'",
        "'a\\nb'",
        "'a\\rb'",
        "'a\\tb'",
        "'a\\vb'",
        "'a\\\\b'",
        "'a\\'b'",
        "\"a\\\"b\"",
        "'a\\zb'",
        "'a\\\nb'",
        "'\\\n'",
        "b'a\\\nb'",
        // A `\\` takes the backslash, so the line feed after it belongs to the
        // literal and stays.
        "'a\\\\\nb'",
        // A unicode escape that names a character, in either digit case, and a
        // character written as itself.
        "'\\u00e9'",
        "'\\u00E9'",
        "'a\\u0041b'",
        "'\\uffff'",
        "'\\U00000041'",
        "'\\U0001f600'",
        "'\\U0010ffff'",
        "'héllo'",
        "'中文'",
        "b'hé'",
        // The escapes that a bytestring takes in addition to its octal escapes.
        "b'a\\tb'",
        "b'a\\nb'",
        "b'a\\vb'",
        "b'a\\\\b'",
        "b\"a\\\"b\"",
        "b'a\\zb'",
        // A binary literal, and the hexadecimal body that an integer reader
        // takes.
        "0b101",
        "0B101",
        "byte 0b11111111",
        "0xe",
        "0x1e5",
        "-0x1",
        "+0x10",
        "0x1.8p1",
        // Both prefix letters take either case, and so do the hexadecimal
        // digits.
        "0X41",
        "0xAB",
        "0xaB",
        "byte 0XFF",
        "@t 0XdeadBEEF",
        // A leading zero with no digit after it is octal zero.
        "0",
        "-0",
        // A leading `+`, and the sign of the exponent.
        "+5",
        "1e+3",
        "1.5e+10",
        "+1.5",
        "@d +1",
        // A hexadecimal body with a fraction is a double with no binary
        // exponent of its own.
        "0x1.8",
        "@d 0x1.8",
        "@d 0x.8",
        "0x.8p1",
        // The reader that the target type selects, which reads the same text
        // twice.
        "@d 017",
        "double 0777",
        "@d 0x10",
        "@d 1E3",
        "double 1E3",
        // The sign that the reader takes before the body.
        "-",
        "@i -",
        "@t -",
        "-+5",
        // Not-a-number and the infinities, which the printer also writes.
        "nan",
        "-nan",
        "inf",
        "-inf",
        "+inf",
        "-infinity",
        "double nan",
        "just nan",
        "[1, nan]",
        // The reader keeps an underflow to zero and refuses a decimal
        // subnormal.
        "1e-400",
        "-1e-400",
        "2.2250738585072014e-308",
        // A hexadecimal body states its value in binary, so the reader keeps a
        // subnormal that the body states exactly. It also keeps an underflow to
        // zero.
        "@d 0x1p-1023",
        "@d 0x1p-1074",
        "@d -0x1p-1074",
        "@d 0x1.000001p-1030",
        "@d 0x1.fffffffffffffffp-1023",
        "@d 0x1p-1075",
        "@d 0x0.8p-1074",
        "@d 0x1p-9999999999",
        "@d 0x0.0p2147483647",
        // A mantissa of more than 32 hexadecimal digits keeps the digits that
        // it states. The digits that are less significant than the lowest bit
        // of the double round the result.
        "@d 0xffffffffffffffffffffffffffffffffffffffffp0",
        "@d 0x1.0000000000000000000000000000000000001p0",
        "@d 0x1000000000000000000000000000000000001p-140",
        "@d 0x1.fffffffffffff7ffffffffp1023",
        // The object paths and the signatures that both readers take.
        "objectpath '/'",
        "objectpath '/a_b'",
        "objectpath '/A/9'",
        "objectpath '/a/b/c'",
        "objectpath '/_'",
        "signature ''",
        "signature 'ii'",
        "signature '{sv}'",
        "signature 'a{sv}'",
        "signature 'v'",
        "signature '()'",
        "signature '(ii)'",
        "signature '{ss}'",
        "signature 'aay'",
        "signature 'ay(i)s'",
        // Each remaining type keyword, and the range edge of the narrow
        // integer types.
        "boolean true",
        "boolean false",
        "string 'x'",
        "int32 -5",
        "double 5",
        "int16 32767",
        "int16 -32768",
        "uint16 65535",
        "handle -1",
        "handle 2147483647",
        // A declaration ends at the character that closes the value around it.
        // This is `>` in a variant, `:` in a dict key, and `,` in a tuple.
        "<@u 5>",
        "{@s 'a': 5}",
        "(@u 5,)",
        "@a{sv} {'a': <@u 5>}",
        // An array sets one element type for all elements, so a later element
        // can state the type that an earlier empty element does not state.
        "[[], [1]]",
        "[@ai [], [1]]",
        "[nothing, just 'a']",
        // A tab separates the same way a space does.
        "\t42",
        "[1,\t2]",
        // The mantissa parts that a decimal literal can omit.
        "1.",
        ".5",
        "-.5",
        "1.e3",
        // A container nested to the depth that both readers take.
        "[[[[[[[[[[1]]]]]]]]]]",
        // A dictionary takes its value type from the first entry. The entry
        // order selects the stored type, and the agreeing checksum states it.
        "{'a': 1, 'b': uint32 2}",
        "{'a': uint32 2, 'b': 1}",
        "{'a': 1.5, 'b': 1}",
        "{'a': just 'y', 'b': 'x'}",
        "{'a': [1], 'b': []}",
        "{'a': {'d': 2}, 'c': {}}",
        "{'a': 1, 'b': 2, 'c': uint32 3}",
        "{'a': uint32 1, 'b': 2, 'c': 3}",
        "{1: 'a', 2.5: 'b'}",
        // A type that is already in force takes the value next to a declaration
        // and drops the declaration. As a result, `@o` under `s` stores a
        // string, and the object-path check of `@o` never runs.
        "{'a': 'x', 'b': @o '/y'}",
        "{'a': 'x', 'b': @o 'notapath'}",
        "{'a': 1, 'b': @mi 2}",
        "@as [@o '/a']",
        "@ai [@u 5]",
    ] {
        let (port, tool) = agrees(&[&format!("--add-metadata=k={value}")]);
        landed(&port, &tool, value, 0);
    }

    // Every refusal that the reader gives, with the offsets that it reports.
    for value in [
        "[]",
        "",
        "garbage syntax (((",
        "uint32 99999999999999999999",
        "'unterminated",
        "(1,2",
        "{'a':}",
        "nothing",
        "@i 'str'",
        "3000000000",
        "9223372036854775807",
        "18446744073709551615",
        "99999999999999999999",
        "uint32 -1",
        "uint32 4294967296",
        "byte 256",
        "0o17",
        "['a', 5]",
        "{'a': 'b', 'c': 5}",
        "42 43",
        "true false",
        "@u",
        "@",
        "[,]",
        "{}",
        "{'a'}",
        "(,)",
        "@b 1",
        "{[1]: 'a'}",
        "B",
        "_x",
        "Foo",
        "uint32x",
        "x1",
        "a",
        "%",
        "trueX",
        "aB",
        "ju st",
        // A one-member tuple needs its comma.
        "(1)",
        "('a')",
        "((1))",
        "@(i) (1)",
        "(1 2)",
        "(1,2,)",
        // In a literal with no type, the exponent marker is lowercase.
        "1E3",
        "1E",
        "0x1p3",
        // A subnormal is out of the range that the reader takes.
        "5e-324",
        "1e-310",
        "1e-308",
        "1e400",
        "1.7976931348623157e309",
        // A hexadecimal body that rounds to a subnormal that it does not state
        // exactly, and a body that is out of the double range.
        "@d 0x1.8p-1074",
        "@d 0x1.0000000000001p-1030",
        "@d 0x1.0000000000000000001p-1075",
        "@d 0x1p1024",
        "@d 0x1.fffffffffffff8p1023",
        "@d 0x1p2147483647",
        // The character at which each reader stopped.
        "1.5.5",
        "1..5",
        "1e",
        "+",
        "++5",
        "--5",
        "0xg",
        "0b12",
        "0b1e1",
        "08",
        "0778",
        "-INF",
        "infinity",
        "nan5",
        "byte nan",
        "@i nan",
        "byte 1.5",
        "int32 1e3",
        "@d 0b101",
        "int64 -9223372036854775809",
        "-18446744073709551615",
        // The range of each narrow integer type, one value past each end.
        "int16 32768",
        "int16 -32769",
        "uint16 65536",
        "uint16 -1",
        "handle 2147483648",
        "handle -2147483649",
        // A type keyword applies the check to the value next to it.
        "boolean 1",
        "string 5",
        // Literals with a quote that never closes. One of them has a backslash
        // at the end of the text.
        "b'x",
        "'a\\",
        // If no element of an array states a type, the refusal names the whole
        // value.
        "[[], []]",
        // An object path and a signature are checked.
        "objectpath 'notapath'",
        "objectpath ''",
        "objectpath '/a/'",
        "objectpath '//'",
        // A path element takes only letters, digits, and the underscore.
        "objectpath '/a-b'",
        "objectpath '/a.b'",
        "objectpath '/a b'",
        "objectpath 'a/b'",
        "@o 'bad'",
        "signature 'zz'",
        "signature 'ms'",
        "@g 'zz'",
        // A signature body holds only complete definite types. The refusals:
        // - a tuple that never closes
        // - a closing bracket with no opening bracket
        // - a dict entry with a key that is not basic
        // - each indefinite character
        "signature '(i'",
        "signature 'i)'",
        "signature '{as}'",
        "signature '{sv'",
        "signature 'r'",
        "signature '*'",
        "signature '?'",
        // The reader scans a declaration whole, and the refusal names an
        // indefinite declaration.
        "@z 5",
        "@r 5",
        "@* 5",
        "@? 5",
        "@m* 5",
        "@i5",
        "@ii",
        // A declaration applies the check to the members.
        "@as [1]",
        "@ai [1,'a']",
        "@a{ss} {'a': 5}",
        "@a{sv} {'a': 1}",
        "@ai 5",
        // If nothing in the value states a type, the refusal names the whole
        // value.
        "[[]]",
        "just []",
        "just nothing",
        "[nothing]",
        "nothing 5",
        "[<[]>]",
        "{nothing: 1}",
        "{'a': 1, 2: 'b'}",
        // Each closing bracket has its own wording.
        "<1 2>",
        "{'a', 5, 6}",
        // The refusal of a unicode escape names the digits that the text holds.
        "'\\uZZZZ'",
        "'\\u12'",
        "'\\U0001'",
        // An escape that names U+0000 gets the same refusal words, at the
        // offset of the digits, in every position of the literal.
        "'\\u0000'",
        "'\\U00000000'",
        "'a\\u0000b'",
        "'\\u0000x'",
        "@s '\\u0000'",
        "@o '/a\\u0000b'",
        "objectpath '\\u0000'",
        "@g '\\u0000'",
        "signature 'a\\u0000y'",
        "{'\\u0000': 1}",
        "{'a': '\\u0000'}",
        "['a', '\\u0000']",
        "<'\\u0000'>",
        "@ms '\\u0000'",
        "('\\u0000',)",
        // The reader checks a later dictionary value against the type that the
        // first entry set, and the refusal names that type.
        "{'a': 1, 'b': 1.5}",
        "{'a': 'x', 'b': just 'y'}",
        "{'a': 1, 'b': just 2}",
        "{'a': @o '/y', 'b': 'x'}",
        "{'a': (1,2), 'b': ('x','y')}",
        "{'a': ('x','y'), 'b': (1,2)}",
        "{'a': 1, 'b': ['x', 5]}",
        "{'a': 1, 'b': 2, 'c': nothing}",
        "{'a': 1, 'b': @s 'x'}",
        "{'a': 5, 'b': []}",
        "{'a': 1, 'b': 0x1.8p1}",
        "{'a': 'y', 'b': nothing}",
        "@as [@i 5]",
        // If the first value states no type, the refusal names the whole value.
        // No later entry sets the type.
        "{'a': [], 'b': 5}",
        "{'a': [], 'b': [1]}",
        "{'a': nothing, 'b': 'y'}",
        "{'a': {}, 'c': {'d': 2}}",
        "{'q': {'a': [], 'b': 5}}",
        "<{'a': [], 'b': 5}>",
        "{'a': [], [1]: 5}",
    ] {
        let (port, tool) = agrees(&[&format!("--add-metadata=k={value}")]);
        landed(&port, &tool, value, 1);
    }

    // The nesting cap. The text reader of ostrya takes 127 levels and refuses
    // the level 128. Both commands refuse a value of 128 or 129 levels. The
    // offset agrees for the brackets. For `<`, `just`, a type
    // keyword, and a declaration, the `ostree` command leaves the offset
    // uninitialized.
    // This is a recorded divergence, and no cell of this test holds it.
    for (open, close) in [("[", "]"), ("(", ")")] {
        for depth in [128usize, 129] {
            let value = format!("{}1{}", open.repeat(depth), close.repeat(depth));
            agrees(&[&format!("--add-metadata=k={value}")]);
        }
    }

    // The type-depth cap. The reader checks a signature value only as a type
    // string, which takes 129 levels. A declaration counts the levels of its
    // type from the level of the declaration, and takes 128 levels in all.
    let arrays = |count: usize| "a".repeat(count);
    for value in [
        // Well inside both caps. At this depth, a reader with a lower cap of
        // its own already differs from the `ostree` command.
        format!("signature '{}y'", arrays(65)),
        format!("@{}y []", arrays(65)),
        format!("@{}r 5", arrays(66)),
        format!("signature '{}y'", arrays(127)),
        format!("signature '{}y'", arrays(128)),
        format!("signature '{}y'", arrays(129)),
        format!("@g '{}y'", arrays(128)),
        format!("@g '{}y'", arrays(129)),
        format!("@{}y []", arrays(127)),
        format!("@{}y []", arrays(128)),
        format!("@{}y []", arrays(129)),
        // The refusal names an indefinite declaration as indefinite only inside
        // the cap. After the cap, the refusal names the depth. After the
        // type-string limit, the declaration is invalid.
        format!("@{}r 5", arrays(127)),
        format!("@{}r 5", arrays(128)),
        format!("@{}r 5", arrays(129)),
        // The empty tuple has no level of its own, so it reaches one level
        // deeper than a leaf. The value of a dict entry sets its depth.
        format!("@{}() []", arrays(128)),
        format!("@{}() []", arrays(129)),
        format!("@{}(y) []", arrays(126)),
        format!("@{}(y) []", arrays(127)),
        format!("@{}{{s()}} []", arrays(127)),
        format!("@{}{{sy}} []", arrays(126)),
        format!("@{}{{sy}} []", arrays(127)),
        // A declaration inside a container counts from the level of that
        // container.
        format!("[@{}y []]", arrays(126)),
        format!("[@{}y []]", arrays(127)),
    ] {
        agrees(&[&format!("--add-metadata=k={value}")]);
    }

    // A missing `=` and an empty key, on each option that takes a pair.
    agrees(&["--add-metadata-string=noequals"]);
    agrees(&["--add-metadata-string==emptykey"]);
    agrees(&["--add-metadata=noequals"]);
    // Each `--add-metadata` is split and then parsed before the next one is
    // read, so the refusal names the first bad argument in command-line order.
    agrees(&["--add-metadata=k=@@", "--add-metadata=noequals"]);
    agrees(&["--add-metadata=noequals", "--add-metadata=k=@@"]);
    agrees(&["--add-metadata=='x'"]);
    agrees(&["--add-metadata==empty"]);
    agrees(&["--add-detached-metadata-string=noequals"]);
}

/// `commit --keep-metadata` copies a key from the resolved parent. If
/// `--parent` is given, the resolved parent is that commit. If not, it is the
/// branch tip.
#[test]
fn commit_keep_metadata_matches_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("commit-keep-metadata");
    let base = tmp.path();
    let (port_repo, tool_repo, tree) = commit_pair(base, RepoMode::Archive);
    let src = tree.to_str().unwrap();

    let mut cell = 0;
    let mut agrees = |extra: &[&str], timestamp: &str| {
        cell += 1;
        let mut args = vec!["commit", timestamp];
        args.extend_from_slice(extra);
        args.push(src);
        assert_agrees(&port_repo, &tool_repo, &args);
    };

    // The parent that both commands then read from: one commit with three
    // keys. One key is numeric, so that the test checks the carried bytes as
    // bytes.
    agrees(
        &[
            "-b",
            "main",
            "--add-metadata-string=k1=v1",
            "--add-metadata-string=k2=v2",
            "--add-metadata=k3=uint32 3",
        ],
        FIXED_TIMESTAMP,
    );
    let parent = ostrya(
        &["rev-parse", "--repo", port_repo.to_str().unwrap(), "main"],
        None,
        &[],
    )
    .ok()
    .stdout_trimmed();
    let explicit = format!("--parent={parent}");

    // The commit carries keys in command-line order, after both add groups. A
    // key given twice is carried twice.
    agrees(
        &[
            "-b",
            "k1",
            &explicit,
            "--keep-metadata=k2",
            "--keep-metadata=k1",
        ],
        FIXED_TIMESTAMP,
    );
    agrees(
        &["-b", "k3", &explicit, "--keep-metadata=k3"],
        FIXED_TIMESTAMP,
    );
    agrees(
        &["-b", "k4", &explicit, "--keep-metadata=ostree.ref-binding"],
        FIXED_TIMESTAMP,
    );
    agrees(
        &[
            "-b",
            "k5",
            &explicit,
            "--keep-metadata=k1",
            "--add-metadata-string=k1=override",
        ],
        FIXED_TIMESTAMP,
    );
    agrees(
        &[
            "-b",
            "k6",
            &explicit,
            "--keep-metadata=k1",
            "--keep-metadata=k1",
        ],
        FIXED_TIMESTAMP,
    );
    agrees(
        &[
            "-b",
            "k7",
            &explicit,
            "--add-metadata=z='zz'",
            "--keep-metadata=k1",
            "--add-metadata-string=s=ss",
        ],
        FIXED_TIMESTAMP,
    );
    // `--no-bindings` turns off only the automatic key, so a key that
    // `--keep-metadata` carries stays.
    agrees(
        &[
            "-b",
            "k8",
            &explicit,
            "--no-bindings",
            "--keep-metadata=ostree.ref-binding",
        ],
        FIXED_TIMESTAMP,
    );
    // The branch tip is the implicit parent, and `--orphan` with an explicit
    // `--parent` still reads that parent.
    agrees(
        &["-b", "main", "--keep-metadata=k1"],
        "--timestamp=@1700000001",
    );
    agrees(
        &["--orphan", &explicit, "--keep-metadata=k1"],
        FIXED_TIMESTAMP,
    );

    // The refusals: a key that the parent does not hold, and every shape that
    // resolves no parent.
    agrees(
        &["-b", "main", &explicit, "--keep-metadata=nosuch"],
        FIXED_TIMESTAMP,
    );
    agrees(&["--orphan", "--keep-metadata=k1"], FIXED_TIMESTAMP);
    agrees(&["-b", "brandnew", "--keep-metadata=k1"], FIXED_TIMESTAMP);
    agrees(
        &["-b", "main", "--parent=none", "--keep-metadata=k1"],
        FIXED_TIMESTAMP,
    );
}

/// A commit metadata dict has several keys in an order that is not the
/// command-line order and not sorted. The dict gets one checksum in ostrya and
/// the `ostree` command. Every key of the dict reads back by name.
#[test]
fn commit_metadata_reads_back_in_any_key_order() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("commit-metadata-order");
    let base = tmp.path();
    let (port_repo, tool_repo, tree) = commit_pair(base, RepoMode::Archive);
    let src = tree.to_str().unwrap();

    // The option groups put both `--add-metadata` keys after both
    // `--add-metadata-string` keys, so the dict order is `zulu`, `alpha`,
    // `mike`, `bravo`, `ostree.ref-binding`. That order is not the order of the
    // command line in any reading, and it is not sorted. The checksums agree,
    // so the stored bytes agree, and the entry order is part of these bytes.
    assert_agrees(
        &port_repo,
        &tool_repo,
        &[
            "commit",
            "-b",
            "order",
            "-s",
            "x",
            FIXED_TIMESTAMP,
            "--add-metadata-string=zulu=z",
            "--add-metadata=mike='m'",
            "--add-metadata-string=alpha=a",
            "--add-metadata=bravo=uint64 4",
            src,
        ],
    );

    // Every key reads back by name, in any slot of the dict. Both commands
    // print the same value for it.
    for key in ["zulu", "alpha", "mike", "bravo", "ostree.ref-binding"] {
        let arg = format!("--print-metadata-key={key}");
        assert_agrees(&port_repo, &tool_repo, &["show", &arg, "order"]);
    }

    // The listing sorts the names, so it tells nothing about the stored order.
    // Both commands list the same five keys.
    assert_agrees(
        &port_repo,
        &tool_repo,
        &["show", "--list-metadata-keys", "order"],
    );
}

/// A metadata key given twice is in the dict twice. In ostrya and in the
/// `ostree` command, a read-back by that name gets the first entry.
#[test]
fn commit_duplicate_metadata_key_reads_back_the_first() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("commit-metadata-duplicate");
    let base = tmp.path();
    let (port_repo, tool_repo, tree) = commit_pair(base, RepoMode::Archive);
    let src = tree.to_str().unwrap();

    // The checksums agree, so both entries are in the dict. The cell
    // `commit/metadata-duplicate-key` holds the same fact.
    assert_agrees(
        &port_repo,
        &tool_repo,
        &[
            "commit",
            "-b",
            "dup",
            "-s",
            "x",
            FIXED_TIMESTAMP,
            "--add-metadata-string=foo=first",
            "--add-metadata-string=foo=second",
            src,
        ],
    );

    // The name gets the first of the two entries, so the slot of an entry
    // sets the value that a read by name gets.
    let args = ["show", "--print-metadata-key=foo", "dup"];
    let (port, tool) = run_both(&port_repo, &tool_repo, &args);
    assert_runs_agree(&port, &tool, &args.join(" "));
    assert_eq!(
        tool.stdout_trimmed(),
        "'first'",
        "the name reaches the entry standing first"
    );
}

/// `commit --add-detached-metadata-string` writes the `.commitmeta` file next
/// to the commit and does not change the commit checksum.
#[test]
fn commit_detached_metadata_matches_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("commit-detached");
    let base = tmp.path();
    let (port_repo, tool_repo, tree) = commit_pair(base, RepoMode::Archive);
    let src = tree.to_str().unwrap();

    let mut cell = 0;
    let mut agrees = |extra: &[&str]| {
        cell += 1;
        let branch = format!("det{cell}");
        let mut args = vec!["commit", "-b", &branch, FIXED_TIMESTAMP];
        args.extend_from_slice(extra);
        args.push(src);
        assert_agrees(&port_repo, &tool_repo, &args);
        let checksum = ostrya(
            &["rev-parse", "--repo", port_repo.to_str().unwrap(), &branch],
            None,
            &[],
        )
        .ok()
        .stdout_trimmed();
        // The detached file is outside the commit object, so the test compares
        // its bytes at the loose path where both commands write it.
        let relative = format!("objects/{}/{}.commitmeta", &checksum[..2], &checksum[2..]);
        let written = std::fs::read(port_repo.join(&relative)).unwrap_or_else(|err| {
            panic!("`{}` wrote no detached metadata: {err}", extra.join(" "))
        });
        assert!(
            !written.is_empty(),
            "`{}` wrote an empty detached file",
            extra.join(" "),
        );
        assert_eq!(
            Some(written),
            std::fs::read(tool_repo.join(&relative)).ok(),
            "`{}` wrote different detached metadata",
            extra.join(" "),
        );
        // The test also compares the key listing of both commands for the file.
        assert_agrees(
            &port_repo,
            &tool_repo,
            &["show", "--list-detached-metadata-keys", &branch],
        );
    };
    agrees(&["--add-detached-metadata-string=dk=dv"]);
    agrees(&[
        "--add-detached-metadata-string=a=1",
        "--add-detached-metadata-string=b=2",
    ]);
    agrees(&[
        "--add-detached-metadata-string=dup=one",
        "--add-detached-metadata-string=dup=two",
    ]);
    // This option accepts an empty key. The two commit-metadata options refuse
    // it.
    agrees(&["--add-detached-metadata-string==x"]);
    agrees(&["--add-detached-metadata-string=k="]);
    agrees(&[
        "--add-detached-metadata-string=x=y",
        "--add-metadata-string=m=n",
    ]);
}

/// `commit --bind-ref` and `--no-bindings` control `ostree.ref-binding` and
/// `ostree.collection-binding`.
#[test]
fn commit_ref_bindings_match_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("commit-bindings");
    let base = tmp.path();
    let (port_repo, tool_repo, tree) = commit_pair(base, RepoMode::Archive);
    let src = tree.to_str().unwrap();

    let mut cell = 0;
    let mut agrees = |extra: &[&str], branch: Option<&str>| {
        cell += 1;
        let named = branch.map(str::to_owned).unwrap_or(format!("bind{cell}"));
        let mut args = vec!["commit", FIXED_TIMESTAMP];
        if branch == Some("") {
            args.push("--orphan");
        } else {
            args.extend_from_slice(&["-b", &named]);
        }
        args.extend_from_slice(extra);
        args.push(src);
        assert_agrees(&port_repo, &tool_repo, &args);
    };

    // The array holds the branch and every bound name, sorted byte-wise
    // ascending, with duplicates kept and no name rule applied.
    agrees(&["--bind-ref=extra"], None);
    agrees(&["--bind-ref=e1", "--bind-ref=e2"], None);
    agrees(&["--bind-ref=aaa", "--bind-ref=mmm"], Some("zzz"));
    agrees(
        &["--bind-ref=B", "--bind-ref=a", "--bind-ref=C"],
        Some("s1"),
    );
    agrees(
        &["--bind-ref=b/z", "--bind-ref=b.a", "--bind-ref=b-a"],
        Some("s2"),
    );
    agrees(
        &["--bind-ref=10", "--bind-ref=9", "--bind-ref=2"],
        Some("s4"),
    );
    agrees(
        &["--bind-ref=zzz", "--bind-ref=aaa", "--bind-ref=aaa"],
        Some("s3"),
    );
    agrees(&["--bind-ref=b5"], Some("b5"));
    for name in [
        "bad name",
        "bad//name",
        "-leading",
        "has^caret",
        ".dotstart",
        "trail/",
        "",
        "UPPER/ok",
        "nul\ttab",
    ] {
        agrees(&[&format!("--bind-ref={name}")], None);
    }
    // `--bind-ref` accepts the 64-lowercase-hex name that `-b` refuses. The
    // guard applies to the ref that the command writes, and not to the name
    // that the command records.
    agrees(
        &["--bind-ref=0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef"],
        Some("okbr"),
    );

    // `--no-bindings` writes no binding key and overrides `--bind-ref`, so a
    // commit that adds nothing else gets one object for all branch names.
    agrees(&["--no-bindings"], Some("b2"));
    agrees(&["--no-bindings", "--bind-ref=x"], Some("b6"));
    agrees(&["--no-bindings"], Some(""));
    let collapsed: Vec<String> = [
        vec![
            "commit",
            "-b",
            "b2",
            "--parent=none",
            FIXED_TIMESTAMP,
            "--no-bindings",
            src,
        ],
        vec!["commit", "--orphan", FIXED_TIMESTAMP, "--no-bindings", src],
        vec![
            "commit",
            "-b",
            "b6",
            "--parent=none",
            FIXED_TIMESTAMP,
            "--no-bindings",
            "--bind-ref=x",
            src,
        ],
    ]
    .iter()
    .map(|args| {
        let mut argv = vec!["--repo", port_repo.to_str().unwrap()];
        argv.extend(args.iter().copied());
        ostrya(&argv, None, &[]).ok().stdout_trimmed()
    })
    .collect();
    for checksum in &collapsed {
        assert_eq!(
            checksum, &collapsed[0],
            "--no-bindings did not collapse the three onto one commit",
        );
    }

    // `--orphan` writes the key with an empty array. With `--bind-ref`, the
    // array holds only the bound names.
    agrees(&[], Some(""));
    agrees(&["--bind-ref=only"], Some(""));
    agrees(&["--bind-ref=zz", "--bind-ref=aa"], Some(""));
    // `--bind-ref` names no branch, so the usual branch check refuses a commit
    // that has only this option.
    assert_agrees(
        &port_repo,
        &tool_repo,
        &["commit", FIXED_TIMESTAMP, "--bind-ref=noBranch", src],
    );

    // A repository with a collection id writes the second binding key after the
    // first. `--no-bindings` removes both keys.
    let collection = base.join("collection");
    std::fs::create_dir_all(&collection).unwrap();
    let mut repos = Vec::new();
    for name in ["port", "tool"] {
        let repo = collection.join(name);
        let argv = [
            "init",
            "--repo",
            repo.to_str().unwrap(),
            "--mode=archive",
            "--collection-id=org.example.Test",
        ];
        if name == "port" {
            ostrya(&argv, None, &[]).ok();
        } else {
            assert!(ostree(&argv).status.success(), "ostree init failed");
        }
        repos.push(repo);
    }
    let mut collection_checksums = Vec::new();
    for extra in [
        vec!["-b", "cb1"],
        vec!["-b", "cb2", "--bind-ref=extra"],
        vec!["-b", "cb3", "--no-bindings"],
        vec!["--orphan"],
        vec!["-b", "cb5", "--add-metadata-string=zz=1"],
    ] {
        let mut args = vec!["commit", FIXED_TIMESTAMP];
        args.extend_from_slice(&extra);
        args.push(src);
        let (port, tool) = run_both(&repos[0], &repos[1], &args);
        assert_runs_agree(&port, &tool, &args.join(" "));
        collection_checksums.push(port.stdout_trimmed());
    }

    // The test reads the dict back from each repository with the `show --raw`
    // of the command that wrote it. The read-back shows three facts:
    // - the second binding key comes after the first
    // - a `--bind-ref` name goes only into the first key
    // - `--no-bindings` keeps neither key
    // The five commits of the loop agree in both commands. Only the read-back
    // of four of them shows the order and the removal.
    let raw = |repo: &Path, checksum: &str, port: bool| -> String {
        let repo_arg = format!("--repo={}", repo.display());
        let args = ["show", &repo_arg, "--raw", checksum];
        let run = if port {
            ostrya(&args, None, &[])
        } else {
            ostree(&args)
        };
        assert!(
            run.status.success(),
            "`show --raw {checksum}` failed:\n{}",
            String::from_utf8_lossy(&run.stderr),
        );
        String::from_utf8(run.stdout).expect("the printed dict is text")
    };
    let collection = "'ostree.collection-binding': <'org.example.Test'>";
    for (repo, port) in [(&repos[0], true), (&repos[1], false)] {
        // The plain branch, the branch with a bound name, and the orphan: the
        // ref binding comes first, and the collection binding comes after it.
        for (checksum, names) in [
            (&collection_checksums[0], "'ostree.ref-binding': <['cb1']>"),
            (
                &collection_checksums[1],
                "'ostree.ref-binding': <['cb2', 'extra']>",
            ),
            (&collection_checksums[3], "'ostree.ref-binding': <@as []>"),
        ] {
            let text = raw(repo, checksum, port);
            let bound = text
                .find(names)
                .unwrap_or_else(|| panic!("{names} is absent from the metadata:\n{text}"));
            let bound_collection = text
                .find(collection)
                .unwrap_or_else(|| panic!("{collection} is absent from the metadata:\n{text}"));
            assert!(
                bound < bound_collection,
                "the collection binding stands ahead of the ref binding:\n{text}"
            );
        }
        // `--no-bindings` removes both keys.
        let text = raw(repo, &collection_checksums[2], port);
        for key in ["ostree.ref-binding", "ostree.collection-binding"] {
            assert!(
                !text.contains(key),
                "`--no-bindings` left `{key}` in the metadata:\n{text}"
            );
        }
    }
}

/// Runs `commit` against `repo` under the fixed timestamp with no parent, and
/// returns the run. `args` go between the timestamp and the source `src`.
fn commit_no_parent(repo: &Path, args: &[&str], src: &Path) -> Run {
    let mut argv = vec![
        "commit",
        "--repo",
        repo.to_str().unwrap(),
        FIXED_TIMESTAMP,
        "--parent=none",
    ];
    argv.extend_from_slice(args);
    argv.push(src.to_str().unwrap());
    ostrya(&argv, None, &[])
}

/// `commit --tag` binds each tag as `--bind-ref` does, so the commit has the
/// checksum of the same commit with `--bind-ref`. It also creates the local
/// ref of each tag at the new commit.
#[test]
fn commit_tag_binds_like_bind_ref_and_creates_the_ref() {
    let tmp = TmpDir::new("commit-tag");
    let base = tmp.path();
    build_fixture_source(base);
    let src = base.join("src");
    let repo = create_repo(base, RepoMode::Archive);
    let collection = base.join("collection");
    ostrya(
        &[
            "init",
            "--repo",
            collection.to_str().unwrap(),
            "--mode=archive",
            "--collection-id=org.example.Test",
        ],
        None,
        &[],
    )
    .ok();

    // Each case: the repository, the options with `--tag`, the same options
    // with `--bind-ref` in place of each `--tag`, the branch, and the tags.
    type Case<'a> = (
        &'a Path,
        &'a [&'a str],
        &'a [&'a str],
        Option<&'a str>,
        &'a [&'a str],
    );
    let cases: [Case; 5] = [
        (
            &repo,
            &["-b", "m1", "--tag=t1"],
            &["-b", "m1", "--bind-ref=t1"],
            Some("m1"),
            &["t1"],
        ),
        (
            &repo,
            &["-b", "m2", "--tag=b", "--tag=a", "--bind-ref=c"],
            &["-b", "m2", "--bind-ref=b", "--bind-ref=a", "--bind-ref=c"],
            Some("m2"),
            &["a", "b"],
        ),
        (
            &repo,
            &["--orphan", "--tag=t3"],
            &["--orphan", "--bind-ref=t3"],
            None,
            &["t3"],
        ),
        (
            &repo,
            &["-b", "m4", "--tag=t4", "--bind-ref=t4"],
            &["-b", "m4", "--bind-ref=t4", "--bind-ref=t4"],
            Some("m4"),
            &["t4"],
        ),
        (
            &collection,
            &["-b", "m5", "--tag=t5"],
            &["-b", "m5", "--bind-ref=t5"],
            Some("m5"),
            &["t5"],
        ),
    ];
    for (repo, tagged, bound, branch, tags) in cases {
        let refs_before = describe_tree_with_content(&repo.join("refs/heads"));
        let expected = commit_no_parent(repo, bound, &src).ok().stdout_trimmed();
        // The bound run moved the branch, so the branch file is in the
        // listing that the tagged run starts from.
        let refs_bound = describe_tree_with_content(&repo.join("refs/heads"));
        let checksum = commit_no_parent(repo, tagged, &src).ok().stdout_trimmed();
        assert_eq!(checksum, expected, "`{tagged:?}` bound other names");
        // The test reads each ref file, because a revision of one hex
        // character such as `a` can name a commit by its prefix.
        let tip = |name: &str| {
            std::fs::read_to_string(repo.join("refs/heads").join(name))
                .ok()
                .map(|text| text.trim().to_owned())
        };
        for tag in tags {
            assert_eq!(
                tip(tag).as_deref(),
                Some(checksum.as_str()),
                "`{tagged:?}` did not create {tag}"
            );
        }
        if let Some(branch) = branch {
            assert_eq!(tip(branch).as_deref(), Some(checksum.as_str()));
        } else {
            // An orphan commit creates its tags and moves no branch.
            assert_eq!(refs_bound, refs_before, "the bound orphan wrote a ref");
        }
        let created = describe_tree_with_content(&repo.join("refs/heads"));
        assert_eq!(
            created.len(),
            refs_bound.len() + tags.len(),
            "`{tagged:?}` wrote other refs: {created:?}"
        );
    }
}

/// `commit --tag` refuses a tag that has an entry at its ref path: a ref, an
/// alias, a dangling alias, a directory of refs, and a name below a ref. The
/// refusal writes no object and no ref.
#[test]
fn commit_tag_refuses_an_existing_ref_and_writes_nothing() {
    let tmp = TmpDir::new("commit-tag-exists");
    let base = tmp.path();
    build_fixture_source(base);
    let repo = create_repo(base, RepoMode::Archive);
    commit_no_parent(&repo, &["-b", "held"], &base.join("src")).ok();
    let repo_arg = repo.to_str().unwrap();
    for args in [
        &["refs", "--repo", repo_arg, "--create=al", "-A", "held"][..],
        &["refs", "--repo", repo_arg, "--create=dir/sub", "held"],
    ] {
        ostrya(args, None, &[]).ok();
    }
    std::os::unix::fs::symlink("nosuch", repo.join("refs/heads/dangling")).unwrap();

    // The changed tree has a new file, so a commit of it writes objects.
    let changed = base.join("changed");
    build_fixture_source(&changed);
    std::fs::write(changed.join("src/extra.txt"), b"extra\n").unwrap();
    let changed = changed.join("src");

    let staging = || -> Vec<String> {
        std::fs::read_dir(repo.join("tmp"))
            .unwrap()
            .map(|entry| entry.unwrap().file_name().to_string_lossy().into_owned())
            .filter(|name| name.starts_with("staging-"))
            .collect()
    };
    for tag in ["held", "al", "dangling", "dir", "held/x"] {
        let objects = loose_objects(&repo);
        let refs = describe_tree_with_content(&repo.join("refs/heads"));
        let run = commit_no_parent(&repo, &["-b", "new", &format!("--tag={tag}")], &changed);
        assert_eq!(run.status.code(), Some(1), "--tag={tag} was not refused");
        assert_eq!(
            String::from_utf8_lossy(&run.stderr).trim(),
            format!("error: --tag specified but ref {tag} already exists"),
        );
        assert_eq!(loose_objects(&repo), objects, "--tag={tag} wrote an object");
        assert!(staging().is_empty(), "--tag={tag} left a staging directory");
        assert_eq!(
            describe_tree_with_content(&repo.join("refs/heads")),
            refs,
            "--tag={tag} changed a ref"
        );
    }
}

/// `commit --tag` checks the ref path of each tag again before the
/// transaction publishes. The editor runs after the first check, so a ref
/// that the editor creates reaches the second check. The refusal writes no
/// object and no ref.
#[test]
fn commit_tag_refuses_a_ref_created_during_the_commit() {
    let tmp = TmpDir::new("commit-tag-late");
    let base = tmp.path();
    build_fixture_source(base);
    let repo = create_repo(base, RepoMode::Archive);
    commit_no_parent(&repo, &["-b", "held"], &base.join("src")).ok();
    let changed = base.join("changed");
    build_fixture_source(&changed);
    std::fs::write(changed.join("src/extra.txt"), b"extra\n").unwrap();

    let editor = write_script(
        &base.join("editor.sh"),
        "#!/bin/sh\ncp \"$HEADS/held\" \"$HEADS/late\"\nprintf 'S\\n' > \"$1\"\n",
    );
    let objects = loose_objects(&repo);
    let heads = repo.join("refs/heads");
    let run = ostrya_no_editor(
        &[
            "commit",
            "--repo",
            repo.to_str().unwrap(),
            FIXED_TIMESTAMP,
            "-b",
            "new",
            "--tag=late",
            "-e",
            changed.join("src").to_str().unwrap(),
        ],
        &[
            ("OSTREE_EDITOR", editor.to_str().unwrap()),
            ("HEADS", heads.to_str().unwrap()),
        ],
    );
    assert_eq!(run.status.code(), Some(1), "the late ref was not refused");
    assert_eq!(
        String::from_utf8_lossy(&run.stderr).trim(),
        "error: --tag specified but ref late already exists",
    );
    assert_eq!(loose_objects(&repo), objects, "the refusal wrote an object");
    assert_eq!(resolve(&repo, "new"), None, "the refusal moved the branch");
    assert_eq!(resolve(&repo, "late"), resolve(&repo, "held"));
}

/// `commit --tag` refuses a bad name before it reads the tree: a name with
/// `:`, a name that the ref-name rule refuses, a checksum-shaped name, the
/// branch name, a name given twice, and a tag with no branch and no
/// `--orphan`. The refusal writes no object and no ref.
#[test]
fn commit_tag_refuses_bad_names_and_writes_nothing() {
    let tmp = TmpDir::new("commit-tag-names");
    let base = tmp.path();
    build_fixture_source(base);
    let src = base.join("src");
    let repo = create_repo(base, RepoMode::Archive);
    let hex = "0123456789abcdef".repeat(4);
    let hex_tag = format!("--tag={hex}");
    let cases: [(&[&str], String); 6] = [
        (
            &["-b", "new", "--tag=a:b"],
            "--tag a:b holds ':', and a tag is a local ref".to_owned(),
        ),
        (
            &["-b", "new", "--tag=-bad"],
            "Invalid refspec -bad".to_owned(),
        ),
        (
            &["-b", "new", &hex_tag],
            format!("Rev name '{hex}' looks like a checksum"),
        ),
        (
            &["-b", "new", "--tag=new"],
            "--tag new is also the --branch name".to_owned(),
        ),
        (
            &["-b", "new", "--tag=t", "--tag=t"],
            "--tag t is given more than once".to_owned(),
        ),
        (
            &["--tag=t"],
            "A branch must be specified with --branch, or use --orphan".to_owned(),
        ),
    ];
    for (args, message) in cases {
        let run = commit_no_parent(&repo, args, &src);
        assert_eq!(run.status.code(), Some(1), "`{args:?}` was not refused");
        assert_eq!(
            String::from_utf8_lossy(&run.stderr).trim(),
            format!("error: {message}"),
            "`{args:?}` was refused in other words"
        );
        assert!(
            loose_objects(&repo).is_empty(),
            "`{args:?}` wrote an object"
        );
        assert!(
            describe_tree_with_content(&repo.join("refs/heads")).is_empty(),
            "`{args:?}` wrote a ref"
        );
    }
}

/// `commit --tag` refuses a name that is a path below another name of the
