/// An `--inline` delta of the `ostree` command holds its part in the metadata
/// dict. ostrya reads the part from there, in the name form and in the path
/// form. `ostree` reads no inline part. In both forms, it opens the part file
/// at its path in the repository and refuses after `PartMeta0`.
///
/// This is the recorded divergence. The part lines of ostrya are the same as
/// the part lines of `ostree` for the same delta with its part written as a
/// file. The test carries `static-delta/show-inline`.
#[test]
fn static_delta_show_reads_an_inline_delta() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-show-inline");
    let (repo, c1, _) = delta_show_repo(tmp.path(), "repo");
    let plain = clone_repo(tmp.path(), &repo, "plain");
    ostree_ok(
        &repo,
        &[
            "static-delta",
            "generate",
            "--empty",
            "--to",
            &c1,
            "--inline",
        ],
    );
    ostree_ok(
        &plain,
        &["static-delta", "generate", "--empty", "--to", &c1],
    );
    let relative = ostrya::static_delta_relative_dir(None, &Checksum::from_hex(&c1).unwrap());
    assert!(
        !repo.join(&relative).join("0").exists(),
        "the part was written as a file"
    );

    let part_lines = |run: &Run| {
        String::from_utf8_lossy(&run.stdout)
            .lines()
            .filter(|line| line.starts_with("PartPayload"))
            .map(str::to_owned)
            .collect::<Vec<_>>()
    };
    let as_file = assert_show_agrees(&plain, &c1);
    let repo_arg = format!("--repo={}", repo.display());
    let path_arg = repo.join(&relative).join("superblock");
    for arg in [c1.as_str(), path_arg.to_str().unwrap()] {
        let args = ["static-delta", &repo_arg, "show", arg];
        let port = ostrya(&args, None, &[]);
        port.ok();
        assert_eq!(part_lines(&port), part_lines(&as_file), "{arg}");
        let tool = ostree(&args);
        assert_eq!(tool.status.code(), Some(1), "{arg}");
        assert_eq!(
            String::from_utf8_lossy(&tool.stderr),
            format!("error: openat({relative}/0): No such file or directory\n"),
            "{arg}"
        );
        // The lines of `ostree` up to its refusal are the same as the lines of
        // ostrya up to the payload line of the first part.
        let printed = String::from_utf8_lossy(&port.stdout).into_owned();
        let cut = printed.find("PartPayload0").unwrap();
        assert_eq!(
            String::from_utf8_lossy(&tool.stdout),
            printed[..cut],
            "{arg}"
        );
    }
}

/// A superblock named by a relative or an absolute path gives the same output
/// in both commands. Both commands refuse a directory and an absent path in
/// the same way. A superblock copied away from its parts is the recorded
/// divergence. The `ostree` command reads the parts in the repository for the
/// delta that the superblock names, and ostrya reads the parts next to the
/// file. The test carries `static-delta/show-path-arg`.
#[test]
fn static_delta_show_takes_a_superblock_path() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-show-path");
    let (repo, c1, _) = delta_show_repo(tmp.path(), "repo");
    ostree_ok(&repo, &["static-delta", "generate", "--empty", "--to", &c1]);
    let relative = ostrya::static_delta_relative_dir(None, &Checksum::from_hex(&c1).unwrap());

    let by_name = assert_show_agrees(&repo, &c1);
    let relative_arg = format!("{relative}/superblock");
    let by_relative = assert_show_agrees_in(&repo, &repo, &relative_arg);
    let absolute = repo.join(&relative_arg);
    let by_absolute = assert_show_agrees(&repo, absolute.to_str().unwrap());
    let tail = |run: &Run| {
        let text = String::from_utf8_lossy(&run.stdout).into_owned();
        text.split_once('\n').unwrap().1.to_owned()
    };
    assert_eq!(tail(&by_relative), tail(&by_name));
    assert_eq!(tail(&by_absolute), tail(&by_name));

    let dir_arg = format!("{relative}/");
    let run = assert_show_agrees_in(&repo, &repo, &dir_arg);
    assert_eq!(
        String::from_utf8_lossy(&run.stderr),
        "error: Is a directory\n"
    );
    let run = assert_show_agrees_in(&repo, &repo, "a/b");
    assert_eq!(
        String::from_utf8_lossy(&run.stderr),
        "error: openat(a/b): No such file or directory\n"
    );

    let copy = tmp.path().join("copy");
    std::fs::create_dir(&copy).unwrap();
    std::fs::copy(absolute, copy.join("superblock")).unwrap();
    let repo_arg = format!("--repo={}", repo.display());
    let args = ["static-delta", &repo_arg, "show", "copy/superblock"];
    let tool = ostree_in(tmp.path(), &args);
    let port = ostrya_in(Some(tmp.path()), &args, None, &[]);
    assert!(
        tool.status.success(),
        "the tool reads the repository's parts"
    );
    assert_eq!(tail(&tool), tail(&by_name));
    assert_eq!(port.status.code(), Some(1));
    assert_eq!(
        String::from_utf8_lossy(&port.stderr),
        "error: openat(copy/0): No such file or directory\n"
    );
    let printed = String::from_utf8_lossy(&port.stdout);
    assert!(printed.contains("\nPartMeta0: "), "{printed}");
    assert!(!printed.contains("PartPayload0"), "{printed}");
}

/// Returns the offsets of the two size fields of the fallback entry with the
/// checksum `hex`, in unsigned superblock bytes. The element `(yaytt)` starts
/// one byte before the checksum. Its two `t` fields are at 40 and 48 in the
/// element.
fn fallback_size_offsets(bytes: &[u8], hex: &str) -> (usize, usize) {
    let checksum = Checksum::from_hex(hex).unwrap();
    let at = bytes
        .windows(32)
        .position(|window| window == checksum.as_bytes())
        .expect("the fallback checksum is in the superblock");
    (at - 1 + 40, at - 1 + 48)
}

/// The size text agrees at each boundary:
///
/// - `0 bytes`, `1 byte`, `N bytes`
/// - the U+00A0 before the unit
/// - the unit chosen on the raw count
/// - the rounding of the exact double
///
/// The superblocks are those of the `ostree` command, with the two sizes of
/// the fallback entry patched in place. They are next to the parts of the
/// delta, so both commands read one set of parts.
#[test]
fn static_delta_show_size_format_matches_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-show-sizes");
    let (repo, c) = delta_fallback_repo(tmp.path(), "repo", false);
    ostree_ok(&repo, &["static-delta", "generate", "--empty", "--to", &c]);
    let dir = repo.join(ostrya::static_delta_relative_dir(
        None,
        &Checksum::from_hex(&c).unwrap(),
    ));
    let original = std::fs::read(dir.join("superblock")).unwrap();
    let show = assert_show_agrees(&repo, &c);
    let text = String::from_utf8_lossy(&show.stdout).into_owned();
    let hex = text
        .lines()
        .find_map(|line| line.strip_prefix("  "))
        .expect("one fallback line")
        .to_owned();
    let (size_at, usize_at) = fallback_size_offsets(&original, &hex);
    assert_eq!(size_at + 8, usize_at);
    assert_eq!(
        u64::from_le_bytes(original[usize_at..usize_at + 8].try_into().unwrap()),
        5_000_000
    );

    for value in [
        0u64,
        1,
        2,
        999,
        1_000,
        1_250,
        1_750,
        999_950,
        999_999,
        1_000_000,
        (1 << 53) + 1,
        u64::MAX,
    ] {
        let mut bytes = original.clone();
        bytes[size_at..size_at + 8].copy_from_slice(&value.to_le_bytes());
        bytes[usize_at..usize_at + 8].copy_from_slice(&value.to_le_bytes());
        let name = format!("sb-{value}");
        std::fs::write(dir.join(&name), &bytes).unwrap();
        let run = assert_show_agrees(&repo, dir.join(&name).to_str().unwrap());
        assert!(run.status.success(), "{value}");
    }
}

/// Rebuilds an unsigned superblock with `recursion` in place of field 5, the
/// recursion array. The function cuts out the variable members of the tuple
/// at the framing offsets at the end of the tuple. It lays them out again with
/// their alignments, and writes the framing at the width that the new length
/// needs.
fn superblock_with_recursion(bytes: &[u8], recursion: &[u8]) -> Vec<u8> {
    // `(a{sv}tayay(a{sv}aya(say)sstayay)aya(uayttay)a(yaytt))`: the alignment of
    // each member, and the members with an end that a framing offset states.
    const ALIGN: [usize; 8] = [8, 8, 1, 1, 8, 1, 8, 8];
    const FRAMED: [usize; 6] = [0, 2, 3, 4, 5, 6];
    let width = |len: usize| match len {
        0..=0xff => 1,
        0x100..=0xffff => 2,
        _ => 4,
    };
    let z = width(bytes.len());
    let framing_start = bytes.len() - FRAMED.len() * z;
    let mut ends = [0usize; 8];
    for (k, &member) in FRAMED.iter().enumerate() {
        let at = bytes.len() - (k + 1) * z;
        let mut raw = [0u8; 8];
        raw[..z].copy_from_slice(&bytes[at..at + z]);
        ends[member] = u64::from_le_bytes(raw) as usize;
    }
    let mut members = Vec::new();
    let mut pos = 0usize;
    for (member, align) in ALIGN.iter().enumerate() {
        let start = pos.next_multiple_of(*align);
        let end = match member {
            1 => start + 8,
            7 => framing_start,
            _ => ends[member],
        };
        members.push(bytes[start..end].to_vec());
        pos = end;
    }
    members[5] = recursion.to_vec();

    let mut out = Vec::new();
    let mut new_ends = Vec::new();
    for (member, align) in ALIGN.iter().enumerate() {
        out.resize(out.len().next_multiple_of(*align), 0);
        out.extend_from_slice(&members[member]);
        if FRAMED.contains(&member) {
            new_ends.push(out.len());
        }
    }
    let z = [1usize, 2, 4]
        .into_iter()
        .find(|z| out.len() + new_ends.len() * z <= (1usize << (8 * z)) - 1)
        .unwrap_or(8);
    for end in new_ends.iter().rev() {
        out.extend_from_slice(&end.to_le_bytes()[..z]);
    }
    out
}

/// In both commands, `Number of parents` is the byte length of field 5 divided
/// by 64, rounded down.
#[test]
fn static_delta_show_parent_count_matches_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-show-parents");
    let (repo, c1, _) = delta_show_repo(tmp.path(), "repo");
    ostree_ok(&repo, &["static-delta", "generate", "--empty", "--to", &c1]);
    let dir = repo.join(ostrya::static_delta_relative_dir(
        None,
        &Checksum::from_hex(&c1).unwrap(),
    ));
    let original = std::fs::read(dir.join("superblock")).unwrap();
    assert_eq!(superblock_with_recursion(&original, &[]), original);

    for (len, parents) in [(0usize, 0usize), (63, 0), (64, 1), (130, 2)] {
        let name = format!("sb-{len}");
        std::fs::write(
            dir.join(&name),
            superblock_with_recursion(&original, &vec![7; len]),
        )
        .unwrap();
        let run = assert_show_agrees(&repo, dir.join(&name).to_str().unwrap());
        let text = String::from_utf8_lossy(&run.stdout);
        assert!(
            text.contains(&format!("\nNumber of parents: {parents}\n")),
            "{len}: {text}"
        );
    }
}

/// The name parser and the refusals agree: exit status, standard output, and
/// standard error. The test carries `static-delta/show-invalid-name` and
/// `static-delta/show-absent`.
#[test]
fn static_delta_show_refusals_match_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-show-refusals");
    let (repo, c1, c2) = delta_show_repo(tmp.path(), "repo");
    ostree_ok(&repo, &["static-delta", "generate", "--empty", "--to", &c1]);
    let repo_arg = format!("--repo={}", repo.display());

    let no_argument = ["static-delta", &repo_arg, "show"];
    let port = ostrya(&no_argument, None, &[]);
    let tool = ostree(&no_argument);
    assert_runs_agree(&port, &tool, "static-delta show");
    assert_eq!(
        String::from_utf8_lossy(&port.stderr),
        "error: DELTA must be specified\n"
    );

    let upper = c1.to_uppercase();
    let bad_last = format!("{}G", &c1[..63]);
    let empty_to = format!("{c1}-");
    let triple = format!("{c1}-{c2}-{c2}");
    let leading = format!(" {c1}");
    let absent = format!("{c1}-{c1}");
    for arg in [
        "ABC",
        "m",
        &c1[..10],
        upper.as_str(),
        bad_last.as_str(),
        empty_to.as_str(),
        triple.as_str(),
        leading.as_str(),
        absent.as_str(),
        "",
    ] {
        let run = assert_show_agrees(&repo, arg);
        assert_eq!(run.status.code(), Some(1), "{arg}");
        assert!(run.stdout.is_empty(), "{arg}");
    }

    // In both commands, a missing part fails after its `PartMeta` line.
    let dir = repo.join(ostrya::static_delta_relative_dir(
        None,
        &Checksum::from_hex(&c1).unwrap(),
    ));
    std::fs::remove_file(dir.join("0")).unwrap();
    let run = assert_show_agrees(&repo, &c1);
    assert_eq!(run.status.code(), Some(1));
    let printed = String::from_utf8_lossy(&run.stdout);
    assert!(printed.contains("\nPartMeta0: "), "{printed}");
    assert!(!printed.contains("PartPayload0"), "{printed}");
}

/// Returns an uncompressed part payload with empty tables, a 64-byte blob, and
/// `ops`, framed at a one-byte offset width.
fn crafted_part(ops: &[u8]) -> Vec<u8> {
    let blob = [0u8; 64];
    let mut part = vec![0u8];
    part.extend_from_slice(&blob);
    part.extend_from_slice(ops);
    assert!(part.len() + 3 < 0x100);
    // The blob end, the xattr table end, the mode table end.
    part.extend_from_slice(&[blob.len() as u8, 0, 0]);
    part
}

/// `show` of the `ostree` command counts some operands of an operation stream
/// with no check. ostrya counts them in the same way, at exit 0:
///
/// - a `w` past the blob with no read source set
/// - a `B` past the blob
///
/// An `S` past the blob causes a refusal in both commands. An `o` with a mode
/// index outside the empty mode table aborts `ostree` (signal 6), and ostrya
/// counts it. This is the recorded exit split. Each crafted part replaces the
/// part of `ostree`, with the checksum and the size in its meta entry patched.
#[test]
fn static_delta_show_counts_unchecked_operands_as_the_tool_does() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-show-operands");
    let (repo, c1, _) = delta_show_repo(tmp.path(), "repo");
    ostree_ok(&repo, &["static-delta", "generate", "--empty", "--to", &c1]);
    let dir = repo.join(ostrya::static_delta_relative_dir(
        None,
        &Checksum::from_hex(&c1).unwrap(),
    ));
    let superblock = std::fs::read(dir.join("superblock")).unwrap();
    let part = std::fs::read(dir.join("0")).unwrap();
    // The meta entry `(uayttay)` holds the part checksum at 4 and the size at
    // 40.
    let entry = superblock
        .windows(32)
        .position(|window| window == ostrya::Checksum::sha256(&part).as_bytes())
        .expect("the part checksum is in the superblock")
        - 4;
    assert_eq!(
        u64::from_le_bytes(superblock[entry + 40..entry + 48].try_into().unwrap()),
        part.len() as u64
    );
    let install = |ops: &[u8]| {
        let part = crafted_part(ops);
        let mut bytes = superblock.clone();
        bytes[entry + 4..entry + 36].copy_from_slice(ostrya::Checksum::sha256(&part).as_bytes());
        bytes[entry + 40..entry + 48].copy_from_slice(&(part.len() as u64).to_le_bytes());
        std::fs::write(dir.join("superblock"), bytes).unwrap();
        std::fs::write(dir.join("0"), part).unwrap();
    };

    for (ops, key) in [
        (&b"w\x64\x00"[..], "write="),
        (&b"B\x00\x64"[..], "bspatch="),
    ] {
        install(ops);
        let run = assert_show_agrees(&repo, &c1);
        assert!(run.status.success(), "{key}");
        assert_eq!(show_count(&run, key), 1, "{key}");
    }

    install(b"S\x64\x00");
    let repo_arg = format!("--repo={}", repo.display());
    let args = ["static-delta", &repo_arg, "show", &c1];
    let port = ostrya(&args, None, &[]);
    let tool = ostree(&args);
    assert_eq!(port.status.code(), Some(1));
    assert_eq!(tool.status.code(), Some(1));

    install(b"o\x00\x00\x05c");
    let port = ostrya(&args, None, &[]);
    port.ok();
    assert_eq!(show_count(&port, "open="), 1);
    let tool = ostree(&args);
    use std::os::unix::process::ExitStatusExt;
    assert_eq!(tool.status.signal(), Some(6), "the tool did not abort");
}

/// `indexes` agrees in these cases:
///
/// - an absent or empty `delta-indexes/`: for an absent one, both commands
///   print `(No static deltas indexes)`
/// - the targets that `reindex` wrote, as a set, because the `ostree` command
///   prints `readdir` order and ostrya sorts
/// - the entries that both commands skip
///
/// A `delta-indexes` that is a file fails in both commands. The test carries
/// `static-delta/indexes-empty`, `static-delta/indexes-after-reindex`, and
/// `static-delta/indexes-skips-invalid`.
#[test]
fn static_delta_indexes_matches_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-indexes");
    let (repo, c1, c2) = delta_show_repo(tmp.path(), "repo");
    // `ostree` reads `static-delta --repo PATH` as a subcommand named PATH, so
    // the repository is given in the `=` form.
    let repo_arg = format!("--repo={}", repo.display());
    let args = ["static-delta", repo_arg.as_str(), "indexes"];
    let both = || (ostrya(&args, None, &[]), ostree(&args));
    let (port, tool) = both();
    assert_runs_agree(&port, &tool, "static-delta indexes");
    assert_eq!(
        String::from_utf8_lossy(&port.stdout),
        "(No static deltas indexes)\n"
    );
    std::fs::create_dir(repo.join("delta-indexes")).unwrap();
    let (port, tool) = both();
    assert_runs_agree(&port, &tool, "static-delta indexes");

    ostree_ok(&repo, &["static-delta", "generate", "--empty", "--to", &c1]);
    ostree_ok(
        &repo,
        &["static-delta", "generate", "--from", &c1, "--to", &c2],
    );
    ostree_ok(&repo, &["static-delta", "reindex"]);
    let lines = |run: &Run| {
        String::from_utf8_lossy(&run.stdout)
            .lines()
            .map(str::to_owned)
            .collect::<Vec<_>>()
    };
    let (port, tool) = both();
    port.ok();
    let mut sorted = lines(&tool);
    sorted.sort();
    assert_eq!(lines(&port), sorted);
    let mut expected = vec![c1.clone(), c2.clone()];
    expected.sort();
    assert_eq!(lines(&port), expected);

    let indexes = repo.join("delta-indexes");
    let a41 = "A".repeat(41);
    let a40 = "A".repeat(40);
    for entry in [
        format!("abc/{a40}.index"),
        format!("abc/{a41}.index"),
        format!("AA/{a40}.index"),
        format!("AA/{}.index", "A".repeat(42)),
        format!("AA/{a41}.INDEX"),
        format!("AA/{a41}.index.index"),
        format!("AA/{a41}.index~"),
        format!("AA/{a41}.idx"),
    ] {
        let file = indexes.join(entry);
        std::fs::create_dir_all(file.parent().unwrap()).unwrap();
        std::fs::write(&file, b"").unwrap();
    }
    std::fs::create_dir_all(indexes.join("AB").join(format!("{a41}.index"))).unwrap();
    std::fs::create_dir_all(indexes.join("AC")).unwrap();
    std::os::unix::fs::symlink("/dev/null", indexes.join("AC").join(format!("{a41}.index")))
        .unwrap();
    std::fs::write(indexes.join("stray"), b"").unwrap();
    let (port, tool) = both();
    port.ok();
    let mut sorted = lines(&tool);
    sorted.sort();
    assert_eq!(lines(&port), sorted);
    assert_eq!(lines(&port), expected);

    std::fs::remove_dir_all(&indexes).unwrap();
    std::fs::write(&indexes, b"").unwrap();
    let (port, tool) = both();
    assert_eq!(port.status.code(), Some(1));
    assert_eq!(tool.status.code(), Some(1));
    assert!(port.stdout.is_empty() && tool.stdout.is_empty());
}

/// `list` agrees in these cases:
///
/// - `(No static deltas)` for an absent `deltas/`, an empty one, and an empty
///   fanout
/// - the names of the deltas that the `ostree` command generated, as a set,
///   because `ostree` prints `readdir` order and ostrya sorts
///
/// Both commands skip an entry with no superblock: an empty directory, a
/// directory with only a part, a regular file, and a dangling `superblock`
/// symlink. The test carries `static-delta/list-empty`,
/// `static-delta/list-skips-dir-without-superblock`, and
/// `static-delta/list-order`.
#[test]
fn static_delta_list_matches_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-list");
    let (repo, c1, c2) = delta_show_repo(tmp.path(), "repo");
    let repo_arg = format!("--repo={}", repo.display());
    let args = ["static-delta", repo_arg.as_str(), "list"];
    let both = || (ostrya(&args, None, &[]), ostree(&args));
    let deltas = repo.join("deltas");
    let _ = std::fs::remove_dir_all(&deltas);
    for step in ["absent", "empty", "empty fanout"] {
        match step {
            "empty" => std::fs::create_dir(&deltas).unwrap(),
            "empty fanout" => std::fs::create_dir(deltas.join("AA")).unwrap(),
            _ => {}
        }
        let (port, tool) = both();
        assert_runs_agree(&port, &tool, "static-delta list");
        assert_eq!(
            String::from_utf8_lossy(&port.stdout),
            "(No static deltas)\n",
            "{step}"
        );
    }

    ostree_ok(&repo, &["static-delta", "generate", "--empty", "--to", &c1]);
    ostree_ok(
        &repo,
        &["static-delta", "generate", "--from", &c1, "--to", &c2],
    );
    let to1 = Checksum::from_hex(&c1).unwrap();
    let to2 = Checksum::from_hex(&c2).unwrap();
    let entry = |from: Option<&Checksum>, to: &Checksum| {
        let path = repo.join(ostrya::static_delta_relative_dir(from, to));
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        path
    };
    std::fs::create_dir(entry(None, &to2)).unwrap();
    let part_only = entry(Some(&to2), &to1);
    std::fs::create_dir(&part_only).unwrap();
    std::fs::write(part_only.join("0"), b"part").unwrap();
    std::fs::write(entry(Some(&to1), &to1), b"file").unwrap();
    let dangling = entry(Some(&to2), &to2);
    std::fs::create_dir(&dangling).unwrap();
    std::os::unix::fs::symlink("nowhere", dangling.join("superblock")).unwrap();

    let lines = |run: &Run| {
        String::from_utf8_lossy(&run.stdout)
            .lines()
            .map(str::to_owned)
            .collect::<Vec<_>>()
    };
    let (port, tool) = both();
    port.ok();
    assert!(tool.status.success() && tool.stderr.is_empty());
    let mut sorted = lines(&tool);
    sorted.sort();
    assert_eq!(lines(&port), sorted);
    let mut expected = vec![c1.clone(), format!("{c1}-{c2}")];
    expected.sort();
    assert_eq!(lines(&port), expected);
}

/// The recorded `list` divergences do not change. The `ostree` command lists
/// an entry with a name that does not decode and that holds a superblock.
/// ostrya refuses it. `ostree` ignores an extra operand, and the parser of
/// ostrya refuses it.
#[test]
fn static_delta_list_divergences_stand_as_recorded() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-list-divergences");
    let repo = tmp.path().join("repo");
    ostree_ok(&repo, &["init", "--mode=archive"]);
    let repo_arg = format!("--repo={}", repo.display());

    let args = ["static-delta", repo_arg.as_str(), "list", "extra"];
    let (port, tool) = (ostrya(&args, None, &[]), ostree(&args));
    assert_eq!(tool.status.code(), Some(0));
    assert_eq!(
        String::from_utf8_lossy(&tool.stdout),
        "(No static deltas)\n"
    );
    assert_ne!(port.status.code(), Some(0));
    assert!(port.stdout.is_empty());

    let garbage = repo.join("deltas/zz/garbage");
    std::fs::create_dir_all(&garbage).unwrap();
    std::fs::write(garbage.join("superblock"), b"superblock").unwrap();
    let args = ["static-delta", repo_arg.as_str(), "list"];
    let (port, tool) = (ostrya(&args, None, &[]), ostree(&args));
    assert_eq!(tool.status.code(), Some(0));
    assert_eq!(String::from_utf8_lossy(&tool.stdout).lines().count(), 1);
    assert_eq!(port.status.code(), Some(1));
    assert!(port.stdout.is_empty());
}

/// What `lay_delta_tree` places in a `deltas/` tree.
#[derive(Clone, Copy, Debug)]
enum DeltaTreeCase {
    /// The delta from a source commit moves out, and a symlink at its delta
    /// path points to it.
    LeafSymlink,
    /// The fanout that both deltas share moves out, and a symlink points to it.
    FanoutSymlink,
    /// A regular file directly under `deltas/`.
    File,
    /// A symlink to itself at a delta path.
    LeafLoop,
    /// A symlink to itself used as a fanout.
    FanoutLoop,
    /// A directory at a delta path, with a `superblock` that is a symlink to
    /// itself.
    SuperblockLoop,
    /// The whole `deltas/` directory moves out, and a symlink at `deltas`
    /// points to it.
    DeltasSymlink,
    /// A symlink at `deltas` that points to nothing.
    DeltasDangling,
    /// A regular file at `deltas`.
    DeltasFile,
}

/// Copies `repo` to `base/<tag>/repo` and places `case` in the copy. The
/// `deltas/` of `repo` holds a delta from scratch to `c1` and a delta from `c1`
/// to `c2` under one fanout. The target of each symlink moves to
/// `base/<tag>/outside`. Each symlink names its target relative to itself, so
/// `describe_tree` gives the same lines for two copies.
fn lay_delta_tree(
    base: &Path,
    repo: &Path,
    tag: &str,
    case: DeltaTreeCase,
    c1: &str,
    c2: &str,
) -> PathBuf {
    std::fs::create_dir_all(base.join(tag)).unwrap();
    let copy = clone_repo(base, repo, &format!("{tag}/repo"));
    let outside = base.join(tag).join("outside");
    std::fs::create_dir(&outside).unwrap();
    let from = Checksum::from_hex(c1).unwrap();
    let to = Checksum::from_hex(c2).unwrap();
    let pair = copy.join(ostrya::static_delta_relative_dir(Some(&from), &to));
    let fanout = pair.parent().unwrap().to_owned();
    let deltas = copy.join("deltas");
    let symlink = |target: &str, link: &Path| std::os::unix::fs::symlink(target, link).unwrap();
    match case {
        DeltaTreeCase::LeafSymlink => {
            std::fs::rename(&pair, outside.join("leaf")).unwrap();
            symlink("../../../outside/leaf", &pair);
        }
        DeltaTreeCase::FanoutSymlink => {
            std::fs::rename(&fanout, outside.join("fanout")).unwrap();
            symlink("../../outside/fanout", &fanout);
        }
        DeltaTreeCase::File => std::fs::write(deltas.join("file"), b"file\n").unwrap(),
        DeltaTreeCase::LeafLoop => symlink("loop", &fanout.join("loop")),
        DeltaTreeCase::FanoutLoop => symlink("floop", &deltas.join("floop")),
        DeltaTreeCase::SuperblockLoop => {
            std::fs::create_dir(fanout.join("zz")).unwrap();
            symlink("superblock", &fanout.join("zz/superblock"));
        }
        DeltaTreeCase::DeltasSymlink => {
            std::fs::rename(&deltas, outside.join("deltas")).unwrap();
            symlink("../outside/deltas", &deltas);
        }
        DeltaTreeCase::DeltasDangling => {
            std::fs::remove_dir_all(&deltas).unwrap();
            symlink("../outside/none", &deltas);
        }
        DeltaTreeCase::DeltasFile => {
            std::fs::remove_dir_all(&deltas).unwrap();
            std::fs::write(&deltas, b"file\n").unwrap();
        }
    }
    copy
}

/// Returns the delta names and digests in the `Static Deltas` line of
/// `summary --view` of the `ostree` command on `repo`. The list is sorted,
/// because `ostree` writes the map in the order of a hash table. The list is
/// empty if the summary holds no delta.
fn summary_delta_entries(repo: &Path) -> Vec<String> {
    let run = ostree(&["summary", &format!("--repo={}", repo.display()), "--view"]);
    assert!(
        run.status.success(),
        "{}",
        String::from_utf8_lossy(&run.stderr)
    );
    let text = String::from_utf8_lossy(&run.stdout);
    let Some(line) = text.lines().find(|line| line.starts_with("Static Deltas")) else {
        return Vec::new();
    };
    let map = line.split_once(": {").unwrap().1.trim_end_matches('}');
    let mut entries: Vec<String> = map.split(">, ").map(str::to_owned).collect();
    for entry in &mut entries {
        if !entry.ends_with('>') {
            entry.push('>');
        }
    }
    entries.sort();
    entries
}

/// `list`, `reindex`, and `summary -u` agree on a `deltas/` tree that holds a
/// symlink, a file, or a symlink loop:
///
/// - The scan follows no symlink at a delta path or used as a fanout. The
///   commands do not list, index, or advertise the deltas behind it.
/// - The scan skips a regular file directly under `deltas/`, and a symlink
///   loop at a delta path or used as a fanout.
/// - The scan follows a symlink at `deltas` itself. The commands list, index,
///   and advertise the deltas behind it.
/// - A dangling symlink at `deltas` holds no delta.
/// - A `superblock` that is a symlink loop and a regular file at `deltas`
///   cause a refusal of all three commands at exit 1.
///
/// The test carries `static-delta/list-skips-dir-without-superblock`.
#[test]
fn static_delta_scan_follows_no_symlink_like_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-scan-symlinks");
    let base = tmp.path();
    let (repo, c1, c2) = delta_show_repo(base, "repo");
    ostree_ok(&repo, &["static-delta", "generate", "--empty", "--to", &c1]);
    ostree_ok(
        &repo,
        &["static-delta", "generate", "--from", &c1, "--to", &c2],
    );
    let _ = std::fs::remove_dir_all(repo.join("delta-indexes"));
    let lines = |run: &Run| {
        let mut lines: Vec<String> = String::from_utf8_lossy(&run.stdout)
            .lines()
            .map(str::to_owned)
            .collect();
        lines.sort();
        lines
    };
    for case in [
        DeltaTreeCase::LeafSymlink,
        DeltaTreeCase::FanoutSymlink,
        DeltaTreeCase::File,
        DeltaTreeCase::LeafLoop,
        DeltaTreeCase::FanoutLoop,
        DeltaTreeCase::SuperblockLoop,
        DeltaTreeCase::DeltasSymlink,
        DeltaTreeCase::DeltasDangling,
        DeltaTreeCase::DeltasFile,
    ] {
        let port_repo = lay_delta_tree(base, &repo, &format!("{case:?}-port"), case, &c1, &c2);
        let tool_repo = lay_delta_tree(base, &repo, &format!("{case:?}-tool"), case, &c1, &c2);
        let run = |args: &[&str]| {
            let port_arg = format!("--repo={}", port_repo.display());
            let tool_arg = format!("--repo={}", tool_repo.display());
            let mut port_args = vec![args[0], port_arg.as_str()];
            port_args.extend_from_slice(&args[1..]);
            let mut tool_args = vec![args[0], tool_arg.as_str()];
            tool_args.extend_from_slice(&args[1..]);
            (ostrya(&port_args, None, &[]), ostree(&tool_args))
        };
        let (port, tool) = run(&["static-delta", "list"]);
        assert_eq!(port.status.code(), tool.status.code(), "{case:?} list");
        assert_eq!(lines(&port), lines(&tool), "{case:?} list");
        if matches!(
            case,
            DeltaTreeCase::SuperblockLoop | DeltaTreeCase::DeltasFile
        ) {
            assert_eq!(tool.status.code(), Some(1), "{case:?} list");
            for args in [&["static-delta", "reindex"][..], &["summary", "-u"]] {
                let (port, tool) = run(args);
                assert_eq!(port.status.code(), Some(1), "{case:?} {args:?}");
                assert_eq!(tool.status.code(), Some(1), "{case:?} {args:?}");
            }
            continue;
        }
        assert!(tool.status.success() && tool.stderr.is_empty(), "{case:?}");
        let (port, tool) = run(&["static-delta", "reindex"]);
        assert_runs_agree(&port, &tool, &format!("static-delta reindex ({case:?})"));
        let indexes = |repo: &Path| {
            let dir = repo.join("delta-indexes");
            dir.exists().then(|| describe_tree(&dir))
        };
        assert_eq!(indexes(&port_repo), indexes(&tool_repo), "{case:?} reindex");
        let (port, tool) = run(&["summary", "-u"]);
        assert_runs_agree(&port, &tool, &format!("summary -u ({case:?})"));
        let entries = summary_delta_entries(&port_repo);
        assert_eq!(
            entries,
            summary_delta_entries(&tool_repo),
            "{case:?} summary"
        );
        let advertised = match case {
            DeltaTreeCase::LeafSymlink => 1,
            DeltaTreeCase::FanoutSymlink | DeltaTreeCase::DeltasDangling => 0,
            _ => 2,
        };
        assert_eq!(entries.len(), advertised, "{case:?} summary");
    }
}

/// The static-delta sweep of a prune agrees on a `deltas/` tree that holds a
/// symlink, a file, or a symlink loop:
///
/// - The sweep follows no symlink at a delta path or at a fanout, and it skips
///   a regular file directly under `deltas/`. The deltas behind a symlink
///   stay, and the run exits 0.
/// - The sweep follows a symlink at `deltas` itself and removes the delta
///   behind it.
/// - A dangling symlink at `deltas` holds no delta, and the run exits 0.
#[test]
fn prune_static_delta_sweep_follows_no_symlink_like_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("prune-delta-symlinks");
    let base = tmp.path();
    let (repo, c1, c2) = delta_show_repo(base, "repo");
    ostree_ok(&repo, &["static-delta", "generate", "--empty", "--to", &c1]);
    ostree_ok(
        &repo,
        &["static-delta", "generate", "--from", &c1, "--to", &c2],
    );
    let delete = format!("--delete-commit={c2}");
    for case in [
        DeltaTreeCase::LeafSymlink,
        DeltaTreeCase::FanoutSymlink,
        DeltaTreeCase::File,
        DeltaTreeCase::LeafLoop,
        DeltaTreeCase::FanoutLoop,
        DeltaTreeCase::DeltasSymlink,
        DeltaTreeCase::DeltasDangling,
    ] {
        let port_repo = lay_delta_tree(base, &repo, &format!("{case:?}-port"), case, &c1, &c2);
        let tool_repo = lay_delta_tree(base, &repo, &format!("{case:?}-tool"), case, &c1, &c2);
        let port_arg = format!("--repo={}", port_repo.display());
        let tool_arg = format!("--repo={}", tool_repo.display());
        let args = |repo_arg| ["prune", repo_arg, "--static-deltas-only", delete.as_str()];
        let port = ostrya(&args(port_arg.as_str()), None, &PRUNE_ENV);
        let tool = ostree_env(&args(tool_arg.as_str()), &PRUNE_ENV);
        assert_runs_agree(&port, &tool, &format!("prune ({case:?})"));
        port.ok();
        for dir in ["repo/deltas", "outside"] {
            let at = |repo: &Path| {
                let path = repo.parent().unwrap().join(dir);
                match std::fs::read_link(&path) {
                    Ok(target) => vec![format!("symlink -> {}", target.display())],
                    Err(_) => describe_tree(&path),
                }
            };
            assert_eq!(at(&port_repo), at(&tool_repo), "{case:?} {dir}");
        }
        if matches!(case, DeltaTreeCase::DeltasSymlink) {
            let deltas = port_repo.join("deltas");
            assert!(deltas.join(scratch_dir(&c1)).join("superblock").exists());
            assert!(!deltas.join(pair_dir(&c1, &c2)).exists());
        }
    }
}

/// Returns the path of the delta from scratch to `to`, relative to `deltas/`.
fn scratch_dir(to: &str) -> PathBuf {
    let to = Checksum::from_hex(to).unwrap();
    let dir = ostrya::static_delta_relative_dir(None, &to);
    PathBuf::from(dir.strip_prefix("deltas/").unwrap())
}

/// Returns the path of the delta from `from` to `to`, relative to `deltas/`.
fn pair_dir(from: &str, to: &str) -> PathBuf {
    let from = Checksum::from_hex(from).unwrap();
    let to = Checksum::from_hex(to).unwrap();
    let dir = ostrya::static_delta_relative_dir(Some(&from), &to);
    PathBuf::from(dir.strip_prefix("deltas/").unwrap())
}

/// `delete` agrees if `deltas` is a symlink. The command follows a symlink at
/// `deltas`, removes the delta behind it, and keeps the link. A dangling
/// symlink at `deltas` holds no delta, and both commands refuse at exit 1.
#[test]
fn static_delta_delete_follows_a_deltas_symlink_like_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-delete-deltas-symlink");
    let base = tmp.path();
    let (repo, c1, c2) = delta_show_repo(base, "repo");
    ostree_ok(&repo, &["static-delta", "generate", "--empty", "--to", &c1]);
    ostree_ok(
        &repo,
        &["static-delta", "generate", "--from", &c1, "--to", &c2],
    );
    let name = format!("{c1}-{c2}");
    for case in [DeltaTreeCase::DeltasSymlink, DeltaTreeCase::DeltasDangling] {
        let port_repo = lay_delta_tree(base, &repo, &format!("{case:?}-port"), case, &c1, &c2);
        let tool_repo = lay_delta_tree(base, &repo, &format!("{case:?}-tool"), case, &c1, &c2);
        let (port, tool) = run_delta_delete(&port_repo, &tool_repo, &[&name]);
        assert_eq!(port.status.code(), tool.status.code(), "{case:?}");
        let outside = |repo: &Path| describe_tree(&repo.parent().unwrap().join("outside"));
        assert_eq!(outside(&port_repo), outside(&tool_repo), "{case:?}");
        for repo in [&port_repo, &tool_repo] {
            assert!(repo.join("deltas").symlink_metadata().unwrap().is_symlink());
        }
        if matches!(case, DeltaTreeCase::DeltasSymlink) {
            port.ok();
            let deltas = port_repo.join("deltas");
            assert!(deltas.join(scratch_dir(&c1)).join("superblock").exists());
            assert!(!deltas.join(pair_dir(&c1, &c2)).exists());
        } else {
            assert_eq!(tool.status.code(), Some(1), "{case:?}");
        }
    }
}

/// Runs `static-delta delete` with `args` in each command on its own
/// repository. The repository is given in the `=` form that the `ostree`
/// command reads.
fn run_delta_delete(port_repo: &Path, tool_repo: &Path, args: &[&str]) -> (Run, Run) {
    let run = |repo: &Path, tool: bool| {
        let repo_arg = format!("--repo={}", repo.display());
        let mut all = vec!["static-delta", repo_arg.as_str(), "delete"];
        all.extend_from_slice(args);
        if tool {
            ostree(&all)
        } else {
            ostrya(&all, None, &[])
        }
    };
    (run(port_repo, false), run(tool_repo, true))
}

/// `delete` agrees:
///
/// - It writes no output, and it exits 0.
/// - It removes the whole entry at the delta path, for each kind of entry.
/// - It removes a symlink as a link.
/// - It does not change the fanout, `delta-indexes/`, or `summary`, so
///   `indexes` still lists the targets.
///
/// The test carries `static-delta/delete-ok` and
/// `static-delta/delete-leaves-index`.
#[test]
fn static_delta_delete_matches_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-delete");
    let (tool_repo, c1, c2) = delta_show_repo(tmp.path(), "tool");
    ostree_ok(
        &tool_repo,
        &["static-delta", "generate", "--empty", "--to", &c1],
    );
    ostree_ok(
        &tool_repo,
        &["static-delta", "generate", "--from", &c1, "--to", &c2],
    );
    ostree_ok(&tool_repo, &["static-delta", "reindex"]);
    ostree_ok(&tool_repo, &["summary", "-u"]);
    let to1 = Checksum::from_hex(&c1).unwrap();
    let to2 = Checksum::from_hex(&c2).unwrap();
    let nested = tool_repo.join(ostrya::static_delta_relative_dir(None, &to1));
    std::fs::create_dir_all(nested.join("n1/n2")).unwrap();
    std::fs::write(nested.join("n1/n2/f"), b"nested\n").unwrap();
    let outside = tmp.path().join("outside");
    std::fs::create_dir(&outside).unwrap();
    std::fs::write(outside.join("file"), b"keep\n").unwrap();
    let scratch2 = ostrya::static_delta_relative_dir(None, &to2);
    let fanout2 = tool_repo.join(&scratch2);
    std::fs::create_dir_all(fanout2.parent().unwrap()).unwrap();
    std::fs::write(tool_repo.join(&scratch2), b"not a delta\n").unwrap();
    let summary = std::fs::read(tool_repo.join("summary")).unwrap();
    let port_repo = clone_repo(tmp.path(), &tool_repo, "port");

    let from_to = format!("{c1}-{c2}");
    // What each step places at the from-scratch path of `c2` before it runs,
    // in both repositories.
    enum Place {
        Nothing,
        LinkToOutside,
        EmptyDir,
    }
    let steps = [
        (c1.as_str(), Place::Nothing),
        (from_to.as_str(), Place::Nothing),
        (c2.as_str(), Place::Nothing),
        (c2.as_str(), Place::LinkToOutside),
        (c2.as_str(), Place::EmptyDir),
    ];
    for (name, place) in steps {
        for repo in [&port_repo, &tool_repo] {
            match place {
                Place::Nothing => {}
                Place::LinkToOutside => {
                    std::os::unix::fs::symlink(&outside, repo.join(&scratch2)).unwrap()
                }
                Place::EmptyDir => std::fs::create_dir(repo.join(&scratch2)).unwrap(),
            }
        }
        let (port, tool) = run_delta_delete(&port_repo, &tool_repo, &[name]);
        assert_runs_agree(&port, &tool, &format!("static-delta delete {name}"));
        port.ok();
        assert!(port.stdout.is_empty() && port.stderr.is_empty(), "{name}");
        assert_eq!(
            describe_tree(&port_repo.join("deltas")),
            describe_tree(&tool_repo.join("deltas")),
            "{name}"
        );
    }
    assert!(
        std::fs::read_dir(port_repo.join("deltas"))
            .unwrap()
            .all(|fanout| std::fs::read_dir(fanout.unwrap().path())
                .unwrap()
                .next()
                .is_none()),
        "every delta is gone and every fanout stays"
    );
    assert_eq!(std::fs::read(outside.join("file")).unwrap(), b"keep\n");
    assert_eq!(
        describe_tree_with_content(&port_repo.join("delta-indexes")),
        describe_tree_with_content(&tool_repo.join("delta-indexes")),
    );
    for repo in [&port_repo, &tool_repo] {
        assert_eq!(std::fs::read(repo.join("summary")).unwrap(), summary);
    }
    let repo_arg = format!("--repo={}", port_repo.display());
    let port = ostrya(&["static-delta", &repo_arg, "indexes"], None, &[]);
    let repo_arg = format!("--repo={}", tool_repo.display());
    let tool = ostree(&["static-delta", &repo_arg, "indexes"]);
    let lines = |run: &Run| {
        let mut lines: Vec<String> = String::from_utf8_lossy(&run.stdout)
            .lines()
            .map(str::to_owned)
            .collect();
        lines.sort();
        lines
    };
    port.ok();
    let mut expected = vec![c1.clone(), c2.clone()];
    expected.sort();
    assert_eq!(lines(&port), lines(&tool));
    assert_eq!(lines(&port), expected, "the index still lists both targets");
}

/// The refusals of `delete` agree for these arguments:
///
/// - no argument
/// - a name that the parser refuses
/// - a path
/// - an absent delta, which includes a dangling symlink at the delta path and
///   a missing `deltas/`
///
/// An extra positional and a symlink loop are the recorded divergences.
/// The test carries `static-delta/delete-absent`.
#[test]
fn static_delta_delete_refusals_match_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-delete-refusals");
    let (tool_repo, c1, c2) = delta_show_repo(tmp.path(), "tool");
    ostree_ok(
        &tool_repo,
        &["static-delta", "generate", "--empty", "--to", &c1],
    );
    let port_repo = clone_repo(tmp.path(), &tool_repo, "port");
    let to1 = Checksum::from_hex(&c1).unwrap();
    let to2 = Checksum::from_hex(&c2).unwrap();
    let relative = ostrya::static_delta_relative_dir(None, &to1);
    let superblock = format!("{relative}/superblock");
    let upper = c1.to_uppercase();
    let agree = |args: &[&str]| {
        let (port, tool) = run_delta_delete(&port_repo, &tool_repo, args);
        let label = format!("static-delta delete {}", args.join(" "));
        assert_runs_agree(&port, &tool, &label);
        assert_eq!(port.status.code(), Some(1), "{label}");
        assert!(port.stdout.is_empty(), "{label}");
        port
    };
    let deltas = |repo: &Path| describe_tree(&repo.join("deltas"));
    let before = deltas(&tool_repo);

    let port = agree(&[]);
    assert_eq!(
        String::from_utf8_lossy(&port.stderr),
        "error: DELTA must be specified\n"
    );
    for arg in [
        "ABC",
        "m",
        &c1[..10],
        upper.as_str(),
        "a/b-c",
        "./x",
        relative.as_str(),
        superblock.as_str(),
        "",
        "C-",
    ] {
        agree(&[arg]);
    }
    assert_eq!(deltas(&port_repo), before);
    assert_eq!(deltas(&tool_repo), before);

    let not_found = format!("error: Can't find delta {c2}\n");
    let port = agree(&[&c2]);
    assert_eq!(String::from_utf8_lossy(&port.stderr), not_found);

    // A dangling symlink at the delta path is an absent delta, and the symlink
    // stays.
    let scratch2 = ostrya::static_delta_relative_dir(None, &to2);
    for repo in [&port_repo, &tool_repo] {
        let link = repo.join(&scratch2);
        std::fs::create_dir_all(link.parent().unwrap()).unwrap();
        std::os::unix::fs::symlink("nowhere", &link).unwrap();
    }
    let port = agree(&[&c2]);
    assert_eq!(String::from_utf8_lossy(&port.stderr), not_found);
    for repo in [&port_repo, &tool_repo] {
        assert!(std::fs::symlink_metadata(repo.join(&scratch2)).is_ok());
        std::fs::remove_file(repo.join(&scratch2)).unwrap();
    }

    // A symlink loop at the delta path fails in both commands, with different
    // messages.
    let leaf = Path::new(&scratch2).file_name().unwrap().to_owned();
    for repo in [&port_repo, &tool_repo] {
        std::os::unix::fs::symlink(&leaf, repo.join(&scratch2)).unwrap();
    }
    let (port, tool) = run_delta_delete(&port_repo, &tool_repo, &[&c2]);
    for run in [&port, &tool] {
        assert_eq!(run.status.code(), Some(1));
        assert!(run.stdout.is_empty());
    }
    assert!(
        String::from_utf8_lossy(&tool.stderr).contains("Too many levels of symbolic links"),
        "{}",
        String::from_utf8_lossy(&tool.stderr)
    );
    assert!(
        String::from_utf8_lossy(&port.stderr).starts_with("error: i/o error: "),
        "{}",
        String::from_utf8_lossy(&port.stderr)
    );
    for repo in [&port_repo, &tool_repo] {
        std::fs::remove_file(repo.join(&scratch2)).unwrap();
    }

    // An extra positional: the `ostree` command ignores it and removes the
    // delta. ostrya refuses it and removes nothing.
    let before = deltas(&port_repo);
    let (port, tool) = run_delta_delete(&port_repo, &tool_repo, &[&c1, "extra"]);
    assert_eq!(tool.status.code(), Some(0));
    assert_eq!(port.status.code(), Some(1));
    assert!(
        String::from_utf8_lossy(&port.stderr).contains("unexpected argument 'extra'"),
        "{}",
        String::from_utf8_lossy(&port.stderr)
    );
    assert_eq!(deltas(&port_repo), before);
    std::fs::remove_dir_all(port_repo.join(&relative)).unwrap();

    // A missing `deltas/` is an absent delta.
    for repo in [&port_repo, &tool_repo] {
        std::fs::remove_dir_all(repo.join("deltas")).unwrap();
    }
    let port = agree(&[&c1]);
    assert_eq!(
        String::from_utf8_lossy(&port.stderr),
        format!("error: Can't find delta {c1}\n")
    );
}

// --- static-delta verify ------------------------------------------------------

/// The public key of `ED25519_SECRET2_B64`.
const ED25519_PUBLIC2_B64: &str = "5WYA48XDLt1Tw6UD6mF5sMzJRCXqpaUjPPrO2C37pto=";
/// The hex of `ED25519_PUBLIC2_B64`, as a failure line names the key.
const ED25519_PUBLIC2_HEX: &str =
    "e56600e3c5c32edd53c3a503ea6179b0ccc94425eaa5a5233cfaced82dfba6da";
/// A 32-byte ed25519 public key of all zero bytes: a valid curve point that
/// verifies no signature.
const ED25519_ZERO_B64: &str = "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=";
/// 32 bytes that decode to no point on the curve.
const ED25519_NOT_A_POINT_B64: &str = "AgAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=";

/// Creates the fixture repository with a from-scratch delta to `COMMIT` that
/// ostrya signs with the shared key. It also writes an unsigned delta of the
/// same commit to `base/unsigned`.
fn verify_fixture(base: &Path) -> PathBuf {
    let repo = commit_fixture(base);
    let repo_s = repo.to_str().unwrap();
    let sign = format!("--sign={ED25519_SECRET_B64}");
    let generate = ["static-delta", "--repo", repo_s, "generate"];
    let pinned = ["--timestamp=1700000000", "--empty", "--to", COMMIT];
    ostrya(&[&generate[..], &pinned[..], &[&sign]].concat(), None, &[]).ok();
    let out = format!("--output-dir={}", base.join("unsigned").display());
    ostrya(&[&generate[..], &pinned[..], &[&out]].concat(), None, &[]).ok();
    repo
}

/// Runs `static-delta verify ARGS` on `repo` from `cwd`.
fn run_delta_verify(cwd: &Path, repo: &Path, args: &[&str]) -> Run {
    let repo_arg = format!("--repo={}", repo.display());
    let all = [&["static-delta", repo_arg.as_str(), "verify"][..], args].concat();
    ostrya_in(Some(cwd), &all, None, &[])
}

/// Asserts the exit status and both streams of a `static-delta verify` run.
fn assert_verify_run(run: &Run, code: i32, stdout: &str, stderr: &str, label: &str) {
    assert_eq!(
        (
            run.status.code(),
            String::from_utf8_lossy(&run.stdout).into_owned(),
            String::from_utf8_lossy(&run.stderr).into_owned(),
        ),
        (Some(code), stdout.to_owned(), stderr.to_owned()),
        "{label}"
    );
}

/// Returns the key-list failure line for `hexes`, in the order that the line
/// names them.
fn verify_key_list_error(hexes: &[&str]) -> String {
    let keys: Vec<String> = hexes.iter().map(|hex| format!("key '{hex}'")).collect();
    format!(
        "error: ed25519: Signature couldn't be verified with: {}\n",
        keys.join("; ")
    )
}

/// Writes a key store under `base/<name>`, with the `trusted` lines in
/// `trusted.ed25519` and the `revoked` lines in `revoked.ed25519`. It writes
/// each file only if its list is not empty.
fn verify_key_store(base: &Path, name: &str, trusted: &[&str], revoked: &[&str]) -> PathBuf {
    let dir = base.join(name);
    std::fs::create_dir_all(&dir).unwrap();
    for (file, keys) in [("trusted.ed25519", trusted), ("revoked.ed25519", revoked)] {
        if !keys.is_empty() {
            std::fs::write(dir.join(file), format!("{}\n", keys.join("\n"))).unwrap();
        }
    }
    dir
}

/// With the signing key, `static-delta verify` prints `Verification OK` at
/// exit 0. With each other key, it prints `Verification fails` and the
/// key-list line at exit 1. The line names the keys in reverse order.
#[test]
fn static_delta_verify_reports_ok_and_fails() {
    let tmp = TmpDir::new("delta-verify-ok");
    let base = tmp.path();
    let repo = verify_fixture(base);
    let run = |args: &[&str]| run_delta_verify(base, &repo, args);

    assert_verify_run(
        &run(&[COMMIT, ED25519_PUBLIC_B64]),
        0,
        "Verification OK\n",
        "",
        "ok",
    );
    assert_verify_run(
        &run(&[COMMIT, ED25519_PUBLIC2_B64]),
        1,
        "Verification fails\n",
        &verify_key_list_error(&[ED25519_PUBLIC2_HEX]),
        "wrong key",
    );
    assert_verify_run(
        &run(&[COMMIT, ED25519_PUBLIC2_B64, ED25519_PUBLIC_B64]),
        0,
        "Verification OK\n",
        "",
        "wrong then right",
    );
    assert_verify_run(
        &run(&[COMMIT, ED25519_PUBLIC2_B64, ED25519_ZERO_B64]),
        1,
        "Verification fails\n",
        &verify_key_list_error(&[&"0".repeat(64), ED25519_PUBLIC2_HEX]),
        "two wrong keys",
    );
    let unsigned = base.join("unsigned/superblock");
    assert_verify_run(
        &run(&[unsigned.to_str().unwrap(), ED25519_PUBLIC_B64]),
        1,
        "Verification fails\n",
        "error: no signatures in static-delta\n",
        "unsigned",
    );
}

/// The key sources:
///
/// - The positionals and the last `--keys-file` combine.
/// - If either one is given, the command does not read `--keys-dir`.
/// - The command reads the last `--keys-dir`, with its `.d` directory and its
///   revoked set.
/// - The command checks for `no keys loaded` before it applies revocation.
#[test]
fn static_delta_verify_key_sources() {
    let tmp = TmpDir::new("delta-verify-keys");
    let base = tmp.path();
    let repo = verify_fixture(base);
    let run = |args: &[&str]| run_delta_verify(base, &repo, args);
    let ok = |args: &[&str], label: &str| {
        assert_verify_run(&run(args), 0, "Verification OK\n", "", label);
    };
    let fails = |args: &[&str], stderr: &str, label: &str| {
        assert_verify_run(&run(args), 1, "Verification fails\n", stderr, label);
    };
    let refused = |args: &[&str], stderr: &str, label: &str| {
        assert_verify_run(&run(args), 1, "", stderr, label);
    };
    std::fs::write(base.join("k1"), format!("{ED25519_PUBLIC_B64}\n")).unwrap();
    std::fs::write(base.join("k2"), format!("{ED25519_PUBLIC2_B64}\n")).unwrap();
    std::fs::write(base.join("kz"), format!("{ED25519_ZERO_B64}\n")).unwrap();
    verify_key_store(base, "store1", &[ED25519_PUBLIC_B64], &[]);
    verify_key_store(base, "store2", &[ED25519_PUBLIC2_B64], &[]);
    verify_key_store(
        base,
        "revoked",
        &[ED25519_PUBLIC_B64],
        &[ED25519_PUBLIC_B64],
    );
    verify_key_store(base, "only-revoked", &[], &[ED25519_PUBLIC_B64]);
    verify_key_store(
        base,
        "some-revoked",
        &[ED25519_PUBLIC2_B64, ED25519_ZERO_B64],
        &[ED25519_ZERO_B64],
    );
    let dotd = base.join("dotd/trusted.ed25519.d");
    std::fs::create_dir_all(&dotd).unwrap();
    std::fs::write(dotd.join("key"), format!("{ED25519_PUBLIC_B64}\n")).unwrap();

    ok(&["--keys-file=k1", COMMIT], "keys file");
    ok(
        &["--keys-file=k2", "--keys-file=k1", COMMIT],
        "last keys file, right",
    );
    fails(
        &["--keys-file=k1", "--keys-file=k2", COMMIT],
        &verify_key_list_error(&[ED25519_PUBLIC2_HEX]),
        "last keys file, wrong",
    );
    ok(
        &["--keys-file=k1", COMMIT, ED25519_PUBLIC2_B64],
        "positional and file",
    );
    fails(
        &["--keys-file=kz", COMMIT, ED25519_PUBLIC2_B64],
        &verify_key_list_error(&[&"0".repeat(64), ED25519_PUBLIC2_HEX]),
        "positional before file lines, listed reversed",
    );
    fails(
        &["--keys-dir=store1", "--keys-file=k2", COMMIT],
        &verify_key_list_error(&[ED25519_PUBLIC2_HEX]),
        "a keys file makes keys-dir unread",
    );
    fails(
        &["--keys-dir=store1", COMMIT, ED25519_PUBLIC2_B64],
        &verify_key_list_error(&[ED25519_PUBLIC2_HEX]),
        "a positional makes keys-dir unread",
    );
    ok(&["--keys-dir=store1", COMMIT], "keys dir");
    ok(
        &["--keys-dir=store2", "--keys-dir=store1", COMMIT],
        "last keys dir, right",
    );
    fails(
        &["--keys-dir=store1", "--keys-dir=store2", COMMIT],
        &verify_key_list_error(&[ED25519_PUBLIC2_HEX]),
        "last keys dir, wrong",
    );
    ok(&["--keys-dir=dotd", COMMIT], "trusted.ed25519.d");
    fails(
        &["--keys-dir=revoked", COMMIT],
        "error: ed25519: no signatures found\n",
        "every trusted key revoked",
    );
    // A key given twice is named once, at its first place.
    verify_key_store(
        base,
        "dups",
        &[ED25519_PUBLIC2_B64, ED25519_ZERO_B64, ED25519_PUBLIC2_B64],
        &[],
    );
    let zero_then_2 = verify_key_list_error(&["0".repeat(64).as_str(), ED25519_PUBLIC2_HEX]);
    fails(
        &[
            COMMIT,
            ED25519_PUBLIC2_B64,
            ED25519_ZERO_B64,
            ED25519_PUBLIC2_B64,
        ],
        &zero_then_2,
        "duplicate positionals",
    );
    fails(
        &[
            "--keys-file=kz",
            COMMIT,
            ED25519_PUBLIC2_B64,
            ED25519_ZERO_B64,
        ],
        &zero_then_2,
        "a positional repeated in the keys file",
    );
    fails(
        &["--keys-dir=dups", COMMIT],
        &zero_then_2,
        "duplicate store keys",
    );
    fails(
        &["--keys-dir=some-revoked", COMMIT],
        &verify_key_list_error(&[ED25519_PUBLIC2_HEX]),
        "a revoked key is left out of the failure line",
    );
    refused(
        &["--keys-dir=only-revoked", COMMIT],
        "error: signature: ed25519: no keys loaded\n",
        "revoked keys alone",
    );
    refused(
        &["--keys-dir=nodir", COMMIT],
        "error: signature: ed25519: no keys loaded\n",
        "absent keys dir",
    );
    refused(
        &["--keys-dir=nodir", "m"],
        "error: signature: ed25519: no keys loaded\n",
        "the keys load before the argument resolves",
    );

    // The reader skips empty lines and lone `\r` lines. It reads CRLF,
    // padding, and a character outside the alphabet leniently.
    let junk = format!("{}!{}", &ED25519_PUBLIC_B64[..4], &ED25519_PUBLIC_B64[4..]);
    std::fs::write(base.join("lenient"), format!("\n\r\n  {junk}  \r\n\n")).unwrap();
    ok(&["--keys-file=lenient", COMMIT], "lenient keys file");
    ok(&[COMMIT, &format!(" {junk}\t")], "lenient positional");

    std::fs::write(base.join("empty"), b"").unwrap();
    refused(
        &["--keys-file=empty", COMMIT],
        "error: signature: ed25519: no valid keys in file 'empty'\n",
        "empty keys file",
    );
    std::fs::write(base.join("blank"), b"\n\r\n").unwrap();
    refused(
        &["--keys-file=blank", COMMIT],
        "error: signature: ed25519: no valid keys in file 'blank'\n",
        "blank keys file",
    );
    // A line of whitespace is a key of zero bytes.
    let no_byte = "error: Invalid ed25519 public key: Ill-formed input: expected 32 bytes, \
                   got 0 bytes\n";
    for (name, text) in [
        ("ws3", "   \n".to_owned()),
        ("ws1", " \n".to_owned()),
        ("wscr", " \r\n".to_owned()),
        ("ws-beside", format!("{ED25519_PUBLIC_B64}\n   \n")),
    ] {
        std::fs::write(base.join(name), text).unwrap();
        refused(&[&format!("--keys-file={name}"), COMMIT], no_byte, name);
    }
    mkfifo_at(&base.join("fifo"));
    std::fs::create_dir_all(base.join("dir")).unwrap();
    for path in ["nosuch", "dir", "fifo", ""] {
        refused(
            &[&format!("--keys-file={path}"), COMMIT],
            &format!("error: File object '{path}' is not a regular file\n"),
            path,
        );
    }
    std::os::unix::fs::symlink("k1", base.join("link")).unwrap();
    ok(&["--keys-file=link", COMMIT], "a symlink to a keys file");

    let mut big = format!("{ED25519_PUBLIC_B64}\n").into_bytes();
    big.resize(1024 * 1024 + 1, b'\n');
    std::fs::write(base.join("big"), &big).unwrap();
    let run_big = run(&["--keys-file=big", COMMIT]);
    assert_eq!(run_big.status.code(), Some(1));
    assert!(run_big.stdout.is_empty());
    assert!(
        String::from_utf8_lossy(&run_big.stderr).contains("'big' is over the 1048576-byte ceiling"),
        "{}",
        String::from_utf8_lossy(&run_big.stderr)
    );
}

/// An invalid key causes a refusal before the command writes to standard
/// output:
///
/// - a positional of the wrong length
/// - a keys-file line of the wrong length, next to a valid line
/// - 32 bytes that are not a curve point, also next to the key that verifies
///   the delta
#[test]
fn static_delta_verify_refuses_invalid_keys_before_output() {
    let tmp = TmpDir::new("delta-verify-invalid");
    let base = tmp.path();
    let repo = verify_fixture(base);
    let run = |args: &[&str]| run_delta_verify(base, &repo, args);
    let wrong_length = "error: Invalid ed25519 public key: Ill-formed input: expected 32 bytes, \
                        got 3 bytes\n";
    assert_verify_run(
        &run(&[COMMIT, ED25519_PUBLIC_B64, "AAAA"]),
        1,
        "",
        wrong_length,
        "invalid positional",
    );
    std::fs::write(base.join("mixed"), format!("AAAA\n{ED25519_PUBLIC_B64}\n")).unwrap();
    assert_verify_run(
        &run(&["--keys-file=mixed", COMMIT]),
        1,
        "",
        wrong_length,
        "invalid keys-file line beside a valid one",
    );
    std::fs::write(base.join("latin1"), b"\xe9AAAAAAAA\n").unwrap();
    assert_verify_run(
        &run(&["--keys-file=latin1", COMMIT]),
        1,
        "",
        "error: Invalid ed25519 public key: Ill-formed input: expected 32 bytes, got 0 bytes\n",
        "a line that is not UTF-8 decodes to no byte",
    );
    for keys in [
        &[ED25519_NOT_A_POINT_B64][..],
        &[ED25519_PUBLIC_B64, ED25519_NOT_A_POINT_B64],
        &[ED25519_NOT_A_POINT_B64, ED25519_PUBLIC_B64],
    ] {
        let run_point = run(&[&[COMMIT][..], keys].concat());
        assert_eq!(run_point.status.code(), Some(1), "{keys:?}");
        assert!(run_point.stdout.is_empty(), "{keys:?}");
    }
}

/// The sign types:
///
/// - `ed25519` is the default.
/// - `dummy` refuses with its own message and writes nothing on standard
///   output.
/// - `gpg` and each unknown name print `Sign-type not supported`.
/// - The last `--sign-type` wins.
///
/// A build with the `spki` engine verifies a delta that ostrya signs with
/// this engine.
#[test]
fn static_delta_verify_sign_types() {
    let tmp = TmpDir::new("delta-verify-types");
    let base = tmp.path();
    let repo = verify_fixture(base);
    let run = |args: &[&str]| run_delta_verify(base, &repo, args);
    assert_verify_run(
        &run(&["--sign-type=dummy", COMMIT, ED25519_PUBLIC_B64]),
        1,
        "",
        "error: dummy signature type is only for ostree testing\n",
        "dummy",
    );
    for name in ["gpg", "nosuch", "", "ED25519"] {
        assert_verify_run(
            &run(&[&format!("--sign-type={name}"), COMMIT, ED25519_PUBLIC_B64]),
            1,
            "Sign-type not supported\n",
            "error: Requested signature type is not implemented\n",
            name,
        );
    }
    assert_verify_run(
        &run(&[
            "--sign-type=nosuch",
            "--sign-type=ed25519",
            COMMIT,
            ED25519_PUBLIC_B64,
        ]),
        0,
        "Verification OK\n",
        "",
        "last sign type wins",
    );

    #[cfg(feature = "spki")]
    {
        const SECRET_PKCS8_B64: &str = "MIGHAgEAMBMGByqGSM49AgEGCCqGSM49AwEHBG0wawIBAQQg2L708EsnnzHER0SYasMNIUcGv63QapC/3kVsoPerzKGhRANCAATxfzfHKUPeJtyLTGMUoxHhvBS1NT9guWhUQPGiZRLZIcB8Wc3csdVU1iOiTRmbZGKJTtekOdEAbVRrx5HxIpst";
        const PUBLIC_SPKI_B64: &str = "MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAE8X83xylD3ibci0xjFKMR4bwUtTU/YLloVEDxomUS2SHAfFnN3LHVVNYjok0Zm2RiiU7XpDnRAG1Ua8eR8SKbLQ==";
        const OTHER_SPKI_B64: &str = "MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAECmz6W9QPu0HuggzW4vGvsnvQIl4Jyl/b9kVl8fm/qw/xJSQfCEzhnGMQzmyj2quUo96zvuxlCllcTkzsOhwEAg==";
        let out = format!("--output-dir={}", base.join("spki").display());
        let sign = format!("--sign={SECRET_PKCS8_B64}");
        ostrya(
            &[
                "static-delta",
                "--repo",
                repo.to_str().unwrap(),
                "generate",
                "--empty",
                "--to",
                COMMIT,
                "--sign-type=spki",
                &sign,
                &out,
            ],
            None,
            &[],
        )
        .ok();
        let superblock = base.join("spki/superblock");
        let superblock = superblock.to_str().unwrap();
        assert_verify_run(
            &run(&["--sign-type=spki", superblock, PUBLIC_SPKI_B64]),
            0,
            "Verification OK\n",
            "",
            "spki",
        );
        let other = run(&["--sign-type=spki", superblock, OTHER_SPKI_B64]);
        assert_eq!(other.status.code(), Some(1));
        assert_eq!(
            String::from_utf8_lossy(&other.stdout),
            "Verification fails\n"
        );
        assert!(
            String::from_utf8_lossy(&other.stderr)
                .starts_with("error: spki: Signature couldn't be verified with: key '"),
            "{}",
            String::from_utf8_lossy(&other.stderr)
        );
        assert_verify_run(
            &run(&["--sign-type=spki", COMMIT, PUBLIC_SPKI_B64]),
            1,
            "Verification fails\n",
            "error: no signature for 'ostree.sign.spki' in static-delta superblock\n",
            "spki over an ed25519-signed delta",
        );
    }
}

/// The argument is a delta name, or a superblock path if it contains `/`.
/// The command reads only the superblock, so a copy with another name
/// verifies away from its parts. Each failure to resolve or read the argument
/// comes after `Verification fails`. If the argument is missing, the command
/// refuses before it reads the sign type.
#[test]
fn static_delta_verify_argument_forms() {
    let tmp = TmpDir::new("delta-verify-args");
    let base = tmp.path();
    let repo = verify_fixture(base);
    let run = |args: &[&str]| run_delta_verify(base, &repo, args);
    let relative = ostrya::static_delta_relative_dir(None, &Checksum::from_hex(COMMIT).unwrap());
    let in_repo = format!("repo/{relative}/superblock");
    std::fs::copy(base.join(&in_repo), base.join("sbcopy")).unwrap();
    let absolute = base.join("sbcopy");
    for arg in [in_repo.as_str(), "./sbcopy", absolute.to_str().unwrap()] {
        assert_verify_run(
            &run(&[arg, ED25519_PUBLIC_B64]),
            0,
            "Verification OK\n",
            "",
            arg,
        );
    }
    let fails = |args: &[&str], stderr: &str| {
        assert_verify_run(&run(args), 1, "Verification fails\n", stderr, args[0]);
    };
    fails(&["./", ED25519_PUBLIC_B64], "error: Is a directory\n");
    fails(
        &["./nosuch", ED25519_PUBLIC_B64],
        "error: openat(./nosuch): No such file or directory\n",
    );
    fails(&["m", ED25519_PUBLIC_B64], "error: Invalid rev m\n");
    let absent = format!("{COMMIT}-{COMMIT}");
    let absent_dir = ostrya::static_delta_relative_dir(
        Some(&Checksum::from_hex(COMMIT).unwrap()),
        &Checksum::from_hex(COMMIT).unwrap(),
    );
    fails(
        &[&absent, ED25519_PUBLIC_B64],
        &format!("error: openat({absent_dir}/superblock): No such file or directory\n"),
    );
    assert_verify_run(
        &run(&[]),
        1,
        "",
        "error: DELTA must be specified\n",
        "no argument",
    );
    assert_verify_run(
        &run(&["--sign-type=nosuch"]),
        1,
        "",
        "error: DELTA must be specified\n",
        "the argument check precedes the sign type",
    );
}

/// If the file is not a superblock, ostrya refuses after `Verification fails`
/// with the message of its parser. The `ostree` command reads only the magic.
#[test]
fn static_delta_verify_does_not_parse_as_the_tool_does() {
    let tmp = TmpDir::new("delta-verify-parse");
    let base = tmp.path();
    let repo = verify_fixture(base);
    std::fs::write(base.join("garbage"), b"garbage\n").unwrap();
    let run = run_delta_verify(base, &repo, &["./garbage", ED25519_PUBLIC_B64]);
    assert_eq!(run.status.code(), Some(1));
    assert_eq!(String::from_utf8_lossy(&run.stdout), "Verification fails\n");
    assert!(String::from_utf8_lossy(&run.stderr).starts_with("error: "));
}

/// Runs `static-delta verify ARGS` against `repo` from `cwd` with ostrya and
/// with the `ostree` command. Asserts that the exit status and both streams
/// agree, and returns the run of ostrya.
fn assert_verify_agrees(cwd: &Path, repo: &Path, args: &[&str]) -> Run {
    let repo_arg = format!("--repo={}", repo.display());
    let all = [&["static-delta", repo_arg.as_str(), "verify"][..], args].concat();
    let port = ostrya_in(Some(cwd), &all, None, &[]);
    let tool = ostree_in(cwd, &all);
    assert_runs_agree(&port, &tool, &all.join(" "));
    port
}

/// Runs the cases of the two tests that compare ostrya with the `ostree`
/// command over `repo`. `repo` has these deltas:
///
/// - an unsigned delta to `c1`
/// - a delta to `c2`, signed with the shared key
/// - a delta from `c1` to `c2`, signed with the shared key
///
/// The key files, the key stores, and the copied superblock are in `base`,
/// the working directory of each run.
fn assert_verify_cases_agree(base: &Path, repo: &Path, c1: &str, c2: &str) {
    std::fs::write(base.join("k1"), format!("{ED25519_PUBLIC_B64}\n")).unwrap();
    std::fs::write(base.join("k2"), format!("{ED25519_PUBLIC2_B64}\n")).unwrap();
    verify_key_store(base, "store1", &[ED25519_PUBLIC_B64], &[]);
    verify_key_store(base, "store2", &[ED25519_PUBLIC2_B64], &[]);
    verify_key_store(
        base,
        "revoked",
        &[ED25519_PUBLIC_B64],
        &[ED25519_PUBLIC_B64],
    );
    // An empty --keys-dir names the working directory.
    std::fs::write(
        base.join("trusted.ed25519"),
        format!("{ED25519_PUBLIC_B64}\n"),
    )
    .unwrap();
    std::fs::write(base.join("kz"), format!("{ED25519_ZERO_B64}\n")).unwrap();
    verify_key_store(
        base,
        "dups",
        &[ED25519_PUBLIC2_B64, ED25519_ZERO_B64, ED25519_PUBLIC2_B64],
        &[],
    );
    let relative = ostrya::static_delta_relative_dir(None, &Checksum::from_hex(c2).unwrap());
    let repo_name = repo.file_name().unwrap().to_str().unwrap();
    let in_repo = format!("{repo_name}/{relative}/superblock");
    std::fs::copy(base.join(&in_repo), base.join("sbcopy")).unwrap();
    let absolute = base.join("sbcopy");
    let from_to = format!("{c1}-{c2}");
    let absent = format!("{c2}-{c1}");

    let cases: Vec<Vec<&str>> = vec![
        vec![c2, ED25519_PUBLIC_B64],
        vec![&from_to, ED25519_PUBLIC_B64],
        vec![c2, ED25519_PUBLIC2_B64],
        vec![c2, ED25519_PUBLIC2_B64, ED25519_PUBLIC_B64],
        vec![c2, ED25519_PUBLIC2_B64, ED25519_ZERO_B64],
        vec![c1, ED25519_PUBLIC_B64],
        vec!["--keys-file=k2", "--keys-file=k1", c2],
        vec!["--keys-file=k1", "--keys-file=k2", c2],
        vec!["--keys-dir=store1", "--keys-file=k2", c2],
        vec!["--keys-dir=store1", c2, ED25519_PUBLIC2_B64],
        vec!["--keys-dir=store1", c2],
        vec!["--keys-dir=revoked", c2],
        vec!["--keys-dir=store1", "--keys-dir=store2", c2],
        vec!["--keys-dir=store2", "--keys-dir=store1", c2],
        vec![
            "--sign-type=nosuch",
            "--sign-type=ed25519",
            c2,
            ED25519_PUBLIC_B64,
        ],
        vec![&in_repo, ED25519_PUBLIC_B64],
        vec!["./sbcopy", ED25519_PUBLIC_B64],
        vec![absolute.to_str().unwrap(), ED25519_PUBLIC2_B64],
        vec!["./", ED25519_PUBLIC_B64],
        vec![&absent, ED25519_PUBLIC_B64],
        vec!["m", ED25519_PUBLIC_B64],
        vec!["--keys-dir=nodir", c2],
        vec!["--keys-dir=", c2],
        vec![
            c2,
            ED25519_PUBLIC2_B64,
            ED25519_ZERO_B64,
            ED25519_PUBLIC2_B64,
        ],
        vec!["--keys-file=kz", c2, ED25519_PUBLIC2_B64, ED25519_ZERO_B64],
        vec!["--keys-dir=dups", c2],
    ];
    for case in &cases {
        assert_verify_agrees(base, repo, case);
    }
}

/// `verify` of ostrya and of the `ostree` command agree byte for byte over
/// the deltas of `ostree`. The test carries
/// `static-delta/verify-{ok,wrong-key,unsigned,keys-file-last-wins,keys-file-overrides-keys-dir,path-arg}`
/// with `ostree` as the producer.
#[test]
fn static_delta_verify_matches_the_tool_over_the_tools_deltas() {
    if !ostree_supports_ed25519() {
        return;
    }
    let tmp = TmpDir::new("delta-verify-tool");
    let (repo, c1, c2) = delta_show_repo(tmp.path(), "repo");
    let sign = format!("--sign={ED25519_SECRET_B64}");
    ostree_ok(&repo, &["static-delta", "generate", "--empty", "--to", &c1]);
    ostree_ok(
        &repo,
        &[
            "static-delta",
            "generate",
            "--empty",
            "--to",
            &c2,
            "--sign-type=ed25519",
            &sign,
        ],
    );
    ostree_ok(
        &repo,
        &[
            "static-delta",
            "generate",
            "--from",
            &c1,
            "--to",
            &c2,
            "--sign-type=ed25519",
            &sign,
        ],
    );
    assert_verify_cases_agree(tmp.path(), &repo, &c1, &c2);
}

/// `verify` of ostrya and of the `ostree` command agree byte for byte over
/// the deltas of ostrya. `verify` of `ostree` reads a delta that ostrya signs.
/// The test carries the same cells as
/// `static_delta_verify_matches_the_tool_over_the_tools_deltas`, with ostrya as
/// the producer.
#[test]
fn static_delta_verify_matches_the_tool_over_the_ports_deltas() {
    if !ostree_supports_ed25519() {
        return;
    }
    let tmp = TmpDir::new("delta-verify-port");
    let (repo, c1, c2) = delta_show_repo(tmp.path(), "repo");
    let repo_s = repo.to_str().unwrap();
    let sign = format!("--sign={ED25519_SECRET_B64}");
    let generate = |extra: &[&str]| {
        let base = [
            "static-delta",
            "--repo",
            repo_s,
            "generate",
            "--timestamp=1700000000",
        ];
        ostrya(&[&base[..], extra].concat(), None, &[]).ok();
    };
    generate(&["--empty", "--to", &c1]);
    generate(&["--empty", "--to", &c2, &sign]);
    generate(&["--from", &c1, "--to", &c2, &sign]);
    assert_verify_cases_agree(tmp.path(), &repo, &c1, &c2);
}

/// The refusals of ostrya and of the `ostree` command agree byte for byte:
///
/// - no argument
/// - an unknown sign type
/// - no key loaded
/// - a positional of the wrong length
/// - an empty keys file
/// - a missing keys file
///
/// The test carries `static-delta/verify-no-keys`.
#[test]
fn static_delta_verify_refusals_match_the_tool() {
    if !ostree_supports_ed25519() {
        return;
    }
    let tmp = TmpDir::new("delta-verify-refusals");
    let base = tmp.path();
    let (repo, _, c2) = delta_show_repo(base, "repo");
    let sign = format!("--sign={ED25519_SECRET_B64}");
    ostree_ok(
        &repo,
        &[
            "static-delta",
            "generate",
            "--empty",
            "--to",
            &c2,
            "--sign-type=ed25519",
            &sign,
        ],
    );
    std::fs::write(base.join("empty"), b"").unwrap();
    std::fs::write(base.join("bad"), b"AAAA\n").unwrap();
    std::fs::write(base.join("ws3"), b"   \n").unwrap();
    std::fs::write(base.join("wscr"), b" \r\n").unwrap();
    std::fs::write(base.join("tabs"), b"\t\t\n").unwrap();
    let cases: Vec<Vec<&str>> = vec![
        vec![],
        vec!["--sign-type=nosuch", &c2, ED25519_PUBLIC_B64],
        vec!["--sign-type=gpg", &c2, ED25519_PUBLIC_B64],
        vec!["--keys-dir=nodir", &c2],
        vec![&c2, "AAAA"],
        vec![&c2, ED25519_PUBLIC_B64, "not-base64!!!"],
        vec!["--keys-file=empty", &c2],
        vec!["--keys-file=bad", &c2],
        vec!["--keys-file=ws3", &c2],
        vec!["--keys-file=wscr", &c2],
        vec!["--keys-file=tabs", &c2],
        vec!["--keys-file=nosuch", &c2],
        vec!["--keys-file=.", &c2],
        vec!["--keys-file=", &c2],
    ];
    for case in &cases {
        let run = assert_verify_agrees(base, &repo, case);
        assert_eq!(run.status.code(), Some(1));
        assert!(run.stdout.is_empty() || run.stdout == b"Sign-type not supported\n");
    }
}

// --- static-delta generate ----------------------------------------------------

/// Returns the standard output of a `generate` run that starts the generation.
fn generate_block(from: Option<&str>, to: &str) -> String {
    format!(
        "Generating static delta:\n  From: {}\n  To:   {to}\n",
        from.unwrap_or("empty")
    )
}

/// Runs `static-delta generate ARGS` from `cwd` against `repo` with one
/// command. If `port` is `true`, the command is ostrya. Otherwise it is the
/// `ostree` command.
fn run_generate(port: bool, cwd: &Path, repo: &Path, args: &[&str]) -> Run {
    let repo_arg = format!("--repo={}", repo.display());
    let all = [&["static-delta", repo_arg.as_str(), "generate"][..], args].concat();
    if port {
        ostrya_in(Some(cwd), &all, None, &[])
    } else {
        ostree_in(cwd, &all)
    }
}

/// Runs `static-delta generate ARGS` with ostrya and with the `ostree`
/// command. Each command runs against its own repository and from its own
/// working directory. Returns the run of ostrya and the run of `ostree`.
fn generate_both(port: (&Path, &Path), tool: (&Path, &Path), args: &[&str]) -> (Run, Run) {
    (
        run_generate(true, port.0, port.1, args),
        run_generate(false, tool.0, tool.1, args),
    )
}

/// Returns the `static-delta list` output of `repo` from the `ostree` command,
/// sorted.
fn listed_deltas(repo: &Path) -> Vec<String> {
    let run = ostree(&[
        &format!("--repo={}", repo.display()),
        "static-delta",
        "list",
    ]);
    assert!(run.status.success());
    let mut names: Vec<String> = String::from_utf8(run.stdout)
        .unwrap()
        .lines()
        .map(str::to_owned)
        .collect();
    names.sort();
    names
}

/// Returns each `superblock` file in the leaf directories of `repo/deltas`.
fn delta_superblocks(repo: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    let Ok(fanouts) = std::fs::read_dir(repo.join("deltas")) else {
        return out;
    };
    for fanout in fanouts {
        for leaf in std::fs::read_dir(fanout.unwrap().path()).unwrap() {
            let superblock = leaf.unwrap().path().join("superblock");
            if superblock.exists() {
                out.push(superblock);
            }
        }
    }
    out
}

/// Returns the sorted names in a directory, or an empty list if the directory
/// is absent.
fn entry_names(dir: &Path) -> Vec<String> {
    let mut names: Vec<String> = std::fs::read_dir(dir)
        .map(|entries| {
            entries
                .map(|entry| entry.unwrap().file_name().to_string_lossy().into_owned())
                .collect()
        })
        .unwrap_or_default();
    names.sort();
    names
}

/// The default source, the positional target, and the two refusals agree in
/// ostrya and in the `ostree` command:
///
/// - If neither `--from` nor `--empty` is given, the source is the parent of
///   TO.
/// - A root commit is refused.
/// - `--empty` with `--from` is refused before any revision resolves.
/// - `--to` wins over the positional.
///
/// If the default parent is absent from the repository, both commands fail
/// after the block and list no delta. The test carries
/// `static-delta/generate-{default-parent,no-parent-refused,empty-and-from-refused,positional-to}`.
#[test]
fn static_delta_generate_defaults_match_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-generate-defaults");
    let base = tmp.path();
    let (repo, c1, c2) = delta_show_repo(base, "repo");
    let port_repo = clone_repo(base, &repo, "port");
    let tool_repo = clone_repo(base, &repo, "tool");
    let port = (base, port_repo.as_path());
    let tool = (base, tool_repo.as_path());

    let (p, t) = generate_both(port, tool, &["--to=m"]);
    for (who, run) in [("port", &p), ("tool", &t)] {
        assert!(run.status.success(), "{who}");
        assert_eq!(
            String::from_utf8_lossy(&run.stdout),
            generate_block(Some(&c1), &c2),
            "{who}"
        );
    }
    assert!(
        p.stderr.is_empty(),
        "{}",
        String::from_utf8_lossy(&p.stderr)
    );
    let from_to = vec![format!("{c1}-{c2}")];
    assert_eq!(listed_deltas(&port_repo), from_to);
    assert_eq!(listed_deltas(&tool_repo), from_to);

    let (p, t) = generate_both(port, tool, &["--empty", "m"]);
    assert!(p.status.success() && t.status.success());
    assert_eq!(p.stdout, t.stdout);
    assert_eq!(
        String::from_utf8_lossy(&p.stdout),
        generate_block(None, &c2)
    );
    assert!(listed_deltas(&port_repo).contains(&c2));
    assert!(listed_deltas(&tool_repo).contains(&c2));

    let to_c1 = format!("--to={c1}");
    let (p, t) = generate_both(port, tool, &["--empty", &to_c1, &c2]);
    assert!(p.status.success() && t.status.success());
    assert_eq!(p.stdout, t.stdout);
    assert_eq!(
        String::from_utf8_lossy(&p.stdout),
        generate_block(None, &c1)
    );

    let (p, t) = generate_both(port, tool, &[&to_c1]);
    assert_runs_agree(&p, &t, &format!("generate {to_c1}"));
    assert_eq!(
        String::from_utf8_lossy(&p.stderr),
        format!("error: Commit {c1} has no parent\n")
    );

    let from_c1 = format!("--from={c1}");
    let (p, t) = generate_both(port, tool, &["--empty", &from_c1, "--to=m"]);
    assert_runs_agree(&p, &t, "generate --empty --from --to");
    assert_eq!(
        String::from_utf8_lossy(&p.stderr),
        "error: Cannot specify both --empty and --from=REV\n"
    );
    let (p, t) = generate_both(port, tool, &["--empty", &from_c1]);
    assert_runs_agree(&p, &t, "generate --empty --from");
    assert_eq!(
        String::from_utf8_lossy(&p.stderr),
        "error: TO revision must be specified\n"
    );

    // A shallow copy has the tip and not its parent.
    let mut shallow = Vec::new();
    for name in ["port-shallow", "tool-shallow"] {
        let copy = base.join(name);
        ostree_ok(&copy, &["init", "--mode=archive"]);
        ostree_ok(
            &copy,
            &["pull-local", "--depth=0", repo.to_str().unwrap(), "m"],
        );
        shallow.push(copy);
    }
    let (p, t) = generate_both((base, &shallow[0]), (base, &shallow[1]), &["--to=m"]);
    for (who, run) in [("port", &p), ("tool", &t)] {
        assert_eq!(run.status.code(), Some(1), "{who}");
        assert_eq!(
            String::from_utf8_lossy(&run.stdout),
            generate_block(Some(&c1), &c2),
            "{who}"
        );
    }
    assert_eq!(listed_deltas(&shallow[0]), vec!["(No static deltas)"]);
    assert_eq!(listed_deltas(&shallow[1]), vec!["(No static deltas)"]);
}

/// If the repository has the superblock of the delta, `-n` prints
/// `Delta <name> already exists.` and writes nothing. This is also true with
/// `--filename`. If the delta directory has only a part, `-n` generates the
/// delta again. The test carries `static-delta/generate-if-not-exists`.
#[test]
fn static_delta_generate_if_not_exists_matches_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-generate-if-not-exists");
    let base = tmp.path();
    let (repo, c1, c2) = delta_show_repo(base, "repo");
    let port_repo = clone_repo(base, &repo, "port");
    let tool_repo = clone_repo(base, &repo, "tool");
    let port_cwd = base.join("port-cwd");
    let tool_cwd = base.join("tool-cwd");
    std::fs::create_dir_all(&port_cwd).unwrap();
    std::fs::create_dir_all(&tool_cwd).unwrap();
    let port = (port_cwd.as_path(), port_repo.as_path());
    let tool = (tool_cwd.as_path(), tool_repo.as_path());
    let to_c1 = format!("--to={c1}");
    for args in [&["--to=m"][..], &["--empty", "m"], &["--empty", &to_c1]] {
        let (p, t) = generate_both(port, tool, args);
        assert!(p.status.success() && t.status.success(), "{args:?}");
    }
    let before: Vec<(Vec<u8>, std::time::SystemTime)> = delta_superblocks(&port_repo)
        .iter()
        .map(|path| {
            (
                std::fs::read(path).unwrap(),
                std::fs::metadata(path).unwrap().modified().unwrap(),
            )
        })
        .collect();

    for (args, name) in [
        (&["-n", "--to=m"][..], format!("{c1}-{c2}")),
        (&["-n", "--empty", "m"], c2.clone()),
        (&["-n", "--empty", &to_c1, "--filename=out/sb"], c1.clone()),
    ] {
        let (p, t) = generate_both(port, tool, args);
        assert_runs_agree(&p, &t, &format!("generate {args:?}"));
        assert!(p.status.success());
        assert_eq!(
            String::from_utf8_lossy(&p.stdout),
            format!("Delta {name} already exists.\n")
        );
    }
    assert!(!port_cwd.join("out").exists() && !tool_cwd.join("out").exists());
    let after: Vec<(Vec<u8>, std::time::SystemTime)> = delta_superblocks(&port_repo)
        .iter()
        .map(|path| {
            (
                std::fs::read(path).unwrap(),
                std::fs::metadata(path).unwrap().modified().unwrap(),
            )
        })
        .collect();
    assert_eq!(before, after, "-n rewrote a superblock");

    // A delta directory with only a part counts as absent.
    let relative = ostrya::static_delta_relative_dir(None, &Checksum::from_hex(&c1).unwrap());
    for r in [&port_repo, &tool_repo] {
        std::fs::remove_file(r.join(&relative).join("superblock")).unwrap();
    }
    let (p, t) = generate_both(port, tool, &["-n", "--empty", &to_c1]);
    for (who, run) in [("port", &p), ("tool", &t)] {
        assert!(run.status.success(), "{who}");
        assert_eq!(
            String::from_utf8_lossy(&run.stdout),
            generate_block(None, &c1),
            "{who}"
        );
    }
    assert!(port_repo.join(&relative).join("superblock").exists());
    assert!(tool_repo.join(&relative).join("superblock").exists());
}

/// `--filename=PATH` writes the superblock to PATH and the parts next to it.
/// For a refused target, ostrya and the `ostree` command exit 1. `verify` of
/// `ostree` reads a superblock that ostrya signed with `--filename`. The test
/// carries `static-delta/generate-filename-{file,dir-refused}`.
#[test]
fn static_delta_generate_filename_matches_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-generate-filename");
    let base = tmp.path();
    let (repo, c1, _) = delta_show_repo(base, "repo");
    let port_repo = clone_repo(base, &repo, "port");
    let tool_repo = clone_repo(base, &repo, "tool");
    let port_cwd = base.join("port-cwd");
    let tool_cwd = base.join("tool-cwd");
    for cwd in [&port_cwd, &tool_cwd] {
        std::fs::create_dir_all(cwd.join("out")).unwrap();
        std::fs::create_dir_all(cwd.join("dir")).unwrap();
    }
    let port = (port_cwd.as_path(), port_repo.as_path());
    let tool = (tool_cwd.as_path(), tool_repo.as_path());
    let to_c1 = format!("--to={c1}");
    let block = generate_block(None, &c1);

    let (p, t) = generate_both(port, tool, &["--empty", &to_c1, "--filename=out/sb"]);
    for (who, run, cwd) in [("port", &p, &port_cwd), ("tool", &t, &tool_cwd)] {
        assert!(run.status.success(), "{who}");
        assert_eq!(String::from_utf8_lossy(&run.stdout), block, "{who}");
        assert_eq!(entry_names(&cwd.join("out")), vec!["0", "sb"], "{who}");
    }
    assert!(delta_superblocks(&port_repo).is_empty());
    assert!(delta_superblocks(&tool_repo).is_empty());

    // A path with no `/` puts both in the working directory.
    let (p, t) = generate_both(port, tool, &["--empty", &to_c1, "--filename=sbx"]);
    for (who, run, cwd) in [("port", &p, &port_cwd), ("tool", &t, &tool_cwd)] {
        assert!(run.status.success(), "{who}");
        assert_eq!(entry_names(cwd), vec!["0", "dir", "out", "sbx"], "{who}");
    }

    // A directory at PATH: ostrya refuses before any write. `ostree` refuses
    // at the rename, after it writes part 0.
    for cwd in [&port_cwd, &tool_cwd] {
        std::fs::remove_dir_all(cwd.join("out")).unwrap();
        std::fs::create_dir_all(cwd.join("out/d")).unwrap();
    }
    let (p, t) = generate_both(port, tool, &["--empty", &to_c1, "--filename=out/d"]);
    for (who, run) in [("port", &p), ("tool", &t)] {
        assert_eq!(run.status.code(), Some(1), "{who}");
        assert_eq!(String::from_utf8_lossy(&run.stdout), block, "{who}");
    }
    assert_eq!(entry_names(&port_cwd.join("out")), vec!["d"]);
    assert_eq!(entry_names(&tool_cwd.join("out")), vec!["0", "d"]);

    let (p, t) = generate_both(port, tool, &["--empty", &to_c1, "--filename=dir/"]);
    assert_eq!(p.status.code(), Some(1));
    assert_eq!(t.status.code(), Some(1));
    assert!(entry_names(&port_cwd.join("dir")).is_empty());

    // A last component `.` after a file or an absent name: both commands
    // refuse after the block and change nothing.
    for cwd in [&port_cwd, &tool_cwd] {
        std::fs::write(cwd.join("dir/keep"), b"keep\n").unwrap();
    }
    for path in ["dir/keep/.", "dir/new/."] {
        let arg = format!("--filename={path}");
        let (p, t) = generate_both(port, tool, &["--empty", &to_c1, &arg]);
        for (who, run, cwd) in [("port", &p, &port_cwd), ("tool", &t, &tool_cwd)] {
            assert_eq!(run.status.code(), Some(1), "{who} {path}");
            assert_eq!(String::from_utf8_lossy(&run.stdout), block, "{who} {path}");
            assert_eq!(entry_names(&cwd.join("dir")), vec!["keep"], "{who} {path}");
            assert_eq!(
                std::fs::read(cwd.join("dir/keep")).unwrap(),
                b"keep\n",
                "{who} {path}"
            );
        }
    }
    // A last component `.` or `..` after a directory: ostrya refuses before
    // any write. `ostree` refuses at the rename, after it writes part 0.
    for path in ["dir/.", "dir/.."] {
        let arg = format!("--filename={path}");
        let (p, t) = generate_both(port, tool, &["--empty", &to_c1, &arg]);
        for (who, run) in [("port", &p), ("tool", &t)] {
            assert_eq!(run.status.code(), Some(1), "{who} {path}");
            assert_eq!(String::from_utf8_lossy(&run.stdout), block, "{who} {path}");
        }
        assert_eq!(entry_names(&port_cwd.join("dir")), vec!["keep"], "{path}");
    }

    // An empty PATH: `clap` in ostrya refuses before the block. `ostree`
    // refuses after the block.
    let (p, t) = generate_both(port, tool, &["--empty", &to_c1, "--filename="]);
    assert_eq!(p.status.code(), Some(1));
    assert!(p.stdout.is_empty());
    assert_eq!(t.status.code(), Some(1));
    assert_eq!(String::from_utf8_lossy(&t.stdout), block);

    let (p, t) = generate_both(port, tool, &["--empty", &to_c1, "--filename=nodir/x/sb"]);
    for (who, run, cwd) in [("port", &p, &port_cwd), ("tool", &t, &tool_cwd)] {
        assert_eq!(run.status.code(), Some(1), "{who}");
        assert_eq!(String::from_utf8_lossy(&run.stdout), block, "{who}");
        assert!(!cwd.join("nodir").exists(), "{who}");
    }

    // A part file name: `ostree` writes a delta, and the superblock replaces
    // its part. ostrya refuses and writes nothing.
    let (p, t) = generate_both(port, tool, &["--empty", &to_c1, "--filename=out/0"]);
    assert_eq!(p.status.code(), Some(1));
    assert!(t.status.success());
    assert_eq!(entry_names(&port_cwd.join("out")), vec!["d"]);

    // ostrya only: --output-dir and --reindex with --filename.
    for extra in ["--output-dir=elsewhere", "--reindex"] {
        let run = run_generate(
            true,
            &port_cwd,
            &port_repo,
            &["--empty", &to_c1, "--filename=out/sb", extra],
        );
        assert_eq!(run.status.code(), Some(1), "{extra}");
        assert!(run.stdout.is_empty(), "{extra}");
        assert_eq!(entry_names(&port_cwd.join("out")), vec!["d"], "{extra}");
        assert!(!port_cwd.join("elsewhere").exists());
    }

    if ostree_supports_ed25519() {
        let sign = format!("--sign={ED25519_SECRET_B64}");
        let run = run_generate(
            true,
            &port_cwd,
            &port_repo,
            &["--empty", &to_c1, "--filename=out/signed", &sign],
        );
        assert!(run.status.success());
        let verified = ostree_in(
            &port_cwd,
            &[
                &format!("--repo={}", port_repo.display()),
                "static-delta",
                "verify",
                "out/signed",
                ED25519_PUBLIC_B64,
            ],
        );
        assert!(
            verified.status.success(),
            "{}",
            String::from_utf8_lossy(&verified.stderr)
        );
        assert_eq!(
            String::from_utf8_lossy(&verified.stdout),
            "Verification OK\n"
        );
    }
}

/// With a bad signing key, ostrya and the `ostree` command exit 1 after the
/// block. Both write the same last line on standard error and no superblock.
/// `ostree` leaves part 0. ostrya reads the key before it writes a part. The
/// test carries `static-delta/generate-bad-sign-key-no-superblock`.
#[test]
fn static_delta_generate_bad_sign_key_writes_no_superblock() {
    if !ostree_supports_ed25519() {
        return;
    }
    let tmp = TmpDir::new("delta-generate-bad-key");
    let base = tmp.path();
    let (repo, c1, _) = delta_show_repo(base, "repo");
    let port_repo = clone_repo(base, &repo, "port");
    let tool_repo = clone_repo(base, &repo, "tool");
    let to_c1 = format!("--to={c1}");
    let (p, t) = generate_both(
        (base, &port_repo),
        (base, &tool_repo),
        &["--empty", &to_c1, "--sign=AAAA"],
    );
    let last_line = |run: &Run| {
        String::from_utf8_lossy(&run.stderr)
            .lines()
            .last()
            .unwrap_or_default()
            .to_owned()
    };
    for (who, run) in [("port", &p), ("tool", &t)] {
        assert_eq!(run.status.code(), Some(1), "{who}");
        assert_eq!(
            String::from_utf8_lossy(&run.stdout),
            generate_block(None, &c1),
            "{who}"
        );
        assert_eq!(
            last_line(run),
            "error: Invalid ed25519 secret key: Ill-formed input: expected 64 bytes, got 3 bytes",
            "{who}"
        );
    }
    for r in [&port_repo, &tool_repo] {
        assert_eq!(listed_deltas(r), vec!["(No static deltas)"]);
        assert!(delta_superblocks(r).is_empty());
    }
    let relative = ostrya::static_delta_relative_dir(None, &Checksum::from_hex(&c1).unwrap());
    assert!(tool_repo.join(&relative).join("0").exists());
    assert!(!port_repo.join("deltas").exists());
}

/// The three size options are in decimal megabytes in ostrya and in the
/// `ostree` command. The fallback count and the part count of the delta of
/// `ostree` and of the delta of ostrya agree.
///
/// ostrya patches a 2-byte edit of a 1,024-byte object at
/// `--max-bsdiff-size=1`, and not at 0. A limit of 1 byte is too small for
/// this patch, so the value 1 is 1 megabyte. ostrya refuses these values and
/// writes nothing:
///
/// - a value that is not only decimal digits
/// - a value more than the largest byte count
/// - `--max-chunk-size=0`
///
/// `ostree` accepts the first two kinds. The test carries
/// `static-delta/generate-units-megabytes` and
/// `static-delta/generate-size-junk-refused`.
#[test]
fn static_delta_generate_sizes_are_megabytes() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-generate-sizes");
    let base = tmp.path();
    // The fallback thresholds need only the 5,000,000-byte file. The three
    // 1,200,000-byte files are for the chunk size.
    let (repo, c) = delta_fallback_repo(base, "repo", false);
    let (parts_repo, parts_c) = delta_fallback_repo(base, "parts", true);
    let counts = |run: &Run| {
        String::from_utf8_lossy(&run.stdout)
            .lines()
            .filter(|line| {
                line.starts_with("Number of fallback entries")
                    || line.starts_with("Number of parts")
            })
            .map(str::to_owned)
            .collect::<Vec<_>>()
    };
    for (index, (source, c, extra)) in [
        (&repo, &c, &[][..]),
        (&repo, &c, &["--min-fallback-size=5"]),
        (&repo, &c, &["--min-fallback-size=6"]),
        (&parts_repo, &parts_c, &["--max-chunk-size=1"]),
    ]
    .iter()
    .enumerate()
    {
        let port_repo = clone_repo(base, source, &format!("port{index}"));
        let tool_repo = clone_repo(base, source, &format!("tool{index}"));
        let to = format!("--to={c}");
        let args = [&["--empty", to.as_str()][..], extra].concat();
        let (p, t) = generate_both((base, &port_repo), (base, &tool_repo), &args);
        assert!(p.status.success() && t.status.success(), "{extra:?}");
        let show = |r: &Path| {
            ostree(&[
                &format!("--repo={}", r.display()),
                "static-delta",
                "show",
                c.as_str(),
            ])
        };
        let port_counts = counts(&show(&port_repo));
        assert_eq!(port_counts.len(), 2, "{extra:?}");
        assert_eq!(port_counts, counts(&show(&tool_repo)), "{extra:?}");
        // The 5,000,000-byte object reaches a 5 MB threshold and not a 6 MB one.
        let fallbacks = if index == 2 { 0 } else { 1 };
        assert!(
            port_counts.contains(&format!("Number of fallback entries: {fallbacks}")),
            "{extra:?}: {port_counts:?}"
        );
    }

    // A 1,024-byte object with a 2-byte edit. If the limit allows it, ostrya
    // patches the object with bspatch.
    let small = base.join("small");
    ostree_ok(&small, &["init", "--mode=archive"]);
    let tree = base.join("small-tree");
    std::fs::create_dir_all(&tree).unwrap();
    let mut data = delta_noise(1024, 9);
    std::fs::write(tree.join("s"), &data).unwrap();
    let tree_arg = format!("--tree=dir={}", tree.display());
    ostree_ok(&small, &["commit", "-b", "m", "-s", "one", &tree_arg]);
    data[500] ^= 0xff;
    data[501] ^= 0xff;
    std::fs::write(tree.join("s"), &data).unwrap();
    let c2 = ostree_ok(&small, &["commit", "-b", "m", "-s", "two", &tree_arg]);
    let name = format!("{}-{c2}", resolve(&small, "m^").unwrap());
    for (value, patches) in [("1", true), ("0", false)] {
        let port_repo = clone_repo(base, &small, &format!("port-bsdiff{value}"));
        let arg = format!("--max-bsdiff-size={value}");
        let run = run_generate(true, base, &port_repo, &["--to=m", &arg]);
        assert!(run.status.success(), "{arg}");
        let shown = ostree(&[
            &format!("--repo={}", port_repo.display()),
            "static-delta",
            "show",
            &name,
        ]);
        assert!(shown.status.success(), "{arg}");
        assert_eq!(show_count(&shown, "bspatch=") > 0, patches, "{arg}");
    }

    for option in [
        "--min-fallback-size",
        "--max-bsdiff-size",
        "--max-chunk-size",
    ] {
        for value in ["abc", "1.5", "-1", "+3", " 3", "3x", "", "18446744073710"] {
            let arg = format!("{option}={value}");
            let run = run_generate(true, base, &small, &["--to=m", &arg]);
            assert_eq!(run.status.code(), Some(1), "{arg}");
            assert!(run.stdout.is_empty(), "{arg}");
            assert!(!small.join("deltas").exists(), "{arg}");
        }
    }
    let tool_junk = clone_repo(base, &small, "tool-junk");
    for value in ["abc", "1.5", "-1"] {
        let arg = format!("--min-fallback-size={value}");
        let run = run_generate(false, base, &tool_junk, &["--to=m", &arg]);
        assert!(run.status.success(), "the tool refused {arg}");
    }

    let run = run_generate(true, base, &small, &["--to=m", "--max-chunk-size=0"]);
    assert_eq!(run.status.code(), Some(1));
    assert!(delta_superblocks(&small).is_empty());
}

/// The GVariant type string of a superblock. The test helpers use it to read
/// the metadata dict of a superblock file.
const DELTA_SUPERBLOCK_SIG: &str = "(a{sv}tayay(a{sv}aya(say)sstayay)aya(uayttay)a(yaytt))";

/// Returns the metadata dict keys of an unsigned superblock file, in dict
/// order.
fn superblock_keys(path: &Path) -> Vec<String> {
    let bytes = std::fs::read(path).unwrap();
    let value = ostrya::from_bytes(&Type::parse(DELTA_SUPERBLOCK_SIG).unwrap(), &bytes).unwrap();
    value.as_tuple().unwrap()[0]
        .as_array()
        .unwrap()
        .iter()
        .map(|entry| entry.as_tuple().unwrap()[0].as_str().unwrap().to_owned())
        .collect()
}

/// Returns the `ostree.endianness` byte of a superblock file, and the parsed
/// superblock.
fn superblock_endianness(path: &Path) -> (u8, ostrya::DeltaSuperblock) {
    let bytes = std::fs::read(path).unwrap();
    let value = ostrya::from_bytes(&Type::parse(DELTA_SUPERBLOCK_SIG).unwrap(), &bytes).unwrap();
    let byte = value.as_tuple().unwrap()[0]
        .dict_get("ostree.endianness")
        .and_then(Value::as_variant)
        .and_then(|(_, byte)| byte.as_byte())
        .unwrap();
    (byte, ostrya::DeltaSuperblock::parse(bytes).unwrap())
}

/// Returns the `PartPayload` lines that `show` of ostrya prints for a delta.
fn port_part_payloads(repo: &Path, arg: &str) -> Vec<String> {
    let repo_arg = format!("--repo={}", repo.display());
    let run = ostrya(&["static-delta", &repo_arg, "show", arg], None, &[]);
    run.ok();
    String::from_utf8_lossy(&run.stdout)
        .lines()
        .filter(|line| line.starts_with("PartPayload"))
        .map(str::to_owned)
        .collect()
}

/// Returns the `ls -R -C` output of a commit in `repo` from the `ostree`
/// command.
fn tool_listing(repo: &Path, commit: &str) -> String {
    ostree_ok(repo, &["ls", "-R", "-C", commit])
}

/// `--inline` agrees in ostrya and in the `ostree` command:
///
/// - Both commands print the block.
/// - Neither command writes a part file.
/// - The metadata keys are the same, in the same order.
/// - `show` of ostrya reads the parts of both superblocks.
///
/// Each command applies the inline delta of the other command, and the trees
/// agree. With `--filename`, the key stays relative to the repository and no
/// command writes a part file next to PATH. The test carries
/// `static-delta/generate-inline`.
#[test]
fn static_delta_generate_inline_matches_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-generate-inline");
    let base = tmp.path();
    let (repo, c1, c2) = delta_show_repo(base, "repo");
    let port_repo = clone_repo(base, &repo, "port");
    let tool_repo = clone_repo(base, &repo, "tool");
    let port = (base, port_repo.as_path());
    let tool = (base, tool_repo.as_path());
    let (from1, to2) = (
        Checksum::from_hex(&c1).unwrap(),
        Checksum::from_hex(&c2).unwrap(),
    );
    for (args, from, name) in [
        (&["--empty", "--to=m", "--inline"][..], None, c2.clone()),
        (&["--to=m", "--inline"], Some(&from1), format!("{c1}-{c2}")),
    ] {
        let (p, t) = generate_both(port, tool, args);
        assert_runs_agree_on_stdout(&p, &t, args);
        assert_eq!(
            String::from_utf8_lossy(&p.stdout),
            generate_block(from.map(|_| c1.as_str()), &c2)
        );
        let relative = ostrya::static_delta_relative_dir(from, &to2);
        assert_eq!(entry_names(&port_repo.join(&relative)), ["superblock"]);
        assert_eq!(entry_names(&tool_repo.join(&relative)), ["superblock"]);
        let keys = superblock_keys(&port_repo.join(&relative).join("superblock"));
        assert_eq!(
            keys,
            superblock_keys(&tool_repo.join(&relative).join("superblock"))
        );
        assert_eq!(keys[1], format!("{}/0", relative));
        // ostrya reads the inline parts of both. The operand offsets of the
        // two generators differ, so the test compares the part count. For the
        // delta from scratch, where both only splice, it also compares the
        // operation counts.
        let (port_lines, tool_lines) = (
            port_part_payloads(&port_repo, &name),
            port_part_payloads(&tool_repo, &name),
        );
        assert_eq!(port_lines.len(), tool_lines.len(), "{args:?}");
        if from.is_none() {
            let ops = |lines: &[String]| {
                lines
                    .iter()
                    .filter(|line| line.starts_with("PartPayloadOps"))
                    .cloned()
                    .collect::<Vec<_>>()
            };
            assert_eq!(ops(&port_lines), ops(&tool_lines));
        }
    }

    // Each command applies the delta from scratch of the other command into a
    // new archive repository.
    let scratch = ostrya::static_delta_relative_dir(None, &to2);
    let into_port = base.join("into-port");
    let into_tool = base.join("into-tool");
    ostree_ok(&into_port, &["init", "--mode=archive"]);
    ostree_ok(&into_tool, &["init", "--mode=archive"]);
    ostree_ok(
        &into_tool,
        &[
            "static-delta",
            "apply-offline",
            port_repo.join(&scratch).to_str().unwrap(),
        ],
    );
    let into_port_arg = format!("--repo={}", into_port.display());
    ostrya(
        &[
            "static-delta",
            &into_port_arg,
            "apply-offline",
            tool_repo.join(&scratch).to_str().unwrap(),
        ],
        None,
        &[],
    )
    .ok();
    ostree_ok(&into_port, &["fsck"]);
    ostree_ok(&into_tool, &["fsck"]);
    assert_eq!(tool_listing(&into_port, &c2), tool_listing(&into_tool, &c2));

    let port_cwd = base.join("port-cwd");
    let tool_cwd = base.join("tool-cwd");
    for cwd in [&port_cwd, &tool_cwd] {
        std::fs::create_dir_all(cwd.join("out")).unwrap();
    }
    let args = ["--empty", "--to=m", "--inline", "--filename=out/sb"];
    let (p, t) = generate_both(
        (port_cwd.as_path(), port_repo.as_path()),
        (tool_cwd.as_path(), tool_repo.as_path()),
        &args,
    );
    assert_runs_agree_on_stdout(&p, &t, &args);
    assert_eq!(entry_names(&port_cwd.join("out")), ["sb"]);
    assert_eq!(entry_names(&tool_cwd.join("out")), ["sb"]);
    let keys = superblock_keys(&port_cwd.join("out/sb"));
    assert_eq!(keys, superblock_keys(&tool_cwd.join("out/sb")));
    assert_eq!(keys[1], format!("{scratch}/0"));
}

/// Asserts that both runs succeed with the same standard output.
fn assert_runs_agree_on_stdout(port: &Run, tool: &Run, args: &[&str]) {
    for (who, run) in [("port", port), ("tool", tool)] {
        assert!(
            run.status.success(),
            "the {who} failed {args:?}: {}",
            String::from_utf8_lossy(&run.stderr)
        );
    }
    assert_eq!(port.stdout, tool.stdout, "{args:?}");
}

/// The endianness options agree in ostrya and in the `ostree` command over
/// eight forms:
///
/// - the byte that both commands write
/// - the sizes, read back through this byte
/// - the part file, which the byte does not change
///
/// The last `--set-endianness` wins. The order of the flags has no effect. A
/// repeated `--swap-endianness` swaps one time. The test carries
/// `static-delta/generate-set-endianness-big` and
/// `static-delta/generate-swap-endianness`.
#[test]
fn static_delta_generate_endianness_matches_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-generate-endianness");
    let base = tmp.path();
    let (repo, c) = delta_fallback_repo(base, "repo", false);
    let port_repo = clone_repo(base, &repo, "port");
    let tool_repo = clone_repo(base, &repo, "tool");
    let port = (base, port_repo.as_path());
    let tool = (base, tool_repo.as_path());
    let relative = ostrya::static_delta_relative_dir(None, &Checksum::from_hex(&c).unwrap());
    let to = format!("--to={c}");
    // The host of these runs is little-endian.
    let cases: [(&[&str], u8); 8] = [
        (&[], b'l'),
        (&["--swap-endianness"], b'B'),
        (&["--set-endianness=B", "--swap-endianness"], b'l'),
        (&["--set-endianness=l", "--swap-endianness"], b'B'),
        (&["--swap-endianness", "--set-endianness=B"], b'l'),
        (&["--set-endianness=B", "--set-endianness=l"], b'l'),
        (&["--set-endianness", "l", "--set-endianness", "B"], b'B'),
        (&["--swap-endianness", "--swap-endianness"], b'B'),
    ];
    let mut reference: Option<(Vec<u64>, Vec<u8>, Vec<u8>)> = None;
    for (extra, byte) in cases {
        let args = [&["--empty", to.as_str()][..], extra].concat();
        let (p, t) = generate_both(port, tool, &args);
        assert_runs_agree_on_stdout(&p, &t, &args);
        let mut sizes = Vec::new();
        for r in [&port_repo, &tool_repo] {
            let (found, sb) = superblock_endianness(&r.join(&relative).join("superblock"));
            assert_eq!(found, byte, "{extra:?} in {}", r.display());
            let mut these = Vec::new();
            for part in sb.parts() {
                these.extend([part.size(), part.uncompressed_size()]);
            }
            for fallback in sb.fallbacks() {
                these.extend([fallback.size(), fallback.uncompressed_size()]);
            }
            sizes.push(these);
        }
        let parts = (
            std::fs::read(port_repo.join(&relative).join("0")).unwrap(),
            std::fs::read(tool_repo.join(&relative).join("0")).unwrap(),
        );
        match &reference {
            None => reference = Some((sizes[0].clone(), parts.0, parts.1)),
            Some((port_sizes, port_part, tool_part)) => {
                assert_eq!(&sizes[0], port_sizes, "{extra:?}");
                assert_eq!(&parts.0, port_part, "{extra:?}");
                assert_eq!(&parts.1, tool_part, "{extra:?}");
            }
        }
        // The fallback sizes agree. The part sizes depend on the generator.
        assert_eq!(sizes[0][2..], sizes[1][2..], "{extra:?}");
    }
}

/// For a value other than `l` or `B`, ostrya and the `ostree` command exit 1
/// with the same line. They write nothing on standard output and nothing to
/// the repository. Both commands check the value after `-n` and after the
/// default parent, and before the `--filename` directory. The test carries
/// `static-delta/generate-invalid-endianness-refused`.
#[test]
fn static_delta_generate_invalid_endianness_is_refused() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-generate-bad-endianness");
    let base = tmp.path();
    let (repo, c1, c2) = delta_show_repo(base, "repo");
    let port_repo = clone_repo(base, &repo, "port");
    let tool_repo = clone_repo(base, &repo, "tool");
    let port = (base, port_repo.as_path());
    let tool = (base, tool_repo.as_path());
    for (value, extra) in [
        ("b", None),
        ("L", None),
        ("", None),
        ("little", None),
        ("big", None),
        ("Bx", None),
        ("x", Some("--swap-endianness")),
    ] {
        let set = format!("--set-endianness={value}");
        let mut args = vec!["--empty", "--to=m", set.as_str()];
        args.extend(extra);
        let (p, t) = generate_both(port, tool, &args);
        assert_runs_agree(&p, &t, &format!("generate {args:?}"));
        assert_eq!(p.status.code(), Some(1));
        assert!(p.stdout.is_empty());
        assert_eq!(
            String::from_utf8_lossy(&p.stderr),
            format!("error: Invalid endianness '{value}'\n")
        );
    }
    assert_eq!(listed_deltas(&port_repo), vec!["(No static deltas)"]);
    assert_eq!(listed_deltas(&tool_repo), vec!["(No static deltas)"]);

    // If the repository has the delta, `-n` exits 0 before the value check.
    let (p, t) = generate_both(port, tool, &["--to=m"]);
    assert_runs_agree_on_stdout(&p, &t, &["--to=m"]);
    let args = ["-n", "--to=m", "--set-endianness=q"];
    let (p, t) = generate_both(port, tool, &args);
    assert_runs_agree(&p, &t, &format!("generate {args:?}"));
    assert_eq!(
        String::from_utf8_lossy(&p.stdout),
        format!("Delta {c1}-{c2} already exists.\n")
    );

    // A root commit with no source is refused before the value check.
    let to_c1 = format!("--to={c1}");
    let args = [to_c1.as_str(), "--set-endianness=q"];
    let (p, t) = generate_both(port, tool, &args);
    assert_runs_agree(&p, &t, &format!("generate {args:?}"));
    assert_eq!(
        String::from_utf8_lossy(&p.stderr),
        format!("error: Commit {c1} has no parent\n")
    );

    // The value is refused before the command opens the `--filename`
    // directory.
    let args = [
        "--empty",
        "--to=m",
        "--set-endianness=q",
        "--filename=missing/sb",
    ];
    let (p, t) = generate_both(port, tool, &args);
    assert_runs_agree(&p, &t, &format!("generate {args:?}"));
    assert_eq!(
        String::from_utf8_lossy(&p.stderr),
        "error: Invalid endianness 'q'\n"
    );
}

/// `apply-offline` of ostrya reads an inline delta of the `ostree` command.
/// The delta is in the delta directory, or in a superblock file that
/// `--filename` writes. The objects agree with the apply of `ostree`. Both
/// commands print nothing.
#[test]
fn static_delta_apply_offline_reads_an_inline_delta() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-apply-inline");
    let base = tmp.path();
    let (repo, _c1, c2) = delta_show_repo(base, "repo");
    ostree_ok(
        &repo,
        &["static-delta", "generate", "--inline", "--empty", "--to=m"],
    );
    let dir = repo.join(ostrya::static_delta_relative_dir(
        None,
        &Checksum::from_hex(&c2).unwrap(),
    ));
    assert_eq!(entry_names(&dir), ["superblock"]);
    std::fs::create_dir_all(base.join("out")).unwrap();
    let filename = format!("--filename={}", base.join("out/sb").display());
    ostree_ok(
        &repo,
        &[
            "static-delta",
            "generate",
            "--inline",
            "--empty",
            "--to=m",
            &filename,
        ],
    );
    assert_eq!(entry_names(&base.join("out")), ["sb"]);
    for (name, path) in [("dir", dir), ("file", base.join("out/sb"))] {
        let into_port = base.join(format!("into-port-{name}"));
        let into_tool = base.join(format!("into-tool-{name}"));
        ostree_ok(&into_port, &["init", "--mode=bare-user"]);
        ostree_ok(&into_tool, &["init", "--mode=bare-user"]);
        let printed = ostree_ok(
            &into_tool,
            &["static-delta", "apply-offline", path.to_str().unwrap()],
        );
        assert_eq!(printed, "", "{name}");
        let into_port_arg = format!("--repo={}", into_port.display());
        let applied = ostrya(
            &[
                "static-delta",
                &into_port_arg,
                "apply-offline",
                path.to_str().unwrap(),
            ],
            None,
            &[],
        );
        assert_applied_without_ref(&applied, &into_port, &c2, name);
        ostree_ok(&into_port, &["fsck"]);
        assert_eq!(tool_listing(&into_port, &c2), tool_listing(&into_tool, &c2));
    }
}

/// Creates a new archive repository at `base/<name>` with the `ostrya`
/// library.
fn fresh_archive(base: &Path, name: &str) -> PathBuf {
    let repo = base.join(name);
    block_on(async {
        Repo::create(&repo, CreateOptions::new(RepoMode::Archive))
            .await
            .unwrap();
    });
    repo
}

/// Runs `static-delta apply-offline ARGS` of ostrya from `cwd` into `dst`.
fn run_apply_offline(cwd: &Path, dst: &Path, args: &[&str]) -> Run {
    let repo_arg = format!("--repo={}", dst.display());
    let all = [
        &["static-delta", repo_arg.as_str(), "apply-offline"][..],
        args,
    ]
    .concat();
    ostrya_in(Some(cwd), &all, None, &[])
}

/// The expected result of an `apply-offline` run.
enum ApplyOutcome {
    /// Exit 0 with both streams empty, the commit object present, no ref.
    Applied,
    /// Exit 1 with nothing on standard output, this standard error, and no
    /// object in the repository.
    Refused(String),
}

/// Runs each case from `cwd` into its own new archive repository in `cwd`,
/// and asserts its outcome. `commit` is the commit that an applied case
/// delivers.
fn assert_apply_cases(cwd: &Path, commit: &str, cases: &[(&[&str], ApplyOutcome)]) {
    for (i, (args, outcome)) in cases.iter().enumerate() {
        let label = args.join(" ");
        let dst = fresh_archive(cwd, &format!("dst-{i}"));
        let run = run_apply_offline(cwd, &dst, args);
        match outcome {
            ApplyOutcome::Applied => assert_applied_without_ref(&run, &dst, commit, &label),
            ApplyOutcome::Refused(stderr) => {
                assert_verify_run(&run, 1, "", stderr, &label);
                assert_eq!(loose_objects(&dst), [], "{label}: objects were written");
            }
        }
    }
}

/// `apply-offline` prints nothing and writes no ref, for each form of PATH:
///
/// - a delta directory
/// - a superblock with another name, next to its parts
/// - a bare `superblock`, from inside the delta directory
/// - an inline superblock that `--filename` writes
#[test]
fn static_delta_apply_offline_prints_nothing_and_writes_no_ref() {
    let tmp = TmpDir::new("delta-apply-forms");
    let base = tmp.path();
    let repo = verify_fixture(base);
    let signed = only_delta_dir(&repo);
    std::fs::copy(base.join("unsigned/superblock"), base.join("unsigned/sb2")).unwrap();
    std::fs::create_dir_all(base.join("out")).unwrap();
    ostrya_in(
        Some(base),
        &[
            "static-delta",
            "--repo=repo",
            "generate",
            "--empty",
            "--to",
            COMMIT,
            "--inline",
            "--filename=out/sb",
        ],
        None,
        &[],
    )
    .ok();
    assert_eq!(entry_names(&base.join("out")), ["sb"]);
    assert_apply_cases(
        base,
        COMMIT,
        &[
            (&[signed.to_str().unwrap()], ApplyOutcome::Applied),
            (&["unsigned"], ApplyOutcome::Applied),
            (&["unsigned/sb2"], ApplyOutcome::Applied),
            (&["out/sb"], ApplyOutcome::Applied),
        ],
    );
    let dst = fresh_archive(base, "dst-inside");
    let run = run_apply_offline(&base.join("unsigned"), &dst, &["superblock"]);
    assert_applied_without_ref(&run, &dst, COMMIT, "superblock from inside");
}

/// The key sources: a positional KEY-ID, `--keys-file`, and `--keys-dir`. Each
/// of them turns on the verification of a signed delta. The verification runs
/// before the command writes an object. An unsigned delta applies with each
/// key source whose keys load.
#[test]
fn static_delta_apply_offline_key_sources() {
    let tmp = TmpDir::new("delta-apply-keys");
    let base = tmp.path();
    let repo = verify_fixture(base);
    let signed = only_delta_dir(&repo);
    let signed = signed.to_str().unwrap();
    std::fs::write(base.join("k1"), format!("{ED25519_PUBLIC_B64}\n")).unwrap();
    std::fs::write(base.join("k2"), format!("{ED25519_PUBLIC2_B64}\n")).unwrap();
    std::fs::create_dir_all(base.join("adir")).unwrap();
    verify_key_store(base, "store1", &[ED25519_PUBLIC_B64], &[]);
    verify_key_store(base, "store2", &[ED25519_PUBLIC2_B64], &[]);
    verify_key_store(
        base,
        "revoked",
        &[ED25519_PUBLIC_B64],
        &[ED25519_PUBLIC_B64],
    );
    let refused = |text: &str| ApplyOutcome::Refused(format!("error: {text}\n"));
    let no_keys = || refused("signature: ed25519: no keys loaded");
    assert_apply_cases(
        base,
        COMMIT,
        &[
            (&[signed, ED25519_PUBLIC_B64], ApplyOutcome::Applied),
            (&["--keys-file=k1", signed], ApplyOutcome::Applied),
            (&["--keys-dir=store1", signed], ApplyOutcome::Applied),
            (
                &["--keys-file=k2", "--keys-file=k1", signed],
                ApplyOutcome::Applied,
            ),
            (
                &["--keys-dir=store2", "--keys-file=k1", signed],
                ApplyOutcome::Applied,
            ),
            (&["--sign-type=ed25519", signed], ApplyOutcome::Applied),
            (&["unsigned", ED25519_PUBLIC_B64], ApplyOutcome::Applied),
            (&["unsigned", ED25519_PUBLIC2_B64], ApplyOutcome::Applied),
            (&["--keys-dir=revoked", "unsigned"], ApplyOutcome::Applied),
            (
                &[signed, ED25519_PUBLIC2_B64],
                ApplyOutcome::Refused(verify_key_list_error(&[ED25519_PUBLIC2_HEX])),
            ),
            (
                &["--keys-dir=revoked", signed],
                refused("ed25519: no signatures found"),
            ),
            (&["--keys-dir=nodir", signed], no_keys()),
            (&["--keys-dir=nodir", "unsigned"], no_keys()),
            (
                &[signed, "AAAA"],
                refused(
                    "Invalid ed25519 public key: Ill-formed input: expected 32 bytes, got 3 bytes",
                ),
            ),
            (
                &["--keys-file=adir", "unsigned"],
                refused("File object 'adir' is not a regular file"),
            ),
        ],
    );
}

/// The command reads the sign type with or without a key source:
///
/// - A name that ostrya does not have is refused with nothing on standard
///   output.
/// - `dummy` is refused with its own message.
/// - The last `--sign-type` wins.
#[test]
fn static_delta_apply_offline_sign_types() {
    let tmp = TmpDir::new("delta-apply-sign-types");
    let base = tmp.path();
    verify_fixture(base);
    let not_implemented =
        || ApplyOutcome::Refused("error: Requested signature type is not implemented\n".to_owned());
    let dummy = || {
        ApplyOutcome::Refused("error: dummy signature type is only for ostree testing\n".to_owned())
    };
    #[cfg_attr(not(feature = "spki"), allow(unused_mut))]
    let mut cases: Vec<(&[&str], ApplyOutcome)> = vec![
        (&["--sign-type=nosuch", "unsigned"], not_implemented()),
        (
            &["--sign-type=nosuch", "unsigned", ED25519_PUBLIC_B64],
            not_implemented(),
        ),
        (&["--sign-type=gpg", "unsigned"], not_implemented()),
        (&["--sign-type=", "unsigned"], not_implemented()),
        (&["--sign-type=dummy", "unsigned"], dummy()),
        (
            &["--sign-type=dummy", "unsigned", ED25519_PUBLIC_B64],
            dummy(),
        ),
        (
            &[
                "--sign-type=nosuch",
                "--sign-type=ed25519",
                "unsigned",
                ED25519_PUBLIC_B64,
            ],
            ApplyOutcome::Applied,
        ),
        (
            &["--sign-type=ed25519", "--sign-type=nosuch", "unsigned"],
            not_implemented(),
        ),
    ];
    #[cfg(feature = "spki")]
    cases.push((&["--sign-type=spki", "unsigned"], ApplyOutcome::Applied));
    assert_apply_cases(base, COMMIT, &cases);
}

/// The refusals of PATH:
///
/// - no PATH
/// - a path that is absent
/// - a delta name, which the command reads as a path
/// - a directory with no `superblock`
/// - a superblock copied away from its parts
///
/// No refusal writes an object.
#[test]
fn static_delta_apply_offline_path_forms() {
    let tmp = TmpDir::new("delta-apply-paths");
    let base = tmp.path();
    verify_fixture(base);
    std::fs::create_dir_all(base.join("lonely")).unwrap();
    std::fs::copy(base.join("unsigned/superblock"), base.join("away")).unwrap();
    let refused = |text: &str| ApplyOutcome::Refused(format!("error: {text}\n"));
    let absent = || refused("openat(O_DIRECTORY): No such file or directory");
    assert_apply_cases(
        base,
        COMMIT,
        &[
            (&[], refused("PATH must be specified")),
            (&["nothere"], absent()),
            (&[COMMIT], absent()),
            (
                &["lonely"],
                refused("openat(superblock): No such file or directory"),
            ),
        ],
    );
    let dst = fresh_archive(base, "dst-away");
    let run = run_apply_offline(base, &dst, &["away"]);
    assert_eq!(run.status.code(), Some(1));
    assert_eq!(String::from_utf8_lossy(&run.stdout), "");
    assert!(String::from_utf8_lossy(&run.stderr).starts_with("error: "));
    assert_eq!(loose_objects(&dst), []);
}

/// Returns the arguments of a command line as `&str`.
fn str_args(args: &[String]) -> Vec<&str> {
    args.iter().map(String::as_str).collect()
}

/// Runs `static-delta apply-offline ARGS` from `cwd` with ostrya and with the
/// `ostree` command. Each command applies into its own new repository, which
/// `ostree` creates in `mode`. If `prep` is given, both commands first apply
/// `prep`. Asserts these facts:
///
/// - The exit status and both streams agree.
/// - Both repositories have the same objects.
/// - Neither repository has a ref.
fn assert_apply_agrees(cwd: &Path, name: &str, mode: &str, prep: Option<&str>, args: &[&str]) {
    let port_dst = cwd.join(format!("{name}-port"));
    let tool_dst = cwd.join(format!("{name}-tool"));
    let init = format!("--mode={mode}");
    ostree_ok(&port_dst, &["init", &init]);
    ostree_ok(&tool_dst, &["init", &init]);
    let apply = |dst: &Path, args: &[&str]| {
        let repo_arg = format!("--repo={}", dst.display());
        [
            &["static-delta", repo_arg.as_str(), "apply-offline"][..],
            args,
        ]
        .concat()
        .into_iter()
        .map(str::to_owned)
        .collect::<Vec<_>>()
    };
    if let Some(prep) = prep {
        ostrya_in(Some(cwd), &str_args(&apply(&port_dst, &[prep])), None, &[]).ok();
        let tool = ostree_in(cwd, &str_args(&apply(&tool_dst, &[prep])));
        assert!(tool.status.success(), "the tool did not apply {prep}");
    }
    let port_args = apply(&port_dst, args);
    let tool_args = apply(&tool_dst, args);
    let port = ostrya_in(Some(cwd), &str_args(&port_args), None, &[]);
    let tool = ostree_in(cwd, &str_args(&tool_args));
    let label = args.join(" ");
    assert_runs_agree(&port, &tool, &format!("static-delta apply-offline {label}"));
    assert_eq!(
        loose_objects(&port_dst),
        loose_objects(&tool_dst),
        "{label}"
    );
    for dst in [&port_dst, &tool_dst] {
        assert_eq!(
            files_under(&dst.join("refs")),
            [] as [PathBuf; 0],
            "{label}"
        );
    }
}

/// Runs the cases of the two tests that compare ostrya with the `ostree`
/// command, from `base` over `base/repo`. `base/repo` has these deltas:
///
/// - an unsigned delta to `c1`
/// - a delta to `c2`, signed with the shared key
/// - a delta from `c1` to `c2`, signed with the shared key
fn assert_apply_cases_agree(base: &Path, c1: &str, c2: &str) {
    std::fs::write(base.join("k1"), format!("{ED25519_PUBLIC_B64}\n")).unwrap();
    std::fs::write(base.join("k2"), format!("{ED25519_PUBLIC2_B64}\n")).unwrap();
    verify_key_store(base, "store1", &[ED25519_PUBLIC_B64], &[]);
    verify_key_store(base, "store2", &[ED25519_PUBLIC2_B64], &[]);
    verify_key_store(
        base,
        "revoked",
        &[ED25519_PUBLIC_B64],
        &[ED25519_PUBLIC_B64],
    );
    std::fs::write(
        base.join("trusted.ed25519"),
        format!("{ED25519_PUBLIC_B64}\n"),
    )
    .unwrap();
    let checksum = |hex: &str| Checksum::from_hex(hex).unwrap();
    let unsigned = format!(
        "repo/{}",
        ostrya::static_delta_relative_dir(None, &checksum(c1))
    );
    let signed = format!(
        "repo/{}",
        ostrya::static_delta_relative_dir(None, &checksum(c2))
    );
    let from_to = format!(
        "repo/{}",
        ostrya::static_delta_relative_dir(Some(&checksum(c1)), &checksum(c2))
    );
    std::os::unix::fs::symlink(&signed, base.join("lnk")).unwrap();
    std::fs::copy(
        base.join(&signed).join("superblock"),
        base.join(&signed).join("sb-other"),
    )
    .unwrap();
    let signed_sb = format!("{signed}/superblock");
    let signed_other = format!("{signed}/sb-other");
    // A lexical resolution of `lnk/../<rest>` gives `<rest>` next to the link.
    // This directory has a copy of the unsigned delta. The kernel resolves the
    // path to the signed delta.
    let rest = Path::new(&signed).file_name().unwrap().to_str().unwrap();
    std::fs::create_dir_all(base.join(rest)).unwrap();
    for entry in std::fs::read_dir(base.join(&unsigned)).unwrap() {
        let entry = entry.unwrap();
        std::fs::copy(entry.path(), base.join(rest).join(entry.file_name())).unwrap();
    }
    let lexical_dir = format!("lnk/../{rest}");
    let lexical_sb = format!("lnk/../{rest}/superblock");
    let sb_parent = format!("{signed_sb}/..");
    let sb_slash = format!("{signed_sb}/");
    let sb_dot = format!("{signed_sb}/.");

    let cases: Vec<Vec<&str>> = vec![
        vec![&signed],
        vec![&signed_sb],
        vec![&signed_other],
        vec!["lnk"],
        vec![&lexical_dir],
        vec![&lexical_sb],
        vec!["lnk/superblock/.."],
        vec![&sb_parent],
        vec![&sb_slash],
        vec![&sb_dot],
        vec![&lexical_dir, ED25519_PUBLIC2_B64],
        vec![&unsigned],
        vec![&signed, ED25519_PUBLIC_B64],
        vec![&signed_sb, ED25519_PUBLIC_B64],
        vec![&signed, ED25519_PUBLIC2_B64],
        vec![&signed, ED25519_PUBLIC2_B64, ED25519_PUBLIC_B64],
        vec![&unsigned, ED25519_PUBLIC2_B64],
        vec!["--keys-file=k2", "--keys-file=k1", &signed],
        vec!["--keys-file=k1", "--keys-file=k2", &signed],
        vec!["--keys-dir=store1", "--keys-file=k2", &signed],
        vec!["--keys-dir=store1", &signed],
        vec!["--keys-dir=store2", &signed],
        vec!["--keys-dir=revoked", &signed],
        vec!["--keys-dir=revoked", &unsigned],
        vec!["--keys-dir=nodir", &unsigned],
        vec!["--keys-dir=", &signed],
        vec![&unsigned, "AAAA"],
        vec!["--sign-type=ed25519", &signed],
        vec![
            "--sign-type=nosuch",
            "--sign-type=ed25519",
            &signed,
            ED25519_PUBLIC_B64,
        ],
    ];
    for (i, case) in cases.iter().enumerate() {
        assert_apply_agrees(base, &format!("dst-{i}"), "archive", None, case);
    }
    // `ostree` applies a delta that opens a source object only into a bare
    // repository.
    assert_apply_agrees(
        base,
        "dst-from",
        "bare-user",
        Some(&unsigned),
        &[&from_to, ED25519_PUBLIC_B64],
    );
    assert_apply_agrees(
        base,
        "dst-from-wrong",
        "bare-user",
        Some(&unsigned),
        &[&from_to, ED25519_PUBLIC2_B64],
    );
}

/// `apply-offline` of ostrya agrees with the `ostree` command over the deltas
/// of `ostree`: the exit status, both streams, and the objects written. The
/// test carries
/// `static-delta/apply-offline-{superblock-file,verify-wrong-key-no-objects,unsigned-with-keys,positional-key}`
/// with `ostree` as the producer.
#[test]
fn static_delta_apply_offline_matches_the_tool_over_the_tools_deltas() {
    if !ostree_supports_ed25519() {
        return;
    }
    let tmp = TmpDir::new("delta-apply-tool");
    let (repo, c1, c2) = delta_show_repo(tmp.path(), "repo");
    let sign = format!("--sign={ED25519_SECRET_B64}");
    ostree_ok(&repo, &["static-delta", "generate", "--empty", "--to", &c1]);
    for from in [&["--empty"][..], &["--from", &c1]] {
        let args = [
            &["static-delta", "generate"][..],
            from,
            &["--to", &c2, "--sign-type=ed25519", &sign],
        ]
        .concat();
        ostree_ok(&repo, &args);
    }
    assert_apply_cases_agree(tmp.path(), &c1, &c2);
}

/// Does the same as
/// `static_delta_apply_offline_matches_the_tool_over_the_tools_deltas` over
/// the deltas of ostrya. The test carries the same cells, with ostrya as the
/// producer.
#[test]
fn static_delta_apply_offline_matches_the_tool_over_the_ports_deltas() {
    if !ostree_supports_ed25519() {
        return;
    }
    let tmp = TmpDir::new("delta-apply-port");
    let (repo, c1, c2) = delta_show_repo(tmp.path(), "repo");
    let repo_s = repo.to_str().unwrap();
    let sign = format!("--sign={ED25519_SECRET_B64}");
    let generate = |extra: &[&str]| {
        let base = [
            "static-delta",
            "--repo",
            repo_s,
            "generate",
            "--timestamp=1700000000",
        ];
        ostrya(&[&base[..], extra].concat(), None, &[]).ok();
    };
    generate(&["--empty", "--to", &c1]);
    generate(&["--empty", "--to", &c2, &sign]);
    generate(&["--from", &c1, "--to", &c2, &sign]);
    assert_apply_cases_agree(tmp.path(), &c1, &c2);
}

/// The refusals of ostrya and of the `ostree` command agree:
///
/// - no PATH
/// - an absent path
/// - a delta name
/// - a directory with no `superblock`
/// - a superblock file that does not open
/// - keys that do not load
///
/// For an unknown sign type, the exit status, standard output, and the last
/// line of standard error agree. `ostree` writes a GLib warning before this
/// line.
#[test]
fn static_delta_apply_offline_refusals_match_the_tool() {
    if !ostree_supports_ed25519() {
        return;
    }
    let tmp = TmpDir::new("delta-apply-refusals");
    let base = tmp.path();
    let (repo, _, c2) = delta_show_repo(base, "repo");
    ostree_ok(&repo, &["static-delta", "generate", "--empty", "--to", &c2]);
    std::fs::create_dir_all(base.join("lonely")).unwrap();
    let delta = format!(
        "repo/{}",
        ostrya::static_delta_relative_dir(None, &Checksum::from_hex(&c2).unwrap())
    );
    let cases: Vec<Vec<&str>> = vec![
        vec![],
        vec!["nothere"],
        vec![&c2],
        vec!["lonely"],
        vec!["lonely", ED25519_PUBLIC_B64],
        vec![&delta, "AAAA"],
        vec!["--keys-dir=nodir", &delta],
        vec!["--keys-file=nosuch", &delta],
    ];
    for (i, case) in cases.iter().enumerate() {
        assert_apply_agrees(base, &format!("dst-{i}"), "archive", None, case);
    }
    // The message names a superblock file that does not open by its last
    // component. Under root, a file of mode 000 opens, so the case checks
    // nothing and the test skips it.
    std::fs::create_dir_all(base.join("perm")).unwrap();
    let locked = base.join("perm/superblock");
    std::fs::copy(base.join(&delta).join("superblock"), &locked).unwrap();
    std::fs::set_permissions(&locked, std::fs::Permissions::from_mode(0o000)).unwrap();
    if std::fs::File::open(&locked).is_err() {
        for (i, case) in [
            vec!["perm/superblock"],
            vec!["perm/../perm/superblock"],
            vec!["perm"],
        ]
        .iter()
        .enumerate()
        {
            assert_apply_agrees(base, &format!("dst-perm-{i}"), "archive", None, case);
        }
    }
    for (i, case) in [
        vec!["--sign-type=nosuch", delta.as_str()],
        vec!["--sign-type=nosuch", delta.as_str(), ED25519_PUBLIC_B64],
        vec!["--sign-type=gpg", delta.as_str()],
    ]
    .iter()
    .enumerate()
    {
        let dst = base.join(format!("sign-type-{i}"));
        ostree_ok(&dst, &["init", "--mode=archive"]);
        let repo_arg = format!("--repo={}", dst.display());
        let all = [
            &["static-delta", repo_arg.as_str(), "apply-offline"][..],
            case,
        ]
        .concat();
        let port = ostrya_in(Some(base), &all, None, &[]);
        let tool = ostree_in(base, &all);
        let last = |run: &Run| {
            let text = String::from_utf8_lossy(&run.stderr).into_owned();
            text.lines().last().unwrap_or_default().to_owned()
        };
        let label = case.join(" ");
        assert_eq!(
            (port.status.code(), &port.stdout, last(&port)),
            (tool.status.code(), &tool.stdout, last(&tool)),
            "{label}"
        );
        assert_eq!(
            last(&port),
            "error: Requested signature type is not implemented"
        );
        assert_eq!(loose_objects(&dst), [], "{label}");
    }
}

/// The recorded divergences do not change:
///
/// - The `ostree` command applies an unsigned delta with `--sign-type=dummy`.
///   ostrya refuses.
/// - `ostree` applies with a key that decodes to no curve point. ostrya
///   refuses. This is true over an unsigned delta. It is also true over a
///   signed delta, next to a key that verifies the delta, in each order.
/// - `ostree` refuses `--sign-type=spki`. ostrya applies with it in a build
///   that has the engine.
///
/// Both commands refuse a part that does not open and a superblock that does
/// not parse, with different messages.
#[test]
fn static_delta_apply_offline_divergences_stand_as_recorded() {
    if !ostree_supports_ed25519() {
        return;
    }
    let tmp = TmpDir::new("delta-apply-divergences");
    let base = tmp.path();
    let (repo, c1, c2) = delta_show_repo(base, "repo");
    ostree_ok(&repo, &["static-delta", "generate", "--empty", "--to", &c2]);
    let sign = format!("--sign={ED25519_SECRET_B64}");
    ostree_ok(
        &repo,
        &[
            "static-delta",
            "generate",
            "--empty",
            "--to",
            &c1,
            "--sign-type=ed25519",
            &sign,
        ],
    );
    let relative = |hex: &str| {
        format!(
            "repo/{}",
            ostrya::static_delta_relative_dir(None, &Checksum::from_hex(hex).unwrap())
        )
    };
    let delta = relative(&c2);
    let signed = relative(&c1);
    std::fs::copy(base.join(&delta).join("superblock"), base.join("away")).unwrap();
    std::fs::write(base.join("garbage"), b"garbage\n").unwrap();
    let run_both_into = |name: &str, args: &[&str]| {
        let port_dst = base.join(format!("{name}-port"));
        let tool_dst = base.join(format!("{name}-tool"));
        ostree_ok(&port_dst, &["init", "--mode=archive"]);
        ostree_ok(&tool_dst, &["init", "--mode=archive"]);
        let all = |dst: &Path| {
            let repo_arg = format!("--repo={}", dst.display());
            let mut all = vec![
                "static-delta".to_owned(),
                repo_arg,
                "apply-offline".to_owned(),
            ];
            all.extend(args.iter().map(|arg| (*arg).to_owned()));
            all
        };
        let port_args = all(&port_dst);
        let tool_args = all(&tool_dst);
        let port = ostrya_in(Some(base), &str_args(&port_args), None, &[]);
        let tool = ostree_in(base, &str_args(&tool_args));
        (
            port,
            tool,
            loose_objects(&port_dst),
            loose_objects(&tool_dst),
        )
    };
    let tool_applies = [
        vec!["--sign-type=dummy", delta.as_str()],
        vec![delta.as_str(), ED25519_NOT_A_POINT_B64],
        vec![signed.as_str(), ED25519_PUBLIC_B64, ED25519_NOT_A_POINT_B64],
        vec![signed.as_str(), ED25519_NOT_A_POINT_B64, ED25519_PUBLIC_B64],
    ];
    for (i, case) in tool_applies.iter().enumerate() {
        let label = case.join(" ");
        let (port, tool, port_objects, tool_objects) = run_both_into(&format!("dst-{i}"), case);
        assert_eq!(tool.status.code(), Some(0), "{label}");
        assert!(!tool_objects.is_empty(), "{label}");
        assert_eq!(port.status.code(), Some(1), "{label}");
        assert_eq!(port_objects, [], "{label}");
    }
    let (port, tool, port_objects, tool_objects) =
        run_both_into("spki", &["--sign-type=spki", &delta]);
    assert_eq!(tool.status.code(), Some(1));
    assert_eq!(tool_objects, []);
    #[cfg(feature = "spki")]
    {
        assert_eq!(port.status.code(), Some(0));
        assert!(!port_objects.is_empty());
    }
    #[cfg(not(feature = "spki"))]
    {
        assert_eq!(port.status.code(), Some(1));
        assert_eq!(port_objects, []);
    }
    for (i, case) in [["away"], ["garbage"]].iter().enumerate() {
        let (port, tool, port_objects, tool_objects) =
            run_both_into(&format!("both-refuse-{i}"), case);
        assert_eq!(port.status.code(), Some(1), "{case:?}");
        assert_eq!(tool.status.code(), Some(1), "{case:?}");
        assert_ne!(port.stderr, tool.stderr, "{case:?}");
        assert_eq!(port_objects, []);
        assert_eq!(tool_objects, []);
    }
}

/// Creates the archive repository of `delta_show_repo` with the `ostree`
/// command, with `count` commits on `m` in total. Each commit after the second
/// changes the small file. Returns the path and the commits, oldest first.
fn delta_chain_repo(base: &Path, name: &str, count: usize) -> (PathBuf, Vec<String>) {
    let (repo, c1, c2) = delta_show_repo(base, name);
    let tree_arg = format!("--tree=dir={}", base.join(format!("{name}-tree")).display());
    let mut commits = vec![c1, c2];
    for i in commits.len()..count {
        std::fs::write(base.join(format!("{name}-tree/a")), format!("hello\n{i}\n")).unwrap();
        let timestamp = format!("--timestamp=@{}", 1_700_000_000 + 100 * i);
        commits.push(ostree_ok(
            &repo,
            &["commit", "-b", "m", "-s", "next", &timestamp, &tree_arg],
        ));
    }
    (repo, commits)
}

/// Returns the entries of the `ostree.static-deltas` map in `dict`, in stored
/// order: each delta name with its digest bytes. `dict` is the `a{sv}` of an
/// index file or the metadata dict of the summary.
fn delta_map_entries(dict: &Value) -> Vec<(String, Vec<u8>)> {
    let entries = dict.as_array().unwrap();
    let map = entries
        .iter()
        .find_map(|entry| {
            let [Value::Str(key), value] = entry.as_tuple().unwrap() else {
                panic!("a dict entry is not (key, value)");
            };
            (key == "ostree.static-deltas").then(|| value.as_variant().unwrap().1)
        })
        .expect("the dict carries ostree.static-deltas");
    map.as_array()
        .unwrap()
        .iter()
        .map(|entry| {
            let [Value::Str(name), value] = entry.as_tuple().unwrap() else {
                panic!("a delta map entry is not (name, digest)");
            };
            let digest = value.as_variant().unwrap().1.as_bytes().unwrap().to_vec();
            (name.clone(), digest)
        })
        .collect()
}

/// Returns the delta map entries of the index file at `path`, in stored order.
fn index_entries(path: &Path) -> Vec<(String, Vec<u8>)> {
    let bytes = std::fs::read(path).unwrap();
    let dict = ostrya::from_bytes(&Type::parse("a{sv}").unwrap(), &bytes).unwrap();
    let entries = delta_map_entries(&dict);
    assert_eq!(
        dict.as_array().unwrap().len(),
        1,
        "{} holds more than the delta map",
        path.display()
    );
    entries
}

/// Returns the delta map entries of the summary of `repo`, in stored order.
fn summary_static_delta_entries(repo: &Path) -> Vec<(String, Vec<u8>)> {
    let bytes = std::fs::read(repo.join("summary")).unwrap();
    delta_map_entries(&ostrya::Summary::parse(&bytes).unwrap().metadata)
}

/// Returns each file in `delta-indexes/` of `repo` with its bytes, keyed by
/// its path relative to `delta-indexes/`. The map is empty if the directory
/// is absent.
fn index_file_bytes(repo: &Path) -> std::collections::BTreeMap<String, Vec<u8>> {
    let mut out = std::collections::BTreeMap::new();
    let Ok(fanouts) = std::fs::read_dir(repo.join("delta-indexes")) else {
        return out;
    };
    for fanout in fanouts {
        let fanout = fanout.unwrap();
        if !fanout.file_type().unwrap().is_dir() {
            continue;
        }
        for file in std::fs::read_dir(fanout.path()).unwrap() {
            let file = file.unwrap();
            if !file.file_type().unwrap().is_file() {
                continue;
            }
            let rel = format!(
                "{}/{}",
                fanout.file_name().to_string_lossy(),
                file.file_name().to_string_lossy()
            );
            out.insert(rel, std::fs::read(file.path()).unwrap());
        }
    }
    out
}

/// Asserts that the `delta-indexes/` trees of `port` and `tool` agree:
///
/// - the same paths, modes, and sizes
/// - the same entries in each index file, with the entries of `port` in name
///   order
/// - the same bytes in each file of one entry
fn assert_delta_indexes_agree(port: &Path, tool: &Path, label: &str) {
    let describe = |repo: &Path| {
        let dir = repo.join("delta-indexes");
        dir.exists().then(|| describe_tree(&dir))
    };
    assert_eq!(describe(port), describe(tool), "{label}: the trees differ");
    let port_files = index_file_bytes(port);
    let tool_files = index_file_bytes(tool);
    for (rel, port_bytes) in &port_files {
        let path = |repo: &Path| repo.join("delta-indexes").join(rel);
        let port_entries = index_entries(&path(port));
        let mut tool_entries = index_entries(&path(tool));
        let mut sorted = port_entries.clone();
        sorted.sort();
        assert_eq!(port_entries, sorted, "{label}: {rel} is not in name order");
        tool_entries.sort();
        assert_eq!(port_entries, tool_entries, "{label}: {rel} entries differ");
        if port_entries.len() == 1 {
            assert_eq!(port_bytes, &tool_files[rel], "{label}: {rel} bytes differ");
        }
    }
}

/// Removes the delta from `from` to `to` in `repo` by hand.
fn remove_delta_dir(repo: &Path, from: Option<&str>, to: &str) {
    let from = from.map(|from| Checksum::from_hex(from).unwrap());
    let relative =
        ostrya::static_delta_relative_dir(from.as_ref(), &Checksum::from_hex(to).unwrap());
    std::fs::remove_dir_all(repo.join(relative)).unwrap();
}

/// Creates a repository of three commits with the `ostree` command. The
/// repository has each delta into each commit, and the full pass of `ostree`
/// indexes them:
///
/// - from scratch into each commit
/// - from the first commit into the second and the third
/// - from the second commit into the third
fn delta_reindex_repo(base: &Path, name: &str) -> (PathBuf, Vec<String>) {
    let (repo, commits) = delta_chain_repo(base, name, 3);
    let [c1, c2, c3] = [&commits[0], &commits[1], &commits[2]];
    for (from, to) in [
        (None, c1),
        (None, c2),
        (Some(c1), c2),
        (None, c3),
        (Some(c1), c3),
        (Some(c2), c3),
    ] {
        let mut args = vec!["static-delta", "generate", "--to", to];
        match from {
            Some(from) => args.extend(["--from", from]),
            None => args.push("--empty"),
        }
        ostree_ok(&repo, &args);
    }
    ostree_ok(&repo, &["static-delta", "reindex"]);
    (repo, commits)
}

/// Returns the path of the index of target `to`, relative to
/// `delta-indexes/`.
fn index_rel(to: &str) -> String {
    let b64 = Checksum::from_hex(to).unwrap().to_base64_modified();
    let (fanout, rest) = b64.split_at(2);
    format!("{fanout}/{rest}.index")
}

/// Runs `static-delta ARGS` against `port` with ostrya and against `tool` with
/// the `ostree` command. A leading `--repo=` names the repository. Returns
/// both runs.
fn run_reindex_both(port: &Path, tool: &Path, args: &[&str]) -> (Run, Run) {
    let all = |repo: &Path| {
        let repo_arg = format!("--repo={}", repo.display());
        let mut all = vec!["static-delta".to_owned(), repo_arg];
        all.extend(args.iter().map(|arg| (*arg).to_owned()));
        all
    };
    let port_args = all(port);
    let tool_args = all(tool);
    let port = ostrya(
        &port_args.iter().map(String::as_str).collect::<Vec<_>>(),
        None,
        &[],
    );
    let tool = ostree(&tool_args.iter().map(String::as_str).collect::<Vec<_>>());
    (port, tool)
}

/// `static-delta reindex --to=REV` of ostrya does the same as the `ostree`
/// command over one repository, in six steps:
///
/// 1. A pass over one target writes its index file again. The other files do
///    not change, byte for byte, and this includes stale files.
/// 2. A pass over a target with no remaining delta removes its file and keeps
///    the fanout directory.
/// 3. If `--to` is given two times, the last value wins.
/// 4. The command writes again an index file that was removed by hand.
/// 5. A target with no delta and no index file changes nothing.
/// 6. A repository with no `deltas/` gets no `delta-indexes/`.
///
/// Each run exits 0 and writes nothing to either stream. After each step, an
/// index file of one entry is byte-identical in the two repositories.
#[test]
fn static_delta_reindex_to_matches_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-reindex-to");
    let base = tmp.path();
    let (repo, commits) = delta_reindex_repo(base, "repo");
    let [c1, c2, c3] = [&commits[0], &commits[1], &commits[2]];
    let port = clone_repo(base, &repo, "port");
    let tool = clone_repo(base, &repo, "tool");

    let reindex = |args: &[&str], label: &str| {
        let all = [&["reindex"][..], args].concat();
        let (port_run, tool_run) = run_reindex_both(&port, &tool, &all);
        assert_runs_agree(&port_run, &tool_run, label);
        assert!(port_run.status.success(), "{label}: the port failed");
        assert!(port_run.stdout.is_empty() && port_run.stderr.is_empty());
        assert_delta_indexes_agree(&port, &tool, label);
    };

    // One target: the index of c3 lists the two remaining deltas, and the
    // other files do not change.
    let before = index_file_bytes(&port);
    for side in [&port, &tool] {
        remove_delta_dir(side, Some(c1), c3);
    }
    reindex(&[&format!("--to={c3}")], "--to=c3");
    let after = index_file_bytes(&port);
    assert_eq!(
        index_entries(&port.join("delta-indexes").join(index_rel(c3))).len(),
        2
    );
    for to in [c1, c2] {
        assert_eq!(
            after[&index_rel(to)],
            before[&index_rel(to)],
            "the index of {to} changed"
        );
    }

    // No remaining delta: the command removes the index file and keeps the
    // fanout directory.
    for side in [&port, &tool] {
        remove_delta_dir(side, None, c1);
    }
    reindex(&[&format!("--to={c1}")], "--to=c1");
    let c1_index = port.join("delta-indexes").join(index_rel(c1));
    assert!(!c1_index.exists(), "the index of c1 stayed");
    assert!(c1_index.parent().unwrap().is_dir(), "the fanout of c1 went");

    // The last `--to` wins: the stale file of c2 still lists c1-c2.
    for side in [&port, &tool] {
        remove_delta_dir(side, Some(c1), c2);
    }
    reindex(
        &[&format!("--to={c2}"), &format!("--to={c3}")],
        "--to=c2 --to=c3",
    );
    let c2_index = port.join("delta-indexes").join(index_rel(c2));
    assert_eq!(
        index_entries(&c2_index).len(),
        2,
        "the stale index of c2 was rewritten"
    );

    // An index file removed by hand is written again.
    for side in [&port, &tool] {
        std::fs::remove_file(side.join("delta-indexes").join(index_rel(c2))).unwrap();
    }
    reindex(&[&format!("--to={c2}")], "--to=c2");
    assert_eq!(index_entries(&c2_index).len(), 1);

    // A target with no delta and no index changes nothing.
    let before = index_file_bytes(&port);
    reindex(&[&format!("--to={}", "0".repeat(64))], "--to=<zeros>");
    assert_eq!(index_file_bytes(&port), before);

    // A repository with no `deltas/` gets no `delta-indexes/`.
    let (bare, bare_commits) = delta_chain_repo(base, "bare", 2);
    let bare_port = clone_repo(base, &bare, "bare-port");
    let label = "--to over no deltas/";
    let to_arg = format!("--to={}", bare_commits[1]);
    let (port_run, tool_run) = run_reindex_both(&bare_port, &bare, &["reindex", &to_arg]);
    assert_runs_agree(&port_run, &tool_run, label);
    assert!(port_run.status.success(), "{label}: the port failed");
    for side in [&bare_port, &bare] {
        assert!(
            !side.join("delta-indexes").exists(),
            "{label}: delta-indexes/ was created"
        );
    }
}

/// The refusals of `--to` agree in ostrya and in the `ostree` command on the
/// exit status and both streams. They do not change `delta-indexes/`. The
/// refused values:
///
/// - a ref
/// - a caret revision
/// - an abbreviated checksum
/// - uppercase hex
/// - 63 and 65 characters
/// - a delta name
/// - an empty value
/// - a character after `f`
///
/// Both commands exit 1 with different messages for a `--to` with no value.
/// This is also true for a directory at the index path, of a target with a
/// delta and of a target with none.
#[test]
fn static_delta_reindex_to_refusals_match_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-reindex-to-refusals");
    let base = tmp.path();
    let (repo, commits) = delta_reindex_repo(base, "repo");
    let [c1, c2, c3] = [&commits[0], &commits[1], &commits[2]];
    let port = clone_repo(base, &repo, "port");
    let tool = clone_repo(base, &repo, "tool");
    let before = index_file_bytes(&port);

    let upper = c1.to_uppercase();
    let long = format!("{c1}0");
    let pair = format!("{c1}-{c2}");
    let bad_char = format!("{}g", &c1[..63]);
    for (value, message) in [
        ("m", "error: Invalid rev m\n".to_owned()),
        ("^m", "error: Invalid rev ^m\n".to_owned()),
        (&c1[..10], format!("error: Invalid rev {}\n", &c1[..10])),
        (
            upper.as_str(),
            format!(
                "error: Invalid character '{}' in rev '{upper}'\n",
                upper.bytes().find(u8::is_ascii_uppercase).unwrap()
            ),
        ),
        (&c1[..63], format!("error: Invalid rev {}\n", &c1[..63])),
        (long.as_str(), format!("error: Invalid rev {c1}\n")),
        (pair.as_str(), format!("error: Invalid rev {c1}\n")),
        ("", "error: Invalid rev \n".to_owned()),
        (
            bad_char.as_str(),
            format!("error: Invalid character '103' in rev '{bad_char}'\n"),
        ),
    ] {
        let to_arg = format!("--to={value}");
        let (port_run, tool_run) = run_reindex_both(&port, &tool, &["reindex", &to_arg]);
        assert_runs_agree(&port_run, &tool_run, &to_arg);
        assert_eq!(port_run.status.code(), Some(1), "{to_arg}");
        assert!(port_run.stdout.is_empty(), "{to_arg}");
        assert_eq!(
            String::from_utf8_lossy(&port_run.stderr),
            message,
            "{to_arg}"
        );
        assert_eq!(index_file_bytes(&port), before, "{to_arg}: the port wrote");
        assert_eq!(index_file_bytes(&tool), before, "{to_arg}: the tool wrote");
    }

    // `--to` with no value: `ostree` and `clap` refuse with different
    // messages.
    let (port_run, tool_run) = run_reindex_both(&port, &tool, &["reindex", "--to"]);
    assert_eq!(
        (port_run.status.code(), tool_run.status.code()),
        (Some(1), Some(1))
    );
    assert!(String::from_utf8_lossy(&tool_run.stderr).contains("error: Missing argument for --to"));
    assert!(
        String::from_utf8_lossy(&port_run.stderr).contains("a value is required for '--to <REV>'")
    );
    assert_eq!(index_file_bytes(&port), before);

    // A directory at the index path, of a target with no remaining delta and
    // of a target with deltas.
    for side in [&port, &tool] {
        remove_delta_dir(side, None, c1);
        for to in [c1, c3] {
            let path = side.join("delta-indexes").join(index_rel(to));
            std::fs::remove_file(&path).unwrap();
            std::fs::create_dir(&path).unwrap();
        }
    }
    for (to, tool_word) in [(c1, "error: unlink("), (c3, "error: renameat(")] {
        let to_arg = format!("--to={to}");
        let (port_run, tool_run) = run_reindex_both(&port, &tool, &["reindex", &to_arg]);
        assert_eq!(
            (port_run.status.code(), tool_run.status.code()),
            (Some(1), Some(1)),
            "{to_arg}"
        );
        let tool_err = String::from_utf8_lossy(&tool_run.stderr);
        assert!(
            tool_err.starts_with(tool_word) && tool_err.contains("Is a directory"),
            "{tool_err}"
        );
        let port_err = String::from_utf8_lossy(&port_run.stderr);
        assert!(port_err.contains("Is a directory"), "{port_err}");
        for side in [&port, &tool] {
            assert!(
                side.join("delta-indexes").join(index_rel(to)).is_dir(),
                "{to_arg}"
            );
            let fanout = side.join("delta-indexes").join(&index_rel(to)[..2]);
            let names: Vec<_> = std::fs::read_dir(&fanout)
                .unwrap()
                .map(|e| e.unwrap().file_name())
                .collect();
            assert_eq!(
                names.len(),
                1,
                "{to_arg}: a temp file stayed in {}",
                fanout.display()
            );
        }
    }

    // The index path of c1, which has no remaining delta, goes through a
    // component that is not a directory:
    // - a regular file at the fanout
    // - a symlink to a regular file at the fanout
    // - a regular file at `delta-indexes`
    // Both commands refuse at exit 1 with different messages. A dangling
    // symlink at the fanout counts as an absent file, and both exit 0.
    let to_arg = format!("--to={c1}");
    let fanout_rel = format!("delta-indexes/{}", &index_rel(c1)[..2]);
    type Setup = fn(&Path, &str);
    let cases: [(&str, Setup, bool); 4] = [
        (
            "a file at the fanout",
            |side, fanout| std::fs::write(side.join(fanout), b"x").unwrap(),
            false,
        ),
        (
            "a symlink to a file at the fanout",
            |side, fanout| {
                std::fs::write(side.join("regular"), b"x").unwrap();
                std::os::unix::fs::symlink("../regular", side.join(fanout)).unwrap();
            },
            false,
        ),
        (
            "a dangling symlink at the fanout",
            |side, fanout| std::os::unix::fs::symlink("../absent", side.join(fanout)).unwrap(),
            true,
        ),
        (
            "a file at delta-indexes",
            |side, _| {
                std::fs::remove_dir_all(side.join("delta-indexes")).unwrap();
                std::fs::write(side.join("delta-indexes"), b"x").unwrap();
            },
            false,
        ),
    ];
    for (label, setup, succeeds) in cases {
        for side in [&port, &tool] {
            let fanout = side.join(&fanout_rel);
            match std::fs::symlink_metadata(&fanout) {
                Ok(meta) if meta.is_dir() => std::fs::remove_dir_all(&fanout).unwrap(),
                Ok(_) => std::fs::remove_file(&fanout).unwrap(),
                Err(_) => {}
            }
            let _ = std::fs::remove_file(side.join("regular"));
            setup(side, &fanout_rel);
        }
        let (port_run, tool_run) = run_reindex_both(&port, &tool, &["reindex", &to_arg]);
        if succeeds {
            assert_runs_agree(&port_run, &tool_run, label);
            assert!(port_run.status.success(), "{label}: the port failed");
            continue;
        }
        assert_eq!(
            (port_run.status.code(), tool_run.status.code()),
            (Some(1), Some(1)),
            "{label}"
        );
        let tool_err = String::from_utf8_lossy(&tool_run.stderr);
        assert!(
            tool_err.starts_with("error: unlink(") && tool_err.contains("Not a directory"),
            "{label}: {tool_err}"
        );
        let port_err = String::from_utf8_lossy(&port_run.stderr);
        assert!(port_err.contains("Not a directory"), "{label}: {port_err}");
    }
}

/// A positional after `reindex` is a divergence from the `ostree` command.
/// `ostree` ignores it and runs the full pass. ostrya refuses it at exit 1 and
/// writes nothing.
#[test]
fn static_delta_reindex_argument_handling_parts_from_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-reindex-positional");
    let base = tmp.path();
    let (repo, commits) = delta_reindex_repo(base, "repo");
    let port = clone_repo(base, &repo, "port");
    let tool = clone_repo(base, &repo, "tool");
    for side in [&port, &tool] {
        remove_delta_dir(side, None, &commits[0]);
    }
    let before = index_file_bytes(&port);

    let (port_run, tool_run) = run_reindex_both(&port, &tool, &["reindex", &commits[1]]);
    assert!(
        tool_run.status.success(),
        "{}",
        String::from_utf8_lossy(&tool_run.stderr)
    );
    assert!(
        !tool
            .join("delta-indexes")
            .join(index_rel(&commits[0]))
            .exists(),
        "the tool did not run the full pass"
    );
    assert_eq!(port_run.status.code(), Some(1));
    assert!(port_run.stdout.is_empty());
    assert!(
        String::from_utf8_lossy(&port_run.stderr).contains(&format!(
            "error: unexpected argument '{}' found",
            commits[1]
        )),
        "{}",
        String::from_utf8_lossy(&port_run.stderr)
    );
    assert_eq!(index_file_bytes(&port), before, "the port wrote");
}

/// The entry order of an index file and of the `ostree.static-deltas` map of
/// the summary is a divergence from the `ostree` command:
///
/// - `ostree` writes both maps in hash-table order. This order depends on the
///   set of names and, for some names, on the order in which `ostree` read
///   them.
/// - ostrya writes both maps in name order.
///
/// Over six deltas into one target, both commands agree on the entries and on
/// each digest, the SHA-256 of the superblock. The order of each map of
/// `ostree` is not name order. `ostree` pulls with `--require-static-deltas`
/// from the repository that ostrya indexed.
#[test]
fn static_delta_index_entry_order_parts_from_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-index-order");
    let base = tmp.path();
    // The test uses a set for which the order of `ostree` differs from name
    // order in both maps. The fixed timestamps fix the commit checksums and
    // the delta names. The order of `ostree` is stable for one set of names.
    // If the checksums differ, a set of six can come out in name order by
    // chance, at about one in 720 for each map.
    let (repo, commits) = delta_chain_repo(base, "repo", 6);
    let to = &commits[5];
    ostree_ok(&repo, &["static-delta", "generate", "--empty", "--to", to]);
    for from in &commits[..5] {
        ostree_ok(
            &repo,
            &["static-delta", "generate", "--from", from, "--to", to],
        );
    }
    let port = clone_repo(base, &repo, "port");
    let tool = clone_repo(base, &repo, "tool");
    for args in [&["static-delta", "reindex"][..], &["summary", "-u"]] {
        let run = ostrya(
            &[args, &["--repo", port.to_str().unwrap()]].concat(),
            None,
            &[],
        );
        assert!(
            run.status.success(),
            "{}",
            String::from_utf8_lossy(&run.stderr)
        );
        ostree_ok(&tool, args);
    }

    let mut expected: Vec<(String, Vec<u8>)> = std::iter::once(None)
        .chain(commits[..5].iter().map(Some))
        .map(|from| {
            let name = match from {
                Some(from) => format!("{from}-{to}"),
                None => to.clone(),
            };
            let from = from.map(|from| Checksum::from_hex(from).unwrap());
            let dir =
                ostrya::static_delta_relative_dir(from.as_ref(), &Checksum::from_hex(to).unwrap());
            let superblock = std::fs::read(repo.join(dir).join("superblock")).unwrap();
            (name, Checksum::sha256(&superblock).as_bytes().to_vec())
        })
        .collect();
    expected.sort();

    let index = |repo: &Path| index_entries(&repo.join("delta-indexes").join(index_rel(to)));
    for (what, port_entries, mut tool_entries) in [
        ("index", index(&port), index(&tool)),
        (
            "summary",
            summary_static_delta_entries(&port),
            summary_static_delta_entries(&tool),
        ),
    ] {
        assert_eq!(port_entries, expected, "the port's {what} map");
        assert_ne!(
            tool_entries, expected,
            "the tool's {what} map is in name order"
        );
        tool_entries.sort();
        assert_eq!(tool_entries, expected, "the tool's {what} map");
    }

    let client = base.join("client");
    ostree_ok(&client, &["init", "--mode=bare-user"]);
    let url = format!("file://{}", port.display());
    ostree_ok(
        &client,
        &["remote", "add", "--no-gpg-verify", "origin", &url],
    );
    ostree_ok(&client, &["pull", "--require-static-deltas", "origin", "m"]);
    ostree_ok(&client, &["fsck"]);
    assert_eq!(ostree_ok(&client, &["rev-parse", "origin:m"]), *to);
}

/// In ostrya and in the `ostree` command, the files that
/// `static-delta generate` and `static-delta reindex` write get mode 0644
/// under umask 077:
///
/// - the superblock and the part files at the repository location
/// - the superblock and the part files at the `--filename` path
/// - the index files of the full pass and of `--to`
///
/// The directories that both commands create follow the umask, and their
/// modes agree.
#[test]
fn static_delta_file_modes_do_not_follow_the_umask() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-file-modes");
    let base = tmp.path();
    let (repo, commits) = delta_chain_repo(base, "repo", 2);
    let [c1, c2] = [&commits[0], &commits[1]];
    let port = clone_repo(base, &repo, "port");
    let tool = clone_repo(base, &repo, "tool");
    let modes = |side: &Path| {
        let mut out = Vec::new();
        for dir in ["deltas", "delta-indexes", "out"] {
            for line in describe_tree(&side.join(dir)) {
                let fields: Vec<&str> = line.split(' ').take(3).collect();
                out.push(format!("{dir}/{}", fields.join(" ")));
            }
        }
        out
    };
    for (program, side) in [(env!("CARGO_BIN_EXE_ostrya"), &port), ("ostree", &tool)] {
        let repo_arg = format!("--repo={}", side.display());
        let filename = format!("--filename={}", side.join("out/superblock").display());
        std::fs::create_dir(side.join("out")).unwrap();
        let to_c1 = format!("--to={c1}");
        let to_c2 = format!("--to={c2}");
        let from_c1 = format!("--from={c1}");
        for args in [
            &["static-delta", "generate", &repo_arg, "--empty", &to_c2][..],
            &["static-delta", "generate", &repo_arg, &from_c1, &to_c2],
            &[
                "static-delta",
                "generate",
                &repo_arg,
                "--empty",
                &to_c1,
                &filename,
            ],
            &["static-delta", "reindex", &repo_arg],
        ] {
            let run = program_with_umask(program, "077", args);
            assert!(
                run.status.success(),
                "{program} {args:?}: {}",
                String::from_utf8_lossy(&run.stderr)
            );
        }
        std::fs::remove_file(side.join("delta-indexes").join(index_rel(c2))).unwrap();
        let run = program_with_umask(
            program,
            "077",
            &["static-delta", "reindex", &repo_arg, &to_c2],
        );
        assert!(run.status.success(), "{program} reindex --to");
    }
    let port_modes = modes(&port);
    assert_eq!(port_modes, modes(&tool));
    let files: Vec<&String> = port_modes
        .iter()
        .filter(|line| line.contains(" file "))
        .collect();
    assert!(
        files.iter().any(|line| line.starts_with("out/")),
        "{port_modes:?}"
    );
    assert!(
        files.iter().any(|line| line.ends_with("/0 file 644")),
        "no part file: {port_modes:?}"
    );
    for line in &files {
        assert!(line.ends_with(" file 644"), "{line}");
    }
}

/// If a delta at the repository location is generated again with `--inline`,
/// the `ostree` command leaves the part files of the old delta. ostrya removes
/// them. The test carries `static-delta/generate-inline-stale-parts`.
#[test]
fn static_delta_generate_inline_removes_stale_parts() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("delta-generate-inline-stale");
    let base = tmp.path();
    let (repo, c) = delta_fallback_repo(base, "repo", true);
    let port_repo = clone_repo(base, &repo, "port");
    let tool_repo = clone_repo(base, &repo, "tool");
    let port = (base, port_repo.as_path());
    let tool = (base, tool_repo.as_path());
    let to = format!("--to={c}");
    let args = ["--empty", to.as_str(), "--max-chunk-size=1"];
    let (p, t) = generate_both(port, tool, &args);
    assert_runs_agree_on_stdout(&p, &t, &args);
    let relative = ostrya::static_delta_relative_dir(None, &Checksum::from_hex(&c).unwrap());
    let parts = entry_names(&tool_repo.join(&relative));
    assert!(parts.len() > 2, "{parts:?}");

    let args = ["--empty", to.as_str(), "--inline"];
    let (p, t) = generate_both(port, tool, &args);
    assert_runs_agree_on_stdout(&p, &t, &args);
    assert_eq!(entry_names(&port_repo.join(&relative)), ["superblock"]);
    assert_eq!(entry_names(&tool_repo.join(&relative)), parts);
}

// --- sign --verify and summary --verify key sources ---------------------------

/// The outcome of one key-source row of `sign --verify` or `summary --verify`.
enum KeySourceOutcome {
    /// The keys load and the command verifies the signatures. The value is the
    /// exit status of the verdict: 0 if verified, 1 if not.
    Verdict(i32),
    /// The keys do not load: exit 1 with nothing on standard output and this
    /// standard error.
    Refused(String),
}

/// One key-source row:
///
/// - the options before the commit
/// - the KEY-ID positionals after it
/// - the outcome
/// - `true` if `sign --verify` of the `ostree` command gives the same outcome
struct KeySourceRow {
    options: Vec<&'static str>,
    keys: Vec<&'static str>,
    outcome: KeySourceOutcome,
    tool_agrees: bool,
}

/// Writes the key files and the key stores that the key-source rows name into
/// `base`, the working directory of each run.
fn key_source_fixtures(base: &Path) {
    std::fs::write(base.join("k1"), format!("{ED25519_PUBLIC_B64}\n")).unwrap();
    std::fs::write(base.join("k2"), format!("{ED25519_PUBLIC2_B64}\n")).unwrap();
    verify_key_store(base, "store1", &[ED25519_PUBLIC_B64], &[]);
    verify_key_store(base, "store2", &[ED25519_PUBLIC2_B64], &[]);
    verify_key_store(
        base,
        "revoked",
        &[ED25519_PUBLIC_B64],
        &[ED25519_PUBLIC_B64],
    );
    verify_key_store(base, "only-revoked", &[], &[ED25519_PUBLIC_B64]);
    let dotd = base.join("dotd/trusted.ed25519.d");
    std::fs::create_dir_all(&dotd).unwrap();
    std::fs::write(dotd.join("key"), format!("{ED25519_PUBLIC_B64}\n")).unwrap();
    // An empty --keys-dir names the working directory.
    std::fs::write(
        base.join("trusted.ed25519"),
        format!("{ED25519_PUBLIC_B64}\n"),
    )
    .unwrap();
    std::fs::create_dir_all(base.join("adir")).unwrap();
    mkfifo_at(&base.join("fifo"));
    std::fs::write(base.join("empty"), b"").unwrap();
    std::fs::write(
        base.join("blank-first"),
        format!("\n{ED25519_PUBLIC_B64}\n"),
    )
    .unwrap();
    let junk = format!("{}!{}", &ED25519_PUBLIC_B64[..4], &ED25519_PUBLIC_B64[4..]);
    std::fs::write(base.join("lenient2"), format!("  {junk}  \r\n")).unwrap();
    std::fs::write(base.join("onebyte-A"), format!("A\n{ED25519_PUBLIC_B64}\n")).unwrap();
}

/// Returns the key-source rows over a commit or a summary that only the shared
/// key signs. Each refusal row comes after all verdict rows, and the FIFO row
/// is the last row. As a result, a build that waits on a FIFO fails an
/// earlier row first.
fn key_source_rows() -> Vec<KeySourceRow> {
    use KeySourceOutcome::{Refused, Verdict};
    let row =
        |options: &[&'static str], keys: &[&'static str], outcome, tool_agrees| KeySourceRow {
            options: options.to_vec(),
            keys: keys.to_vec(),
            outcome,
            tool_agrees,
        };
    let no_keys = || Refused("error: signature: ed25519: no keys loaded\n".to_owned());
    let not_regular = |path: &str| {
        Refused(format!(
            "error: File object '{path}' is not a regular file\n"
        ))
    };
    let invalid = |n: usize| {
        Refused(format!(
            "error: Invalid ed25519 public key: Ill-formed input: expected 32 bytes, got {n} \
             bytes\n"
        ))
    };
    vec![
        row(&["--keys-file=k2", "--keys-file=k1"], &[], Verdict(0), true),
        row(&["--keys-file=k1", "--keys-file=k2"], &[], Verdict(1), true),
        row(
            &["--keys-file=k1"],
            &[ED25519_PUBLIC2_B64],
            Verdict(0),
            true,
        ),
        row(
            &["--keys-dir=store1", "--keys-file=k2"],
            &[],
            Verdict(1),
            true,
        ),
        row(
            &["--keys-dir=store1"],
            &[ED25519_PUBLIC2_B64],
            Verdict(1),
            true,
        ),
        row(
            &["--keys-dir=revoked"],
            &[ED25519_PUBLIC_B64],
            Verdict(0),
            true,
        ),
        row(
            &["--keys-dir=revoked", "--keys-file=k1"],
            &[],
            Verdict(0),
            true,
        ),
        row(&["--keys-dir=store1"], &[], Verdict(0), true),
        row(
            &["--keys-dir=store1", "--keys-dir=store2"],
            &[],
            Verdict(1),
            true,
        ),
        row(
            &["--keys-dir=store2", "--keys-dir=store1"],
            &[],
            Verdict(0),
            true,
        ),
        row(&["--keys-dir="], &[], Verdict(0), true),
        row(&["--keys-dir=dotd"], &[], Verdict(0), true),
        row(&["--keys-dir=revoked"], &[], Verdict(1), true),
        row(
            &["--keys-dir=nodir"],
            &[ED25519_PUBLIC_B64],
            Verdict(0),
            true,
        ),
        row(&["--keys-file=lenient2"], &[], Verdict(0), true),
        row(&["--keys-file=blank-first"], &[], Verdict(0), false),
        row(&["--keys-dir=only-revoked"], &[], no_keys(), true),
        row(&["--keys-dir=nodir"], &[], no_keys(), true),
        row(
            &["--keys-file=empty"],
            &[],
            Refused("error: signature: ed25519: no valid keys in file 'empty'\n".to_owned()),
            true,
        ),
        row(&["--keys-file=onebyte-A"], &[], invalid(0), false),
        row(&[], &["AAAA"], invalid(3), false),
        row(&["--keys-file=nosuch"], &[], not_regular("nosuch"), true),
        row(&["--keys-file=adir"], &[], not_regular("adir"), true),
        row(&["--keys-file="], &[], not_regular(""), true),
        row(&["--keys-file=fifo"], &[], not_regular("fifo"), true),
    ]
}

/// Returns the label of a key-source row.
fn key_source_label(row: &KeySourceRow) -> String {
    [&row.options[..], &row.keys[..]].concat().join(" ")
}

/// Asserts the outcome of each key-source row. `run` builds and runs the
/// command for the options and the KEY-IDs of the row. `verified` and `failed`
/// are the standard output of a verified and of a failed verdict.
fn assert_key_source_rows(run: &dyn Fn(&[&str], &[&str]) -> Run, verified: &str, failed: &str) {
    for row in key_source_rows() {
        let label = key_source_label(&row);
        let got = run(&row.options, &row.keys);
        let (code, stdout, stderr) = match &row.outcome {
            KeySourceOutcome::Verdict(0) => (0, verified, ""),
            KeySourceOutcome::Verdict(code) => (*code, failed, ""),
            KeySourceOutcome::Refused(stderr) => (1, "", stderr.as_str()),
        };
        assert_verify_run(&got, code, stdout, stderr, &label);
    }
}

/// Creates a commit fixture in `base/<name>`, signed with the shared key. If
/// `tool` is `true`, the `ostree` command signs it. Otherwise ostrya signs it.
fn signed_commit_fixture(base: &Path, name: &str, tool: bool) -> PathBuf {
    let dir = base.join(name);
    std::fs::create_dir_all(&dir).unwrap();
    let repo = commit_fixture(&dir);
    if tool {
        ostree_ok(
            &repo,
            &["sign", "--sign-type=ed25519", COMMIT, ED25519_SECRET_B64],
        );
    } else {
        let repo_arg = format!("--repo={}", repo.display());
        ostrya(&["sign", &repo_arg, COMMIT, ED25519_SECRET_B64], None, &[]).ok();
    }
    repo
}

/// Creates a commit fixture in `base/<name>` with a summary signed with the
/// shared key. If `tool` is `true`, the `ostree` command signs the summary.
/// Otherwise ostrya signs it.
fn signed_summary_fixture(base: &Path, name: &str, tool: bool) -> PathBuf {
    let dir = base.join(name);
    std::fs::create_dir_all(&dir).unwrap();
    let repo = commit_fixture(&dir);
    let sign = format!("--sign={ED25519_SECRET_B64}");
    if tool {
        ostree_ok(&repo, &["summary", "-u", "--sign-type=ed25519", &sign]);
    } else {
        let repo_arg = format!("--repo={}", repo.display());
        ostrya(
            &[
                "summary",
                &repo_arg,
                "-u",
                "--last-modified=1700000000",
                &sign,
            ],
            None,
            &[],
        )
        .ok();
    }
    repo
}

/// Runs `sign --verify` over `COMMIT` in `repo` from `cwd`, with `options`
/// before the commit and `keys` after it. If `tool` is `true`, the command is
/// `ostree`. Otherwise it is ostrya.
fn run_sign_verify(cwd: &Path, repo: &Path, options: &[&str], keys: &[&str], tool: bool) -> Run {
    let repo_arg = format!("--repo={}", repo.display());
    let head = ["sign", repo_arg.as_str(), "--verify"];
    let all = [&head[..], options, &[COMMIT], keys].concat();
    if tool {
        ostree_in(cwd, &all)
    } else {
        ostrya_in(Some(cwd), &all, None, &[])
    }
}

/// Runs `summary --verify` of ostrya over `repo` from `cwd`.
fn run_summary_verify(cwd: &Path, repo: &Path, options: &[&str], keys: &[&str]) -> Run {
    let repo_arg = format!("--repo={}", repo.display());
    let head = ["summary", repo_arg.as_str(), "--verify"];
    ostrya_in(Some(cwd), &[&head[..], options, keys].concat(), None, &[])
}

/// `sign --verify` reads the same key sources as `static-delta verify`:
///
/// - the positionals and the last `--keys-file`
/// - the last `--keys-dir`, which the command does not read if a positional
///   or a `--keys-file` is given
/// - an empty `--keys-dir`, which names the working directory
///
/// The command checks for `no keys loaded` before it applies revocation. If a
/// key source does not load, the command refuses the run with nothing on
/// standard output.
#[test]
fn sign_verify_key_sources() {
    let tmp = TmpDir::new("sign-verify-keys");
    let base = tmp.path();
    let repo = signed_commit_fixture(base, "p", false);
    key_source_fixtures(base);
    assert_key_source_rows(
        &|options, keys| run_sign_verify(base, &repo, options, keys, false),
        "signature 1: good\nverification OK\n",
        "signature 1: no public key\nverification FAILED\n",
    );
}

/// `summary --verify` reads the same key sources as `sign --verify`.
#[test]
fn summary_verify_key_sources() {
    let tmp = TmpDir::new("summary-verify-keys");
    let base = tmp.path();
    let repo = signed_summary_fixture(base, "p", false);
    key_source_fixtures(base);
    assert_key_source_rows(
        &|options, keys| run_summary_verify(base, &repo, options, keys),
        "signature 1: good\nverification OK\n",
        "signature 1: no public key\nverification FAILED\n",
    );
}

/// The gpg engine reads keyrings only from `--keys-file`. `sign --verify` and
/// `summary --verify` both refuse `--keys-dir` with this engine, with the same
/// message and exit status. They write nothing on standard output.
#[test]
fn gpg_verify_refuses_keys_dir() {
    let tmp = TmpDir::new("gpg-verify-keys-dir");
    let base = tmp.path();
    key_source_fixtures(base);
    let options = ["-s", "gpg", "--keys-dir=store1"];
    let refusal = "error: signature: --keys-dir is not used by the gpg engine; \
                   supply keyrings with --keys-file\n";
    let commit_repo = signed_commit_fixture(base, "c", false);
    let sign = run_sign_verify(base, &commit_repo, &options, &[], false);
    assert_verify_run(&sign, 1, "", refusal, "sign --verify -s gpg --keys-dir");
    let summary_repo = signed_summary_fixture(base, "s", false);
    let summary = run_summary_verify(base, &summary_repo, &options, &[]);
    assert_verify_run(
        &summary,
        1,
        "",
        refusal,
        "summary --verify -s gpg --keys-dir",
    );
}

/// The test uses a commit that the `ostree` command signed and a commit that
/// ostrya signed. Over each commit, `sign --verify` of ostrya gives the verdict
/// of `ostree` on each key-source row with `tool_agrees` set. Each refusal
/// before verification agrees byte for byte. The verdict reports of the two
/// commands differ. The test carries
/// `sign/verify-{keys-file-last-wins,keys-file-overrides-keys-dir,keys-dir-last-wins,no-keys,keys-file-not-regular,report}`.
#[test]
fn sign_verify_key_sources_match_the_tool() {
    if !ostree_supports_ed25519() {
        return;
    }
    let tmp = TmpDir::new("sign-verify-keys-tool");
    let base = tmp.path();
    key_source_fixtures(base);
    for (who, tool_signed) in [("tool", true), ("port", false)] {
        let repo = signed_commit_fixture(base, who, tool_signed);
        for row in key_source_rows().iter().filter(|row| row.tool_agrees) {
            let label = format!("{who}-signed: {}", key_source_label(row));
            let port = run_sign_verify(base, &repo, &row.options, &row.keys, false);
            let tool = run_sign_verify(base, &repo, &row.options, &row.keys, true);
            match &row.outcome {
                KeySourceOutcome::Verdict(code) => {
                    assert_eq!(port.status.code(), Some(*code), "port, {label}");
                    assert_eq!(tool.status.code(), Some(*code), "tool, {label}");
                }
                KeySourceOutcome::Refused(_) => assert_runs_agree(&port, &tool, &label),
            }
        }
        // The report: `ostree` prints one line with the key that verified.
        // ostrya prints one line for each signature, and the verdict.
        let port = run_sign_verify(base, &repo, &[], &[ED25519_PUBLIC_B64], false);
        let tool = run_sign_verify(base, &repo, &[], &[ED25519_PUBLIC_B64], true);
        assert_eq!(
            String::from_utf8_lossy(&tool.stdout),
            "ed25519: Signature verified successfully with key \
             'c23b346c1d572f8184e8cfacce6f93af2bfbfc9c7e8a7cb47775f76c9fa652c9'\n",
            "{who}-signed"
        );
        assert_verify_run(
            &port,
            0,
            "signature 1: good\nverification OK\n",
            "",
            &format!("{who}-signed report"),
        );
    }
}

/// Returns `true` if the `ostree` command verifies the summary of `server` with
/// the ed25519 public key file `key`, through its own client repository.
fn tool_verifies_ed25519_summary(base: &Path, name: &str, server: &Path, key: &Path) -> bool {
    let client = base.join(name);
    let client_arg = format!("--repo={}", client.display());
    ostree(&[&client_arg, "init", "--mode=archive"]).ok();
    ostree(&[
        &client_arg,
        "remote",
        "add",
        "--set=gpg-verify=false",
        "--set=gpg-verify-summary=false",
        "--set=sign-verify-summary=true",
        &format!("--set=verification-ed25519-file={}", key.display()),
        "origin",
        &format!("file://{}", server.display()),
    ])
    .ok();
    ostree(&[&client_arg, "remote", "summary", "origin"])
        .status
        .success()
}

/// The `ostree` command has no `summary --verify`. The test uses a summary
/// that `ostree` signed and a summary that ostrya signed. Over each summary:
///
/// - `summary --verify` of ostrya applies the key sources of `sign --verify`.
/// - `remote summary` of `ostree` verifies the summary with the signing key,
///   and refuses it with another key.
///
/// The test carries
/// `summary/verify-{keys-file-last-wins,keys-file-overrides-keys-dir}`.
#[test]
fn summary_verify_key_sources_over_both_signers() {
    if !ostree_supports_ed25519() {
        return;
    }
    let tmp = TmpDir::new("summary-verify-keys-tool");
    let base = tmp.path();
    key_source_fixtures(base);
    for (who, tool_signed) in [("tool", true), ("port", false)] {
        let repo = signed_summary_fixture(base, who, tool_signed);
        let refused = ostree(&[&format!("--repo={}", repo.display()), "summary", "--verify"]);
        assert_eq!(refused.status.code(), Some(1));
        assert!(
            String::from_utf8_lossy(&refused.stderr).contains("error: Unknown option --verify"),
            "{}",
            String::from_utf8_lossy(&refused.stderr)
        );
        assert_key_source_rows(
            &|options, keys| run_summary_verify(base, &repo, options, keys),
            "signature 1: good\nverification OK\n",
            "signature 1: no public key\nverification FAILED\n",
        );
        assert!(
            tool_verifies_ed25519_summary(
                base,
                &format!("client-{who}-k1"),
                &repo,
                &base.join("k1")
            ),
            "the tool did not verify the {who}'s summary"
        );
        assert!(
            !tool_verifies_ed25519_summary(
                base,
                &format!("client-{who}-k2"),
                &repo,
                &base.join("k2")
            ),
            "the tool verified the {who}'s summary under another key"
        );
    }
}

/// Fills `tmp` with top-level entries on both sides of the default expiry
/// window:
///
/// - an old file, an old fifo, an old dotfile, and an old `staging-` name that
///   is not a directory
/// - an old directory with a new child
/// - an old symlink to `outside`
/// - a new file
/// - a new directory with an old child
/// - an old `cache/` entry
fn aged_tmp_layout(tmp: &Path, outside: &Path) {
    let stamp = |path: &Path| {
        let status = Command::new("touch")
            .args(["-h", "-d", "2020-01-01T00:00:00Z"])
            .arg(path)
            .status()
            .unwrap();
        assert!(status.success(), "touch could not stamp {}", path.display());
    };
    for name in ["oldfile", ".tmp-old", "staging-not-a-dir"] {
        std::fs::write(tmp.join(name), b"o").unwrap();
        stamp(&tmp.join(name));
    }
    let fifo = Command::new("mkfifo")
        .arg(tmp.join("oldfifo"))
        .status()
        .unwrap();
    assert!(fifo.success(), "mkfifo failed");
    stamp(&tmp.join("oldfifo"));
    std::fs::create_dir_all(tmp.join("olddir/sub")).unwrap();
    std::fs::write(tmp.join("olddir/sub/fresh"), b"n").unwrap();
    stamp(&tmp.join("olddir"));
    std::os::unix::fs::symlink(outside, tmp.join("oldlink")).unwrap();
    stamp(&tmp.join("oldlink"));
    std::fs::write(tmp.join("newfile"), b"n").unwrap();
    std::fs::create_dir(tmp.join("newdir")).unwrap();
    std::fs::write(tmp.join("newdir/oldkid"), b"o").unwrap();
    stamp(&tmp.join("newdir/oldkid"));
    std::fs::write(tmp.join("cache/oldentry"), b"o").unwrap();
    stamp(&tmp.join("cache/oldentry"));
    stamp(&tmp.join("cache"));
}

/// Returns the sorted relative paths in `dir`, at each depth.
fn tmp_tree(dir: &Path) -> Vec<String> {
    let mut out = Vec::new();
    let mut stack = vec![dir.to_path_buf()];
    while let Some(d) = stack.pop() {
        for entry in std::fs::read_dir(&d).unwrap() {
            let entry = entry.unwrap();
            let path = entry.path();
            out.push(path.strip_prefix(dir).unwrap().display().to_string());
            if entry.file_type().unwrap().is_dir() {
                stack.push(path);
            }
        }
    }
    out.sort();
    out
}

/// A `commit` of ostrya and of the `ostree` command removes the same old
/// `tmp/` entries:
///
/// - The command removes each entry whose own mtime is older than
///   `tmp-expiry-secs`.
/// - It removes a directory as a full tree, and a symlink as the link.
/// - `tmp/cache` and the new entries stay.
#[test]
fn commit_reaps_aged_tmp_entries_as_the_tool_does() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("tmp-reap");
    let base = tmp.path();
    let tree = base.join("tree");
    std::fs::create_dir(&tree).unwrap();
    std::fs::write(tree.join("a"), b"a\n").unwrap();
    let outside = base.join("outside");
    std::fs::create_dir(&outside).unwrap();
    std::fs::write(outside.join("keep"), b"k").unwrap();

    let tree_arg = format!("--tree=dir={}", tree.display());
    let mut left = Vec::new();
    for side in ["port", "tool"] {
        let repo = base.join(side);
        block_on(Repo::create(&repo, CreateOptions::new(RepoMode::Archive))).unwrap();
        aged_tmp_layout(&repo.join("tmp"), &outside);
        let repo_arg = format!("--repo={}", repo.display());
        let args = ["commit", &repo_arg, "-b", "main", &tree_arg, "-s", "s"];
        let run = if side == "port" {
            ostrya(&args, None, &[])
        } else {
            ostree(&args)
        };
        assert!(
            run.status.success(),
            "{side} commit failed: {}",
            String::from_utf8_lossy(&run.stderr)
        );
        left.push(tmp_tree(&repo.join("tmp")));
    }
    assert_eq!(
        left[0],
        [
            "cache",
            "cache/oldentry",
            "newdir",
            "newdir/oldkid",
            "newfile"
        ],
        "the port's tmp/ after commit"
    );
    assert_eq!(
        left[0], left[1],
        "the port and the tool leave the same tmp/"
    );
    assert!(outside.join("keep").exists(), "the symlink target stays");
}

// --- pull-local: verification and static deltas -------------------------
//
// The M10 records under "pull-local -- verification and static deltas" cite
// these tests as `evidence:`. They do this where a setup of the harness cannot
// hold the source that a case needs.

/// Creates an archive repository at `base/<name>` with the `ostree` command.
/// The repository has two commits on `main`, the second on top of the first,
/// and the deltas that `deltas` names:
///
/// - `scratch`: the delta from scratch to the second commit
/// - `from-to`: the delta between the two commits
///
/// If `summary` is `true`, the repository also has a summary. Returns the path
/// and both commits.
fn pull_local_delta_source(
    base: &Path,
    name: &str,
    deltas: &[&str],
    summary: bool,
) -> (PathBuf, String, String) {
    let repo = base.join(name);
    ostree_ok(&repo, &["init", "--mode=archive"]);
    let tree = base.join(format!("{name}-tree"));
    std::fs::create_dir_all(tree.join("d")).unwrap();
    std::fs::write(tree.join("a"), b"hello\n").unwrap();
    std::fs::write(tree.join("big"), delta_noise(300_000, 1)).unwrap();
    std::fs::write(tree.join("d/b"), b"x\n").unwrap();
    let tree_arg = format!("--tree=dir={}", tree.display());
    let commit = |subject: &str, ts: &str| {
        ostree_ok(
            &repo,
            &[
                "commit",
                "-b",
                "main",
                "-s",
                subject,
                "--no-xattrs",
                ts,
                &tree_arg,
            ],
        )
    };
    let c1 = commit("one", "--timestamp=@1700000000");
    std::fs::write(tree.join("c"), b"more\n").unwrap();
    let c2 = commit("two", "--timestamp=@1700000100");
    for delta in deltas {
        let to = format!("--to={c2}");
        match *delta {
            "scratch" => ostree_ok(&repo, &["static-delta", "generate", "--empty", &to]),
            "from-to" => ostree_ok(&repo, &["static-delta", "generate", &to, "main^"]),
            other => panic!("no delta {other}"),
        };
    }
    if summary {
        ostree_ok(&repo, &["summary", "-u"]);
    }
    (repo, c1, c2)
}

/// One `pull-local` case: a name, the setup of the destination, and the
/// arguments after `--repo`.
type PullLocalRow<'a> = (&'a str, &'a dyn Fn(&Path), Vec<String>);

/// A `PullLocalRow` and the statistics line that ostrya prints. The line is
/// `<..>` if the test only compares it with the line of `ostree`.
type PullLocalLineRow<'a> = (&'a str, &'a dyn Fn(&Path), Vec<String>, &'a str);

/// Runs `pull-local` with `args` into a new repository of `mode` in
/// `base/<name>-<who>`, after `setup` runs with the repository path. If `who`
/// is `"port"`, the command is ostrya. Otherwise it is the `ostree` command.
/// Returns the run, the refs, and the loose objects.
fn pull_local_case(
    base: &Path,
    name: &str,
    who: &str,
    mode: RepoMode,
    setup: &dyn Fn(&Path),
    args: &[&str],
) -> (Run, Vec<String>, Vec<(String, String)>) {
    let dir = base.join(format!("{name}-{who}"));
    std::fs::create_dir_all(&dir).unwrap();
    let dest = create_repo(&dir, mode);
    setup(&dest);
    let repo_arg = format!("--repo={}", dest.display());
    let mut argv = vec!["pull-local", repo_arg.as_str()];
    argv.extend_from_slice(args);
    let run = if who == "port" {
        ostrya(&argv, None, &[])
    } else {
        ostree(&argv)
    };
    let refs = block_on(async {
        let repo = Repo::open(&dest).await.unwrap();
        let mut refs: Vec<String> = repo
            .list_refs(None)
            .await
            .unwrap()
            .into_iter()
            .map(|(name, _)| name)
            .collect();
        refs.sort();
        refs
    });
    (run, refs, loose_objects(&dest))
}

/// With the two delta switches of `pull-local`, ostrya gives the outcome, the
/// refs, the objects, and the statistics line of the `ostree` command:
///
/// - the delta from scratch
/// - a from-to delta from a commit that the destination has under no ref
/// - a delta from scratch that the commit of the ref declines
/// - a source with no delta for the commit
/// - a source with no summary
/// - a source that is not in archive mode
/// - a commit-only pull
/// - deltas disabled over a source with a corrupt superblock
///
/// Each command writes its own message on standard error.
#[test]
fn pull_local_static_delta_switches_match_the_tool() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("pull-local-delta-switches");
    let base = tmp.path();
    let (both, c1, c2) = pull_local_delta_source(base, "both", &["scratch", "from-to"], true);
    let (from_to, _, _) = pull_local_delta_source(base, "from-to", &["from-to"], true);
    let (unlisted, _, _) = pull_local_delta_source(base, "unlisted", &["scratch"], false);
    let (corrupt, _, _) = pull_local_delta_source(base, "corrupt", &["scratch"], true);
    for leaf in std::fs::read_dir(corrupt.join("deltas")).unwrap() {
        for dir in std::fs::read_dir(leaf.unwrap().path()).unwrap() {
            std::fs::write(dir.unwrap().path().join("superblock"), b"junk").unwrap();
        }
    }
    let bare = base.join("bare-source");
    ostree_ok(&bare, &["init", "--mode=bare-user"]);
    ostree_ok(&bare, &["pull-local", both.to_str().unwrap(), "main"]);
    ostree_ok(&bare, &["summary", "-u"]);

    let s = |path: &Path| path.to_str().unwrap().to_owned();
    let hold = |commit: String, src: PathBuf, reference: bool| {
        move |dest: &Path| {
            ostree_ok(dest, &["pull-local", src.to_str().unwrap(), &commit]);
            if reference {
                ostree_ok(dest, &["refs", "--create=main", &commit]);
            }
        }
    };
    let nothing = |_: &Path| {};
    let hold_c1 = hold(c1.clone(), both.clone(), false);
    let hold_c1_ref = hold(c1.clone(), both.clone(), true);
    let rows: Vec<PullLocalLineRow> = vec![
        (
            "scratch",
            &nothing,
            vec!["--require-static-deltas".into(), s(&both), "main".into()],
            "1 delta parts, 2 loose fetched; 294 KiB transferred in <n> seconds; \
             0 bytes content written\n",
        ),
        (
            "from-to",
            &hold_c1,
            vec!["--require-static-deltas".into(), s(&both), "main".into()],
            "1 delta parts, 2 loose fetched; 991 B transferred in <n> seconds; \
             0 bytes content written\n",
        ),
        (
            "declined",
            &hold_c1_ref,
            vec!["--require-static-deltas".into(), s(&both), "main".into()],
            "<declined>",
        ),
        (
            "none-found",
            &nothing,
            vec!["--require-static-deltas".into(), s(&from_to), "main".into()],
            "",
        ),
        (
            "no-summary",
            &nothing,
            vec![
                "--require-static-deltas".into(),
                s(&unlisted),
                "main".into(),
            ],
            "",
        ),
        (
            "bare-source",
            &nothing,
            vec!["--require-static-deltas".into(), s(&bare), "main".into()],
            "",
        ),
        (
            "commit-only",
            &nothing,
            vec![
                "--commit-metadata-only".into(),
                "--require-static-deltas".into(),
                s(&from_to),
                "main".into(),
            ],
            "<commit-only>",
        ),
        (
            "disabled",
            &nothing,
            vec!["--disable-static-deltas".into(), s(&corrupt), "main".into()],
            "4 metadata, 4 content objects imported; 300.0\u{a0}kB content written\n",
        ),
    ];
    for (name, setup, args, expected) in rows {
        let args: Vec<&str> = args.iter().map(String::as_str).collect();
        let (ours, our_refs, our_objects) =
            pull_local_case(base, name, "port", RepoMode::BareUser, setup, &args);
        let (theirs, their_refs, their_objects) =
            pull_local_case(base, name, "tool", RepoMode::BareUser, setup, &args);
        assert_eq!(ours.status.code(), theirs.status.code(), "{name}");
        assert_eq!(our_refs, their_refs, "{name}");
        assert_eq!(our_objects, their_objects, "{name}");
        let line = normalized_statistics(&ours.stdout);
        assert_eq!(line, normalized_statistics(&theirs.stdout), "{name}");
        if !expected.starts_with('<') {
            assert_eq!(line, expected, "{name}");
        }
        if ours.status.success() {
            assert!(ours.stderr.is_empty(), "{name}");
        } else {
            assert!(our_objects.is_empty() && our_refs.is_empty(), "{name}");
        }
        if name == "none-found" {
            assert_eq!(
                String::from_utf8_lossy(&ours.stderr),
                format!("error: pull: Static deltas required, but none found for main to {c2}\n")
            );
            assert_eq!(
                String::from_utf8_lossy(&theirs.stderr),
                format!("error: Static deltas required, but none found for main to {c2}\n")
            );
        }
    }
}

/// The divergences of the delta switches of `pull-local` from the `ostree`
/// command:
///
/// - Into an `archive` destination, `ostree` refuses a required delta and
///   ostrya applies it. `fsck` of `ostree` accepts what ostrya wrote.
/// - With both switches, `ostree` ends on an assertion at exit 134. `clap` in
///   ostrya refuses them at exit 1, on `pull-local` and on `pull`.
///
/// Neither refusal writes an object or a ref.
#[test]
fn pull_local_static_delta_divergences() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("pull-local-delta-divergences");
    let base = tmp.path();
    let (src, _c1, c2) = pull_local_delta_source(base, "src", &["scratch"], true);
    let s = src.to_str().unwrap();
    let nothing = |_: &Path| {};
    let args = ["--require-static-deltas", s, "main"];
    let (ours, our_refs, _) =
        pull_local_case(base, "archive", "port", RepoMode::Archive, &nothing, &args);
    let (theirs, their_refs, their_objects) =
        pull_local_case(base, "archive", "tool", RepoMode::Archive, &nothing, &args);
    assert!(ours.status.success());
    assert_eq!(our_refs, vec!["main".to_owned()]);
    assert_eq!(theirs.status.code(), Some(1));
    assert_eq!(
        String::from_utf8_lossy(&theirs.stderr),
        "error: Can't use static deltas in an archive repo\n"
    );
    assert!(their_refs.is_empty() && their_objects.is_empty());
    let port_dest = base.join("archive-port/repo");
    ostree_ok(&port_dest, &["fsck"]);
    assert_eq!(resolve(&port_dest, "main").as_deref(), Some(c2.as_str()));

    let both = [
        "--require-static-deltas",
        "--disable-static-deltas",
        s,
        "main",
    ];
    let (ours, our_refs, our_objects) =
        pull_local_case(base, "both", "port", RepoMode::BareUser, &nothing, &both);
    let (theirs, their_refs, their_objects) =
        pull_local_case(base, "both", "tool", RepoMode::BareUser, &nothing, &both);
    assert_eq!(ours.status.code(), Some(1));
    assert!(
        String::from_utf8_lossy(&ours.stderr).contains(
            "the argument '--require-static-deltas' cannot be used with \
             '--disable-static-deltas'"
        ),
        "{}",
        String::from_utf8_lossy(&ours.stderr)
    );
    assert_eq!(theirs.status.code(), None, "the tool ended on a signal");
    for (refs, objects) in [(our_refs, our_objects), (their_refs, their_objects)] {
        assert!(refs.is_empty() && objects.is_empty());
    }

    std::fs::create_dir_all(base.join("pull-both")).unwrap();
    let dest = create_repo(&base.join("pull-both"), RepoMode::BareUser);
    let repo_arg = format!("--repo={}", dest.display());
    let run = ostrya(
        &[
            "pull",
            &repo_arg,
            "--require-static-deltas",
            "--disable-static-deltas",
            "origin",
            "main",
        ],
        None,
        &[],
    );
    assert_eq!(run.status.code(), Some(1));
    assert!(
        String::from_utf8_lossy(&run.stderr).contains("cannot be used with"),
        "{}",
        String::from_utf8_lossy(&run.stderr)
    );
    assert!(loose_objects(&dest).is_empty());
}

/// The GPG switches of `pull-local` of ostrya refuse where the `ostree`
/// command refuses, and write no object and no ref:
///
/// - with no `--remote`
/// - over an unsigned commit, with a configured remote and with a remote that
///   is not configured
/// - over a source with no `summary.sig`, and over a source with no summary
/// - with `--gpg-verify=false`, which `clap` refuses and `ostree` reads as
///   `--gpg-verify` with no remote
///
/// The messages differ.
#[test]
fn pull_local_gpg_switches_refuse_where_the_tool_refuses() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("pull-local-gpg-switches");
    let base = tmp.path();
    let (signed_summary, _, _) = pull_local_delta_source(base, "summary", &[], true);
    let (no_summary, _, _) = pull_local_delta_source(base, "no-summary", &[], false);
    let s = |path: &Path| path.to_str().unwrap().to_owned();
    let nothing = |_: &Path| {};
    let remote = |dest: &Path| {
        ostree_ok(dest, &["remote", "add", "o", "file:///nonexistent"]);
    };
    let rows: Vec<PullLocalRow> = vec![
        (
            "no-remote",
            &nothing,
            vec!["--gpg-verify".into(), s(&no_summary), "main".into()],
        ),
        (
            "summary-no-remote",
            &nothing,
            vec![
                "--gpg-verify-summary".into(),
                s(&signed_summary),
                "main".into(),
            ],
        ),
        (
            "unsigned",
            &remote,
            vec![
                "--gpg-verify".into(),
                "--remote=o".into(),
                s(&no_summary),
                "main".into(),
            ],
        ),
        (
            "unconfigured",
            &nothing,
            vec![
                "--gpg-verify".into(),
                "--remote=nosuch".into(),
                s(&no_summary),
                "main".into(),
            ],
        ),
        (
            "no-summary-sig",
            &remote,
            vec![
                "--gpg-verify-summary".into(),
                "--remote=o".into(),
                s(&signed_summary),
                "main".into(),
            ],
        ),
        (
            "no-summary",
            &remote,
            vec![
                "--gpg-verify-summary".into(),
                "--remote=o".into(),
                s(&no_summary),
                "main".into(),
            ],
        ),
        (
            "value",
            &nothing,
            vec!["--gpg-verify=false".into(), s(&no_summary), "main".into()],
        ),
    ];
    for (name, setup, args) in rows {
        let args: Vec<&str> = args.iter().map(String::as_str).collect();
        for who in ["port", "tool"] {
            let (run, refs, objects) =
                pull_local_case(base, name, who, RepoMode::BareUser, setup, &args);
            assert_eq!(run.status.code(), Some(1), "{name} {who}");
            assert!(refs.is_empty(), "{name} {who}");
            assert!(objects.is_empty(), "{name} {who}");
        }
    }
}

/// `pull-local --gpg-verify` opens each source commit object as many times as
/// the same pull with no verification. The verification reads the bytes that
/// the walk of the chain read to find the parent. The pull opens each source
/// commit object one time. The walk of the chain reads it, and the walk of its
/// tree takes the root from that read. The test counts the opens under
/// `strace`, over a full pull of a chain of two signed commits.
#[cfg(feature = "gpg")]
#[test]
fn pull_local_gpg_verify_adds_no_commit_read() {
    if !gpg_available() || !strace_available() {
        return;
    }
    let tmp = TmpDir::new("pull-local-gpg-commit-reads");
    let base = tmp.path();
    let home = GpgHome::create(base, "Pull Reads <reads@example.invalid>");
    let homedir = format!("--gpg-homedir={}", home.dir.display());
    let sign = format!("--gpg-sign={}", home.fingerprint());
    let keyring = base.join("export.gpg");
    home.export_to(&keyring);
    let import = format!("--gpg-import={}", keyring.display());

    let src = base.join("src");
    let src_s = src.to_str().unwrap();
    ostrya(&["init", "--repo", src_s, "--mode=archive"], None, &[]).ok();
    let tree = base.join("tree");
    std::fs::create_dir(&tree).unwrap();
    let tree_arg = format!("--tree=dir={}", tree.display());
    let mut commits = Vec::new();
    for subject in ["one", "two"] {
        std::fs::write(tree.join("a"), subject).unwrap();
        let run = ostrya(
            &[
                "commit", "--repo", src_s, "-b", "main", "-s", subject, &sign, &homedir, &tree_arg,
            ],
            None,
            &[("SOURCE_DATE_EPOCH", SOURCE_DATE_EPOCH)],
        );
        commits.push(run.ok().stdout_trimmed());
    }

    // The opens of each source commit object, in the order of `commits`.
    // `strace -y` prints the path of the directory descriptor that an open is
    // relative to, so a line names the source repository and the object.
    let opens = |name: &str, extra: &[&str]| -> Vec<usize> {
        let dest = base.join(name);
        let dest_s = dest.to_str().unwrap();
        ostrya(&["init", "--repo", dest_s, "--mode=archive"], None, &[]).ok();
        ostrya(
            &[
                "remote",
                "add",
                "--repo",
                dest_s,
                &import,
                "o",
                "file:///nonexistent",
            ],
            None,
            &[],
        )
        .ok();
        let trace = base.join(format!("{name}.trace"));
        let run = Command::new("strace")
            .args(["-y", "-f", "-e", "trace=open,openat,openat2", "-o"])
            .arg(&trace)
            .arg(env!("CARGO_BIN_EXE_ostrya"))
            .args(["pull-local", "--repo", dest_s, "--remote=o", "--depth=-1"])
            .args(extra)
            .args([src_s, "main"])
            .output()
            .expect("strace runs");
        assert!(
            run.status.success(),
            "{name}: {}",
            String::from_utf8_lossy(&run.stderr)
        );
        let text = std::fs::read_to_string(&trace).expect("the trace is written");
        commits
            .iter()
            .map(|commit| {
                let object = format!("{}/{}.commit\"", &commit[..2], &commit[2..]);
                text.lines()
                    .filter(|line| line.contains(src_s) && line.contains(&object))
                    .count()
            })
            .collect()
    };
    let unchecked = opens("unchecked", &[]);
    let checked = opens("checked", &["--gpg-verify"]);
    assert_eq!(
        unchecked,
        vec![1; commits.len()],
        "the opens of each source commit object, unchecked"
    );
    assert_eq!(
        checked, unchecked,
        "the opens of each source commit object, checked and unchecked"
    );
}

/// `pull-local` from a source with a ref whose name is 64 lowercase hex
/// digits:
///
/// - The `ostree` command reads the name as a checksum and fails, with the ref
///   named and with no ref named.
/// - If the ref is named, ostrya reads the name as a checksum and fails. If
///   the pull takes each ref, ostrya copies the ref.
#[test]
fn pull_local_checksum_shaped_ref() {
    if !ostree_available() {
        return;
    }
    let tmp = TmpDir::new("pull-local-checksum-ref");
    let base = tmp.path();
    let (src, _, c2) = pull_local_delta_source(base, "src", &[], false);
    let name = "a".repeat(64);
    std::fs::write(src.join("refs/heads").join(&name), format!("{c2}\n")).unwrap();
    let s = src.to_str().unwrap();
    let nothing = |_: &Path| {};
    let expected = format!("error: Importing {name}.commit: linkat: No such file or directory\n");
    for (case, args) in [
        ("named", vec!["--disable-verify-bindings", s, name.as_str()]),
        ("all", vec!["--disable-verify-bindings", s]),
    ] {
        let (theirs, their_refs, _) =
            pull_local_case(base, case, "tool", RepoMode::BareUser, &nothing, &args);
        assert_eq!(theirs.status.code(), Some(1), "{case}");
        assert_eq!(String::from_utf8_lossy(&theirs.stderr), expected, "{case}");
        assert!(their_refs.is_empty(), "{case}");
        let (ours, our_refs, _) =
            pull_local_case(base, case, "port", RepoMode::BareUser, &nothing, &args);
        if case == "named" {
            assert_eq!(ours.status.code(), Some(1), "{case}");
            assert!(our_refs.is_empty(), "{case}");
        } else {
            assert!(ours.status.success(), "{case}");
            assert!(our_refs.contains(&name), "{case}: {our_refs:?}");
        }
    }
}
